INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26446, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "两个人之间一问一答的谈话内容。", "primary_collocate": null, "pronunciation": "duì huà", "ipa": "tuei˥˩ xua˥˩", "syllable_count": 2, "sentences": [{"text": "请听下面这段对话，然后回答问题。", "target_word": "对话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段对话是在饭店里发生的。", "target_word": "对话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们两个人练习对话。", "target_word": "对话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里有一段很有意思的对话。", "target_word": "对话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的对话我听得很清楚。", "target_word": "对话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课本里的对话都很短。", "target_word": "对话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和朋友的对话只有几句。", "target_word": "对话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在门外听到了他们的对话。", "target_word": "对话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个对话的第一句是“你好”。", "target_word": "对话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对话结束后，两个人都笑了。", "target_word": "对话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "两个人之间一问一答的谈话内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fc57a-06de-4b32-86c6-7fa8c22896d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26446, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水果", "is_correct": false, "explanation": "搭配：量词“段”不用于水果，且“水果”不能听，句意不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指体形，不是可以听的内容，“请听下面这段身材”不成立。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：“眼镜”是器具，不能被听，句子意义不通。"}, {"text": "对话", "is_correct": true, "explanation": "“对话”是可以听的一问一答的谈话，且与“段”搭配，符合句意。"}], "explanations": {"水果": "搭配：量词“段”不用于水果，且“水果”不能听，句意不通。", "身材": "体貌：“身材”指体形，不是可以听的内容，“请听下面这段身材”不成立。", "眼镜": "语义：“眼镜”是器具，不能被听，句子意义不通。", "对话": "“对话”是可以听的一问一答的谈话，且与“段”搭配，符合句意。"}, "sentence_index": 0, "correct_answer": "对话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的对话很感人。", "explanation": "这里应该用〈歌词〉。“对话”指两人一问一答的谈话内容，不能用于歌曲的文字。"}, {"text": "这本书的对话有三百页。", "explanation": "这里应该用〈内容〉。“对话”指两人一问一答的谈话，不用来指整本书的篇幅。"}, {"text": "这座桥的对话很结实。", "explanation": "这里应该用〈结构〉。“对话”指两人之间的谈话内容，不用来说桥的结构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26446, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "语义：“体重”是身体的重量，不能用“只有几句”来计量，句意不通。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：“长相”指外貌，不能用“只有几句”来计量。"}, {"text": "对话", "is_correct": true, "explanation": "“对话”可以用“几句”计量，与“我和朋友的”搭配，符合句意。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”是建筑，不能用“几句”来计量，句意不通。"}], "explanations": {"体重": "语义：“体重”是身体的重量，不能用“只有几句”来计量，句意不通。", "长相": "体貌：“长相”指外貌，不能用“只有几句”来计量。", "对话": "“对话”可以用“几句”计量，与“我和朋友的”搭配，符合句意。", "房子": "语义：“房子”是建筑，不能用“几句”来计量，句意不通。"}, "sentence_index": 6, "correct_answer": "对话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一个人在房间里写了一篇对话日记。", "explanation": "这里应该用〈心情〉。“对话”是两人之间的一问一答，一个人写日记没有对话。"}, {"text": "这道菜的对话很香。", "explanation": "这里应该用〈味道〉。“对话”指谈话内容，不能用来说菜。"}, {"text": "窗外的对话是一棵大树。", "explanation": "这里应该用〈风景〉。“对话”指两人的谈话内容，不用来说看到的景物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师和学生的一只对话很短。", "corrected_sentence": "老师和学生的一段对话很短。", "error_description": "量词错误：“对话”前应用“段”，不能用“只”。“只”用于动物或成对的物品，不能计量“对话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们的对话很快就结束着。", "corrected_sentence": "他们的对话很快就结束了。", "error_description": "动态助词错误：“结束”表示动作已完成，应用“了”。“着”表示动作持续，与句意不符。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
