INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26450, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "自己愿意做或不做。", "primary_collocate": null, "pronunciation": "zì yuàn", "ipa": "tsɹ̩˥˩ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "老师说，想帮忙的同学可以自愿举手。", "target_word": "自愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他自愿放弃了这次机会。", "target_word": "自愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐自愿陪我去医院。", "target_word": "自愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们自愿排队等车。", "target_word": "自愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些钱是大家自愿给的。", "target_word": "自愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们自愿分成两组做练习。", "target_word": "自愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她自愿早起为家人做早饭。", "target_word": "自愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没人要求他道歉，他自愿说了对不起。", "target_word": "自愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们自愿轮流照顾那只小猫。", "target_word": "自愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王自愿留在公司等客人。", "target_word": "自愿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自愿的", "label": "复合"}, {"form": "自願", "label": "繁体"}], "register": "中性", "sense_fingerprint": "按照自己的意愿决定做或者不做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abb8f175-d215-4d05-b870-efdc6b6faf90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26450, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自愿", "is_correct": true, "explanation": "自愿（zì yuàn）意思是按自己的意愿决定做或不做，是本题的目标词。"}, {"text": "紫苑", "is_correct": false, "explanation": "紫苑（zǐ yuàn）：与 zì yuàn 只差第一个音节的声调，是一种植物。"}, {"text": "寺院", "is_correct": false, "explanation": "sì（第四声）与 zì（第四声）声母不同（s 与 z），意思是寺庙。"}, {"text": "资源", "is_correct": false, "explanation": "两个音节声调均不同（zī yuán），意思是资源。"}], "explanations": {"自愿": "自愿（zì yuàn）意思是按自己的意愿决定做或不做，是本题的目标词。", "紫苑": "紫苑（zǐ yuàn）：与 zì yuàn 只差第一个音节的声调，是一种植物。", "寺院": "sì（第四声）与 zì（第四声）声母不同（s 与 z），意思是寺庙。", "资源": "两个音节声调均不同（zī yuán），意思是资源。"}, "sentence_index": null, "correct_answer": "自愿"}, "level_3": {"options": [{"text": "自愿", "is_correct": true, "explanation": "正确：自愿表示按自己的意愿决定做或不做，与“可以”的许可语气相符。"}, {"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示义务，与“可以”的许可语气冲突。"}, {"text": "不得不", "is_correct": false, "explanation": "语义：“不得不”表示被迫，与“可以”的自由选择矛盾。"}, {"text": "硬", "is_correct": false, "explanation": "语域：“硬”口语色彩强，且带强迫意味，与老师的许可语气不合。"}], "explanations": {"自愿": "正确：自愿表示按自己的意愿决定做或不做，与“可以”的许可语气相符。", "必须": "语义：“必须”表示义务，与“可以”的许可语气冲突。", "不得不": "语义：“不得不”表示被迫，与“可以”的自由选择矛盾。", "硬": "语域：“硬”口语色彩强，且带强迫意味，与老师的许可语气不合。"}, "sentence_index": 0, "correct_answer": "自愿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我自愿遇到了老同学。", "explanation": "这里应该用〈偶然〉。自愿表示有意识地主动选择，遇到老同学不是人主动选择的，应说“我偶然遇到了老同学”。"}, {"text": "电梯自愿关门了。", "explanation": "这里应该用〈自动〉。自愿要求有意志的人主动选择，电梯没有意志，应说“电梯自动关门”。"}, {"text": "她很有自愿精神，经常去社区帮忙。", "explanation": "这里应该用〈志愿〉。自愿指自己愿意做或不做，与“志愿者”的志愿不同，应说“志愿精神”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7791b646-2fff-46a8-9818-b19524defa3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26450, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自愿", "is_correct": true, "explanation": "正确：“自愿”修饰后面的动作，表示主动选择，与“早起为家人做早饭”的主动行为相符。"}, {"text": "无意", "is_correct": false, "explanation": "语义：“无意”指并非有意，与“为家人做早饭”的有意行为矛盾。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”指徒然、没有效果，与“为家人做早饭”的善意目的相悖。"}, {"text": "被迫", "is_correct": false, "explanation": "语义：“被迫”表示不得已而为，与“自愿”的主动选择相反。"}], "explanations": {"自愿": "正确：“自愿”修饰后面的动作，表示主动选择，与“早起为家人做早饭”的主动行为相符。", "无意": "语义：“无意”指并非有意，与“为家人做早饭”的有意行为矛盾。", "白白": "语义：“白白”指徒然、没有效果，与“为家人做早饭”的善意目的相悖。", "被迫": "语义：“被迫”表示不得已而为，与“自愿”的主动选择相反。"}, "sentence_index": 6, "correct_answer": "自愿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈逼着我自愿去上课。", "explanation": "这里不能用“自愿”。这句表示被迫去做，与自己选择的意思相反，应去掉“自愿”。"}, {"text": "水往低处流，是一种自愿的规律。", "explanation": "这里应该用〈自然〉。自愿指出于自己的意愿，水往低处流是自然的规律，不是人能选择的，应说“自然的规律”。"}, {"text": "他自愿感冒了，只好在家休息。", "explanation": "这里不能用“自愿”。感冒不是人能自己选择的事，应去掉“自愿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7791b646-2fff-46a8-9818-b19524defa3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26450, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他被自愿陪奶奶散步。", "corrected_sentence": "他自愿陪奶奶散步。", "error_description": "错误：“被自愿”；正确：“自愿”。“自愿”表示主动选择，与表示被动的“被”意义相反，二者不能连用，应去掉“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7791b646-2fff-46a8-9818-b19524defa3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26450, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐自愿了留下来帮忙收拾。", "corrected_sentence": "姐姐自愿留下来帮忙收拾。", "error_description": "体标错误：“自愿”后不能直接加“了”，应说“姐姐自愿留下来帮忙收拾”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7791b646-2fff-46a8-9818-b19524defa3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
