INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26452, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在地上挖一个洞。", "primary_collocate": null, "pronunciation": "wā kēng", "ipa": "ua˥ kʰɤŋ˥", "syllable_count": 2, "sentences": [{"text": "他在草地上挖坑，想做一个小小的池塘。", "target_word": "挖坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在后院挖坑，打算建一个小鱼池。", "target_word": "挖坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在雪地里挖坑，躲在里面玩游戏。", "target_word": "挖坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上很湿，挖坑时鞋上全是泥。", "target_word": "挖坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿起锄头，在菜地边挖坑。", "target_word": "挖坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说要在院子里挖坑，把垃圾埋掉。", "target_word": "挖坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明用手挖坑，一会儿手就脏了。", "target_word": "挖坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用机器挖坑，比用手快多了。", "target_word": "挖坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在那儿挖坑做什么？是不是丢了东西？", "target_word": "挖坑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "露营时，我们在地上挖坑生火。", "target_word": "挖坑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挖了坑", "label": "体标"}, {"form": "挖过坑", "label": "体标"}], "register": "中性", "sense_fingerprint": "在地上挖出一个洞或凹坑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616a40b2-ff1d-4894-b98c-a82aa79ff0f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26452, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挖坑", "is_correct": true, "explanation": "「挖坑」指在草地上挖出坑，与「做一个小小的池塘」的目的相合。"}, {"text": "砌墙", "is_correct": false, "explanation": "语义：砌墙是用来建墙的，与做小池塘的目的不符。"}, {"text": "拆房子", "is_correct": false, "explanation": "语义：拆房子与在草地上做池塘毫无关系。"}, {"text": "洗衣服", "is_correct": false, "explanation": "搭配：「洗衣服」的对象不是地面，不能与「在草地上……做池塘」搭配。"}], "explanations": {"挖坑": "「挖坑」指在草地上挖出坑，与「做一个小小的池塘」的目的相合。", "砌墙": "语义：砌墙是用来建墙的，与做小池塘的目的不符。", "拆房子": "语义：拆房子与在草地上做池塘毫无关系。", "洗衣服": "搭配：「洗衣服」的对象不是地面，不能与「在草地上……做池塘」搭配。"}, "sentence_index": 0, "correct_answer": "挖坑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在纸上挖坑，画出一个小池塘。", "explanation": "这里应该用〈画〉。挖坑指在地面挖洞，纸上画池塘要用画。"}, {"text": "木匠用刻刀挖坑，做出一朵花。", "explanation": "这里应该用〈雕〉。挖坑指在地面挖出小坑，用刻刀做花纹要用雕。"}, {"text": "她在汤碗里挖坑，想把汤喝完。", "explanation": "这里应该用〈舀〉。挖坑指在地面挖洞，从汤碗里取汤要用舀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6f69f0-eb3d-442c-b60c-16570c7f1216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26452, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挖坑", "is_correct": true, "explanation": "「挖坑」指用手挖出坑，与后面「手就脏了」的结果相合。"}, {"text": "踢球", "is_correct": false, "explanation": "搭配：「踢球」要用脚，不能说用手踢球。"}, {"text": "吹泡泡", "is_correct": false, "explanation": "语义：用手吹泡泡说不通，与「手就脏了」的句意不合。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：用手唱歌说不通，与句中的手脏情节不合。"}], "explanations": {"挖坑": "「挖坑」指用手挖出坑，与后面「手就脏了」的结果相合。", "踢球": "搭配：「踢球」要用脚，不能说用手踢球。", "吹泡泡": "语义：用手吹泡泡说不通，与「手就脏了」的句意不合。", "唱歌": "语义：用手唱歌说不通，与句中的手脏情节不合。"}, "sentence_index": 6, "correct_answer": "挖坑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在河面上挖坑，想养一群鱼。", "explanation": "这里应该用〈挖池塘〉。挖坑只能在地面上进行，河面上不能挖坑；养鱼要先挖池塘。"}, {"text": "他在半空中挖坑，想盖一个树屋。", "explanation": "这里应该用〈搭〉。挖坑要在地面上进行，半空中的树屋要用搭。"}, {"text": "她在书桌上挖坑，想种一株小草。", "explanation": "这里应该用〈摆〉。挖坑只能在地面上进行，书桌上放小草要用摆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6f69f0-eb3d-442c-b60c-16570c7f1216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在草地上挖坑着，想做一个小小的池塘。", "corrected_sentence": "他在草地上挖着坑，想做一个小小的池塘。", "error_description": "体标「着」位置错误：应紧接动词，说“挖着坑”，不能说“挖坑着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6f69f0-eb3d-442c-b60c-16570c7f1216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在花园里很挖坑，准备种花。", "corrected_sentence": "他在花园里挖坑，准备种花。", "error_description": "副词“很”不能直接修饰动词“挖坑”，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6f69f0-eb3d-442c-b60c-16570c7f1216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
