INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26460, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "树木就是长在地上的大树，比如杨树和柳树。", "primary_collocate": null, "pronunciation": "shù mù", "ipa": "ʂu˥˩ mu˥˩", "syllable_count": 2, "sentences": [{"text": "那条路两边都是高大的树木。", "target_word": "树木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村子后面有一片树木。", "target_word": "树木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多小鸟在这片树木里安家。", "target_word": "树木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天我们常在高大的树木下面乘凉。", "target_word": "树木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的树木有杨树，也有柳树。", "target_word": "树木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震以后，很多树木倒在地上。", "target_word": "树木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个周末都去给树木浇水。", "target_word": "树木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上的树木已经长了几十年。", "target_word": "树木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后，树木的叶子干净又绿。", "target_word": "树木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人正在砍倒路边的树木。", "target_word": "树木", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "长在地上的大树，如杨树、柳树", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7aa7a4f-1236-4805-b7d4-46fc3a94a1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26460, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "树木", "is_correct": true, "explanation": "正确：“高大的树木”指路两旁的大树，符合句意。"}, {"text": "蚂蚁", "is_correct": false, "explanation": "语义：“蚂蚁”很小，不能说“高大的蚂蚁”。"}, {"text": "纸张", "is_correct": false, "explanation": "搭配：“高大”不用于纸张，“高大的纸张”不成立。"}, {"text": "铅笔", "is_correct": false, "explanation": "搭配：“高大”形容人或大的东西，不说“高大的铅笔”。"}], "explanations": {"树木": "正确：“高大的树木”指路两旁的大树，符合句意。", "蚂蚁": "语义：“蚂蚁”很小，不能说“高大的蚂蚁”。", "纸张": "搭配：“高大”不用于纸张，“高大的纸张”不成立。", "铅笔": "搭配：“高大”形容人或大的东西，不说“高大的铅笔”。"}, "sentence_index": 0, "correct_answer": "树木"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家门口有一块树木。", "explanation": "这里应该用〈片〉。“块”不用于树木，指一片树木要说“一片”。"}, {"text": "我们把树木放进冰箱里保鲜。", "explanation": "这里应该用〈蔬菜〉。“树木”是长在地上的大树，放不进冰箱。"}, {"text": "他的书包里装满了树木。", "explanation": "这里应该用〈书本〉。“树木”是长在地上的大树，装不进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26460, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "树木", "is_correct": true, "explanation": "正确：“给树木浇水”是常见搭配，符合句意。"}, {"text": "墙壁", "is_correct": false, "explanation": "语义：“浇水”的对象应是植物，墙壁不需要浇水。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：“鞋子”不是植物，“给鞋子浇水”不成立。"}, {"text": "书本", "is_correct": false, "explanation": "搭配：“浇水”不搭配“书本”，句子不通。"}], "explanations": {"树木": "正确：“给树木浇水”是常见搭配，符合句意。", "墙壁": "语义：“浇水”的对象应是植物，墙壁不需要浇水。", "鞋子": "语义：“鞋子”不是植物，“给鞋子浇水”不成立。", "书本": "搭配：“浇水”不搭配“书本”，句子不通。"}, "sentence_index": 6, "correct_answer": "树木"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶去山上捡树木烧火。", "explanation": "这里应该用〈柴火〉。“树木”是整棵长在地上的树，捡来烧火的是柴火。"}, {"text": "秋天，树木纷纷落下来。", "explanation": "这里应该用〈树叶〉。落下来的是树叶，“树木”是整棵植物，不会这样落下。"}, {"text": "路边有一只树木。", "explanation": "这里应该用〈片〉。“只”用于动物等，不用于树木，指一片树木要用“片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26460, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里的树木们都很高大。", "corrected_sentence": "院子里的树木都很高大。", "error_description": "错误：“树木们”；正确：“树木”。“树木”本身是总称，不能再加“们”表示复数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26460, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "河边有一条树木。", "corrected_sentence": "河边有一片树木。", "error_description": "量词错误：“树木”是总称，成片的树木用“片”，不用“条”，应说“一片树木”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
