INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26462, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指我们住的地方，比如房子、村子或城市。", "primary_collocate": null, "pronunciation": "jiā yuán", "ipa": "tɕia˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我们的家园是一个安静的小村子。", "target_word": "家园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市是我们的家园。", "target_word": "家园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水过后，村民们终于回到了自己的家园。", "target_word": "家园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们花了三年才建好新家园。", "target_word": "家园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片家园里有房子、树和小河。", "target_word": "家园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新家园很漂亮，很多人想来住。", "target_word": "家园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在新家园里认识了很多朋友。", "target_word": "家园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们在新家园里种了很多花。", "target_word": "家园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震以后，人们一起重建家园。", "target_word": "家园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起打扫了自己的家园。", "target_word": "家园", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家園", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人们居住的具体地方，如房子、村子或城市", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7aa7a4f-1236-4805-b7d4-46fc3a94a1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26462, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家园", "is_correct": true, "explanation": "正确：指人们居住的具体地方，与“安静的小村子”相符。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是教学的地方，不是一个安静的小村子。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是生产的场所，与“安静的小村子”的描述不相符。"}, {"text": "王宫", "is_correct": false, "explanation": "语义：王宫是帝王居住的宫殿，不是一个安静的小村子。"}], "explanations": {"家园": "正确：指人们居住的具体地方，与“安静的小村子”相符。", "学校": "语义：学校是教学的地方，不是一个安静的小村子。", "工厂": "语义：工厂是生产的场所，与“安静的小村子”的描述不相符。", "王宫": "语义：王宫是帝王居住的宫殿，不是一个安静的小村子。"}, "sentence_index": 0, "correct_answer": "家园"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今天的家园很好，大家都很开心。", "explanation": "这里应用〈心情〉。“家园”指住的地方，不能说“家园好”，描述心情应说〈心情〉。"}, {"text": "他们花了三年才建好一场新家园。", "explanation": "量词：这里应用〈个〉，“场”用于比赛、事件等，不用于“家园”。"}, {"text": "他每天骑着家园去上班。", "explanation": "这里应该用〈自行车〉。“家园”是居住的地方，不能骑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26462, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家园", "is_correct": true, "explanation": "正确：指孩子们生活的具体地方，与“在新地方认识朋友”的语境相符。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字是抽象的符号，不能作为孩子们认识朋友的地方。"}, {"text": "机器", "is_correct": false, "explanation": "语义：机器不是人可以在里面认识朋友的地方。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱是记录音乐的符号，不是孩子们认识朋友的地方。"}], "explanations": {"家园": "正确：指孩子们生活的具体地方，与“在新地方认识朋友”的语境相符。", "数字": "语义：数字是抽象的符号，不能作为孩子们认识朋友的地方。", "机器": "语义：机器不是人可以在里面认识朋友的地方。", "乐谱": "语义：乐谱是记录音乐的符号，不是孩子们认识朋友的地方。"}, "sentence_index": 6, "correct_answer": "家园"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师认真批改了家园。", "explanation": "搭配：这里应用〈作业〉。“批改”的对象是作业，“家园”不能被批改。"}, {"text": "我们一起打扫了自己的家园，然后把家园吃掉了。", "explanation": "这里应该用〈午饭〉。“家园”是居住的地方，不能被吃掉。"}, {"text": "我们一起洗了自己的家园。", "explanation": "搭配：这里应用〈衣服〉。“洗”的对象应是衣物等，“家园”不能被洗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们终于找到了一条新家园。", "corrected_sentence": "他们终于找到了一个新家园。", "error_description": "量词错误：“家园”应配“个”，“条”用于细长的东西。正确形式：一个新家园。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些家园们都很美丽。", "corrected_sentence": "这些家园都很美丽。", "error_description": "词缀错误：“家园”指地方而非人，一般不加“们”表复数；“这些”已表明复数。正确形式：这些家园都很美丽。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
