INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26464, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "小时候就是一个人很小的时候。", "primary_collocate": null, "pronunciation": "xiǎo shí hou", "ipa": "ɕjɑʊ˨˩˦ ʂɻ̩˧˥ xoʊ", "syllable_count": 3, "sentences": [{"text": "我小时候很瘦。", "target_word": "小时候", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她小时候不会游泳。", "target_word": "小时候", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小时候我常常在河边玩。", "target_word": "小时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候他怕黑，晚上要开着灯。", "target_word": "小时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说他小时候没有电视。", "target_word": "小时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我小时候最大的愿望是有一只小狗。", "target_word": "小时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候的夏天，我们总是吃西瓜。", "target_word": "小时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候跟外婆住在一起。", "target_word": "小时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈小时候走路去上学。", "target_word": "小时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你小时候也喜欢下雨天吗？", "target_word": "小时候", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "小時候", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个人年纪很小的时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b265e353-0a56-4f5b-a790-095a42c113c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26464, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小时候", "is_correct": true, "explanation": "正确。“小时候”指一个人年纪很小的时候，与“很瘦”描述的童年身形相符。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来的一天，不能说明一个人过去年幼时的身形。"}, {"text": "刚才", "is_correct": false, "explanation": "搭配：“刚才”指片刻之前，不能与“很瘦”这种长期的身形状态搭配。"}, {"text": "半夜", "is_correct": false, "explanation": "语义：“半夜”指一个具体的夜间时段，不能用来说明一个人长期的身形。"}], "explanations": {"小时候": "正确。“小时候”指一个人年纪很小的时候，与“很瘦”描述的童年身形相符。", "明天": "语义：“明天”指将来的一天，不能说明一个人过去年幼时的身形。", "刚才": "搭配：“刚才”指片刻之前，不能与“很瘦”这种长期的身形状态搭配。", "半夜": "语义：“半夜”指一个具体的夜间时段，不能用来说明一个人长期的身形。"}, "sentence_index": 0, "correct_answer": "小时候"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他小时候在北京读研究生。", "explanation": "这里应该用〈以前〉。“小时候”只指童年，不能用来说成年后读研究生的经历；“以前”可泛指任何过去的时期。"}, {"text": "你等我小时候，我就回来。", "explanation": "这里应该用〈一个小时〉。“小时候”指童年，不是时间单位“小时”；应说“你等我一个小时，我就回来”。"}, {"text": "我小时候明天要考试。", "explanation": "这里应该用〈将来〉。“小时候”只指过去的童年，不能与“明天”这样的将来时间搭配；〈将来〉才泛指将来的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26464, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小时候", "is_correct": true, "explanation": "正确。“小时候”指童年，与“夏天”“总是吃西瓜”的过去习惯相符。"}, {"text": "上周", "is_correct": false, "explanation": "语义：“上周”指一周前的一段时间，与“夏天”这一季节不相符。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：“冬天”与句中的“夏天”冲突，“冬天的夏天”说不通，不能填入此处。"}, {"text": "昨天", "is_correct": false, "explanation": "搭配：“昨天”指具体的一天，不能与“夏天”这样的季节搭配。"}], "explanations": {"小时候": "正确。“小时候”指童年，与“夏天”“总是吃西瓜”的过去习惯相符。", "上周": "语义：“上周”指一周前的一段时间，与“夏天”这一季节不相符。", "冬天": "语义：“冬天”与句中的“夏天”冲突，“冬天的夏天”说不通，不能填入此处。", "昨天": "搭配：“昨天”指具体的一天，不能与“夏天”这样的季节搭配。"}, "sentence_index": 6, "correct_answer": "小时候"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小时候是我的弟弟。", "explanation": "这里应该用〈孩子〉。〈小时候〉表示童年这段时间，不能指人；〈孩子〉才是指人的名词。"}, {"text": "爸爸把小时候装进了箱子。", "explanation": "这里应该用〈玩具〉之类的物品。〈小时候〉是时间，不能被“装”进箱子，应说“爸爸把玩具装进了箱子”。"}, {"text": "吃完饭以后，小时候就出门散步了。", "explanation": "这里应该用〈接着〉。〈小时候〉指童年，不能指吃完饭之后的当下时刻；〈接着〉才表示紧接着的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26464, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候的喜欢画画。", "corrected_sentence": "我小时候喜欢画画。", "error_description": "“小时候”是时间状语，后面不能直接加“的”再接动词，“的”应去掉；正确说法是“我小时候喜欢画画”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26464, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我小时候了常常去河边。", "corrected_sentence": "我小时候常常去河边。", "error_description": "“小时候”是时间词，后面不能直接加“了”，“了”应去掉；正确说法是“我小时候常常去河边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26466, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出去", "is_correct": true, "explanation": "正确：“出去”表示从里面到外面，与“进来”的方向相反。"}, {"text": "坐下", "is_correct": false, "explanation": "不是反义：“坐下”是动作，不表示方向相反。"}, {"text": "写字", "is_correct": false, "explanation": "不是反义：“写字”与进出的方向无关。"}, {"text": "吃饭", "is_correct": false, "explanation": "不是反义：“吃饭”与进出的方向无关。"}], "correct_answer": "出去", "explanations": {"出去": "正确：“出去”表示从里面到外面，与“进来”的方向相反。", "坐下": "不是反义：“坐下”是动作，不表示方向相反。", "写字": "不是反义：“写字”与进出的方向无关。", "吃饭": "不是反义：“吃饭”与进出的方向无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26466, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出去", "is_correct": true, "explanation": "正确：“出去”表示从里到外，与“进来”的方向相反。"}, {"text": "笑", "is_correct": false, "explanation": "不是反义：“笑”与移动的方向无关。"}, {"text": "哭", "is_correct": false, "explanation": "不是反义：“哭”与移动的方向无关。"}, {"text": "说话", "is_correct": false, "explanation": "不是反义：“说话”与移动的方向无关。"}], "correct_answer": "出去", "explanations": {"出去": "正确：“出去”表示从里到外，与“进来”的方向相反。", "笑": "不是反义：“笑”与移动的方向无关。", "哭": "不是反义：“哭”与移动的方向无关。", "说话": "不是反义：“说话”与移动的方向无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26466, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从外面走到里面。", "primary_collocate": null, "pronunciation": "jìn lái", "ipa": "tɕin˥˩ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "请进来坐吧。", "target_word": "进来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门开着，你进来吧。", "target_word": "进来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面太冷，快进来。", "target_word": "进来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他敲门，我说：“请进来。”", "target_word": "进来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大了，大家快进来躲雨。", "target_word": "进来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“别站在门口，进来吧。”", "target_word": "进来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只小鸟从窗外进来了。", "target_word": "进来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么进来的？门不是锁着吗？", "target_word": "进来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一进来就问大家吃饭了没有。", "target_word": "进来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面有人找你，让他进来吗？", "target_word": "进来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进来了", "label": "完成体"}, {"form": "进来过", "label": "经历体"}, {"form": "进不来", "label": "可能补语否定式"}], "register": "通用", "sense_fingerprint": "从外面向说话人所在的里面移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ac6ae9e-65f2-4cd8-afbe-fbecadfb9dc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "进来", "is_correct": true, "explanation": "正确：“进来”表示请人从外面进到屋里，之后再坐下。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：请人进来坐，不会先让人洗澡，语境不合。"}, {"text": "跑步", "is_correct": false, "explanation": "搭配：“跑步”与“请……坐吧”的语境不搭，请人坐不用跑步。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与请人进屋坐下的语境不合，说不通。"}], "explanations": {"进来": "正确：“进来”表示请人从外面进到屋里，之后再坐下。", "洗澡": "语义：请人进来坐，不会先让人洗澡，语境不合。", "跑步": "搭配：“跑步”与“请……坐吧”的语境不搭，请人坐不用跑步。", "唱歌": "语义：“唱歌”与请人进屋坐下的语境不合，说不通。"}, "sentence_index": 0, "correct_answer": "进来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我站在院子里，看见他从窗户爬进来了。", "explanation": "这里应该用〈进去〉。说话人在院子里，他进的是屋子，不是说话人所在的地方；“进来”表示朝说话人所在的地方移动。"}, {"text": "我站在院子里，看见他从楼上走进来了。", "explanation": "这里应该用〈下来〉。他从楼上往下走，应说“下来”；“进来”指朝说话人所在的地方移动，与“从楼上往下”的方向不合。"}, {"text": "他想进来散步，你要一起去吗？", "explanation": "这里应该用〈出去〉。散步一般是到外面去，“出去”表示从里往外，“进来”方向不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进来", "is_correct": true, "explanation": "正确：小鸟从窗外飞进屋里，用“进来”表示向里移动。"}, {"text": "站起来", "is_correct": false, "explanation": "语义：小鸟不会“从窗外站起来”，“站起来”与“从窗外”的移动不合。"}, {"text": "跳舞", "is_correct": false, "explanation": "搭配：“从窗外”后面不接“跳舞”，跳舞没有移动的方向。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”表示停留在一处，不表示从窗外移动。"}], "explanations": {"进来": "正确：小鸟从窗外飞进屋里，用“进来”表示向里移动。", "站起来": "语义：小鸟不会“从窗外站起来”，“站起来”与“从窗外”的移动不合。", "跳舞": "搭配：“从窗外”后面不接“跳舞”，跳舞没有移动的方向。", "睡觉": "语义：“睡觉”表示停留在一处，不表示从窗外移动。"}, "sentence_index": 6, "correct_answer": "进来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸在国外工作，每年春节才进来。", "explanation": "这里应该用〈回来〉。说人从外地回到家要用“回来”，“进来”指向说话人所在的地方移动，这里不对。"}, {"text": "我要进来了，明天见。", "explanation": "这里应该用〈回去〉。说话人要离开时用“回去”，“进来”表示走向说话人所在的地方，与要离开相反。"}, {"text": "他一步一步走进来，爬到了屋顶。", "explanation": "这里应该用〈上去〉。要表示向高处移动，应说“上去”；“进来”指朝说话人所在的地方移动，与“爬到屋顶”的方向不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一进来屋就脱了外套。", "corrected_sentence": "他一进屋来就脱了外套。", "error_description": "错误：“进来”和宾语“屋”的位置错误；正确：“进屋来”，宾语要放在“进”和“来”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只猫从门口被进来了。", "corrected_sentence": "一只猫从门口进来了。", "error_description": "错误：“被”用在不及物的趋向动词“进来”前面，“进来”不能带受事，不能用“被”；正确：“进来了”，直接用动词加趋向补语和“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
