INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26470, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很多人住在一起的地方，有房子和路。", "primary_collocate": null, "pronunciation": "xiǎo qū", "ipa": "ɕjɑʊ˨˩˦ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "这个小区不大，但是住了很多人。", "target_word": "小区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区里有路，也有一个小公园。", "target_word": "小区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天走过小区的小路去上班。", "target_word": "小区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区的房子都是新的。", "target_word": "小区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸在小区里遇到了老同事。", "target_word": "小区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区里的路很窄，车开得慢。", "target_word": "小区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们搬进了离学校近的小区。", "target_word": "小区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区里住着三百多户人家。", "target_word": "小区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚饭后，邻居们在小区里散步。", "target_word": "小区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友在对面的小区租了房子。", "target_word": "小区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很多人住在一起、有房子和路的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b265e353-0a56-4f5b-a790-095a42c113c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26470, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小区", "is_correct": true, "explanation": "小区 xiǎoqū：很多人住在一起、有房子和路的地方，即本词的正确读音和意思。"}, {"text": "校区", "is_correct": false, "explanation": "xiào（第四声）与 xiǎo（第三声）声调不同，意思是学校的校园范围。"}, {"text": "小曲", "is_correct": false, "explanation": "qǔ（第三声）与 qū（第一声）声调不同，意思是小段的曲子。"}, {"text": "小渠", "is_correct": false, "explanation": "qú（第二声）与 qū（第一声）声调不同，意思是小水渠。"}], "explanations": {"小区": "小区 xiǎoqū：很多人住在一起、有房子和路的地方，即本词的正确读音和意思。", "校区": "xiào（第四声）与 xiǎo（第三声）声调不同，意思是学校的校园范围。", "小曲": "qǔ（第三声）与 qū（第一声）声调不同，意思是小段的曲子。", "小渠": "qú（第二声）与 qū（第一声）声调不同，意思是小水渠。"}, "sentence_index": null, "correct_answer": "小区"}, "level_3": {"options": [{"text": "小区", "is_correct": true, "explanation": "小区：很多人住在一起的地方，不大但住了很多人，符合语境。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是住人的地方，“住了很多人”说不通。"}, {"text": "饭盒", "is_correct": false, "explanation": "语义：饭盒是盛饭的容器，不能住很多人。"}, {"text": "书包", "is_correct": false, "explanation": "配价：“住了很多人”要求主语是能住人的地方，书包不能住人。"}], "explanations": {"小区": "小区：很多人住在一起的地方，不大但住了很多人，符合语境。", "手机": "语义：手机不是住人的地方，“住了很多人”说不通。", "饭盒": "语义：饭盒是盛饭的容器，不能住很多人。", "书包": "配价：“住了很多人”要求主语是能住人的地方，书包不能住人。"}, "sentence_index": 0, "correct_answer": "小区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小区每天早上都有很多学生上课。", "explanation": "这里应该用〈学校〉。有老师教、学生上课的地方要说学校，小区是人居住的地方。"}, {"text": "这个小区一共有十层，每层都有很多公司。", "explanation": "这里应该用〈办公楼〉。分层办公的建筑要说办公楼，小区不是办公场所。"}, {"text": "这个小区有很多游客在拍照。", "explanation": "这里应该用〈景点〉。供游客游览拍照的地方要说景点，小区是居住区。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小区", "is_correct": true, "explanation": "小区：很多人住在一起、有房子和路的地方，他们搬进了离学校近的这里，符合语境。"}, {"text": "书架", "is_correct": false, "explanation": "搭配：“搬进”后面接住所，书架不是住所。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是电器，不能搬进去住人。"}, {"text": "花盆", "is_correct": false, "explanation": "语义：花盆是种花的容器，不是人搬进去住的地方。"}], "explanations": {"小区": "小区：很多人住在一起、有房子和路的地方，他们搬进了离学校近的这里，符合语境。", "书架": "搭配：“搬进”后面接住所，书架不是住所。", "冰箱": "语义：冰箱是电器，不能搬进去住人。", "花盆": "语义：花盆是种花的容器，不是人搬进去住的地方。"}, "sentence_index": 6, "correct_answer": "小区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小区的病房都住满了病人，大家都在等着看病。", "explanation": "这里应该用〈医院〉。病房和看病的地方要说医院，小区不设病房。"}, {"text": "这个小区的停机坪上停着几架飞机。", "explanation": "这里应该用〈机场〉。停放飞机的地方要说机场，小区是居住区。"}, {"text": "这个小区养了很多牛和羊。", "explanation": "这里应该用〈农场〉。养牛羊的地方要说农场，小区是居住区。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只小区附近有一个很大的公园。", "corrected_sentence": "这个小区附近有一个很大的公园。", "error_description": "量词错误：“小区”应该用“个”，不用“只”。改为：这个小区。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们选择了一个离公司近小区。", "corrected_sentence": "他们选择了一个离公司近的小区。", "error_description": "定语错误：修饰“小区”的“离公司近”后面要加“的”。改为：离公司近的小区。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
