INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26474, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "坏东西来伤害人或东西。", "primary_collocate": null, "pronunciation": "qīn xí", "ipa": "tɕʰin˥ ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "寒冷的空气侵袭着山村。", "target_word": "侵袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，流感常常侵袭小学生。", "target_word": "侵袭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雨侵袭了海边的小镇。", "target_word": "侵袭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一场大雾侵袭了这座城市，飞机都不能起飞。", "target_word": "侵袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暴风雪侵袭了整个北方。", "target_word": "侵袭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病菌侵袭人的身体，人就会生病。", "target_word": "侵袭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天台风常常侵袭这个海岛。", "target_word": "侵袭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了不让寒风侵袭，他们把窗户关好了。", "target_word": "侵袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "霜冻侵袭了田里的菜，菜都冻坏了。", "target_word": "侵袭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨晚寒潮侵袭本地，早上特别冷。", "target_word": "侵袭", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "侵袭了", "label": "体标"}, {"form": "侵袭着", "label": "体标"}, {"form": "侵袭过", "label": "体标"}, {"form": "侵襲", "label": "繁体"}], "register": "书面", "sense_fingerprint": "恶劣天气或病菌等坏东西来伤害人或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a99ff1f-84fe-4580-9f45-814e6a0bd5f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26474, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "侵袭", "is_correct": true, "explanation": "侵袭指坏东西突然来伤害，“寒冷的空气侵袭着山村”说寒气正在伤害山村，句意通顺。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：照顾需要照料的意愿，寒冷的空气不会照顾山村，句意说不通。"}, {"text": "祝福", "is_correct": false, "explanation": "语义：祝福是美好的心愿，寒冷的空气不会祝福山村，这与“寒冷”的描写矛盾。"}, {"text": "欢迎", "is_correct": false, "explanation": "配价：“欢迎”的主语须是有意愿的人，“寒冷的空气”不能欢迎山村。"}], "explanations": {"侵袭": "侵袭指坏东西突然来伤害，“寒冷的空气侵袭着山村”说寒气正在伤害山村，句意通顺。", "照顾": "语义：照顾需要照料的意愿，寒冷的空气不会照顾山村，句意说不通。", "祝福": "语义：祝福是美好的心愿，寒冷的空气不会祝福山村，这与“寒冷”的描写矛盾。", "欢迎": "配价：“欢迎”的主语须是有意愿的人，“寒冷的空气”不能欢迎山村。"}, "sentence_index": 0, "correct_answer": "侵袭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们的笑声侵袭了整个屋子，大家都很开心。", "explanation": "这里应该用〈充满〉。侵袭指坏东西来伤害人或东西，笑声不是坏东西，充满整个屋子要说“充满”，不能说“侵袭”。"}, {"text": "他侵袭了对方的弱点，对方很难防守。", "explanation": "这里应该用〈攻击〉。侵袭多指坏东西突然来袭造成损害，对准对方的弱点进攻要说“攻击”。"}, {"text": "老师侵袭了我们的班级，大家都很紧张。", "explanation": "用法不对。侵袭的主语须是灾害、病菌等坏东西，老师不是坏东西，不能“侵袭”班级，应该说“管理”或“走进”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26474, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "侵袭", "is_correct": true, "explanation": "侵袭指坏天气突然来袭造成破坏，“夏天台风常常侵袭这个海岛”说台风常来造成危害，句意通顺。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”的主语须是有意愿的人，台风不能去参观海岛。"}, {"text": "喜爱", "is_correct": false, "explanation": "语义：喜爱是人的情感，台风没有情感，“台风常常喜爱这个海岛”说不通。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：赞美是对人或事物的称赞，台风不会赞美海岛，句子与台风带来破坏的语境矛盾。"}], "explanations": {"侵袭": "侵袭指坏天气突然来袭造成破坏，“夏天台风常常侵袭这个海岛”说台风常来造成危害，句意通顺。", "参观": "配价：“参观”的主语须是有意愿的人，台风不能去参观海岛。", "喜爱": "语义：喜爱是人的情感，台风没有情感，“台风常常喜爱这个海岛”说不通。", "赞美": "语义：赞美是对人或事物的称赞，台风不会赞美海岛，句子与台风带来破坏的语境矛盾。"}, "sentence_index": 6, "correct_answer": "侵袭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他侵袭了朋友的信任，朋友很失望。", "explanation": "这里应该用〈辜负〉。侵袭指坏东西来伤害人或东西，对不起别人的信任要说“辜负”。"}, {"text": "同学们侵袭他的口音，他不太高兴。", "explanation": "这里应该用〈嘲笑〉。侵袭不用于言语上的取笑，拿别人的口音开玩笑要说“嘲笑”。"}, {"text": "他一口气侵袭了三个包子，很快就吃完了。", "explanation": "这里应该用〈吃〉。侵袭指坏东西来伤害人或东西，吃东西要说“吃”，不能说“侵袭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26474, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天夜里，寒潮侵袭在北方的几个省份。", "corrected_sentence": "昨天夜里，寒潮侵袭了北方的几个省份。", "error_description": "补语错误：“侵袭”后应直接带宾语，正确说法是“侵袭了北方的几个省份”。说成“侵袭在”是错的，“在”不能接在“侵袭”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26474, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "入冬以后，暴雪侵袭得这个小镇。", "corrected_sentence": "入冬以后，暴雪侵袭了这个小镇。", "error_description": "助词错误：“侵袭”后应接动态助词“了”表示动作完成，不能用“得”。说成“侵袭得这个小镇”是错的，正确说法是“侵袭了这个小镇”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
