INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26476, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "风和沙土一起吹来，会让人睁不开眼睛。", "primary_collocate": null, "pronunciation": "fēng shā", "ipa": "fɤŋ˥ ʂa˥", "syllable_count": 2, "sentences": [{"text": "风沙太大，我睁不开眼睛。", "target_word": "风沙", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一阵风沙吹过来，孩子们赶紧闭上了眼。", "target_word": "风沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用围巾捂住脸，不让风沙进眼睛。", "target_word": "风沙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风沙一来，天一下子就黄了。", "target_word": "风沙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "戴上眼镜，风沙就吹不进眼睛了。", "target_word": "风沙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大风带着风沙，打在脸上很疼。", "target_word": "风沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风沙中，我们只能慢慢往前走。", "target_word": "风沙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑车的人都低着头，躲避迎面的风沙。", "target_word": "风沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户没关，风沙吹进了屋里。", "target_word": "风沙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风沙迷了她的眼，她只好停下来。", "target_word": "风沙", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一阵风沙", "label": "量词"}, {"form": "一场风沙", "label": "量词"}, {"form": "風沙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "风和沙土一起吹来，迷眼扑面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a99ff1f-84fe-4580-9f45-814e6a0bd5f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26476, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风沙", "is_correct": true, "explanation": "风沙是风和沙土一起吹来的东西，“风沙太大，我睁不开眼睛”说明风沙让人看不清，句意通顺。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包的大小与睁不开眼睛没有关系，“书包太大，我睁不开眼睛”说不通。"}, {"text": "嗓门", "is_correct": false, "explanation": "语义：嗓门大是声音响，不会让人睁不开眼睛，“嗓门太大，我睁不开眼睛”说不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“太大”修饰价格，不能导致睁不开眼睛，“价格”与后面的因果关系不搭。"}], "explanations": {"风沙": "风沙是风和沙土一起吹来的东西，“风沙太大，我睁不开眼睛”说明风沙让人看不清，句意通顺。", "书包": "语义：书包的大小与睁不开眼睛没有关系，“书包太大，我睁不开眼睛”说不通。", "嗓门": "语义：嗓门大是声音响，不会让人睁不开眼睛，“嗓门太大，我睁不开眼睛”说不通。", "价格": "搭配：“太大”修饰价格，不能导致睁不开眼睛，“价格”与后面的因果关系不搭。"}, "sentence_index": 0, "correct_answer": "风沙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一朵风沙吹进了眼睛，我睁不开。", "explanation": "这里量词用错。〈朵〉用于花、云等东西，风沙应该用〈阵〉或〈场〉。"}, {"text": "厨房里冒出了浓浓的风沙。", "explanation": "这里应该用〈烟雾〉。烟雾从火中冒出来，风沙是风吹起的沙土，不会从厨房里冒出来。"}, {"text": "风沙当头，地都烤裂了。", "explanation": "这里应该用〈烈日〉。烈日的热力能把地面烤裂，风沙只带沙土，不能烤裂地面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26476, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风沙", "is_correct": true, "explanation": "风沙是风和沙土一起吹来的东西，“风沙中，我们只能慢慢往前走”说明在恶劣天气里行走困难，句意通顺。"}, {"text": "书本", "is_correct": false, "explanation": "语义：书本是纸张装订成的物品，不是可以走进去的场所，“书本中，我们只能慢慢往前走”说不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "配价：“中”前面的成分要能作为人行走的场所，钢琴不能作为可以行走的地方。"}, {"text": "海报", "is_correct": false, "explanation": "语义：海报是贴在墙上的纸，人不能在里面行走，“海报中，我们只能慢慢往前走”不符合常识。"}], "explanations": {"风沙": "风沙是风和沙土一起吹来的东西，“风沙中，我们只能慢慢往前走”说明在恶劣天气里行走困难，句意通顺。", "书本": "语义：书本是纸张装订成的物品，不是可以走进去的场所，“书本中，我们只能慢慢往前走”说不通。", "钢琴": "配价：“中”前面的成分要能作为人行走的场所，钢琴不能作为可以行走的地方。", "海报": "语义：海报是贴在墙上的纸，人不能在里面行走，“海报中，我们只能慢慢往前走”不符合常识。"}, "sentence_index": 6, "correct_answer": "风沙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一根风沙从沙漠那边刮了过来。", "explanation": "这里量词用错。〈根〉用于细长的东西，风沙应该用〈阵〉或〈股〉。"}, {"text": "风沙拂面，她觉得很舒服。", "explanation": "这里应该用〈清风〉。清风是舒适的凉风，风沙带着沙土，会让人睁不开眼，不会让人觉得舒服。"}, {"text": "风沙洒在草地上，草地很温暖。", "explanation": "这里应该用〈阳光〉。阳光能带来温暖，风沙只带沙土和寒意，不能让草地变得温暖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26476, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "傍晚，一座风沙吹过来，街上的人都躲进了屋里。", "corrected_sentence": "傍晚，一阵风沙吹过来，街上的人都躲进了屋里。", "error_description": "量词错误：“风沙”应说“一阵风沙”，说成“一座风沙”是错的。“座”用于山、楼等大型固定的东西，不能计量风沙，正确的量词是“阵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26476, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "路上起了一张风沙，他眯着眼睛慢慢走。", "corrected_sentence": "路上起了一阵风沙，他眯着眼睛慢慢走。", "error_description": "量词错误：“风沙”应说“一阵风沙”，说成“一张风沙”是错的。“张”用于纸张、桌子等扁平的东西，不能计量风沙，正确的量词是“阵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
