INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26478, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26478, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "总是遇到不好的事情。", "primary_collocate": null, "pronunciation": "bǎo shòu", "ipa": "pɑʊ˨˩˦ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他从小饱受病痛，身体一直不好。", "target_word": "饱受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市每年夏天都饱受大雨之苦。", "target_word": "饱受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗没有家，每天饱受饥饿和寒冷。", "target_word": "饱受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她工作很忙，长期饱受头疼的困扰。", "target_word": "饱受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区的孩子饱受贫穷之苦。", "target_word": "饱受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家小店饱受客人的批评。", "target_word": "饱受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手曾经饱受网络上的恶意评论。", "target_word": "饱受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们住的地方饱受噪音困扰，晚上睡不好。", "target_word": "饱受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些树饱受虫子的伤害，叶子都黄了。", "target_word": "饱受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "许多老人冬天饱受寒冷的折磨。", "target_word": "饱受", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "飽受", "label": "繁体"}, {"form": "饱受着", "label": "体标"}, {"form": "饱受过", "label": "体标"}], "register": "书面", "sense_fingerprint": "总是碰到坏事或苦处，受了很多苦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c74c4ae1-9515-4459-b540-8770b8d0940f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26478, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饱受", "is_correct": true, "explanation": "饱受表示长时间遭受痛苦，与“病痛”的负面含义相合。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”指愉快地享用，不能与病痛搭配。"}, {"text": "迎接", "is_correct": false, "explanation": "语义：“迎接”表示欢迎到来的人或事，与“病痛”的负面含义不合。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的宾语须是值得赏玩的事物，不能说欣赏病痛。"}], "explanations": {"饱受": "饱受表示长时间遭受痛苦，与“病痛”的负面含义相合。", "享受": "语义：“享受”指愉快地享用，不能与病痛搭配。", "迎接": "语义：“迎接”表示欢迎到来的人或事，与“病痛”的负面含义不合。", "欣赏": "搭配：“欣赏”的宾语须是值得赏玩的事物，不能说欣赏病痛。"}, "sentence_index": 0, "correct_answer": "饱受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天饱受周末的休息时光。", "explanation": "这里应该用〈享受〉。饱受只用于遭受痛苦，不用于愉快的休息；享受周末的休息时光才对。"}, {"text": "这所学校饱受了两位新老师。", "explanation": "这里应该用〈迎来〉。饱受不表示人员增加；学校迎来两位新老师才对。"}, {"text": "这个月我的工资饱受了三百元。", "explanation": "这里应该用〈增加〉。饱受表示遭受痛苦，不表示数量上升；工资增加三百元才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26478, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饱受", "is_correct": true, "explanation": "饱受表示长时间遭受，与“恶意评论”的负面含义相合。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示乐于接受，与恶意评论不相容。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”的对象是善意或帮助，不能感谢恶意评论。"}, {"text": "观赏", "is_correct": false, "explanation": "搭配：“观赏”的对象是景物，不能说观赏恶意评论。"}], "explanations": {"饱受": "饱受表示长时间遭受，与“恶意评论”的负面含义相合。", "欢迎": "语义：“欢迎”表示乐于接受，与恶意评论不相容。", "感谢": "语义：“感谢”的对象是善意或帮助，不能感谢恶意评论。", "观赏": "搭配：“观赏”的对象是景物，不能说观赏恶意评论。"}, "sentence_index": 6, "correct_answer": "饱受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个班饱受了一批奖学金。", "explanation": "这里应该用〈获得〉。饱受用于遭受不好的事，奖学金是好事；这个班获得一批奖学金才对。"}, {"text": "这个国家的人民饱受言论自由。", "explanation": "这里应该用〈享有〉。饱受表示遭受不好的事情，言论自由是应有的权利，不是痛苦或困难；这个国家的人民享有言论自由才对。"}, {"text": "我饱受了一份礼物。", "explanation": "这里应该用〈收到〉。饱受表示遭受，不用于接受礼物；我收到一份礼物才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小镇的老人饱受寒冷苦。", "corrected_sentence": "这个小镇的老人饱受寒冷之苦。", "error_description": "错误：“寒冷苦”不成话，“苦”前面漏了“之”。应说“饱受寒冷之苦”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "许多老人冬天被饱受寒冷之苦。", "corrected_sentence": "许多老人冬天饱受寒冷之苦。", "error_description": "错误：“饱受”本身已表示遭受，前面不能再加“被”。应说“许多老人冬天饱受寒冷之苦。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
