INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26480, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西的最外面靠近边界的地方。", "primary_collocate": null, "pronunciation": "biān yuán", "ipa": "pjɛn˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "桌子的边缘有点尖，小心碰到。", "target_word": "边缘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书页的边缘已经黄了。", "target_word": "边缘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "池塘的边缘长满了水草。", "target_word": "边缘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走到广场的边缘，再往前就是马路。", "target_word": "边缘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "盘子的边缘有一圈红色的花。", "target_word": "边缘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市的边缘住着不少农民。", "target_word": "边缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把图片的边缘剪整齐。", "target_word": "边缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水从屋顶的边缘一滴一滴落下来。", "target_word": "边缘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猫站在窗台的边缘，快要掉下去了。", "target_word": "边缘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湖的边缘结了一层薄冰。", "target_word": "边缘", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "邊緣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西最外面靠近边界的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a99ff1f-84fe-4580-9f45-814e6a0bd5f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26480, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "边缘", "is_correct": true, "explanation": "“边缘”指物体最外面靠近界限的部分，与“有点尖，小心碰到”的语境相合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能用“尖”来形容，搭配不通。"}, {"text": "作者", "is_correct": false, "explanation": "语义：“作者”指创作者，不是桌子的组成部分，与“有点尖，小心碰到”的语境矛盾。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不能被“碰到”，与“小心碰到”所指的物理接触相冲突。"}], "explanations": {"边缘": "“边缘”指物体最外面靠近界限的部分，与“有点尖，小心碰到”的语境相合。", "颜色": "搭配：“颜色”不能用“尖”来形容，搭配不通。", "作者": "语义：“作者”指创作者，不是桌子的组成部分，与“有点尖，小心碰到”的语境矛盾。", "声音": "语义：“声音”不能被“碰到”，与“小心碰到”所指的物理接触相冲突。"}, "sentence_index": 0, "correct_answer": "边缘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盆花摆在窗台的边缘正中央，阳光最充足。", "explanation": "此处应该用〈中央〉。“边缘”指最外侧的部分，与“正中央”的位置矛盾。"}, {"text": "这条街的边缘是最中心、最热闹的地方。", "explanation": "此处应该用〈中心〉。“边缘”指靠外侧的部分，不能指最中心的地方。"}, {"text": "这座城市的边缘是政府大楼所在的核心区域。", "explanation": "此处应该用〈核心〉。“边缘”指最外侧的部分，与“核心区域”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26480, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "边缘", "is_correct": true, "explanation": "“边缘”指物体靠近界限的部分，与“请把……剪整齐”的操作对象相合，指图片的外缘。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不属于图片，也不能被剪，“图片的天气剪整齐”说不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：图片没有声音，声音也不能用剪刀剪，句意说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不能用“剪”来修饰，搭配不通。"}], "explanations": {"边缘": "“边缘”指物体靠近界限的部分，与“请把……剪整齐”的操作对象相合，指图片的外缘。", "天气": "语义：“天气”不属于图片，也不能被剪，“图片的天气剪整齐”说不通。", "声音": "语义：图片没有声音，声音也不能用剪刀剪，句意说不通。", "年龄": "搭配：“年龄”不能用“剪”来修饰，搭配不通。"}, "sentence_index": 6, "correct_answer": "边缘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把花瓶放在桌子的边缘，花瓶正好在桌子的正中间。", "explanation": "此处应该用〈中间〉。“边缘”指最外侧的部分，与“正中间”的位置矛盾。"}, {"text": "这部电影的边缘是最精彩的高潮部分。", "explanation": "此处应该用〈高潮〉。“边缘”指最外侧的部分，不能指电影最精彩的高潮。"}, {"text": "这家商店的边缘正中央摆着收银台，是人流最密集的地方。", "explanation": "此处应该用〈中心〉。“边缘”指最外侧的部分，与“正中央”“人流最密集”的位置矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "碗的边缘们都破了。", "corrected_sentence": "碗的边缘都破了。", "error_description": "“们”多余：“们”不能加在表示事物部位的“边缘”后面，应说“碗的边缘都破了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "杯子的边缘的有一道裂纹。", "corrected_sentence": "杯子的边缘有一道裂纹。", "error_description": "“的”多余：“边缘”后面不能再加“的”，应说“杯子的边缘有一道裂纹”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
