INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26484, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "意思是安静地，没有声音地。", "primary_collocate": null, "pronunciation": "qiǎo rán", "ipa": "tɕʰiɑʊ˨˩ ɻan˧˥", "syllable_count": 2, "sentences": [{"text": "小猫悄然跳上了桌子。", "target_word": "悄然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他怕被发现，悄然躲在门后。", "target_word": "悄然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜深了，妈妈悄然走进孩子的房间。", "target_word": "悄然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们悄然坐下，没有一点声音。", "target_word": "悄然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她悄然推开窗，看了看外面。", "target_word": "悄然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他悄然离开会场，没有人听见。", "target_word": "悄然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家悄然等着，谁也没有说话。", "target_word": "悄然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小船悄然靠了岸。", "target_word": "悄然", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妹妹睡着了，爸爸悄然关了灯。", "target_word": "悄然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他悄然站在一旁，听着大家讲话。", "target_word": "悄然", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "悄然", "label": "基本形式"}, {"form": "悄然无声", "label": "复合"}], "register": "书面", "sense_fingerprint": "安静地、不发出声音地做动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a557264c-4aa5-46b9-b35c-1063d06c8088') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26484, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "悄然", "is_correct": true, "explanation": "正确：“悄然”表示安静、不发出声音地做动作，与“跳上了桌子”相合。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，与“跳上了”的完成态矛盾。"}, {"text": "将要", "is_correct": false, "explanation": "体貌：“将要”表示尚未发生，与“跳上了”的完成态矛盾。"}, {"text": "大声", "is_correct": false, "explanation": "语义：“大声”说明动作有响声，与小猫轻悄跳上桌子的情状不合。"}], "explanations": {"悄然": "正确：“悄然”表示安静、不发出声音地做动作，与“跳上了桌子”相合。", "正在": "体貌：“正在”表示动作进行中，与“跳上了”的完成态矛盾。", "将要": "体貌：“将要”表示尚未发生，与“跳上了”的完成态矛盾。", "大声": "语义：“大声”说明动作有响声，与小猫轻悄跳上桌子的情状不合。"}, "sentence_index": 0, "correct_answer": "悄然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他悄然大笑起来，把旁边的人都吓了一跳。", "explanation": "这里应该用〈放声〉。悄然表示无声无息，不能修饰“大笑”这种响亮的动作。"}, {"text": "她悄然唱起歌来，整栋楼都听见了。", "explanation": "这里应该用〈大声〉。悄然表示没有声音，与“整栋楼都听见了”矛盾。"}, {"text": "她悄然推开门，门轴吱呀一响，把全屋的人都惊醒了。", "explanation": "这里应该用〈猛地〉。悄然强调无声无息、不惊动别人；门轴吱呀作响并惊醒全屋的人，应说猛地推开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26484, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "悄然", "is_correct": true, "explanation": "正确：“悄然”表示安静、不引人注意，与“谁也没有说话”相合。"}, {"text": "齐声", "is_correct": false, "explanation": "搭配：“齐声”用于一起发出声音，不能用来修饰“等着”这种安静的状态。"}, {"text": "嘈杂地", "is_correct": false, "explanation": "语义：“嘈杂”指声音杂乱，与“谁也没有说话”矛盾。"}, {"text": "高声", "is_correct": false, "explanation": "语义：“高声”指大声，与“谁也没有说话”的安静状态矛盾。"}], "explanations": {"悄然": "正确：“悄然”表示安静、不引人注意，与“谁也没有说话”相合。", "齐声": "搭配：“齐声”用于一起发出声音，不能用来修饰“等着”这种安静的状态。", "嘈杂地": "语义：“嘈杂”指声音杂乱，与“谁也没有说话”矛盾。", "高声": "语义：“高声”指大声，与“谁也没有说话”的安静状态矛盾。"}, "sentence_index": 6, "correct_answer": "悄然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他悄然宣布了比赛结果，全校顿时炸开了锅。", "explanation": "这里应该用〈当众〉。悄然强调无声无息、不引人注意；宣布比赛结果并引起全校轰动，需要当众进行。"}, {"text": "孩子们悄然拍手欢呼，声音传到了街上。", "explanation": "这里应该用〈大声〉。悄然表示不发出声音，与“拍手欢呼”“声音传到了街上”矛盾。"}, {"text": "他悄然举起话筒，大喊一声，全场吓得跳了起来。", "explanation": "这里应该用〈高声〉。悄然形容无声无息，不能修饰“大喊”这类高声的动作；应说“高声大喊”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26484, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们悄然的围住了老师，没有人说话。", "corrected_sentence": "孩子们悄然地围住了老师，没有人说话。", "error_description": "错误在于用了“的”。“悄然”修饰动词作状语，后面应接“地”，应说“悄然地围住了老师”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26484, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她悄然得坐在窗边，看着雨。", "corrected_sentence": "她悄然地坐在窗边，看着雨。", "error_description": "“悄然”作状语修饰动词，后面应接“地”，不能用“得”；“得”用于动词或形容词之后作补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
