INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26488, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "住在村子里的人。", "primary_collocate": null, "pronunciation": "cūn mín", "ipa": "tsʰuən˥ min˧˥", "syllable_count": 2, "sentences": [{"text": "我奶奶村里的村民都很热情。", "target_word": "村民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们坐在树下聊天。", "target_word": "村民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小村子只有五十多个村民。", "target_word": "村民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，村民们在村口放鞭炮。", "target_word": "村民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有个村民在路边捡到了一个钱包。", "target_word": "村民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们给来玩的孩子们送了水果。", "target_word": "村民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的村民喝的是泉水。", "target_word": "村民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村长请全体村民晚上到学校开会。", "target_word": "村民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老村民说，这条河以前有很多鱼。", "target_word": "村民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天下大雪，村民们一起扫雪。", "target_word": "村民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "村民委员会", "label": "复合"}], "register": "通用", "sense_fingerprint": "住在村子里的人，泛指村里的居民", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a99ff1f-84fe-4580-9f45-814e6a0bd5f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26488, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "村民", "is_correct": true, "explanation": "“村民”指住在村子里的人，与“我奶奶村里的……都很热情”的语境相合。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：“乘客”指乘车的人，不是“村里的”住户，与语境不符。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：电脑不能用“热情”来形容，搭配不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有感情，不能“热情”，与句意矛盾。"}], "explanations": {"村民": "“村民”指住在村子里的人，与“我奶奶村里的……都很热情”的语境相合。", "乘客": "语义：“乘客”指乘车的人，不是“村里的”住户，与语境不符。", "电脑": "搭配：电脑不能用“热情”来形容，搭配不通。", "石头": "语义：石头没有感情，不能“热情”，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "村民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "过年时，城里的白领都是村民，他们在村口放鞭炮。", "explanation": "此处应该用〈居民〉。“村民”指住在村子里的人，与“城里的白领”的身份矛盾。"}, {"text": "过年时，从北京来玩的游客都是村民，他们住在宾馆里。", "explanation": "此处应该用〈游客〉。“村民”指住在村子里的人，来玩、住宾馆的是游客。"}, {"text": "这几位村民是刚下飞机的美国商人，从没来过中国。", "explanation": "此处应该用〈商人〉。“村民”指住在村子里的人，与“刚下飞机的美国商人”的身份矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26488, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "村民", "is_correct": true, "explanation": "“村民”指住在村子里的人，是喝泉水的人群，符合“山里的……喝的是泉水”的语境。"}, {"text": "机器", "is_correct": false, "explanation": "语义：机器不喝水，与“喝的是泉水”的语境矛盾。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不喝水，“山里的冰箱喝的是泉水”说不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不喝水，与句中描述的情境不符。"}], "explanations": {"村民": "“村民”指住在村子里的人，是喝泉水的人群，符合“山里的……喝的是泉水”的语境。", "机器": "语义：机器不喝水，与“喝的是泉水”的语境矛盾。", "冰箱": "语义：冰箱不喝水，“山里的冰箱喝的是泉水”说不通。", "汽车": "语义：汽车不喝水，与句中描述的情境不符。"}, "sentence_index": 6, "correct_answer": "村民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些村民是坐游船来参观的外国人，明天就回国。", "explanation": "此处应该用〈游客〉。“村民”指住在村子里的人，来参观、明天回国的人是游客。"}, {"text": "他是一名村民，住在市中心的公寓里，每天坐地铁上班。", "explanation": "此处应该用〈居民〉。“村民”指住在村子里的人，住在市中心的公寓里应说“居民”。"}, {"text": "这位村民每天住在纽约的公寓里，每周乘飞机去北京上班。", "explanation": "此处应该用〈居民〉。“村民”指住在村子里的人，住在纽约的公寓里应说“居民”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26488, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山上住着两只村民。", "corrected_sentence": "山上住着两位村民。", "error_description": "量词错误：“村民”指人，应用人的量词“位”，不能用动物或物品的量词“只”，应说“两位村民”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26488, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位村民们很热情。", "corrected_sentence": "这位村民很热情。", "error_description": "“们”多余：“们”不能加在“这位”这类指示词加量词的名词短语后面，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26490, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26490, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26490, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西送回给别人。", "primary_collocate": null, "pronunciation": "huán gěi", "ipa": "xwan˧˥ kei˨˩˦", "syllable_count": 2, "sentences": [{"text": "我昨天借了你的笔，现在还给你。", "target_word": "还给", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天我把借的书还给你。", "target_word": "还给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钥匙还给了妈妈。", "target_word": "还给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学把雨伞还给我了。", "target_word": "还给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你什么时候把电脑还给小李？", "target_word": "还给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把借来的衣服洗好，还给了姐姐。", "target_word": "还给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本词典要还给老师。", "target_word": "还给", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟把玩具还给了邻居的孩子。", "target_word": "还给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别忘了把相机还给小王。", "target_word": "还给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看完这张光盘就还给你。", "target_word": "还给", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "还给了", "label": "体标"}, {"form": "还给过", "label": "体标"}, {"form": "還給", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把借来的具体物品送回给原来的主人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b265e353-0a56-4f5b-a790-095a42c113c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26490, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "还给", "is_correct": true, "explanation": "正确。“借了你的笔”之后说“还给你”，表示把借来的笔送回原主，语境相符。"}, {"text": "送给", "is_correct": false, "explanation": "语义：“送给”是赠予，与前文“借了你的笔”的借还关系不符。"}, {"text": "卖给", "is_correct": false, "explanation": "语义：“卖给”是出售，与前文“借”的临时使用不符。"}, {"text": "借给", "is_correct": false, "explanation": "配价：“借给”的借出方向是我把东西借给你，与“借了你的笔”的方向相反。"}], "explanations": {"还给": "正确。“借了你的笔”之后说“还给你”，表示把借来的笔送回原主，语境相符。", "送给": "语义：“送给”是赠予，与前文“借了你的笔”的借还关系不符。", "卖给": "语义：“卖给”是出售，与前文“借”的临时使用不符。", "借给": "配价：“借给”的借出方向是我把东西借给你，与“借了你的笔”的方向相反。"}, "sentence_index": 0, "correct_answer": "还给"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把生日蛋糕还给了妹妹。", "explanation": "这里应该用〈送给〉。还给表示归还原本属于对方的东西；蛋糕不是妹妹原来的，应说“送给妹妹”。"}, {"text": "我把刚写完的作文还给了希望小学。", "explanation": "这里应该用〈交给〉。还给要求东西原属对方；作文是我刚写的，学校从未拥有过，应说“交给希望小学”。"}, {"text": "他把自己画的画还给了老师。", "explanation": "这里应该用〈送给〉。还给要求东西原属对方；这幅画是他自己画的，老师从未拥有过，应说“送给老师”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26490, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "还给", "is_correct": true, "explanation": "正确。“这本词典要还给老师”表示把借来的词典归还老师，语境相符。"}, {"text": "喜欢", "is_correct": false, "explanation": "配价：“喜欢”的主语应是人，“词典喜欢老师”说不通。"}, {"text": "认识", "is_correct": false, "explanation": "配价：“认识”的主语应是人，词典不能认识老师。"}, {"text": "长大", "is_correct": false, "explanation": "语法：“长大”不带宾语，不能说“长大老师”。"}], "explanations": {"还给": "正确。“这本词典要还给老师”表示把借来的词典归还老师，语境相符。", "喜欢": "配价：“喜欢”的主语应是人，“词典喜欢老师”说不通。", "认识": "配价：“认识”的主语应是人，词典不能认识老师。", "长大": "语法：“长大”不带宾语，不能说“长大老师”。"}, "sentence_index": 6, "correct_answer": "还给"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把刚买的新衣服还给了同学。", "explanation": "这里应该用〈送给〉。还给要求东西原属对方；这件衣服是我刚买的，同学从未拥有过，应说“送给同学”。"}, {"text": "他把刚从树上摘的苹果还给了邻居。", "explanation": "这里应该用〈送给〉。还给要求东西原属对方；苹果是他刚摘的，邻居从未拥有过，应说“送给邻居”。"}, {"text": "他把自己写的小说还给了朋友。", "explanation": "这里应该用〈送给〉。还给要求东西原属对方；小说是他自己写的，朋友从未拥有过，应说“送给朋友”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我用完你的电脑就把还给你。", "corrected_sentence": "我用完你的电脑就还给你。", "error_description": "“把”字句中“把”后必须接宾语，此处“把”后直接接“还给”，应去掉“把”，说“我用完你的电脑就还给你”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我看完这本杂志就了还给你。", "corrected_sentence": "我看完这本杂志就还给你。", "error_description": "“了”表示动作完成，应放在动词之后，不能直接放在“还给”前；应去掉“了”，说“我看完这本杂志就还给你”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
