INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26494, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在土地上种很多树，让环境更好。", "primary_collocate": null, "pronunciation": "zhí shù zào lín", "ipa": "ʈʂɻ̩³⁵ ʂu⁵¹ tsɑʊ̯⁵¹ lin³⁵", "syllable_count": 4, "sentences": [{"text": "我们在山上植树造林，山变得越来越绿。", "target_word": "植树造林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了让城市空气更好，市民一起去植树造林。", "target_word": "植树造林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校旁边的荒地上，同学们正在植树造林。", "target_word": "植树造林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植树造林可以让河水更干净，也能挡住大风。", "target_word": "植树造林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王每个周末都去郊外植树造林。", "target_word": "植树造林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片土地太干了，所以要先植树造林。", "target_word": "植树造林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们学会了植树造林，还给小树浇水。", "target_word": "植树造林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的人用了五年时间植树造林。", "target_word": "植树造林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他觉得植树造林是在帮助地球。", "target_word": "植树造林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年春天我第一次参加了植树造林。", "target_word": "植树造林", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "植樹造林", "label": "繁体"}], "register": "中性", "sense_fingerprint": "植树造林：在土地上种很多树让环境变好（日常动作）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a557264c-4aa5-46b9-b35c-1063d06c8088') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26494, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "植树造林", "is_correct": true, "explanation": "正确：“植树造林”指在山上种树，与后句“山变得越来越绿”的因果关系相符。"}, {"text": "砍伐森林", "is_correct": false, "explanation": "语义：砍伐森林会让山变秃，与后句“山变得越来越绿”正好相反。"}, {"text": "开采矿产", "is_correct": false, "explanation": "语义：开采矿产会破坏山体植被，不能让山变绿，与后句矛盾。"}, {"text": "拆树", "is_correct": false, "explanation": "搭配：“拆”一般用于房屋、桥梁等建筑，不说“拆树”。"}], "explanations": {"植树造林": "正确：“植树造林”指在山上种树，与后句“山变得越来越绿”的因果关系相符。", "砍伐森林": "语义：砍伐森林会让山变秃，与后句“山变得越来越绿”正好相反。", "开采矿产": "语义：开采矿产会破坏山体植被，不能让山变绿，与后句矛盾。", "拆树": "搭配：“拆”一般用于房屋、桥梁等建筑，不说“拆树”。"}, "sentence_index": 0, "correct_answer": "植树造林"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家阳台太小，只能植树造林。", "explanation": "这里应该用〈种树〉。植树造林指大面积、成片地造林，阳台上只能种几棵树，应说种树。"}, {"text": "妈妈每天在窗台上植树造林，养了几盆花。", "explanation": "这里应该用〈养花〉。植树造林只用于造林，不能用来指窗台上养花这类小范围的活动。"}, {"text": "他在花园里植树造林，种了很多青菜。", "explanation": "这里应该用〈种菜〉。植树造林的对象是树木，不能用来指种青菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26494, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "植树造林", "is_correct": true, "explanation": "正确：孩子们学会的是种树，后句“还给小树浇水”与之衔接。"}, {"text": "砍树", "is_correct": false, "explanation": "语义：“砍树”与后句“还给小树浇水”的爱护之意相反，前后不连贯。"}, {"text": "毁林", "is_correct": false, "explanation": "语义：“毁林”指破坏森林，与后句“给小树浇水”的爱护之意相反。"}, {"text": "写树", "is_correct": false, "explanation": "搭配：“写”的对象是文字、文章等，不能说“写树”。"}], "explanations": {"植树造林": "正确：孩子们学会的是种树，后句“还给小树浇水”与之衔接。", "砍树": "语义：“砍树”与后句“还给小树浇水”的爱护之意相反，前后不连贯。", "毁林": "语义：“毁林”指破坏森林，与后句“给小树浇水”的爱护之意相反。", "写树": "搭配：“写”的对象是文字、文章等，不能说“写树”。"}, "sentence_index": 6, "correct_answer": "植树造林"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们只用了一分钟就完成了植树造林。", "explanation": "这里应该用〈种树〉。植树造林指长期、成片的造林工程，不能一分钟就完成，只能说种树。"}, {"text": "妈妈在花盆里植树造林，栽了一朵花。", "explanation": "这里应该用〈栽花〉。植树造林针对树木，不能用于在花盆里栽花。"}, {"text": "他去超市买菜时，顺便植树造林。", "explanation": "这里应该用〈种树〉。植树造林是有计划的大型活动，不能像顺手做的小事那样随手完成，顺便做的小事应说种树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在荒山上植树造林着。", "corrected_sentence": "我们在荒山上植树造林。", "error_description": "错误在于多加了动态助词“着”。“植树造林”表示一个完整的行动，不能直接接“着”，应去掉“着”，写成“我们在荒山上植树造林。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26494, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年春天，我们班去山上植树造林树。", "corrected_sentence": "今年春天，我们班去山上植树造林。", "error_description": "错误在于多加了“树”。“植树造林”已包含宾语“树”，后面不能再加“树”，应说“植树造林”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
