INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26496, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "最开始的时候。", "primary_collocate": null, "pronunciation": "qǐ chū", "ipa": "tɕʰi²¹⁴ ʈʂʰu⁵⁵", "syllable_count": 2, "sentences": [{"text": "起初我很怕水，后来学会了游泳。", "target_word": "起初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "起初她不想去，后来还是去了。", "target_word": "起初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书起初很难懂，我看了三遍才明白。", "target_word": "起初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起初只有五个学生，现在有五十个了。", "target_word": "起初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟起初不吃青菜，现在什么都吃。", "target_word": "起初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "起初我找不到路，后来问了一位老人。", "target_word": "起初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他起初住在北京，后来搬到了上海。", "target_word": "起初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "起初大家笑他，可是他没有放弃。", "target_word": "起初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我起初不明白，老师说了两次才懂。", "target_word": "起初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "起初雨很小，后来越下越大。", "target_word": "起初", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "起初：副词，最开始的时候，后面常接变化后的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a557264c-4aa5-46b9-b35c-1063d06c8088') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26496, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起初", "is_correct": true, "explanation": "正确：“起初”表示最开始的时候，与后面“后来学会了游泳”的变化相对照。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”指一直如此，与后句“后来学会了游泳”的变化相矛盾。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”说一直如此，与后句“后来学会了游泳”的变化相矛盾。"}, {"text": "最后", "is_correct": false, "explanation": "语义：“最后”指结束的时候，与“后来学会了游泳”的先后顺序冲突。"}], "explanations": {"起初": "正确：“起初”表示最开始的时候，与后面“后来学会了游泳”的变化相对照。", "从来": "语义：“从来”指一直如此，与后句“后来学会了游泳”的变化相矛盾。", "总是": "语义：“总是”说一直如此，与后句“后来学会了游泳”的变化相矛盾。", "最后": "语义：“最后”指结束的时候，与“后来学会了游泳”的先后顺序冲突。"}, "sentence_index": 0, "correct_answer": "起初"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他起初已经工作了五年。", "explanation": "这里应该用〈以前〉。起初指最开始的阶段，不能用来描述已经持续很久的工作，较早的一段时间应说以前。"}, {"text": "明年起初我们要搬家。", "explanation": "这里应该用〈开始〉。起初只说明过去的开端，不能用于将来的事。"}, {"text": "请你起初先坐下。", "explanation": "这里应该用〈现在〉。起初指最开始的阶段，不能用于命令句，请对方立即行动应说现在。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26496, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起初", "is_correct": true, "explanation": "正确：“起初”表示开始的时候，与后句“后来搬到了上海”的变化相连。"}, {"text": "始终", "is_correct": false, "explanation": "语义：“始终”说一直如此，与后句“后来搬到了上海”的变化相矛盾。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示一直不变，与后句“后来搬到了上海”冲突。"}, {"text": "向来", "is_correct": false, "explanation": "语义：“向来”表示一贯如此，与后句“后来搬到了上海”的变化矛盾。"}], "explanations": {"起初": "正确：“起初”表示开始的时候，与后句“后来搬到了上海”的变化相连。", "始终": "语义：“始终”说一直如此，与后句“后来搬到了上海”的变化相矛盾。", "永远": "语义：“永远”表示一直不变，与后句“后来搬到了上海”冲突。", "向来": "语义：“向来”表示一贯如此，与后句“后来搬到了上海”的变化矛盾。"}, "sentence_index": 6, "correct_answer": "起初"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "起初，他终于考上了大学。", "explanation": "这里应该用〈最后〉。“终于”表示最后的结果，与“起初”（开始）相矛盾。"}, {"text": "起初，我们才明白了原因。", "explanation": "这里应该用〈后来〉。“才”表示较晚发生，与“起初”（最开始）相矛盾。"}, {"text": "起初，我的汉语已经很流利了。", "explanation": "这里应该用〈现在〉。起初指最开始的阶段，不能用来描述已经达到的水平，描述当前的状况应说现在。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26496, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我起初的不会骑车，后来请朋友教我。", "corrected_sentence": "我起初不会骑车，后来请朋友教我。", "error_description": "错误在于“起初”后多加了“的”。“起初”是副词，不能带“的”，应说“我起初不会骑车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26496, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的起初很害羞，后来变得很外向。", "corrected_sentence": "他起初很害羞，后来变得很外向。", "error_description": "错误在于多加了“的”。“起初”是副词，不能加“的”，应说“他起初很害羞”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
