INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26498, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在学校里教小朋友学知识的人。", "primary_collocate": null, "pronunciation": "jiào shī", "ipa": "tɕjɑʊ˥˩ ʂɨ˥", "syllable_count": 2, "sentences": [{"text": "小学教师每天陪孩子们读书。", "target_word": "教师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位教师带着一年级的小朋友唱歌。", "target_word": "教师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教师教小朋友写自己的名字。", "target_word": "教师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们都喜欢新来的教师。", "target_word": "教师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她是幼儿园的教师，天天和小朋友玩。", "target_word": "教师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教师让小朋友们排好队去操场。", "target_word": "教师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友生病了，教师打电话给妈妈。", "target_word": "教师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我长大了想当教师，教小朋友读书。", "target_word": "教师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教师给一年级的孩子们讲了一个故事。", "target_word": "教师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友把画送给了教师。", "target_word": "教师", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "教師", "label": "繁体"}], "register": "中性", "sense_fingerprint": "教小朋友学知识的学校老师", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f659c16-daa9-43a1-9d53-9dc21665adf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26498, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教师", "is_correct": true, "explanation": "正确：“教师”指教小朋友学知识的人，与“小学”和“陪孩子们读书”相合。"}, {"text": "工程师", "is_correct": false, "explanation": "语义：工程师的工作不是陪小朋友读书，与“小学”的语境不合。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师在厨房工作，不陪孩子们读书。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“陪孩子们读书”需要有生命的施事，石头不能做这个动作。"}], "explanations": {"教师": "正确：“教师”指教小朋友学知识的人，与“小学”和“陪孩子们读书”相合。", "工程师": "语义：工程师的工作不是陪小朋友读书，与“小学”的语境不合。", "厨师": "语义：厨师在厨房工作，不陪孩子们读书。", "石头": "配价：“陪孩子们读书”需要有生命的施事，石头不能做这个动作。"}, "sentence_index": 0, "correct_answer": "教师"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那位教师每天给孩子们打针。", "explanation": "这里应该用〈医生〉。打针的是医生，“教师”指教小朋友学知识的人。"}, {"text": "这位教师在路口指挥交通。", "explanation": "这里应该用〈交警〉。在路口指挥交通的是交警，“教师”指教小朋友学知识的人。"}, {"text": "这位教师是饭店的大厨，每天炒很多菜。", "explanation": "这里应该用〈厨师〉。在饭店炒菜的是厨师，“教师”指教小朋友学知识的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教师", "is_correct": true, "explanation": "正确：“教师”能打电话给家长，与“小朋友生病了”的语境相合。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不会打电话，这句话说不通。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不会打电话给妈妈。"}, {"text": "冰箱", "is_correct": false, "explanation": "配价：“打电话”需要有生命的施事，冰箱不能做这个动作。"}], "explanations": {"教师": "正确：“教师”能打电话给家长，与“小朋友生病了”的语境相合。", "小狗": "语义：小狗不会打电话，这句话说不通。", "小猫": "语义：小猫不会打电话给妈妈。", "冰箱": "配价：“打电话”需要有生命的施事，冰箱不能做这个动作。"}, "sentence_index": 6, "correct_answer": "教师"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教师每天开车送客人。", "explanation": "这里应该用〈司机〉。开车送人的是司机，“教师”指教小朋友学知识的人。"}, {"text": "教师给病人换药。", "explanation": "这里应该用〈护士〉。给病人换药的是护士，教师不做这件事。"}, {"text": "这位教师在法庭上替被告辩护。", "explanation": "这里应该用〈律师〉。在法庭上替被告辩护的是律师，“教师”指教小朋友学知识的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的叔叔是一只小学教师。", "corrected_sentence": "我的叔叔是一位小学教师。", "error_description": "量词错误：指人的“教师”应该用“位”或“名”，“一只”是错的，“只”用于动物等。正确说法是“一位小学教师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班来了两位教师们。", "corrected_sentence": "我们班来了两位教师。", "error_description": "“们”的用法错误：数词后面不能加“们”，“两位教师”不能再说“两位教师们”。正确说法是去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26500, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
