INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26500, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不再工作，开始休息。", "primary_collocate": null, "pronunciation": "tuì xiū", "ipa": "tʰweɪ̯⁵¹ ɕjoʊ̯⁵⁵", "syllable_count": 2, "sentences": [{"text": "退休以后，爷爷每天早上去公园走路。", "target_word": "退休", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈退休了，终于有时间睡懒觉。", "target_word": "退休", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "李老师退休前教了三十年书。", "target_word": "退休", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想退休后搬到安静的小镇。", "target_word": "退休", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他工作太累了，真想马上退休。", "target_word": "退休", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "叔叔去年退休，现在天天钓鱼。", "target_word": "退休", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸退休后学会了做饭。", "target_word": "退休", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们俩都退休了，经常一起爬山。", "target_word": "退休", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "退休不是结束，而是新生活的开始。", "target_word": "退休", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外婆退休十年了，身体还很好。", "target_word": "退休", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "退休了", "label": "体标"}, {"form": "退休金", "label": "复合"}, {"form": "退休年龄", "label": "复合"}], "register": "中性", "sense_fingerprint": "退休：不再工作，开始过休息的生活（日常说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a557264c-4aa5-46b9-b35c-1063d06c8088') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26500, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "退休", "is_correct": true, "explanation": "正确。“退休”表示不再工作，与“以后”和“每天早上去公园走路”的退休生活相符。"}, {"text": "去世", "is_correct": false, "explanation": "语义：“去世”指人死亡，死后不能再去公园走路，与句意矛盾。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指刚来到世界，婴儿不能每天自己去公园走路，与“爷爷”矛盾。"}, {"text": "上学", "is_correct": false, "explanation": "语义：“上学”指学生去学校读书，爷爷并不上学，与句意不符。"}], "explanations": {"退休": "正确。“退休”表示不再工作，与“以后”和“每天早上去公园走路”的退休生活相符。", "去世": "语义：“去世”指人死亡，死后不能再去公园走路，与句意矛盾。", "出生": "语义：“出生”指刚来到世界，婴儿不能每天自己去公园走路，与“爷爷”矛盾。", "上学": "语义：“上学”指学生去学校读书，爷爷并不上学，与句意不符。"}, "sentence_index": 0, "correct_answer": "退休"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天下班后都要退休，陪孩子做作业。", "explanation": "这里应该用〈下班〉。“退休”指永久离开工作岗位，每天离开工作应说“下班”。"}, {"text": "他想退休一个月，去海边玩玩。", "explanation": "这里应该用〈休假〉。“退休”是永久离开工作，只放一个月的假应说“休假”。"}, {"text": "他大学退休后去北京工作了。", "explanation": "这里应该用〈毕业〉。“退休”指离开工作岗位，大学生结束学业应说“毕业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26500, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "退休", "is_correct": true, "explanation": "正确。“退休”表示不再工作，与“爸爸……后学会了做饭”的语境相符。"}, {"text": "去世", "is_correct": false, "explanation": "语义：“去世”指人死亡，死后不可能再学会做饭，与句意矛盾。"}, {"text": "病故", "is_correct": false, "explanation": "语域：“病故”是书面语，多见于讣告，与口语叙述不合；且意思是死亡，与“学会了做饭”矛盾。"}, {"text": "诞生", "is_correct": false, "explanation": "语义：“诞生”指事物或生命开始出现，爸爸已经成年，与句意不符。"}], "explanations": {"退休": "正确。“退休”表示不再工作，与“爸爸……后学会了做饭”的语境相符。", "去世": "语义：“去世”指人死亡，死后不可能再学会做饭，与句意矛盾。", "病故": "语域：“病故”是书面语，多见于讣告，与口语叙述不合；且意思是死亡，与“学会了做饭”矛盾。", "诞生": "语义：“诞生”指事物或生命开始出现，爸爸已经成年，与句意不符。"}, "sentence_index": 6, "correct_answer": "退休"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "办完手续后他就退休，下个月还要回公司上班。", "explanation": "这里应该用〈请假〉。“退休”是永久离开工作岗位，下个月还要回公司上班应说“请假”。"}, {"text": "病人上个月刚退休，已经可以回家了。", "explanation": "这里应该用〈出院〉。“退休”指离开工作岗位，病人离开医院应说“出院”。"}, {"text": "明天我们退休，下周一还要来上班。", "explanation": "这里应该用〈放假〉。“退休”是永久离开工作，明天放假、短暂休息应说“放假”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26500, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我父亲去年退休了工作。", "corrected_sentence": "我父亲去年退休了。", "error_description": "错误：“退休”后面带了宾语“工作”。“退休”是不及物动词，后面不能直接带宾语，正确说法是“我父亲去年退休了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26500, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我舅舅五十五岁就退休着，每天在家养花。", "corrected_sentence": "我舅舅五十五岁就退休了，每天在家养花。", "error_description": "错误：“退休”后面用了动态助词“着”。“退休”是一次性完成的动作，表示变化完成要用“了”，正确说法是“我舅舅五十五岁就退休了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
