INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26502, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "村口就是村子入口的地方。", "primary_collocate": null, "pronunciation": "cūn kǒu", "ipa": "tsʰwən˥ kʰoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "村口就是进村的地方。", "target_word": "村口", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下了车，我先走到村口。", "target_word": "村口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸在村口接我回家。", "target_word": "村口", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "村口有一条小河。", "target_word": "村口", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家离村口很近，走几步就到。", "target_word": "村口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村口那条路通向山外。", "target_word": "村口", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "客人到了村口，大家都出来欢迎。", "target_word": "村口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗跑到村口，不见了。", "target_word": "村口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村口站着一位老人。", "target_word": "村口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里村口的灯一直亮着。", "target_word": "村口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "村子入口的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f659c16-daa9-43a1-9d53-9dc21665adf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26502, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "村口", "is_correct": true, "explanation": "正确：“村口”指村子入口的地方，与“进村的地方”的解释相合。"}, {"text": "出口", "is_correct": false, "explanation": "语义：“出口”指出去的地方，与“进村”的方向相反。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不是进村的地方。"}, {"text": "村民", "is_correct": false, "explanation": "配价：“是……的地方”需要处所名词，“村民”指人，不能这样用。"}], "explanations": {"村口": "正确：“村口”指村子入口的地方，与“进村的地方”的解释相合。", "出口": "语义：“出口”指出去的地方，与“进村”的方向相反。", "厨房": "语义：厨房是做饭的地方，不是进村的地方。", "村民": "配价：“是……的地方”需要处所名词，“村民”指人，不能这样用。"}, "sentence_index": 0, "correct_answer": "村口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车站的村口挤满了游客。", "explanation": "这里应该用〈入口〉。车站的出入处叫入口，“村口”只指村子的入口。"}, {"text": "这条河的村口有很多鱼。", "explanation": "这里应该用〈河口〉。河流入海或流入别的河的地方叫河口，“村口”只指村子的入口。"}, {"text": "学校的村口每天七点开。", "explanation": "这里应该用〈大门〉。商店、学校有大门，不说“村口”；“村口”只指村子的入口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "村口", "is_correct": true, "explanation": "正确：客人到了村子的入口，大家出来欢迎，符合语境。"}, {"text": "大海", "is_correct": false, "explanation": "语义：客人到了大海，大家不会“出来欢迎”，句子说不通。"}, {"text": "厕所", "is_correct": false, "explanation": "语义：厕所不是迎接客人的地方，“出来欢迎”的说法不合。"}, {"text": "游戏", "is_correct": false, "explanation": "配价：“客人到了”需要表示地点的名词，“游戏”不是可以到达的地方。"}], "explanations": {"村口": "正确：客人到了村子的入口，大家出来欢迎，符合语境。", "大海": "语义：客人到了大海，大家不会“出来欢迎”，句子说不通。", "厕所": "语义：厕所不是迎接客人的地方，“出来欢迎”的说法不合。", "游戏": "配价：“客人到了”需要表示地点的名词，“游戏”不是可以到达的地方。"}, "sentence_index": 6, "correct_answer": "村口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "商场的村口很宽。", "explanation": "这里应该用〈入口〉。商场的出入处叫入口，“村口”只指村子的入口。"}, {"text": "三条马路在这里交汇，是一个很大的村口。", "explanation": "这里应该用〈路口〉。几条马路交汇的地方叫路口，“村口”指村子的入口。"}, {"text": "机场的村口很多。", "explanation": "这里应该用〈出口〉。机场的出入处叫出口，“村口”只指村子的入口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们村有两只村口。", "corrected_sentence": "我们村有两个村口。", "error_description": "量词错误：“村口”的量词应该用“个”，“只”用于动物等，不能修饰“村口”。正确说法是“我们村有两个村口”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们村口玩耍。", "corrected_sentence": "孩子们在村口玩耍。", "error_description": "缺少介词：表示地点的“村口”前面要加“在”，漏掉“在”就不通。正确说法是“孩子们在村口玩耍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
