INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26506, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "荒坡是长满野草、没有人种庄稼的斜坡地。", "primary_collocate": null, "pronunciation": "huāng pō", "ipa": "xwɑŋ˥ pʰwo˥", "syllable_count": 2, "sentences": [{"text": "荒坡上没有人种庄稼，只有野草。", "target_word": "荒坡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷带我去荒坡上放羊。", "target_word": "荒坡", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下雨后，荒坡上的路很滑。", "target_word": "荒坡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那片荒坡离我家不远。", "target_word": "荒坡", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "荒坡上有很多石头和杂草。", "target_word": "荒坡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在荒坡上种了几棵树。", "target_word": "荒坡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们爬上荒坡看夕阳。", "target_word": "荒坡", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这块荒坡很多年没人管了。", "target_word": "荒坡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "荒坡边上有一条小路。", "target_word": "荒坡", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "野兔从荒坡跑进了树林。", "target_word": "荒坡", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "块", "label": "量词"}], "register": "中性", "sense_fingerprint": "长满野草、无人种庄稼的斜坡地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f659c16-daa9-43a1-9d53-9dc21665adf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26506, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "荒坡", "is_correct": true, "explanation": "荒坡是长满野草、无人种庄稼的斜坡地，与“没有人种庄稼，只有野草”相符。"}, {"text": "农田", "is_correct": false, "explanation": "语义：农田是耕种庄稼的地，与“没有人种庄稼”的说法矛盾。"}, {"text": "菜园", "is_correct": false, "explanation": "语义：菜园里有人种菜，与“没有人种庄稼”的说法矛盾。"}, {"text": "麦田", "is_correct": false, "explanation": "语义：麦田里种着小麦，是庄稼地，与“没有人种庄稼”的说法矛盾。"}], "explanations": {"荒坡": "荒坡是长满野草、无人种庄稼的斜坡地，与“没有人种庄稼，只有野草”相符。", "农田": "语义：农田是耕种庄稼的地，与“没有人种庄稼”的说法矛盾。", "菜园": "语义：菜园里有人种菜，与“没有人种庄稼”的说法矛盾。", "麦田": "语义：麦田里种着小麦，是庄稼地，与“没有人种庄稼”的说法矛盾。"}, "sentence_index": 0, "correct_answer": "荒坡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片荒坡平坦宽阔，很适合建停车场。", "explanation": "这里应该用〈荒地〉。荒坡指有坡度、无人种庄稼的地，平坦的地面不能说荒坡。"}, {"text": "这片荒坡上种满了玉米，今年收成很好。", "explanation": "这里应该用〈山坡〉。荒坡指无人种庄稼的坡地，种满玉米就不能再叫荒坡。"}, {"text": "这块荒坡上盖起了一排排楼房，住满了人。", "explanation": "这里应该用〈住宅区〉。荒坡是长满野草的坡地，盖满楼房的地方要说住宅区。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "荒坡", "is_correct": true, "explanation": "荒坡是可以攀登的斜坡地，孩子们爬上去看夕阳，符合句意。"}, {"text": "水库", "is_correct": false, "explanation": "语义：水库是水面，人不能爬上水库去看夕阳。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见摸不着，不能“爬上”去看夕阳。"}, {"text": "河面", "is_correct": false, "explanation": "语义：河面是水面，不能爬上去看夕阳。"}], "explanations": {"荒坡": "荒坡是可以攀登的斜坡地，孩子们爬上去看夕阳，符合句意。", "水库": "语义：水库是水面，人不能爬上水库去看夕阳。", "空气": "语义：空气看不见摸不着，不能“爬上”去看夕阳。", "河面": "语义：河面是水面，不能爬上去看夕阳。"}, "sentence_index": 6, "correct_answer": "荒坡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这面荒坡平坦得像操场，孩子们在上面踢球。", "explanation": "这里应该用〈空地〉。荒坡是有坡度的斜坡，平整的场地要说空地。"}, {"text": "我家门前的荒坡修剪得整整齐齐，全家常在上面晒太阳。", "explanation": "这里应该用〈草坪〉。荒坡指未经开垦、长满野草的坡地，修剪整齐的草地要说草坪。"}, {"text": "这片荒坡上铺满了水泥，停满了汽车。", "explanation": "这里应该用〈停车场〉。荒坡是长满野草的坡地，铺满水泥、停满汽车的地方要说停车场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们在一只荒坡上放风筝。", "corrected_sentence": "孩子们在一块荒坡上放风筝。", "error_description": "错误：量词“只”用于动物或小件物品，荒坡是地面，应用“块”。正确：一块荒坡。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "傍晚，孩子们坐在一张荒坡上看夕阳。", "corrected_sentence": "傍晚，孩子们坐在一片荒坡上看夕阳。", "error_description": "错误：量词“张”用于桌子、纸等平面物品，荒坡是一大片坡地，应用“片”。正确：一片荒坡。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
