INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26508, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26508, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为了得到名声。", "primary_collocate": null, "pronunciation": "wèi míng", "ipa": "weɪ˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他做好事不为名，也不为利。", "target_word": "为名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有些人做事只为名，不管别人。", "target_word": "为名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她写书不是为名，只是想帮助孩子。", "target_word": "为名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生工作多年，从来不为名。", "target_word": "为名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他参加比赛不为名，只为学习。", "target_word": "为名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人为名而忙，也有人为钱而忙。", "target_word": "为名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，学习不要为名，要为自己。", "target_word": "为名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们捐钱是为了帮人，不是为名。", "target_word": "为名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为名也好，为利也好，他都不在乎。", "target_word": "为名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总是为名的人，常常不快乐。", "target_word": "为名", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "为名", "label": "基本形式"}, {"form": "为名为利", "label": "复合"}], "register": "书面", "sense_fingerprint": "做事是为了追求名声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a557264c-4aa5-46b9-b35c-1063d06c8088') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26508, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "为名", "is_correct": true, "explanation": "正确：“为名”指为了得到名声，与后文“也不为利”相对应。"}, {"text": "为恶", "is_correct": false, "explanation": "语义：“为恶”指做坏事，与“做好事”相反，不能与之并列。"}, {"text": "为害", "is_correct": false, "explanation": "语义：“为害”指造成伤害，与“做好事”的意思冲突。"}, {"text": "为难", "is_correct": false, "explanation": "语义：“为难”指使人感到困难或刁难别人，不表示做事的目的，“做好事不为难”意思不通。"}], "explanations": {"为名": "正确：“为名”指为了得到名声，与后文“也不为利”相对应。", "为恶": "语义：“为恶”指做坏事，与“做好事”相反，不能与之并列。", "为害": "语义：“为害”指造成伤害，与“做好事”的意思冲突。", "为难": "语义：“为难”指使人感到困难或刁难别人，不表示做事的目的，“做好事不为难”意思不通。"}, "sentence_index": 0, "correct_answer": "为名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小镇因一座老桥而为名，每年都有很多游客来。", "explanation": "这里应该用〈闻名〉。为名表示为了得到名声去做事，不能表示因某事而变得有名；闻名指名声传开。"}, {"text": "这位画家一幅画就为名天下，连外国人都来看。", "explanation": "这里应该用〈扬名〉。“扬名天下”是固定说法；为名只表示为了得到名声去做事，不能表示名声传播开来的结果。"}, {"text": "他拼命工作，只想为名远扬。", "explanation": "这里应该用〈扬名〉。为名表示做事的目的，不能接“远扬”这类结果补语，应说“扬名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "为名", "is_correct": true, "explanation": "正确：“为名”指为了得到名声，与后文“要为自己”相对应。"}, {"text": "为非", "is_correct": false, "explanation": "语义：“为非”指做错事，与“学习”的正当目的不合。"}, {"text": "为患", "is_correct": false, "explanation": "搭配：“为患”指造成祸害，不能与“学习”搭配。"}, {"text": "为敌", "is_correct": false, "explanation": "语义：“为敌”指与人对立，与“学习”无关，句子意思不通。"}], "explanations": {"为名": "正确：“为名”指为了得到名声，与后文“要为自己”相对应。", "为非": "语义：“为非”指做错事，与“学习”的正当目的不合。", "为患": "搭配：“为患”指造成祸害，不能与“学习”搭配。", "为敌": "语义：“为敌”指与人对立，与“学习”无关，句子意思不通。"}, "sentence_index": 6, "correct_answer": "为名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一夜为名，每天都有人找他签名。", "explanation": "这里应该用〈成名〉。成名指变得有名气，为名表示为了名声去做事，“一夜为名”语义不通。"}, {"text": "很多游客为名而来，只为尝一口这道菜。", "explanation": "这里应该用〈慕名〉。慕名指仰慕名声而来；为名指为了得到名声而做，与“只为尝一口这道菜”矛盾。"}, {"text": "他年轻时为名四海，如今却很平静。", "explanation": "这里应该用〈闻名〉。“闻名四海”指名声传遍各地；为名表示为了名声去做事，不能表示名声传开的范围，“为名四海”不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位作家写作只为名着，并不在乎读者。", "corrected_sentence": "这位作家写作只为名，并不在乎读者。", "error_description": "“为名”表示做事的目的（为了得到名声），后面不能加持续体标记“着”；应去掉“着”，写成“只为名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人做慈善从不为名了，只为帮助别人。", "corrected_sentence": "老人做慈善从不为名，只为帮助别人。", "error_description": "“为名”是动词，表示为了得到名声，不能直接带“了”表示完成；“从不为名”之后不能再加“了”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
