INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26512, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小树的小宝宝，会长成大树。", "primary_collocate": null, "pronunciation": "shù miáo", "ipa": "ʂu˥˩ mjɑʊ̯˧˥", "syllable_count": 2, "sentences": [{"text": "院子里有一棵树苗。", "target_word": "树苗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这棵树苗是我去年种的。", "target_word": "树苗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "奶奶每天给树苗浇水。", "target_word": "树苗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春天，我和爸爸去买了两棵树苗。", "target_word": "树苗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "树苗要喝水，也要晒太阳。", "target_word": "树苗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "风很大，树苗站不稳。", "target_word": "树苗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山上新种了一片树苗。", "target_word": "树苗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些树苗过几年就会长成大树。", "target_word": "树苗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "树苗一天天长高了。", "target_word": "树苗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，树苗需要阳光和水。", "target_word": "树苗", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一棵树苗", "label": "量词"}, {"form": "小树苗", "label": "复合"}], "register": "中性", "sense_fingerprint": "树苗:会长成大树的小树", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f659c16-daa9-43a1-9d53-9dc21665adf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26512, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "树苗", "is_correct": true, "explanation": "树苗：会长成大树的小树，与“院子里有一棵”相合。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：叶子应用“片”计量，“院子里有一棵树叶”不通。"}, {"text": "树皮", "is_correct": false, "explanation": "搭配：树皮应用“块”或“层”计量，不用“棵”。"}, {"text": "木板", "is_correct": false, "explanation": "量词：木板应用“块”或“张”计量，不用“棵”。"}], "explanations": {"树苗": "树苗：会长成大树的小树，与“院子里有一棵”相合。", "树叶": "搭配：叶子应用“片”计量，“院子里有一棵树叶”不通。", "树皮": "搭配：树皮应用“块”或“层”计量，不用“棵”。", "木板": "量词：木板应用“块”或“张”计量，不用“棵”。"}, "sentence_index": 0, "correct_answer": "树苗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片山上的树苗高得遮住了太阳。", "explanation": "树苗指刚长出、还很小的树，不能说高得遮住太阳；这里应该用〈大树〉。"}, {"text": "妈妈从菜市场买了一斤树苗回来炒菜。", "explanation": "树苗是会长成大树的小树，不能炒着吃；能吃的嫩苗这里应该用〈豆苗〉。"}, {"text": "这块稻田里刚插上了一片树苗。", "explanation": "“树苗”指树的小苗，稻田里插的是水稻苗，这里应该用〈秧苗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26512, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "树苗", "is_correct": true, "explanation": "树苗：可以种下的小树，“一片”指成片栽种，与“新种了”相合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能“种”，与“新种了”冲突。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能种下去，与“新种了”冲突。"}, {"text": "花瓶", "is_correct": false, "explanation": "搭配：“片”不用于花瓶，应用“个”计量。"}], "explanations": {"树苗": "树苗：可以种下的小树，“一片”指成片栽种，与“新种了”相合。", "石头": "语义：石头不能“种”，与“新种了”冲突。", "玩具": "语义：玩具不能种下去，与“新种了”冲突。", "花瓶": "搭配：“片”不用于花瓶，应用“个”计量。"}, "sentence_index": 6, "correct_answer": "树苗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片古林里的树苗已经有几百年的树龄。", "explanation": "树苗是刚长出的小树，说几百年的树龄要用〈树木〉。"}, {"text": "这座木屋是用上好的树苗搭起来的。", "explanation": "树苗还没长成，不能用来搭建房屋；这里应该用〈木材〉。"}, {"text": "这片果园里的树苗结满了果子。", "explanation": "树苗还没有长大，不会结果；这里应该用〈果树〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26512, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只树苗已经长高了。", "corrected_sentence": "那棵树苗已经长高了。", "error_description": "量词“只”用于动物，“树苗”的量词应为“棵”，应说“那棵树苗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26512, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子的角落里有一本树苗。", "corrected_sentence": "院子的角落里有一棵树苗。", "error_description": "量词“本”用于书本，“树苗”的量词应为“棵”，应说“一棵树苗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
