INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26514, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "种（植物）。", "primary_collocate": null, "pronunciation": "zāi xià", "ipa": "tsaɪ̯˥ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "秋天，农民在地里栽下了白菜苗。", "target_word": "栽下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在阳台上栽下了一株小花。", "target_word": "栽下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷在后院栽下了三棵桃树。", "target_word": "栽下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在公园里栽下了很多小树。", "target_word": "栽下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在山上栽下了一片果树。", "target_word": "栽下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐在窗前栽下了一株月季。", "target_word": "栽下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们沿着马路栽下两排小树。", "target_word": "栽下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年春天，这里栽下了一百棵松树。", "target_word": "栽下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明和爸爸一起栽下了一棵梧桐树。", "target_word": "栽下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶在门口栽下过一棵石榴树，现在还在。", "target_word": "栽下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "栽下了", "label": "体标"}, {"form": "栽下过", "label": "体标"}], "register": "中性", "sense_fingerprint": "栽下:种植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f659c16-daa9-43a1-9d53-9dc21665adf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26514, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "栽下", "is_correct": true, "explanation": "栽下（zāi xià）：把幼苗埋进土里使其生长，意思是种植。"}, {"text": "摘下", "is_correct": false, "explanation": "摘下（zhāi xià）与 zāi 声母不同（zh 与 z），意思是摘取、取下。"}, {"text": "砸下", "is_correct": false, "explanation": "砸下（zá xià）与 zāi 声调不同（第二声与第一声），意思是用力打下。"}, {"text": "在下", "is_correct": false, "explanation": "在下（zài xià）与 zāi 声调不同（第四声），是谦称“我”。"}], "explanations": {"栽下": "栽下（zāi xià）：把幼苗埋进土里使其生长，意思是种植。", "摘下": "摘下（zhāi xià）与 zāi 声母不同（zh 与 z），意思是摘取、取下。", "砸下": "砸下（zá xià）与 zāi 声调不同（第二声与第一声），意思是用力打下。", "在下": "在下（zài xià）与 zāi 声调不同（第四声），是谦称“我”。"}, "sentence_index": null, "correct_answer": "栽下"}, "level_3": {"options": [{"text": "栽下", "is_correct": true, "explanation": "栽下指把白菜苗栽进地里，与句意相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象不能是白菜苗，与句意不合。"}, {"text": "碾", "is_correct": false, "explanation": "搭配：“碾”用于粮食，不能用于白菜苗。"}, {"text": "吹", "is_correct": false, "explanation": "语义：“吹”的对象不能是白菜苗，与种植的语境不符。"}], "explanations": {"栽下": "栽下指把白菜苗栽进地里，与句意相符。", "唱": "语义：“唱”的对象不能是白菜苗，与句意不合。", "碾": "搭配：“碾”用于粮食，不能用于白菜苗。", "吹": "语义：“吹”的对象不能是白菜苗，与种植的语境不符。"}, "sentence_index": 0, "correct_answer": "栽下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "姐姐在窗台上栽下了一本书。", "explanation": "这里应该用〈放〉。栽下只用于植物的种植，书应当用“放”。"}, {"text": "他在墙角栽下了一坛酒。", "explanation": "这里应该用〈埋〉。栽下只用于植物，埋藏酒坛要用“埋”。"}, {"text": "工人在墙上栽下了一块招牌。", "explanation": "这里应该用〈挂〉。栽下只用于植物，招牌要挂在墙上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "栽下", "is_correct": true, "explanation": "栽下指把树苗栽进土里，工人沿马路栽树，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象不能是小树，不能说吃两排小树。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象是动物或人，不能用于小树。"}, {"text": "讲", "is_correct": false, "explanation": "语义：“讲”的对象不能是小树，与句意不合。"}], "explanations": {"栽下": "栽下指把树苗栽进土里，工人沿马路栽树，符合句意。", "吃": "搭配：“吃”的对象不能是小树，不能说吃两排小树。", "喂": "搭配：“喂”的对象是动物或人，不能用于小树。", "讲": "语义：“讲”的对象不能是小树，与句意不合。"}, "sentence_index": 6, "correct_answer": "栽下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在河边栽下了一块石头。", "explanation": "这里应该用〈扔〉。栽下只用于植物的种植，石头应当用“扔”。"}, {"text": "妈妈在厨房里栽下了一锅汤。", "explanation": "这里应该用〈煮〉。栽下只用于植物的种植，汤应当用“煮”。"}, {"text": "我在本子上栽下了几个字。", "explanation": "这里应该用〈写〉。栽下用于种植物，字要用“写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26514, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸在院子里栽下着两棵柿子树。", "corrected_sentence": "爸爸在院子里栽下了两棵柿子树。", "error_description": "错误：“栽下”后应接完成态“了”，说“栽下了”，不能接“着”。正确：栽下了两棵柿子树。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26514, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校的老师带学生在操场边栽下了一只小树林。", "corrected_sentence": "学校的老师带学生在操场边栽下了一片小树林。", "error_description": "错误：量词“只”用于动物，小树林应用“片”。正确：一片小树林。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
