INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26516, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比某个数大。", "primary_collocate": null, "pronunciation": "chāo guò", "ipa": "tʂʰɑʊ˥ kwo˥˩", "syllable_count": 2, "sentences": [{"text": "教室里的学生超过五十人。", "target_word": "超过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河长超过一千公里。", "target_word": "超过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超过一百个人参加了今天的会。", "target_word": "超过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今年已经超过六十岁了。", "target_word": "超过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会的时间不要超过一个小时。", "target_word": "超过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超过十个同学没有交作业。", "target_word": "超过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司有超过两千名工人。", "target_word": "超过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我等了超过半个小时。", "target_word": "超过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的存款超过了十万元。", "target_word": "超过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我花了超过三百块。", "target_word": "超过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "超过了", "label": "体标"}, {"form": "超過", "label": "繁体"}], "register": "中性", "sense_fingerprint": "数量比某个数大，多于某数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25e7a64-8d32-41c0-a4a3-43a2e96bdbc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26516, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "超过", "is_correct": true, "explanation": "正确：“超过”表示数量比五十大，与“教室里的学生”和数字相合。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”接的是活动、比赛，不接“五十人”这类人数。"}, {"text": "教", "is_correct": false, "explanation": "语义：学生不用来“教”人，句子语义不通。"}, {"text": "包括", "is_correct": false, "explanation": "语义：“包括”表示包含在内，学生不能包括五十人，句意不通。"}], "explanations": {"超过": "正确：“超过”表示数量比五十大，与“教室里的学生”和数字相合。", "参加": "搭配：“参加”接的是活动、比赛，不接“五十人”这类人数。", "教": "语义：学生不用来“教”人，句子语义不通。", "包括": "语义：“包括”表示包含在内，学生不能包括五十人，句意不通。"}, "sentence_index": 0, "correct_answer": "超过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他超过了一杯水。", "explanation": "这里应该用〈喝〉。喝水是饮用动作；超过表示数量比某数大，不能用于水。"}, {"text": "我超过了一封信。", "explanation": "这里应该用〈写〉。写信是动笔书写信件；超过表示数量比某数大，不能用于信件。"}, {"text": "我超过了一块蛋糕。", "explanation": "这里应该用〈吃〉。吃蛋糕是进食动作；超过表示数量比某数大，不能用于蛋糕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26516, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "超过", "is_correct": true, "explanation": "正确：“超过”表示数量比两千大，修饰“两千名”，与句意相合。"}, {"text": "包括", "is_correct": false, "explanation": "语义：“包括”表示把对象算在内，与“有”加数量的结构不合，句子不通。"}, {"text": "雇用", "is_correct": false, "explanation": "搭配：“有”后应接数量或名词，“雇用”不能直接接在“有”后面。"}, {"text": "聘请", "is_correct": false, "explanation": "语义：聘请指聘用人员，与“有两千名工人”的存在义不合，句子不通。"}], "explanations": {"超过": "正确：“超过”表示数量比两千大，修饰“两千名”，与句意相合。", "包括": "语义：“包括”表示把对象算在内，与“有”加数量的结构不合，句子不通。", "雇用": "搭配：“有”后应接数量或名词，“雇用”不能直接接在“有”后面。", "聘请": "语义：聘请指聘用人员，与“有两千名工人”的存在义不合，句子不通。"}, "sentence_index": 6, "correct_answer": "超过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我超过了作业。", "explanation": "这里应该用〈交〉。交作业指提交；超过表示数量比某数大，不能用于作业。"}, {"text": "她超过了一首歌。", "explanation": "这里应该用〈唱〉。唱歌是发声动作；超过表示数量比某数大，不能用于歌。"}, {"text": "妈妈超过了衣服。", "explanation": "这里应该用〈洗〉。洗衣服是清洁动作；超过表示数量比某数大，不能用于衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器的温度已经超过过了一百五十度。", "corrected_sentence": "这台机器的温度已经超过了一百五十度。", "error_description": "错误形式：“超过过了”，“过”重复。“超过”本身已含“过”，表示完成只需说“超过了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司有比超过三千名工人。", "corrected_sentence": "这家公司有超过三千名工人。", "error_description": "多余成分：“超过”本身已表示数量比某数大，前面不能再加“比”。应说“这家公司有超过三千名工人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
