INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26518, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "树有很多种，比如松树、柳树，它们都是不同的树种。", "primary_collocate": null, "pronunciation": "shù zhǒng", "ipa": "ʂu˥˩ ʈʂʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "松树和柳树是不同的树种。", "target_word": "树种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山上有很多树种。", "target_word": "树种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢的树种是柳树。", "target_word": "树种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方常见的树种有杨树和松树。", "target_word": "树种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一看叶子就知道这是什么树种。", "target_word": "树种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的小树林里有十几个树种。", "target_word": "树种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠边上要选能耐旱的树种。", "target_word": "树种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了中国常见的树种。", "target_word": "树种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红木是一种很贵的树种。", "target_word": "树种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的树种，树叶的样子也不一样。", "target_word": "树种", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "樹種", "label": "繁体"}], "register": "中性", "sense_fingerprint": "树的不同种类，如松树、柳树各是一个树种", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25e7a64-8d32-41c0-a4a3-43a2e96bdbc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26518, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "树种", "is_correct": true, "explanation": "正确：“不同的树种”指松树和柳树各自所属的树的种类，符合句意。"}, {"text": "作物", "is_correct": false, "explanation": "语义：松树和柳树是树，不是农作物，“不同的作物”不成立。"}, {"text": "鱼类", "is_correct": false, "explanation": "语义：松树和柳树都是植物，不能说是不同的鱼类。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：“松树和柳树”要比较的是树的类别，“树叶”是树的一部分，不能用来并列区分。"}], "explanations": {"树种": "正确：“不同的树种”指松树和柳树各自所属的树的种类，符合句意。", "作物": "语义：松树和柳树是树，不是农作物，“不同的作物”不成立。", "鱼类": "语义：松树和柳树都是植物，不能说是不同的鱼类。", "树叶": "搭配：“松树和柳树”要比较的是树的类别，“树叶”是树的一部分，不能用来并列区分。"}, "sentence_index": 0, "correct_answer": "树种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大熊猫是一种濒危树种。", "explanation": "这里应该用〈物种〉。树种指树木的种类，大熊猫是动物，要用“物种”。"}, {"text": "这种大米是新树种。", "explanation": "这里应该用〈品种〉。树种只指树木，大米是农作物，要用“品种”。"}, {"text": "这只鸡是村里最好的树种，一年能下二百个蛋。", "explanation": "这里应该用〈良种〉。树种只指树木的种类，指家禽的优良品种要说“良种”，不能说“树种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26518, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "树种", "is_correct": true, "explanation": "正确：“能耐旱的树种”指适合沙漠种植的树的种类，搭配自然。"}, {"text": "花瓣", "is_correct": false, "explanation": "语义：“耐旱”说的是植物的特性，花瓣不是可以挑选来种植的种类。"}, {"text": "沙子", "is_correct": false, "explanation": "语义：“选”的对象是植物，沙子不能被挑选成耐旱的种类。"}, {"text": "水域", "is_correct": false, "explanation": "搭配：“耐旱”只修饰植物或作物，不说“能耐旱的水域”。"}], "explanations": {"树种": "正确：“能耐旱的树种”指适合沙漠种植的树的种类，搭配自然。", "花瓣": "语义：“耐旱”说的是植物的特性，花瓣不是可以挑选来种植的种类。", "沙子": "语义：“选”的对象是植物，沙子不能被挑选成耐旱的种类。", "水域": "搭配：“耐旱”只修饰植物或作物，不说“能耐旱的水域”。"}, "sentence_index": 6, "correct_answer": "树种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "北方的主要树种是小麦。", "explanation": "这里应该用〈作物〉。树种只指树木，小麦属于粮食作物，要用“作物”。"}, {"text": "这条河里有很多树种。", "explanation": "这里应该用〈鱼类〉。河里的生物是鱼，树种只指树木的种类。"}, {"text": "我们家每天吃很多树种。", "explanation": "这里应该用〈蔬菜〉。树种是树木的种类，不能当蔬菜吃，日常食物要用“蔬菜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在山上找到了一个少见地树种。", "corrected_sentence": "我们在山上找到了一个少见的树种。", "error_description": "错误形式：“少见地树种”；正确形式：“少见的树种”。“地”用于修饰动词或形容词，修饰名词要用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里有一棵树种，长得很特别。", "corrected_sentence": "这里有一种树种，长得很特别。", "error_description": "错误形式：“一棵树种”；正确形式：“一种树种”。“棵”用于树木、植株，“树种”指树木的种类，量词应用“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
