INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26520, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "自己知道应该做什么，不用别人提醒。", "primary_collocate": null, "pronunciation": "zì jué", "ipa": "tsz̩˥˩ tɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "他很自觉，不用妈妈提醒就写作业。", "target_word": "自觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们自觉排队进教室。", "target_word": "自觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都很自觉，没有人说话。", "target_word": "自觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请自觉把垃圾带走。", "target_word": "自觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天自觉早起跑步。", "target_word": "自觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子自觉关了电视。", "target_word": "自觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不自觉，总要别人催。", "target_word": "自觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘客自觉让座给老人。", "target_word": "自觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要自觉一点，别总玩手机。", "target_word": "自觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人自觉遵守医院的规定。", "target_word": "自觉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自覺", "label": "繁体"}, {"form": "自觉性", "label": "复合"}, {"form": "自觉自愿", "label": "复合"}], "register": "中性", "sense_fingerprint": "不用别人提醒，自己主动去做该做的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25e7a64-8d32-41c0-a4a3-43a2e96bdbc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26520, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自觉", "is_correct": true, "explanation": "形容词，指自己知道该做什么，不用别人提醒，与“不用妈妈提醒就写作业”相符。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”与“不用提醒就主动写作业”语义相反，句子读不通。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，不能用来描述学习习惯。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”形容外貌或事物美观，与写作业的主动性无关。"}], "explanations": {"自觉": "形容词，指自己知道该做什么，不用别人提醒，与“不用妈妈提醒就写作业”相符。", "懒惰": "语义：“懒惰”与“不用提醒就主动写作业”语义相反，句子读不通。", "高大": "体貌：“高大”形容身材，不能用来描述学习习惯。", "漂亮": "语义：“漂亮”形容外貌或事物美观，与写作业的主动性无关。"}, "sentence_index": 0, "correct_answer": "自觉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到好消息，她很自觉。", "explanation": "这里应该用〈高兴〉。自觉形容人不用提醒就主动做事，不表示情绪。"}, {"text": "她身体很自觉，每天跑步。", "explanation": "这里应该用〈健康〉。自觉形容做事的主动性，不用于形容身体状况。"}, {"text": "他很自觉，需要多穿点衣服。", "explanation": "这里应该用〈冷〉。自觉形容人不用提醒就主动做事，不指身体的冷暖感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26520, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自觉", "is_correct": true, "explanation": "形容词，指不用别人催促、自己主动去做，与“总要别人催”相对，语境相符。"}, {"text": "结实", "is_correct": false, "explanation": "语义：“结实”形容物体牢固或人的体格强壮，与做事的主动性无关。"}, {"text": "嘹亮", "is_correct": false, "explanation": "语义：“嘹亮”形容声音响亮，与主动做事的特点无关，句子读不通。"}, {"text": "清晰", "is_correct": false, "explanation": "语义：“清晰”形容清楚分明，不能描述一个人是否需要别人催促。"}], "explanations": {"自觉": "形容词，指不用别人催促、自己主动去做，与“总要别人催”相对，语境相符。", "结实": "语义：“结实”形容物体牢固或人的体格强壮，与做事的主动性无关。", "嘹亮": "语义：“嘹亮”形容声音响亮，与主动做事的特点无关，句子读不通。", "清晰": "语义：“清晰”形容清楚分明，不能描述一个人是否需要别人催促。"}, "sentence_index": 6, "correct_answer": "自觉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做事很自觉，经常出错。", "explanation": "这里应该用〈粗心〉。自觉指不用提醒就主动做事，不指做事马虎。"}, {"text": "他很自觉，大家都爱听他讲话。", "explanation": "这里应该用〈幽默〉。自觉指主动做该做的事，不指说话风趣。"}, {"text": "这扇门会自觉关上。", "explanation": "这里应该用〈自动〉。自觉用于人，指不用别人提醒而主动去做；门自己关上要用自动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26520, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一个很自觉得学生。", "corrected_sentence": "他是一个很自觉的学生。", "error_description": "形容词「自觉」修饰名词时要用「的」，不用「得」；「得」用于补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26520, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他自觉得遵守纪律。", "corrected_sentence": "他自觉地遵守纪律。", "error_description": "表示动作的方式时，「自觉」后应用「地」，不用「得」；「得」用于补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
