INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26522, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个村子，是中国最基层的行政单位。", "primary_collocate": null, "pronunciation": "xíng zhèng cūn", "ipa": "ɕiŋ˧˥ ʈʂɤŋ˥˩ tsʰwn˥", "syllable_count": 3, "sentences": [{"text": "行政村是中国最基层的行政单位。", "target_word": "行政村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们行政村的村长。", "target_word": "行政村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行政村的办公室就在学校旁边。", "target_word": "行政村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行政村有三百多户人家。", "target_word": "行政村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民去行政村办公室开证明。", "target_word": "行政村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "镇政府每个月到行政村检查工作。", "target_word": "行政村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年我们行政村新建了图书室。", "target_word": "行政村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们行政村离县城二十公里。", "target_word": "行政村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们行政村的名字叫“李家庄”。", "target_word": "行政村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行政村的年轻人大多去城里工作了。", "target_word": "行政村", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "中国最基层的行政单位，一个村子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25e7a64-8d32-41c0-a4a3-43a2e96bdbc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26522, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行政村", "is_correct": true, "explanation": "正确：“行政村”是中国最基层的行政单位，与句中的定义相合。"}, {"text": "公司", "is_correct": false, "explanation": "搭配：“行政单位”指政府机关等单位，公司不属于行政单位。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是事业单位，不是最基层的行政单位。"}, {"text": "县", "is_correct": false, "explanation": "语义：县比乡镇大，不是最基层的行政单位，与“最基层”的说法矛盾。"}], "explanations": {"行政村": "正确：“行政村”是中国最基层的行政单位，与句中的定义相合。", "公司": "搭配：“行政单位”指政府机关等单位，公司不属于行政单位。", "学校": "语义：学校是事业单位，不是最基层的行政单位。", "县": "语义：县比乡镇大，不是最基层的行政单位，与“最基层”的说法矛盾。"}, "sentence_index": 0, "correct_answer": "行政村"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从行政村毕业后回到了家乡。", "explanation": "这里应该用〈学校〉。毕业是学生在学校完成学业；行政村是基层行政单位，不能用来指毕业。"}, {"text": "这个行政村判决了那起离婚案。", "explanation": "这里应该用〈法院〉。判决是法院对案件作出的裁决；行政村是基层行政单位，不能判决案件。"}, {"text": "这个行政村发行了一种新的货币。", "explanation": "这里应该用〈中央银行〉。发行货币是中央银行的职能；行政村不发行货币。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26522, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行政村", "is_correct": true, "explanation": "正确：“行政村”是可以新建图书室的基层单位，与“今年”“新建”的语境相合。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是个人物品，不能新建图书室。"}, {"text": "水库", "is_correct": false, "explanation": "语义：水库是水利设施，不能用来新建图书室，句子语义不通。"}, {"text": "鱼塘", "is_correct": false, "explanation": "配价：“新建”的施事应是能进行建设的单位或机构，鱼塘不能充当这一角色。"}], "explanations": {"行政村": "正确：“行政村”是可以新建图书室的基层单位，与“今年”“新建”的语境相合。", "手机": "语义：手机是个人物品，不能新建图书室。", "水库": "语义：水库是水利设施，不能用来新建图书室，句子语义不通。", "鱼塘": "配价：“新建”的施事应是能进行建设的单位或机构，鱼塘不能充当这一角色。"}, "sentence_index": 6, "correct_answer": "行政村"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个行政村招收了一万名新生。", "explanation": "这里应该用〈大学〉。招收新生是学校的职能；行政村不招生。"}, {"text": "这个行政村去年在海外上市了。", "explanation": "这里应该用〈公司〉。上市是企业的行为；行政村不是企业，不能上市。"}, {"text": "这个行政村每天营业到晚上十点。", "explanation": "这里应该用〈超市〉。营业用于商店、企业；行政村是基层行政单位，不说营业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26522, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位行政村有四百多户人家。", "corrected_sentence": "这个行政村有四百多户人家。", "error_description": "量词错误：行政村应使用量词“个”，“位”只用于人，不能用于村。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26522, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每年都这个行政村种很多果树。", "corrected_sentence": "他每年都在这个行政村种很多果树。", "error_description": "漏掉介词“在”：表示地点的状语要用“在”引出，应说“他每年都在这个行政村种很多果树”，不能省略“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
