INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26524, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "一个地方只属于某个地区的特点。", "primary_collocate": null, "pronunciation": "qū yù xìng", "ipa": "tɕʰy˥ y˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这种方言有很强的区域性。", "target_word": "区域性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日有区域性，只在北方过。", "target_word": "区域性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饮食的区域性很明显，南方人爱吃甜的。", "target_word": "区域性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花有区域性，别的地方很难见到。", "target_word": "区域性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个习惯有区域性，不是每个地方都有。", "target_word": "区域性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这个词的区域性很强。", "target_word": "区域性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南北方的口音都有区域性。", "target_word": "区域性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种天气现象有区域性，不会到处发生。", "target_word": "区域性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在书里学到了语言的区域性。", "target_word": "区域性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个风俗的区域性让它很特别。", "target_word": "区域性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "區域性", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物只属于某个地方的特点，如方言、饮食、风俗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25e7a64-8d32-41c0-a4a3-43a2e96bdbc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26524, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "区域性", "is_correct": true, "explanation": "正确：“很强的区域性”指方言只属于某个地区的特点，符合句意。"}, {"text": "传染性", "is_correct": false, "explanation": "语义：方言不会传播疾病，“传染性”只用于疾病等事物。"}, {"text": "观赏性", "is_correct": false, "explanation": "搭配：“观赏性”多修饰花木、景观、表演，不用来形容方言。"}, {"text": "季节性", "is_correct": false, "explanation": "语义：方言不随季节出现或消失，“季节性”不能用来形容方言。"}], "explanations": {"区域性": "正确：“很强的区域性”指方言只属于某个地区的特点，符合句意。", "传染性": "语义：方言不会传播疾病，“传染性”只用于疾病等事物。", "观赏性": "搭配：“观赏性”多修饰花木、景观、表演，不用来形容方言。", "季节性": "语义：方言不随季节出现或消失，“季节性”不能用来形容方言。"}, "sentence_index": 0, "correct_answer": "区域性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个道理很有区域性，适用于所有人。", "explanation": "这里应该用〈普遍性〉。区域性指事物只属于某地，不指适用于各处；说适用于所有人要用“普遍性”。"}, {"text": "这门课很有区域性，要学好几年。", "explanation": "这里应该用〈专业性〉。区域性指事物只属于某地，不指课程的专门程度。"}, {"text": "这道题很有区域性，难度很高。", "explanation": "这里应该用〈挑战性〉。区域性指事物只属于某地，不指题目的难度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26524, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "区域性", "is_correct": true, "explanation": "正确：“口音都有区域性”指口音只属于南北方的某一地区，符合句意。"}, {"text": "时效性", "is_correct": false, "explanation": "语义：口音没有新鲜程度之分，“时效性”不能用来形容口音。"}, {"text": "危险性", "is_correct": false, "explanation": "语义：口音不会造成伤害，“危险性”说的是可能造成危害的性质。"}, {"text": "学术性", "is_correct": false, "explanation": "语域：“学术性”是书面的专业用语，不用来形容日常口音。"}], "explanations": {"区域性": "正确：“口音都有区域性”指口音只属于南北方的某一地区，符合句意。", "时效性": "语义：口音没有新鲜程度之分，“时效性”不能用来形容口音。", "危险性": "语义：口音不会造成伤害，“危险性”说的是可能造成危害的性质。", "学术性": "语域：“学术性”是书面的专业用语，不用来形容日常口音。"}, "sentence_index": 6, "correct_answer": "区域性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的区域性很高，工人可以放心操作。", "explanation": "这里应该用〈安全性〉。区域性指特点只属于某地，不指机器的安全程度，要说“安全性很高”。"}, {"text": "这套方案的区域性很好，成本很低。", "explanation": "这里应该用〈经济性〉。区域性不指成本高低，要说“经济性好”。"}, {"text": "这套系统的区域性很强，可以随时调整。", "explanation": "这里应该用〈灵活性〉。区域性不指系统能否灵活调整。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26524, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种菜有区域性很强。", "corrected_sentence": "这种菜的区域性很强。", "error_description": "句式杂糅：“有区域性”与“区域性很强”混在一起。应说“这种菜的区域性很强”或“这种菜有很强的区域性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26524, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要研究这个地方的很区域性特点。", "corrected_sentence": "我们要研究这个地方的区域性特点。", "error_description": "多余成分：“区域性”是名词，前面不能加程度副词“很”修饰。应说“这个地方的区域性特点”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
