INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26526, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水源是水开始流出来的地方。", "primary_collocate": null, "pronunciation": "shuǐ yuán", "ipa": "ʂweɪ˨˩˦ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这条小河的水源在山上。", "target_word": "水源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们走到山里，看见了水源。", "target_word": "水源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水源很干净，可以喝。", "target_word": "水源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里没有水源，种不了菜。", "target_word": "水源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小河的水源是一个小湖。", "target_word": "水源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸带我去看河的水源。", "target_word": "水源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "村里人都去山上的水源打水。", "target_word": "水源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天雪化了，水源的水变多了。", "target_word": "水源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "找到水源，我们就有水喝了。", "target_word": "水源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人说，这个水源从来没干过。", "target_word": "水源", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "处", "label": "量词"}, {"form": "水源地", "label": "复合词"}], "register": "中性", "sense_fingerprint": "水最开始流出来的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fb8b2f-b472-4aa2-8a65-2e4c070b5208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26526, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水源", "is_correct": true, "explanation": "与“在山上”搭配，指小河水流开始的地方，符合句意。"}, {"text": "水费", "is_correct": false, "explanation": "语义：“水费”是用水的费用，不是地点，“这条小河的水费在山上”说不通。"}, {"text": "水质", "is_correct": false, "explanation": "搭配：“水质”是水的品质，不能说“在山上”。"}, {"text": "河口", "is_correct": false, "explanation": "语义：“河口”是河流入海的地方，不在山上，与“小河的起点”相反。"}], "explanations": {"水源": "与“在山上”搭配，指小河水流开始的地方，符合句意。", "水费": "语义：“水费”是用水的费用，不是地点，“这条小河的水费在山上”说不通。", "水质": "搭配：“水质”是水的品质，不能说“在山上”。", "河口": "语义：“河口”是河流入海的地方，不在山上，与“小河的起点”相反。"}, "sentence_index": 0, "correct_answer": "水源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河的水源在大海边。", "explanation": "这里应该用〈河口〉。河口是河流入海的地方，水源是水开始流出的地方。"}, {"text": "这片大水源能养很多鱼。", "explanation": "这里应该用〈水库〉。水库是能养鱼的水域，水源指水流出的地方，不是水域。"}, {"text": "这条河的水源很宽，能行船。", "explanation": "这里应该用〈河面〉。宽、能行船说的是河面，水源只是水开始流出的地方，不说宽窄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26526, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水源", "is_correct": true, "explanation": "与“去山上”“打水”搭配，指取水的来源，符合句意。"}, {"text": "水位", "is_correct": false, "explanation": "语义：“水位”指水面的高度，不是取水的地点，不能用“去……打水”。"}, {"text": "水费", "is_correct": false, "explanation": "语义：“水费”是用水的费用，不是地点，与“去山上”不搭。"}, {"text": "水泥", "is_correct": false, "explanation": "搭配：“打水”取的是水，水泥不能用来打水，与动词“打”不搭。"}], "explanations": {"水源": "与“去山上”“打水”搭配，指取水的来源，符合句意。", "水位": "语义：“水位”指水面的高度，不是取水的地点，不能用“去……打水”。", "水费": "语义：“水费”是用水的费用，不是地点，与“去山上”不搭。", "水泥": "搭配：“打水”取的是水，水泥不能用来打水，与动词“打”不搭。"}, "sentence_index": 6, "correct_answer": "水源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路的水源在车站。", "explanation": "这里应该用〈终点〉。终点是路的末端，水源是开始的地方。"}, {"text": "这个水源的年龄很大，已经一百年了。", "explanation": "这里应该用〈历史〉。水源是地点，说它存在了多久要用〈历史〉，不能用岁数来形容地点。"}, {"text": "这个水源的价格很贵，一个月要交五百块。", "explanation": "这里应该用〈水费〉。水费是用水的价格，水源是地方，没有价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雪山上有一座水源，流下来的水很清。", "corrected_sentence": "雪山上有一处水源，流下来的水很清。", "error_description": "量词错误：“水源”作地点用“处”；“座”多用于山、楼、桥等大型物体，不用于水源。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山脚下有一根水源，大家都去那里打水。", "corrected_sentence": "山脚下有一处水源，大家都去那里打水。", "error_description": "量词错误：“水源”作地点，应说“一处水源”；“根”用于细长的东西，不用于水源。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
