INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26528, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "志愿者是自愿帮助别人的人。", "primary_collocate": null, "pronunciation": "zhì yuàn zhě", "ipa": "ʈʂɻ̩⁵¹ ɥɛn⁵¹ ʈʂɤ²¹⁴", "syllable_count": 3, "sentences": [{"text": "志愿者不拿工资，只是自愿帮助别人。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，很多志愿者赶到了现场。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个志愿者会说英语，所以带外国游客参观。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周六早上，志愿者在公园里捡垃圾。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是图书馆的志愿者，每周来两次。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者小王把书送到了山区学校。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马拉松比赛中，志愿者给跑步的人发水。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们社区需要志愿者来照顾孤单的老人。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做志愿者不是为了钱，是为了帮助别人。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "穿红衣服的志愿者站在车站，告诉旅客怎么走。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "志愿者们", "label": "复数"}], "register": "中性", "sense_fingerprint": "自愿帮助别人、不拿工资的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb894594-6404-49e9-b276-afb1f1d52d67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26528, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "志愿者", "is_correct": true, "explanation": "志愿者：不拿工资、自愿帮助别人的人，与句意相符。"}, {"text": "员工", "is_correct": false, "explanation": "语义：员工领工资，与“不拿工资”的句意相矛盾。"}, {"text": "机器人", "is_correct": false, "explanation": "语义：机器人不能自愿帮助别人，与“自愿”的句意不符。"}, {"text": "保姆", "is_correct": false, "explanation": "搭配：保姆通常是有偿雇用的，与“自愿”“不拿工资”搭配不当。"}], "explanations": {"志愿者": "志愿者：不拿工资、自愿帮助别人的人，与句意相符。", "员工": "语义：员工领工资，与“不拿工资”的句意相矛盾。", "机器人": "语义：机器人不能自愿帮助别人，与“自愿”的句意不符。", "保姆": "搭配：保姆通常是有偿雇用的，与“自愿”“不拿工资”搭配不当。"}, "sentence_index": 0, "correct_answer": "志愿者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周六早上，志愿者在公园里捡垃圾，按月领工资。", "explanation": "这里应该用〈环卫工人〉。志愿者不取报酬，按月领工资、负责清扫的人要用环卫工人。"}, {"text": "周六早上，一只志愿者在公园里捡垃圾。", "explanation": "量词错误：这里应该用〈位〉或〈名〉。“只”多用于动物或成对物品中的一个，指人不用“只”。"}, {"text": "志愿者每月领固定工资，在机关上班。", "explanation": "这里应该用〈公务员〉。志愿者不取报酬，领固定工资、在机关任职的人要用公务员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26528, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "志愿者", "is_correct": true, "explanation": "志愿者：在比赛中给跑步的人发水的服务人员，与句意相符。"}, {"text": "售票员", "is_correct": false, "explanation": "语义：售票员在售票窗口工作，不在马拉松赛场给跑步的人发水，与句意不符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能给人发水，与句意矛盾。"}, {"text": "饮料", "is_correct": false, "explanation": "配价：“发”的施事必须是人，饮料不能给跑步的人发水。"}], "explanations": {"志愿者": "志愿者：在比赛中给跑步的人发水的服务人员，与句意相符。", "售票员": "语义：售票员在售票窗口工作，不在马拉松赛场给跑步的人发水，与句意不符。", "石头": "语义：石头不能给人发水，与句意矛盾。", "饮料": "配价：“发”的施事必须是人，饮料不能给跑步的人发水。"}, "sentence_index": 6, "correct_answer": "志愿者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不想去，可是公司逼他当志愿者。", "explanation": "这里不能用〈志愿者〉。志愿者是自愿的，被逼去做事的人不是志愿者。"}, {"text": "房东每月按时收房租，志愿者每月按时收房租，不肯便宜一分钱。", "explanation": "这里应该用〈出租人〉。志愿者不以营利为目的，不向他人收费；收房租的人是出租人。"}, {"text": "老板每个月给志愿者发很高的工资。", "explanation": "这里应该用〈员工〉。志愿者不拿工资，每月领工资的人要用员工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26528, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是社区的志愿者们。", "corrected_sentence": "她是社区的志愿者。", "error_description": "“们”只用于表示复数，这里指一个人，应说“志愿者”，不能说“志愿者们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26528, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一条志愿者。", "corrected_sentence": "他是一名志愿者。", "error_description": "量词错误：指人的“志愿者”应说“名”或“位”，“条”用于细长的东西，不能用于人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26532, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上升", "is_correct": true, "explanation": "正确。“上升”指从低往高移动，与“下跌”的从上往下移动相反。"}, {"text": "保持", "is_correct": false, "explanation": "“保持”指维持原状，不表示与下跌方向相反的移动。"}, {"text": "出现", "is_correct": false, "explanation": "“出现”指显现，与物体下落没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”指加入某项活动，与物体移动无关。"}], "correct_answer": "上升", "explanations": {"上升": "正确。“上升”指从低往高移动，与“下跌”的从上往下移动相反。", "保持": "“保持”指维持原状，不表示与下跌方向相反的移动。", "出现": "“出现”指显现，与物体下落没有反义关系。", "参加": "“参加”指加入某项活动，与物体移动无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26532, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上升", "is_correct": true, "explanation": "正确。“上升”指从低往高移动，与“下跌”的从上往下移动相反。"}, {"text": "继续", "is_correct": false, "explanation": "“继续”指接着进行下去，与下落的运动没有反义关系。"}, {"text": "诞生", "is_correct": false, "explanation": "“诞生”指事物开始出现，与物体下落没有反义关系。"}, {"text": "入睡", "is_correct": false, "explanation": "“入睡”指进入睡眠状态，与物体移动无关。"}], "correct_answer": "上升", "explanations": {"上升": "正确。“上升”指从低往高移动，与“下跌”的从上往下移动相反。", "继续": "“继续”指接着进行下去，与下落的运动没有反义关系。", "诞生": "“诞生”指事物开始出现，与物体下落没有反义关系。", "入睡": "“入睡”指进入睡眠状态，与物体移动无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26532, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从上往下移动。", "primary_collocate": null, "pronunciation": "xià diē", "ipa": "ɕja˥˩ tje˥", "syllable_count": 2, "sentences": [{"text": "飞机突然下跌了几百米。", "target_word": "下跌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电梯突然下跌，大家都叫了起来。", "target_word": "下跌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热气球漏了气，慢慢向地面下跌。", "target_word": "下跌", "complexity_tier": "T3", "furigana": "xià diē", "sentence_source": "generated"}, {"text": "跳伞员没打开伞，身体快速下跌。", "target_word": "下跌", "complexity_tier": "T3", "furigana": "xià diē", "sentence_source": "generated"}, {"text": "一块石头从崖顶下跌，掉进了河里。", "target_word": "下跌", "complexity_tier": "T3", "furigana": "xià diē", "sentence_source": "generated"}, {"text": "风停以后，风筝开始向地面下跌。", "target_word": "下跌", "complexity_tier": "T3", "furigana": "xià diē", "sentence_source": "generated"}, {"text": "飞机遇到强气流，一下子下跌了。", "target_word": "下跌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吊篮的绳子断了，吊篮急速下跌。", "target_word": "下跌", "complexity_tier": "T3", "furigana": "xià diē", "sentence_source": "generated"}, {"text": "游乐设备的座椅突然下跌，乘客大叫。", "target_word": "下跌", "complexity_tier": "T3", "furigana": "xià diē", "sentence_source": "generated"}, {"text": "屋顶的积雪突然下跌，差点砸到人。", "target_word": "下跌", "complexity_tier": "T3", "furigana": "xià diē", "sentence_source": "generated"}], "morphological_forms": [{"form": "下跌了", "label": "体标"}, {"form": "下跌过", "label": "体标"}], "register": "中性", "sense_fingerprint": "下跌|物体从上往下移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fb8b2f-b472-4aa2-8a65-2e4c070b5208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26532, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下跌", "is_correct": true, "explanation": "正确。“突然下跌了几百米”指飞机从高处急速向下移动，符合句意。"}, {"text": "咆哮", "is_correct": false, "explanation": "语义：“咆哮”指发出巨大的吼声，与飞机移动的距离无关。"}, {"text": "旋转", "is_correct": false, "explanation": "配价：“旋转”不带“几百米”这样的距离宾语，不能说旋转了几百米。"}, {"text": "倾斜", "is_correct": false, "explanation": "配价：“倾斜”描写物体的角度，不说倾斜了几百米。"}], "explanations": {"下跌": "正确。“突然下跌了几百米”指飞机从高处急速向下移动，符合句意。", "咆哮": "语义：“咆哮”指发出巨大的吼声，与飞机移动的距离无关。", "旋转": "配价：“旋转”不带“几百米”这样的距离宾语，不能说旋转了几百米。", "倾斜": "配价：“倾斜”描写物体的角度，不说倾斜了几百米。"}, "sentence_index": 0, "correct_answer": "下跌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从楼梯上下跌，摔伤了腿。", "explanation": "这里应该用〈摔下来〉。人从楼梯上摔落要说“摔下来”，“下跌”不用于人摔倒。"}, {"text": "飞机平稳地下跌在跑道上。", "explanation": "这里应该用〈降落〉。飞机平稳着陆要说“降落”，“下跌”强调从高处快速向下掉落，与平稳着陆的语境不符。"}, {"text": "小孩在操场上奔跑时下跌了。", "explanation": "这里应该用〈跌倒〉。人在平地上摔倒要说“跌倒”，“下跌”不用于人在平地摔倒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26532, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下跌", "is_correct": true, "explanation": "正确。“一下子下跌了”描写飞机遇到气流后急速向下，符合句意。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指固体因受热变为液体，不能用于描述飞机的移动。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：“发芽”指植物长出新芽，与飞机的运动无关。"}, {"text": "增长", "is_correct": false, "explanation": "搭配：“增长”多用于数量或能力，不说飞机一下子增长了。"}], "explanations": {"下跌": "正确。“一下子下跌了”描写飞机遇到气流后急速向下，符合句意。", "融化": "语义：“融化”指固体因受热变为液体，不能用于描述飞机的移动。", "发芽": "语义：“发芽”指植物长出新芽，与飞机的运动无关。", "增长": "搭配：“增长”多用于数量或能力，不说飞机一下子增长了。"}, "sentence_index": 6, "correct_answer": "下跌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "苹果熟了，从树上下跌到地上。", "explanation": "这里应该用〈掉〉。果子从树上落下要说“掉”，“下跌”不用于这种日常小物体的落下。"}, {"text": "这个班的学生人数下跌了三个。", "explanation": "这里应该用〈减少〉。下跌多用于价格、股价，人数的减少要用“减少”。"}, {"text": "他把书下跌在桌子上。", "explanation": "这里应该用〈放〉。“下跌”是不及物动词，不能带“把”字宾语；把东西放到某处要用“放”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26532, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "热气球向地面下跌着几十米。", "corrected_sentence": "热气球向地面下跌了几十米。", "error_description": "动态助词错误：表示下跌已经完成的位移应用“了”，不能用“着”。“着”表示动作的持续状态，与“下跌了几十米”的完成义不符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26532, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨伞突然被下跌，把他吓了一跳。", "corrected_sentence": "雨伞突然下跌，把他吓了一跳。", "error_description": "被字句错误：“下跌”是不及物动词，不能加“被”构成被动句，应说“雨伞突然下跌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
