INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26534, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "水没有了，或者东西用完了。", "primary_collocate": null, "pronunciation": "kū jié", "ipa": "kʰu˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "夏天太热，湖里的水慢慢枯竭了。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这口老井的水早就枯竭了。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球上的石油不是无限的，终会枯竭。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河流枯竭后，农民没有水浇地。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乱用水的话，水源会很快枯竭。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的小溪在冬天枯竭了。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的天然气快要枯竭了。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂用水太多，附近的泉水枯竭了。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，资源枯竭是大问题。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "池塘枯竭了，里面的鱼都死了。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "枯竭了", "label": "体标"}, {"form": "枯竭过", "label": "体标"}], "register": "中性", "sense_fingerprint": "水没有了或东西用完了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb894594-6404-49e9-b276-afb1f1d52d67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26534, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "枯竭", "is_correct": true, "explanation": "正确：“水慢慢枯竭了”与“夏天太热”的因果相合，表示水没有了。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：句中是“夏天太热”，湖水不会在夏天结冰，与前文矛盾。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：水遇冷才会凝固，句中是“夏天太热”，湖水不会凝固，与前文矛盾。"}, {"text": "沸腾", "is_correct": false, "explanation": "语义：“慢慢”与“沸腾”的剧烈、急促义相矛盾，湖水不会因为天热而慢慢沸腾。"}], "explanations": {"枯竭": "正确：“水慢慢枯竭了”与“夏天太热”的因果相合，表示水没有了。", "结冰": "语义：句中是“夏天太热”，湖水不会在夏天结冰，与前文矛盾。", "凝固": "语义：水遇冷才会凝固，句中是“夏天太热”，湖水不会凝固，与前文矛盾。", "沸腾": "语义：“慢慢”与“沸腾”的剧烈、急促义相矛盾，湖水不会因为天热而慢慢沸腾。"}, "sentence_index": 0, "correct_answer": "枯竭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种动物已经枯竭了。", "explanation": "这里应该用〈灭绝〉。枯竭指水没有了或东西用完了，物种消失应说灭绝。"}, {"text": "这棵花因为缺水已经枯竭了。", "explanation": "这里应该用〈枯萎〉。枯竭不用于植物凋谢，植物失水凋谢应说枯萎。"}, {"text": "这块冰已经枯竭了。", "explanation": "这里应该用〈融化〉。枯竭不用于固体受热变成液体，冰受热应说融化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26534, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "枯竭", "is_correct": true, "explanation": "正确：“天然气快要枯竭了”表示资源即将用尽，符合句意。"}, {"text": "枯萎", "is_correct": false, "explanation": "搭配：“枯萎”指植物失水凋谢，天然气不会枯萎。"}, {"text": "沉淀", "is_correct": false, "explanation": "搭配：“沉淀”指悬浮物下沉，气体不会沉淀。"}, {"text": "消融", "is_correct": false, "explanation": "语义：“消融”指冰雪等固体慢慢变成液体或消散，天然气不会消融，句意不符。"}], "explanations": {"枯竭": "正确：“天然气快要枯竭了”表示资源即将用尽，符合句意。", "枯萎": "搭配：“枯萎”指植物失水凋谢，天然气不会枯萎。", "沉淀": "搭配：“沉淀”指悬浮物下沉，气体不会沉淀。", "消融": "语义：“消融”指冰雪等固体慢慢变成液体或消散，天然气不会消融，句意不符。"}, "sentence_index": 6, "correct_answer": "枯竭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片雾已经枯竭了。", "explanation": "这里应该用〈散去〉。枯竭指水没有了或东西用完了，雾气消散应说散去。"}, {"text": "黑夜已经枯竭了。", "explanation": "这里应该用〈结束〉。枯竭指水没有了或东西用完了，黑夜过去应说结束。"}, {"text": "气温已经枯竭了。", "explanation": "这里应该用〈下降〉。枯竭指水或东西用完，气温降低应说下降。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这眼泉的水已经被枯竭了。", "corrected_sentence": "这眼泉的水已经枯竭了。", "error_description": "错误在于多加了“被”。“枯竭”是不及物动词，不能构成被动句，应说“泉水已经枯竭了”，不说“被枯竭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "抽水太多，地下的水会慢慢枯竭过。", "corrected_sentence": "抽水太多，地下的水会慢慢枯竭。", "error_description": "体标错误：“会”表示将来，与表示经历的“过”矛盾，应去掉“过”，说“会慢慢枯竭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
