INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26536, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很陡很陡的山崖。", "primary_collocate": null, "pronunciation": "duàn yá", "ipa": "tuan˥˩ ja˧˥", "syllable_count": 2, "sentences": [{"text": "这座山有一面很高的断崖。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着断崖边的小路走。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "断崖太陡，没有人能爬上去。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在断崖前停了下来。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "断崖上长着几棵小松树。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子离断崖太近，妈妈很担心。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从断崖上往下看，什么都看不清。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水从断崖上流下来，变成了瀑布。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，断崖上全是白雪。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面是断崖，车不能再开了。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一处断崖", "label": "量词"}, {"form": "斷崖", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很陡的山崖", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb894594-6404-49e9-b276-afb1f1d52d67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26536, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "断崖", "is_correct": true, "explanation": "正确：“一面很高的断崖”指陡峭的山崖，与“很高”“一面”搭配自然。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是水道，不是可以量为“一面”、说“很高”的山体。"}, {"text": "草地", "is_correct": false, "explanation": "搭配：草地一般平坦，不说“很高的草地”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是山的一面，“一面很高的天空”句意不通。"}], "explanations": {"断崖": "正确：“一面很高的断崖”指陡峭的山崖，与“很高”“一面”搭配自然。", "河流": "语义：河流是水道，不是可以量为“一面”、说“很高”的山体。", "草地": "搭配：草地一般平坦，不说“很高的草地”。", "天空": "语义：天空不是山的一面，“一面很高的天空”句意不通。"}, "sentence_index": 0, "correct_answer": "断崖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在断崖勒马，及时改正了错误。", "explanation": "这里应该用〈悬崖〉。“悬崖勒马”是固定说法，“断崖”不能用于此固定搭配。"}, {"text": "妈妈把鸡蛋放进断崖里煮。", "explanation": "这里应该用〈锅〉。断崖是山崖，不是容器，煮东西要用锅。"}, {"text": "溪水在断崖里奔流，声音很大。", "explanation": "这里应该用〈峡谷〉。断崖指很陡的山崖本身，不是能容纳溪水奔流的空间；溪水奔流的谷地要说峡谷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26536, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "断崖", "is_correct": true, "explanation": "正确：“从断崖上往下看”，断崖是可以站立并俯视的高处。"}, {"text": "地图", "is_correct": false, "explanation": "搭配：“地图上”只能说“在地图上看”，不能说“从地图上往下看”。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：海浪是流动的水，不能作为人站立俯视的高处。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不能作为俯视的高处，句意不通。"}], "explanations": {"断崖": "正确：“从断崖上往下看”，断崖是可以站立并俯视的高处。", "地图": "搭配：“地图上”只能说“在地图上看”，不能说“从地图上往下看”。", "海浪": "语义：海浪是流动的水，不能作为人站立俯视的高处。", "饼干": "语义：饼干不能作为俯视的高处，句意不通。"}, "sentence_index": 6, "correct_answer": "断崖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司陷入断崖，濒临破产。", "explanation": "这里应该用〈深渊〉。断崖指很陡的山崖，比喻困境时不能说“陷入断崖”，要说“陷入深渊”。"}, {"text": "断崖从山顶倾泻而下，像一道白练。", "explanation": "这里应该用〈瀑布〉。断崖是静止的山崖，不会倾泻；水从高处流下形成白练要说瀑布。"}, {"text": "谈判陷入断崖，双方都很焦虑。", "explanation": "这里应该用〈僵局〉。断崖指很陡的山崖，比喻困境时不能说“陷入断崖”；谈判陷入停滞要说“陷入僵局”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "游客把断崖边拍照。", "corrected_sentence": "游客在断崖边拍照。", "error_description": "“把”字句误用：“拍照”的处所应由“在”引出，“把”后不能接处所，应说“游客在断崖边拍照”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "前面有一只断崖，大家只好绕路。", "corrected_sentence": "前面有一道断崖，大家只好绕路。", "error_description": "量词错误：断崖是地形，应说“一道断崖”或“一处断崖”；“只”多用于动物或船、鞋等单个器物，不能用于断崖。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
