INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26538, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26538, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有些东西在某个时候会有，其他时候没有，比如冬天很冷，夏天很热。", "primary_collocate": null, "pronunciation": "jì jié xìng", "ipa": "tɕi˥˩ tɕje˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这种花是季节性的，只有春天有。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "季节性的水果，过了夏天就没有了。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做季节性工作，冬天不上班。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边的生意有季节性，夏天最好。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家冰淇淋店有很强的季节性。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "季节性的菜，一年只能吃几个月。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的雨有季节性，夏天下得多。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条小河是季节性的，冬天没有水。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "感冒有季节性，冬天得病的人最多。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的鸟是季节性的，春天才来。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "季節性", "label": "繁体"}], "register": "中性", "sense_fingerprint": "随季节变化，有的时候有、有的时候没有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fb8b2f-b472-4aa2-8a65-2e4c070b5208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26538, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "季节性", "is_correct": true, "explanation": "正确。“季节性的”指只在某个时候才有，与“只有春天有”相合。"}, {"text": "常年性", "is_correct": false, "explanation": "语义：“常年性”指全年都有，与“只有春天有”相矛盾。"}, {"text": "永久性", "is_correct": false, "explanation": "语义：“永久性”指长久不变，与“只有春天有”的时限矛盾。"}, {"text": "长久性", "is_correct": false, "explanation": "搭配：“长久性”多用于关系、制度，不用来形容花的开放时间。"}], "explanations": {"季节性": "正确。“季节性的”指只在某个时候才有，与“只有春天有”相合。", "常年性": "语义：“常年性”指全年都有，与“只有春天有”相矛盾。", "永久性": "语义：“永久性”指长久不变，与“只有春天有”的时限矛盾。", "长久性": "搭配：“长久性”多用于关系、制度，不用来形容花的开放时间。"}, "sentence_index": 0, "correct_answer": "季节性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂季节性检修，每个月都一样。", "explanation": "这里应该用〈定期〉。季节性指只在一定时期出现，每个月都检修的安排要说“定期”。"}, {"text": "这家店季节性营业，全年都开门。", "explanation": "这里应该用〈常年〉。季节性指只在一定时期出现，全年都开门的营业要说“常年”。"}, {"text": "这位老师的讲课风格是季节性的，一年四季都一样。", "explanation": "这里应该用〈一贯〉。季节性指只在一定时期出现，一年四季都一样的风格要说“一贯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26538, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "季节性", "is_correct": true, "explanation": "正确。“有季节性”指雨水只在某些时期多，与“夏天下得多”相合。"}, {"text": "恒定性", "is_correct": false, "explanation": "语义：“恒定性”指始终如一，与“夏天下得多”的时段差异矛盾。"}, {"text": "偶然性", "is_correct": false, "explanation": "语义：“偶然性”指偶尔发生，与“夏天下得多”的规律性不符。"}, {"text": "永恒性", "is_correct": false, "explanation": "搭配：“永恒性”多用于抽象事物或感情，不说雨水有永恒性。"}], "explanations": {"季节性": "正确。“有季节性”指雨水只在某些时期多，与“夏天下得多”相合。", "恒定性": "语义：“恒定性”指始终如一，与“夏天下得多”的时段差异矛盾。", "偶然性": "语义：“偶然性”指偶尔发生，与“夏天下得多”的规律性不符。", "永恒性": "搭配：“永恒性”多用于抽象事物或感情，不说雨水有永恒性。"}, "sentence_index": 6, "correct_answer": "季节性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位工人在这里有季节性工作，每天都来。", "explanation": "这里应该用〈固定〉。季节性指只在一定时期出现，每天都来的工作要说“固定”。"}, {"text": "这里的护士是季节性的，一年四季都在。", "explanation": "这里应该用〈常驻〉。季节性指只在一定时期出现，一年四季都在的人员要说“常驻”。"}, {"text": "这班公交车是季节性发车的，一年四季都运行。", "explanation": "这里应该用〈常年〉。季节性指只在一定时期出现，一年四季都运行的班次要说“常年”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店的客流季节性强很，冬天人很少。", "corrected_sentence": "这家店的客流季节性很强，冬天人很少。", "error_description": "语序错误：“很”修饰形容词，应放在“强”前，说“季节性很强”，不能说“季节性强很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种虫子只在夏天被季节性地出现。", "corrected_sentence": "这种虫子只在夏天季节性地出现。", "error_description": "被字句错误：“季节性地出现”中的“出现”是不及物动词，不能加“被”，应去掉“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
