INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26540, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大家轮流做一件事，比如今天你值班，明天我值班。", "primary_collocate": null, "pronunciation": "lún zhí", "ipa": "lu̯ən³⁵ ʈʂɻ̩³⁵", "syllable_count": 2, "sentences": [{"text": "室友们轮值做饭，今天轮到我。", "target_word": "轮值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每天轮值，今天是你，明天是我。", "target_word": "轮值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让学生每天两人一组轮值擦黑板。", "target_word": "轮值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里三个孩子轮值洗碗，谁也不能偷懒。", "target_word": "轮值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室的同事轮值接电话，每人一天。", "target_word": "轮值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们轮值守夜，让别人好好睡觉。", "target_word": "轮值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天谁轮值，谁就早点来开门。", "target_word": "轮值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这周我轮值，所以不能出去玩。", "target_word": "轮值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者轮值，每天都有人看着图书角。", "target_word": "轮值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士们分成三组轮值，白天晚上都有人在。", "target_word": "轮值", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "轮值了", "label": "体标"}, {"form": "轮值过", "label": "体标"}, {"form": "轮值着", "label": "体标"}], "register": "中性", "sense_fingerprint": "大家轮流值班或做某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb894594-6404-49e9-b276-afb1f1d52d67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26540, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "轮值", "is_correct": true, "explanation": "正确。轮值指大家按顺序担任，与“今天轮到我”相符。"}, {"text": "包揽", "is_correct": false, "explanation": "语义：“包揽”指全部承担，与“今天轮到我”矛盾。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”的对象是人或成果，不能说“赞美做饭”这一动作。"}, {"text": "耕种", "is_correct": false, "explanation": "语义：“耕种”指种地，与做饭无关。"}], "explanations": {"轮值": "正确。轮值指大家按顺序担任，与“今天轮到我”相符。", "包揽": "语义：“包揽”指全部承担，与“今天轮到我”矛盾。", "赞美": "搭配：“赞美”的对象是人或成果，不能说“赞美做饭”这一动作。", "耕种": "语义：“耕种”指种地，与做饭无关。"}, "sentence_index": 0, "correct_answer": "轮值"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间教室的灯轮值亮着，灭了一盏就换另一盏。", "explanation": "这里应该用〈轮换〉。轮值指人员按顺序担任职务，不用于物件之间的交替。"}, {"text": "这次由新软件轮值了旧系统。", "explanation": "这里应该用〈替代〉。轮值指人员按顺序担任，不能表示用一物取代另一物。"}, {"text": "这学期，他一个人轮值了全部打扫工作。", "explanation": "这里应该用〈包揽〉。轮值要求大家按顺序担任，一个人全包时不用轮值。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26540, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轮值", "is_correct": true, "explanation": "正确。轮值指按顺序担任，与“谁就早点来开门”的安排相符。"}, {"text": "请假", "is_correct": false, "explanation": "语义：“请假”指不来上班，与“早点来开门”矛盾。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：“旅游”与值班无关，也与“早点来开门”不符。"}, {"text": "报销", "is_correct": false, "explanation": "语义：“报销”指核销费用，与值班、开门无关。"}], "explanations": {"轮值": "正确。轮值指按顺序担任，与“谁就早点来开门”的安排相符。", "请假": "语义：“请假”指不来上班，与“早点来开门”矛盾。", "旅游": "语义：“旅游”与值班无关，也与“早点来开门”不符。", "报销": "语义：“报销”指核销费用，与值班、开门无关。"}, "sentence_index": 6, "correct_answer": "轮值"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护士每天轮值病人。", "explanation": "这里应该用〈照料〉。轮值指按顺序担任职务，不能带“病人”作对象。"}, {"text": "工人每天轮值路面。", "explanation": "这里应该用〈清洁〉。轮值是人员按顺序担任，不能带“路面”这类对象。"}, {"text": "孩子们在公园里轮值树叶。", "explanation": "这里应该用〈收集〉。轮值不能表示收拢物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26540, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天我们组轮值过，大家要早点来。", "corrected_sentence": "明天我们组轮值，大家要早点来。", "error_description": "“明天”指将来，“轮值”后不能用“过”（“过”表示经历过），应去掉“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26540, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末把他们三个人轮值，负责开门。", "corrected_sentence": "周末他们三个人轮值，负责开门。", "error_description": "“轮值”是不带处置宾语的动作，不能用“把”字句；去掉“把”，施事直接作主语即可：“周末他们三个人轮值”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
