INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26542, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "存活率是指一群东西里，活下来的占多少比例。", "primary_collocate": null, "pronunciation": "cún huó lǜ", "ipa": "tsʰu̯ən˧˥ xu̯ɔ˧˥ ly˥˩", "syllable_count": 3, "sentences": [{"text": "这些小鸡的存活率很高。", "target_word": "存活率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太冷，小树的存活率很低。", "target_word": "存活率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老农说今年菜苗的存活率不错。", "target_word": "存活率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们数了数，鱼苗的存活率是八成。", "target_word": "存活率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水干净，小鱼的存活率就会高。", "target_word": "存活率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批花的存活率只有一半。", "target_word": "存活率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想提高小羊的存活率。", "target_word": "存活率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年雨多，种子的存活率变高了。", "target_word": "存活率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们：这些草的存活率是多少？", "target_word": "存活率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院想知道病人的存活率。", "target_word": "存活率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一群东西里活下来的比例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16383963-1406-40ee-9a87-a2a0f98c8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26542, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "存活率", "is_correct": true, "explanation": "“存活率”指一群东西里活下来的比例，「这些小鸡的存活率很高」语义通顺。"}, {"text": "报名率", "is_correct": false, "explanation": "语义：报名率说的是报名人数的比例，小鸡不会报名，与句意不符。"}, {"text": "收视率", "is_correct": false, "explanation": "搭配：收视率指观众收看节目的比例，不能用来说小鸡。"}, {"text": "上座率", "is_correct": false, "explanation": "搭配：上座率用于剧场、航班等的座位使用情况，不能用于小鸡。"}], "explanations": {"存活率": "“存活率”指一群东西里活下来的比例，「这些小鸡的存活率很高」语义通顺。", "报名率": "语义：报名率说的是报名人数的比例，小鸡不会报名，与句意不符。", "收视率": "搭配：收视率指观众收看节目的比例，不能用来说小鸡。", "上座率": "搭配：上座率用于剧场、航班等的座位使用情况，不能用于小鸡。"}, "sentence_index": 0, "correct_answer": "存活率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛的存活率是八成。", "explanation": "存活率指活下来的比例，比赛不存在存活。这里应该用〈胜率〉，表示取得胜利的比例。"}, {"text": "这部电影的存活率很高。", "explanation": "存活率只用于有生命的个体群体，电影不能存活。这里应该用〈票房〉来说明观众的购买情况。"}, {"text": "我们班的存活率在年级里排第一。", "explanation": "“存活率”是群体中活下来的比例，不是可以排名次的成绩。这里应该用〈成绩〉来说明班级的学习水平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26542, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "存活率", "is_correct": true, "explanation": "“存活率”指活下来的比例，「他想提高小羊的存活率」语义通顺，提高的对象是比例。"}, {"text": "中奖率", "is_correct": false, "explanation": "语义：中奖率指中奖的比例，小羊不能参与抽奖，与句意不符。"}, {"text": "录取率", "is_correct": false, "explanation": "语义：录取率用于考试或招生，小羊无法被录取，句子不通。"}, {"text": "及格率", "is_correct": false, "explanation": "语义：及格率指考试或测验中合格的比例，小羊不参加考试，句子不通。"}], "explanations": {"存活率": "“存活率”指活下来的比例，「他想提高小羊的存活率」语义通顺，提高的对象是比例。", "中奖率": "语义：中奖率指中奖的比例，小羊不能参与抽奖，与句意不符。", "录取率": "语义：录取率用于考试或招生，小羊无法被录取，句子不通。", "及格率": "语义：及格率指考试或测验中合格的比例，小羊不参加考试，句子不通。"}, "sentence_index": 6, "correct_answer": "存活率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场演唱会的存活率很高。", "explanation": "存活率只用于有生命的个体群体，演唱会不能存活。这里应该用〈上座率〉来说明观众坐满的情况。"}, {"text": "这款手机的存活率今年翻了一番。", "explanation": "“存活率”只用于有生命的个体所组成的群体，手机不能存活。这里应该用〈销量〉来说明卖得多。"}, {"text": "老师问我们这次作业的存活率是多少？", "explanation": "作业不是有生命的个体，不能存活。这里应该用〈完成率〉来说明作业完成的比例。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那群小鸭的存活率很多。", "corrected_sentence": "那群小鸭的存活率很高。", "error_description": "搭配错误：「存活率」是比例，要用「高」或「低」来形容，不能说「很多」；应说「存活率很高」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年雨少，草的存活率变长了。", "corrected_sentence": "今年雨少，草的存活率变低了。", "error_description": "搭配错误：「存活率」是比例，只能说变高或变低，不能说「变长」；应说「存活率变低了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
