INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26544, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指普通老百姓的生活和想法，和当官的、做大官的人不一样。", "primary_collocate": null, "pronunciation": "mín jiān", "ipa": "min˧˥ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "我想听听民间的声音。", "target_word": "民间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家常写民间的生活。", "target_word": "民间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民间的看法和官方不太一样。", "target_word": "民间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走进民间，了解老百姓的想法。", "target_word": "民间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民间有句老话：吃一堑，长一智。", "target_word": "民间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些画记录了民间的生活。", "target_word": "民间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民间的日子过得很简单。", "target_word": "民间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在书里写了民间的快乐和苦恼。", "target_word": "民间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位官员常去民间看看。", "target_word": "民间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民间的想法有时更实在。", "target_word": "民间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "民間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "普通老百姓的生活和想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: 堑 (Zipf 2.32)']::text[], '16383963-1406-40ee-9a87-a2a0f98c8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26544, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "民间", "is_correct": true, "explanation": "“民间”指普通老百姓的生活和想法，「我想听听民间的声音」语义通顺。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是人体的温度数值，没有可以「听」的声音，与句意不符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是可以发出“声音”的对象，句子不通。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：台灯是照明用具，与“听声音”的语境不合。"}], "explanations": {"民间": "“民间”指普通老百姓的生活和想法，「我想听听民间的声音」语义通顺。", "体温": "语义：体温是人体的温度数值，没有可以「听」的声音，与句意不符。", "书包": "语义：书包不是可以发出“声音”的对象，句子不通。", "台灯": "语义：台灯是照明用具，与“听声音”的语境不合。"}, "sentence_index": 0, "correct_answer": "民间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的民间很大，大家都很佩服。", "explanation": "“民间”指普通老百姓的生活和想法，不能用来说个人的能力或地位。这里应该用〈威望〉来说明他的影响力。"}, {"text": "这家公司的民间今年增长了一倍。", "explanation": "“民间”不指公司的规模或业绩，这里应该用〈营业额〉来说明增长的情况。"}, {"text": "这次会议的民间由他主持。", "explanation": "“民间”指普通老百姓的生活和想法，不是会议的组织者。这里应该用〈主办方〉来说明谁组织会议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26544, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "民间", "is_correct": true, "explanation": "“民间”指普通老百姓的生活，「民间的日子过得很简单」语义通顺，符合普通百姓的生活特点。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度是冷热的程度，不能“过日子”，句子不通。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是一门学科，不能“过日子”，句子不通。"}, {"text": "游乐场", "is_correct": false, "explanation": "语义：游乐场是场所，不是可以“过日子”的群体，句子不通。"}], "explanations": {"民间": "“民间”指普通老百姓的生活，「民间的日子过得很简单」语义通顺，符合普通百姓的生活特点。", "温度": "语义：温度是冷热的程度，不能“过日子”，句子不通。", "数学": "语义：数学是一门学科，不能“过日子”，句子不通。", "游乐场": "语义：游乐场是场所，不是可以“过日子”的群体，句子不通。"}, "sentence_index": 6, "correct_answer": "民间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位大臣的民间是皇帝亲自任命的。", "explanation": "“民间”指普通老百姓，不指官职。这位大臣的职位是朝廷任命的，这里应该用〈官职〉来说明他的身份。"}, {"text": "这份报告的民间很有价值。", "explanation": "“民间”指普通老百姓的生活和想法，不能指报告的内容或价值。这里应该用〈内容〉来说明报告的价值。"}, {"text": "我的民间比你高。", "explanation": "“民间”指普通老百姓的生活和想法，不能用来比较个人的身高。这里应该用〈身高〉来说明高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26544, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他深刻民间，收集了很多故事。", "corrected_sentence": "他深入民间，收集了很多故事。", "error_description": "搭配错误：「深入」是动词，能带处所宾语「民间」；「深刻」是形容词，不能带宾语，应说「他深入民间」，不能说「他深刻民间」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26544, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种习惯在民间们很常见。", "corrected_sentence": "这种习惯在民间很常见。", "error_description": "错误：「民间」是抽象的范围，不能加「们」（「们」只用于指人的名词）；应去掉「们」，说「在民间很常见」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
