INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26546, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "走来走去看看有没有危险。", "primary_collocate": null, "pronunciation": "xún hù", "ipa": "ɕy̯ɪn³⁵ xu⁵¹", "syllable_count": 2, "sentences": [{"text": "夜里，护林员在山里巡护，看有没有危险。", "target_word": "巡护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护区的工作人员每天来回巡护，看着野生动物。", "target_word": "巡护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里可能有火灾，护林员每天出去巡护。", "target_word": "巡护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们拿着手电筒在河边巡护，担心有人掉进水里。", "target_word": "巡护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "景区的工作人员一直在湖边巡护，保证游客安全。", "target_word": "巡护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在果园里巡护，怕有人偷苹果。", "target_word": "巡护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民轮流在村口巡护，保护大家的家。", "target_word": "巡护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，他们到山路上巡护，看哪里有石头掉下来。", "target_word": "巡护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巡护的人看到有烟，马上打了电话。", "target_word": "巡护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里有野火的危险，他们巡护着每一条路。", "target_word": "巡护", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "巡护了", "label": "体标"}, {"form": "巡护过", "label": "体标"}, {"form": "巡护着", "label": "体标"}], "register": "中性", "sense_fingerprint": "走来走去查看有没有危险", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb894594-6404-49e9-b276-afb1f1d52d67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26546, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巡护", "is_correct": true, "explanation": "正确。巡护指走来走去查看有没有危险，与“看有没有危险”相符。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”与在山里查看有没有危险无关。"}, {"text": "收费", "is_correct": false, "explanation": "语义：“收费”与查看有没有危险无关。"}, {"text": "烧制", "is_correct": false, "explanation": "语义：“烧制”指烧陶瓷，与保安的巡视无关。"}], "explanations": {"巡护": "正确。巡护指走来走去查看有没有危险，与“看有没有危险”相符。", "洗澡": "语义：“洗澡”与在山里查看有没有危险无关。", "收费": "语义：“收费”与查看有没有危险无关。", "烧制": "语义：“烧制”指烧陶瓷，与保安的巡视无关。"}, "sentence_index": 0, "correct_answer": "巡护"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶在院子里巡护孙子。", "explanation": "这里应该用〈照看〉。巡护指在区域内来回查看，不能用于照看人。"}, {"text": "厨师每天巡护鱼。", "explanation": "这里应该用〈烹饪〉。巡护是查看危险的行动，不能用于做饭。"}, {"text": "师傅认真巡护自行车。", "explanation": "这里应该用〈修理〉。巡护指在区域内查看，不能用于修理器物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26546, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巡护", "is_correct": true, "explanation": "正确。巡护指在区域内来回查看，与“保护大家的家”相符。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体症状，与保护家园无关。"}, {"text": "洗涤", "is_correct": false, "explanation": "搭配：“洗涤”的对象是衣物等，不能用于村口。"}, {"text": "烹调", "is_correct": false, "explanation": "语义：“烹调”指做菜，与村口的看守无关。"}], "explanations": {"巡护": "正确。巡护指在区域内来回查看，与“保护大家的家”相符。", "咳嗽": "语义：“咳嗽”是身体症状，与保护家园无关。", "洗涤": "搭配：“洗涤”的对象是衣物等，不能用于村口。", "烹调": "语义：“烹调”指做菜，与村口的看守无关。"}, "sentence_index": 6, "correct_answer": "巡护"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察在街上巡护小偷。", "explanation": "这里应该用〈抓捕〉。巡护指在区域内查看，不能用来抓人。"}, {"text": "消防员冲进火场巡护被困的人。", "explanation": "这里应该用〈救助〉。巡护指查看区域，不能用于营救人。"}, {"text": "奶奶独自巡护三个孩子。", "explanation": "这里应该用〈抚养〉。巡护是查看区域，不能用于养育孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26546, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他巡护的很仔细，没有漏掉一个角落。", "corrected_sentence": "他巡护得很仔细，没有漏掉一个角落。", "error_description": "补语要用“得”连接，“的”误用：“巡护得很仔细”是正确形式，“巡护的很仔细”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26546, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在巡护了那座山。", "corrected_sentence": "他正在巡护那座山。", "error_description": "“正在”表示动作进行中，不能与“了”同用，应去掉“了”：“他正在巡护那座山”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
