INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26548, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "林带是一排一排的树，像一条带子。", "primary_collocate": null, "pronunciation": "lín dài", "ipa": "lin˧˥ tai˥˩", "syllable_count": 2, "sentences": [{"text": "路边有一条林带，树排得很整齐。", "target_word": "林带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从山上看，林带像一条绿色的带子。", "target_word": "林带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校后面有一条林带。", "target_word": "林带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "林带里的树一棵挨着一棵。", "target_word": "林带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着林带慢慢往前走。", "target_word": "林带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的林带夏天很凉快。", "target_word": "林带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条林带有三排杨树。", "target_word": "林带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟儿都住在林带里。", "target_word": "林带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农田旁边的林带很长。", "target_word": "林带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天，林带的叶子都黄了。", "target_word": "林带", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条林带", "label": "量词"}, {"form": "防护林带", "label": "复合"}], "register": "中性", "sense_fingerprint": "一排一排像带子的树", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb894594-6404-49e9-b276-afb1f1d52d67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26548, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "林带", "is_correct": true, "explanation": "正确答案：林带，指一排一排像带子的树。"}, {"text": "林地", "is_correct": false, "explanation": "dài 与 dì 韵母不同（ai 与 i），意思是林地，指树林覆盖的土地。"}, {"text": "连带", "is_correct": false, "explanation": "lín 与 lián 韵母不同（in 与 ian），意思是连带，指牵连、带动。"}, {"text": "领带", "is_correct": false, "explanation": "lín 与 lǐng 韵尾与声调都不同（in 与 ing，阳平与上声），意思是领带。"}], "explanations": {"林带": "正确答案：林带，指一排一排像带子的树。", "林地": "dài 与 dì 韵母不同（ai 与 i），意思是林地，指树林覆盖的土地。", "连带": "lín 与 lián 韵母不同（in 与 ian），意思是连带，指牵连、带动。", "领带": "lín 与 lǐng 韵尾与声调都不同（in 与 ing，阳平与上声），意思是领带。"}, "sentence_index": null, "correct_answer": "林带"}, "level_3": {"options": [{"text": "林带", "is_correct": true, "explanation": "林带：一排一排的树，与“树排得很整齐”相符。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠没有成排的树，与“树排得很整齐”的描述矛盾。"}, {"text": "河床", "is_correct": false, "explanation": "语义：河床是河水流过的低地，与路边整齐排列的树不符。"}, {"text": "石阶", "is_correct": false, "explanation": "体貌：石阶是台阶的形状，不是一排一排的树。"}], "explanations": {"林带": "林带：一排一排的树，与“树排得很整齐”相符。", "沙漠": "语义：沙漠没有成排的树，与“树排得很整齐”的描述矛盾。", "河床": "语义：河床是河水流过的低地，与路边整齐排列的树不符。", "石阶": "体貌：石阶是台阶的形状，不是一排一排的树。"}, "sentence_index": 0, "correct_answer": "林带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把一条林带围在脖子上，很暖和。", "explanation": "这里应该用〈围巾〉。林带是成排的树，不是布料；围在脖子上取暖的要用围巾。"}, {"text": "阳台上摆着一排林带，开满了花。", "explanation": "这里应该用〈盆栽〉。林带是地面上成片的树木，不能摆在阳台上；盆里开花的植物要用盆栽。"}, {"text": "老师在林带上写满了字。", "explanation": "这里应该用〈黑板〉。林带是成排的树，不能用来写字；写字要在黑板上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26548, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "林带", "is_correct": true, "explanation": "林带：成排的树，有三排杨树的正是林带。"}, {"text": "绳子", "is_correct": false, "explanation": "语义：绳子上不可能长出三排杨树，与句意矛盾。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包里不可能有三排杨树，与句意矛盾。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包上不可能有三排杨树，与句意矛盾。"}], "explanations": {"林带": "林带：成排的树，有三排杨树的正是林带。", "绳子": "语义：绳子上不可能长出三排杨树，与句意矛盾。", "书包": "语义：书包里不可能有三排杨树，与句意矛盾。", "面包": "语义：面包上不可能有三排杨树，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "林带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "足球场中间铺着一大片林带。", "explanation": "这里应该用〈草坪〉。林带是成排的树木，铺在场地上的草要用草坪。"}, {"text": "公园门口的墙上贴着一圈林带，很漂亮。", "explanation": "这里应该用〈彩纸〉。林带是成排的树，不能贴在墙上；贴在墙上装饰的纸要用彩纸。"}, {"text": "苗圃里整齐地摆着一排排林带。", "explanation": "这里应该用〈小树苗〉。林带是成片种植的树木，苗圃里待移栽的小树苗不能称为林带。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "沿河的堤坝上有一个林带，树都排得很整齐。", "corrected_sentence": "沿河的堤坝上有一条林带，树都排得很整齐。", "error_description": "量词错误：林带呈带状，应说“一条林带”，“个”不用于带状的林带。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26548, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家门口有一朵林带。", "corrected_sentence": "我家门口有一条林带。", "error_description": "量词错误：林带呈带状，应说“一条林带”；“朵”多用于花、云等，不能用于林带。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
