INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26550, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "放机器观测天气或路况的地方。", "primary_collocate": null, "pronunciation": "jiān cè zhàn", "ipa": "tɕjɛn˥ tsʰɤ˥˩ ʈʂan˥˩", "syllable_count": 3, "sentences": [{"text": "路口有一个监测站，能看车多不多。", "target_word": "监测站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的监测站可以看天气。", "target_word": "监测站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "监测站里放着很多小机器。", "target_word": "监测站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人每天去监测站看天气。", "target_word": "监测站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个监测站在高高的山顶上。", "target_word": "监测站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在监测站旁边等雨停。", "target_word": "监测站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "监测站告诉大家明天有大风。", "target_word": "监测站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的监测站能看到车流。", "target_word": "监测站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把新机器放进了监测站。", "target_word": "监测站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "监测站的灯一直亮着。", "target_word": "监测站", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "監測站", "label": "繁体"}], "register": "中性", "sense_fingerprint": "放机器看天气或看路的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16383963-1406-40ee-9a87-a2a0f98c8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26550, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "监测站", "is_correct": true, "explanation": "正确：监测站可以观测路况，与“能看车多不多”相符。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：饭店供人吃饭，不能观测车流。"}, {"text": "雕像", "is_correct": false, "explanation": "语义：雕像是艺术品，不能观测车流。"}, {"text": "书店", "is_correct": false, "explanation": "语义：书店是卖书的地方，不能观测车流。"}], "explanations": {"监测站": "正确：监测站可以观测路况，与“能看车多不多”相符。", "饭店": "语义：饭店供人吃饭，不能观测车流。", "雕像": "语义：雕像是艺术品，不能观测车流。", "书店": "语义：书店是卖书的地方，不能观测车流。"}, "sentence_index": 0, "correct_answer": "监测站"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆货车每年都要去监测站做检验。", "explanation": "这里应该用〈检测站〉。这里的监测站指放机器看天气或路况的地方，车辆检验要去检测站。"}, {"text": "工厂门口装了监测站，防止有人偷东西。", "explanation": "这里应该用〈监控〉。监测站是看天气或路况的设施，不用于防盗。"}, {"text": "孩子发烧了，我们去监测站看病。", "explanation": "这里应该用〈诊所〉。监测站用于看天气或路况，看病要去诊所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "监测站", "is_correct": true, "explanation": "正确：监测站能观测天气，可以告诉大家天气变化。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能观测和发布天气信息。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不能预报天气。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“告诉”的施事应是能发布信息的人或设施，雨伞不能发布信息。"}], "explanations": {"监测站": "正确：监测站能观测天气，可以告诉大家天气变化。", "冰箱": "语义：冰箱不能观测和发布天气信息。", "厨房": "语义：厨房是做饭的地方，不能预报天气。", "雨伞": "搭配：“告诉”的施事应是能发布信息的人或设施，雨伞不能发布信息。"}, "sentence_index": 6, "correct_answer": "监测站"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子感冒了，我们去监测站买药。", "explanation": "这里应该用〈药店〉。监测站用于看天气或路况，买药要去药店。"}, {"text": "周末我去监测站理发。", "explanation": "这里应该用〈理发店〉。监测站是测量设施，理发要去理发店。"}, {"text": "中午我们去监测站吃饭。", "explanation": "这里应该用〈饭店〉。监测站不供人用餐，吃饭要去饭店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在山顶新建了一只监测站，专门看天气。", "corrected_sentence": "我们在山顶新建了一座监测站，专门看天气。", "error_description": "量词错误：监测站是设施，应说“一座监测站”，不说“一只监测站”；“只”用于动物或成对器物中的一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "路边新建了一条监测站，能看到车流。", "corrected_sentence": "路边新建了一座监测站，能看到车流。", "error_description": "量词错误：监测站是建筑设施，应说“一座监测站”；“条”用于长条形事物，不能用来计量监测站。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26552, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "困难", "is_correct": true, "explanation": "反义：“简易”指不难、容易做，“困难”指不容易做，二者相对。"}, {"text": "热闹", "is_correct": false, "explanation": "与“简易”无反义关系，“热闹”形容场面或气氛。"}, {"text": "安静", "is_correct": false, "explanation": "与“简易”无反义关系，“安静”形容环境或状态。"}, {"text": "寒冷", "is_correct": false, "explanation": "与“简易”无反义关系，“寒冷”形容温度低。"}], "correct_answer": "困难", "explanations": {"困难": "反义：“简易”指不难、容易做，“困难”指不容易做，二者相对。", "热闹": "与“简易”无反义关系，“热闹”形容场面或气氛。", "安静": "与“简易”无反义关系，“安静”形容环境或状态。", "寒冷": "与“简易”无反义关系，“寒冷”形容温度低。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26552, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "困难", "is_correct": true, "explanation": "反义：“简易”指不难、容易做，“困难”指不容易做，二者相对。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“简易”无反义关系，“漂亮”形容外观好看。"}, {"text": "明亮", "is_correct": false, "explanation": "与“简易”无反义关系，“明亮”形容光线或颜色。"}, {"text": "快乐", "is_correct": false, "explanation": "与“简易”无反义关系，“快乐”形容心情。"}], "correct_answer": "困难", "explanations": {"困难": "反义：“简易”指不难、容易做，“困难”指不容易做，二者相对。", "漂亮": "与“简易”无反义关系，“漂亮”形容外观好看。", "明亮": "与“简易”无反义关系，“明亮”形容光线或颜色。", "快乐": "与“简易”无反义关系，“快乐”形容心情。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26552, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不难，很容易做。", "primary_collocate": null, "pronunciation": "jiǎn yì", "ipa": "tɕjɛn˨˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "这个游戏的规则很简易，孩子一学就会。", "target_word": "简易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的操作十分简易，老人也能用。", "target_word": "简易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这道菜的步骤很简易，十分钟就好了。", "target_word": "简易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器使用起来很简易，不用看说明书。", "target_word": "简易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报名的手续很简易，只要填一张表。", "target_word": "简易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种方法简易有效，大家都喜欢用。", "target_word": "简易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "安装方法非常简易，一个人就能完成。", "target_word": "简易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件的使用步骤很简易，一看就懂。", "target_word": "简易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种面包做法简易，只需要面粉和水。", "target_word": "简易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种小游戏玩法简易，三岁的孩子也会玩。", "target_word": "简易", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "簡易", "label": "繁体"}], "register": "书面", "sense_fingerprint": "简易·形容词·方法、操作不难，容易做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16383963-1406-40ee-9a87-a2a0f98c8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26552, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "简易", "is_correct": true, "explanation": "正确：“规则很简易”指规则不难，与“孩子一学就会”相符。"}, {"text": "繁琐", "is_correct": false, "explanation": "语义：规则繁琐就不容易学会，与“孩子一学就会”矛盾。"}, {"text": "昂贵", "is_correct": false, "explanation": "搭配：“规则”不能用“昂贵”形容，与句意也不符。"}, {"text": "高深", "is_correct": false, "explanation": "语义：高深的规则不是孩子一学就会的，与句意相反。"}], "explanations": {"简易": "正确：“规则很简易”指规则不难，与“孩子一学就会”相符。", "繁琐": "语义：规则繁琐就不容易学会，与“孩子一学就会”矛盾。", "昂贵": "搭配：“规则”不能用“昂贵”形容，与句意也不符。", "高深": "语义：高深的规则不是孩子一学就会的，与句意相反。"}, "sentence_index": 0, "correct_answer": "简易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脾气很简易，从不发火。", "explanation": "这里应该用〈简单〉。简易指方法、操作不难，形容人的脾气要用简单。"}, {"text": "他对待工作的态度很简易，经常迟到。", "explanation": "这里应该用〈随便〉。简易用于方法、操作不难，形容对待工作的态度要用随便。"}, {"text": "他们之间的关系很简易，从不吵架。", "explanation": "这里应该用〈简单〉。简易用于方法、操作不难，形容人与人的关系要用简单。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26552, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "简易", "is_correct": true, "explanation": "正确：“安装方法非常简易”指方法不难，与“一个人就能完成”相符。"}, {"text": "繁复", "is_correct": false, "explanation": "语义：安装方法繁复就难以一个人完成，与句意矛盾。"}, {"text": "幽默", "is_correct": false, "explanation": "搭配：“幽默”形容人的言语或风格，不用来形容安装方法。"}, {"text": "冗长", "is_correct": false, "explanation": "语义：冗长的安装过程不可能一个人很快完成，与句意相反。"}], "explanations": {"简易": "正确：“安装方法非常简易”指方法不难，与“一个人就能完成”相符。", "繁复": "语义：安装方法繁复就难以一个人完成，与句意矛盾。", "幽默": "搭配：“幽默”形容人的言语或风格，不用来形容安装方法。", "冗长": "语义：冗长的安装过程不可能一个人很快完成，与句意相反。"}, "sentence_index": 6, "correct_answer": "简易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天的心思很简易，不想说话。", "explanation": "这里应该用〈简单〉。简易用于方法、操作不难，形容心思要用简单。"}, {"text": "他讲话的语气很简易，像在训人。", "explanation": "这里应该用〈生硬〉。简易用于方法、操作不难，形容语气要用生硬。"}, {"text": "这位老人的性格很简易，从不计较。", "explanation": "这里应该用〈简单〉。简易指方法、操作不难，形容人的性格要用简单。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一种简易地操作方法，老人也能学会。", "corrected_sentence": "这是一种简易的操作方法，老人也能学会。", "error_description": "助词错误：“简易”修饰名词“方法”，应用“的”，不能用“地”；“地”用于动词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种软件的操作地简易，初学者很快就能上手。", "corrected_sentence": "这种软件的操作很简易，初学者很快就能上手。", "error_description": "助词错误：作谓语的形容词“简易”前应用程度副词“很”，不能用结构助词“地”；“地”用于动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
