INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26554, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "跟在某人或某物后面，想要找到他或它。", "primary_collocate": null, "pronunciation": "zhuī zōng", "ipa": "ʈʂweɪ˥ tsʊŋ˥", "syllable_count": 2, "sentences": [{"text": "猎人沿着脚印追踪那只受伤的鹿。", "target_word": "追踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察追踪小偷跑进了小巷。", "target_word": "追踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警犬闻着气味追踪逃跑的人。", "target_word": "追踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他悄悄追踪那个陌生人走了很远。", "target_word": "追踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者开车追踪那位明星到了机场。", "target_word": "追踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狼群追踪着一只受伤的羊。", "target_word": "追踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "侦探开着车追踪了那辆车一个晚上。", "target_word": "追踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们顺着雪地上的小脚印追踪那只小猫。", "target_word": "追踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老猎人能根据雪地上的脚印追踪动物。", "target_word": "追踪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他发现有人在后面追踪自己。", "target_word": "追踪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "追踪了", "label": "完成体"}, {"form": "追踪着", "label": "持续体"}, {"form": "追踪过", "label": "经历体"}, {"form": "追蹤", "label": "繁体"}], "register": "中性", "sense_fingerprint": "追踪：亲身跟在人或动物后面，沿着痕迹或身影去寻找", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71266d48-abd2-408d-ab3d-49d9cf61150e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26554, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "追踪", "is_correct": true, "explanation": "正确：“追踪”指沿着脚印跟在受伤的鹿后面寻找，与句意相符。"}, {"text": "打扮", "is_correct": false, "explanation": "配价：“打扮”的对象通常是人，不能以“那只受伤的鹿”作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱一只鹿”。"}, {"text": "设计", "is_correct": false, "explanation": "语义：“设计”是人为规划，与“沿着脚印”的追寻动作不合。"}], "explanations": {"追踪": "正确：“追踪”指沿着脚印跟在受伤的鹿后面寻找，与句意相符。", "打扮": "配价：“打扮”的对象通常是人，不能以“那只受伤的鹿”作宾语。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱一只鹿”。", "设计": "语义：“设计”是人为规划，与“沿着脚印”的追寻动作不合。"}, "sentence_index": 0, "correct_answer": "追踪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她努力追踪落下的进度。", "explanation": "这里应该用〈追赶〉。“追赶”指赶上落后的进度，“追踪”指沿着痕迹寻找人或动物，不能用来说赶上落下的进度。"}, {"text": "他每天追踪老师学书法。", "explanation": "这里应该用〈跟随〉。“追踪”指沿着痕迹跟在人或动物后面找，不能说跟着人学习。"}, {"text": "他一直在追踪老师的思想。", "explanation": "这里应该用〈追随〉。“追踪”指寻找人、动物或物体的行踪，不能用来说跟随别人的思想或主张，那要用〈追随〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26554, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "追踪", "is_correct": true, "explanation": "正确：“追踪”指开车跟在那辆车后面寻找，与“侦探”和“一个晚上”相符。"}, {"text": "拜访", "is_correct": false, "explanation": "配价：“拜访”的对象必须是人，“那辆车”不能作“拜访”的宾语。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，把车当作食物吃掉与句子语境完全不符。"}, {"text": "喂养", "is_correct": false, "explanation": "语义：“喂养”只用于活的动物，车辆不能被喂养。"}], "explanations": {"追踪": "正确：“追踪”指开车跟在那辆车后面寻找，与“侦探”和“一个晚上”相符。", "拜访": "配价：“拜访”的对象必须是人，“那辆车”不能作“拜访”的宾语。", "吃": "语义：“吃”指进食，把车当作食物吃掉与句子语境完全不符。", "喂养": "语义：“喂养”只用于活的动物，车辆不能被喂养。"}, "sentence_index": 6, "correct_answer": "追踪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直在追踪自己的梦想。", "explanation": "这里应该用〈追求〉。“追踪”只用于寻找人、动物或物体的行踪，不用于梦想。"}, {"text": "老师追踪学生为什么迟到。", "explanation": "这里应该用〈追问〉。“追踪”不能接“为什么迟到”这类问句，要表示穷追不舍地问要用〈追问〉。"}, {"text": "奶奶每天追踪孙子玩耍。", "explanation": "这里应该用〈陪伴〉。“追踪”指沿着痕迹跟在后面寻找，孙子在身边玩耍不需要追踪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26554, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "猎人顺着血迹追踪了着那只受伤的熊。", "corrected_sentence": "猎人顺着血迹追踪着那只受伤的熊。", "error_description": "错误：“了”与“着”不能同用，写成“追踪了着”。正确：“追踪着”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26554, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "侦探一直在追踪了那个嫌疑人。", "corrected_sentence": "侦探一直在追踪那个嫌疑人。", "error_description": "错误：“一直在”表示动作进行，“了”表示完成，二者不能同用，写成“在追踪了”。正确：“一直在追踪”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
