INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26556, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动物们从一个地方搬到另一个地方去住。", "primary_collocate": null, "pronunciation": "qiān xǐ", "ipa": "tɕʰjɛn˥ ɕi˨˩", "syllable_count": 2, "sentences": [{"text": "冬天到了，天鹅会迁徙到暖和的地方。", "target_word": "迁徙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟们迁徙以前，先在树上休息几天。", "target_word": "迁徙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草地变黄了，羊群只好迁徙到别的山上。", "target_word": "迁徙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雁迁徙的时候，会排成整齐的队伍。", "target_word": "迁徙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北极燕鸥每年从北极迁徙到南极。", "target_word": "迁徙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在电视上看到，成千上万的动物在迁徙。", "target_word": "迁徙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天，蝴蝶迁徙到南方过冬。", "target_word": "迁徙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水干了，鱼群只好迁徙到几百公里外的大湖。", "target_word": "迁徙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物迁徙是为了找到吃的和住的地方。", "target_word": "迁徙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，燕子又从南方迁徙回来了。", "target_word": "迁徙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "迁徙了", "label": "体标"}, {"form": "迁徙过", "label": "体标"}, {"form": "遷徙", "label": "繁体"}], "register": "书面", "sense_fingerprint": "迁徙·动词·动物从一处搬到另一处居住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16383963-1406-40ee-9a87-a2a0f98c8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26556, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迁徙", "is_correct": true, "explanation": "正确：天鹅前往暖和的地方是迁徙。"}, {"text": "冬眠", "is_correct": false, "explanation": "语义：冬眠是静止不动地睡过冬天，不是前往暖和的地方。"}, {"text": "产卵", "is_correct": false, "explanation": "语义：产卵是生蛋的行为，不能表示前往某地。"}, {"text": "换毛", "is_correct": false, "explanation": "搭配：“换毛”是身体的变化，不能与“到……的地方”搭配。"}], "explanations": {"迁徙": "正确：天鹅前往暖和的地方是迁徙。", "冬眠": "语义：冬眠是静止不动地睡过冬天，不是前往暖和的地方。", "产卵": "语义：产卵是生蛋的行为，不能表示前往某地。", "换毛": "搭配：“换毛”是身体的变化，不能与“到……的地方”搭配。"}, "sentence_index": 0, "correct_answer": "迁徙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新买的沙发迁徙到了客厅的角落。", "explanation": "这里应该用〈搬到〉。迁徙指动物成群地转移，家具的挪动要说搬到。"}, {"text": "小偷趁夜迁徙了。", "explanation": "这里应该用〈逃跑〉。迁徙指生物有规律地转移，形容人的逃跑不能用迁徙。"}, {"text": "树叶顺着小溪迁徙到了下游。", "explanation": "这里应该用〈漂流〉。迁徙是生物的转移，树叶被水带走应说漂流。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26556, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迁徙", "is_correct": true, "explanation": "正确：秋天蝴蝶前往南方过冬是迁徙。"}, {"text": "羽化", "is_correct": false, "explanation": "语义：羽化指昆虫蜕皮长出翅膀，不能表示前往南方。"}, {"text": "蜕变", "is_correct": false, "explanation": "语义：蜕变指形态的根本改变，不能表示到某地过冬。"}, {"text": "繁殖", "is_correct": false, "explanation": "搭配：“到南方过冬”要求主语能够移动，“繁殖”不能带“到……过冬”。"}], "explanations": {"迁徙": "正确：秋天蝴蝶前往南方过冬是迁徙。", "羽化": "语义：羽化指昆虫蜕皮长出翅膀，不能表示前往南方。", "蜕变": "语义：蜕变指形态的根本改变，不能表示到某地过冬。", "繁殖": "搭配：“到南方过冬”要求主语能够移动，“繁殖”不能带“到……过冬”。"}, "sentence_index": 6, "correct_answer": "迁徙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这列火车每天迁徙到北方。", "explanation": "这里应该用〈开往〉。迁徙只用于动物成群地转移，火车的行驶不能说迁徙。"}, {"text": "白云迁徙过了山顶。", "explanation": "这里应该用〈飘〉。迁徙只用于生物，云的移动应说飘过去。"}, {"text": "轮船迁徙到了港口。", "explanation": "这里应该用〈航行〉。迁徙指生物的转移，船只航行到港口不能说迁徙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26556, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冬天到了，很多天鹅都迁徙南方去了。", "corrected_sentence": "冬天到了，很多天鹅都迁徙到南方去了。", "error_description": "错误：“迁徙南方”；正确：“迁徙到南方”。迁徙是不及物动词，表示去往某地要用介词“到”引出处所。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26556, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春天一到，燕子又从南方迁徙回来过。", "corrected_sentence": "春天一到，燕子又从南方迁徙回来了。", "error_description": "体标错误：“迁徙回来”表示已经完成的动作，应用“了”；“过”表示曾经有过的经历，不能用于此处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
