INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26560, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "地下水位就是地底下水的上表面的位置。", "primary_collocate": null, "pronunciation": "dì xià shuǐ wèi", "ipa": "ti˥˩ ɕja˥˩ ʂweɪ˨˩ weɪ˥˩", "syllable_count": 4, "sentences": [{"text": "地下水位就是地底下水面的高度。", "target_word": "地下水位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在井里放了一根尺子，量一量地下水位。", "target_word": "地下水位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旱季到了，村里的地下水位越来越低。", "target_word": "地下水位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水井越挖越深，因为地下水位已经很低了。", "target_word": "地下水位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暴雨过后，河边的地下水位一下子升高了。", "target_word": "地下水位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带学生到井边，看今年的地下水位有多深。", "target_word": "地下水位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里的路面太多，雨水进不去，地下水位就会下降。", "target_word": "地下水位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这口井的水忽然少了，说明地下水位变低了。", "target_word": "地下水位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下水位变化很大，我们要节约用水。", "target_word": "地下水位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天雨雪少，山下的地下水位往往比较低。", "target_word": "地下水位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "地下水位·名词·地底下水的上表面所在的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16383963-1406-40ee-9a87-a2a0f98c8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26560, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地下水位", "is_correct": true, "explanation": "正确：定义中被说明的词就是地下水位。"}, {"text": "水井", "is_correct": false, "explanation": "语义：水井是取水的设施，不是水面的高度，与定义不符。"}, {"text": "地下水", "is_correct": false, "explanation": "语义：地下水是水本身，不是水面的高度，与定义不符。"}, {"text": "地下室", "is_correct": false, "explanation": "语义：地下室是建筑空间，不能作为水面高度的定义对象。"}], "explanations": {"地下水位": "正确：定义中被说明的词就是地下水位。", "水井": "语义：水井是取水的设施，不是水面的高度，与定义不符。", "地下水": "语义：地下水是水本身，不是水面的高度，与定义不符。", "地下室": "语义：地下室是建筑空间，不能作为水面高度的定义对象。"}, "sentence_index": 0, "correct_answer": "地下水位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人用水泵把地下水位抽了上来。", "explanation": "这里应该用〈地下水〉。地下水位是水面的高度，不能被抽上来，被抽的是水本身。"}, {"text": "这栋楼的地下水位很结实。", "explanation": "这里应该用〈地基〉。水位是水面的高度，不会结实或松软，形容建筑的承载力应说地基。"}, {"text": "这口井是村里唯一的地下水位。", "explanation": "这里应该用〈水源〉。这口井是供水的来源，水位只是水面的高度，不能充当水源。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地下水位", "is_correct": true, "explanation": "正确：雨水进不去、路面太多时，下降的是地下水面的高度。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不会因为路面或雨水的变化而下降，句中说的是水文现象。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“下降”可以用于水位、温度等数量，“名字”不能说下降。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“下降”可以用于水位、温度等数量，“天空”不能说下降。"}], "explanations": {"地下水位": "正确：雨水进不去、路面太多时，下降的是地下水面的高度。", "年龄": "语义：年龄不会因为路面或雨水的变化而下降，句中说的是水文现象。", "名字": "搭配：“下降”可以用于水位、温度等数量，“名字”不能说下降。", "天空": "搭配：“下降”可以用于水位、温度等数量，“天空”不能说下降。"}, "sentence_index": 6, "correct_answer": "地下水位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "杯子里的地下水位降下来了。", "explanation": "这里应该用〈水位〉。杯子里的水在地面以上，不在地下，不能说地下水位。"}, {"text": "湖泊和河流都属于地下水位。", "explanation": "这里应该用〈地表水〉。地下水位是一个高度数值，不是一类水体；湖泊和河流属于地表水。"}, {"text": "工厂的废水让这条河的地下水位变脏了。", "explanation": "这里应该用〈水质〉。水位是高度，不会变脏，说水变脏应说水质变差。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这口井的一条地下水位慢慢降低了。", "corrected_sentence": "这口井的地下水位慢慢降低了。", "error_description": "量词错误：“条”用于长条形事物，“地下水位”不能用“条”计量；此处应直接说“地下水位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "干旱的年份，这一带的地下水位的比往年低。", "corrected_sentence": "干旱的年份，这一带的地下水位比往年低。", "error_description": "错误：主语“地下水位”后多加了“的”；正确：“地下水位比往年低”。比字句的主语后面不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26562, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "阻力", "is_correct": true, "explanation": "“阻力”指阻碍事物前进的力量，与推动车前进的驱动力意思相反。"}, {"text": "车速", "is_correct": false, "explanation": "“车速”指车辆行驶的快慢，是结果而非与驱动力相对的力量。"}, {"text": "轮胎", "is_correct": false, "explanation": "“轮胎”是车轮的外层部件，与驱动力不构成反义关系。"}, {"text": "颜色", "is_correct": false, "explanation": "“颜色”指色彩，与驱动力没有相对的关系。"}], "correct_answer": "阻力", "explanations": {"阻力": "“阻力”指阻碍事物前进的力量，与推动车前进的驱动力意思相反。", "车速": "“车速”指车辆行驶的快慢，是结果而非与驱动力相对的力量。", "轮胎": "“轮胎”是车轮的外层部件，与驱动力不构成反义关系。", "颜色": "“颜色”指色彩，与驱动力没有相对的关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26562, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "阻力", "is_correct": true, "explanation": "“阻力”指阻碍事物前进的力量，与推动车前进的驱动力意思相反。"}, {"text": "海拔", "is_correct": false, "explanation": "“海拔”指地面高出海平面的高度，与驱动力没有相对的关系。"}, {"text": "体积", "is_correct": false, "explanation": "“体积”指物体所占空间的大小，与驱动力不构成反义。"}, {"text": "温度", "is_correct": false, "explanation": "“温度”指冷热的程度，与驱动力不构成反义关系。"}], "correct_answer": "阻力", "explanations": {"阻力": "“阻力”指阻碍事物前进的力量，与推动车前进的驱动力意思相反。", "海拔": "“海拔”指地面高出海平面的高度，与驱动力没有相对的关系。", "体积": "“体积”指物体所占空间的大小，与驱动力不构成反义。", "温度": "“温度”指冷热的程度，与驱动力不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26562, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "驱动力是让人或东西动起来的力量。", "primary_collocate": null, "pronunciation": "qū dòng lì", "ipa": "tɕʰy˥ tʊŋ˥˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "汽车的驱动力来自发动机。", "target_word": "驱动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的驱动力很大，爬坡没问题。", "target_word": "驱动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风是帆船前进的驱动力。", "target_word": "驱动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水流给小水车提供了驱动力。", "target_word": "驱动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你每天工作的驱动力是什么？", "target_word": "驱动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天跑步的驱动力是想变健康。", "target_word": "驱动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有驱动力，机器就不会动。", "target_word": "驱动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电动机给机器带来了驱动力。", "target_word": "驱动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩学习的驱动力常常是好奇。", "target_word": "驱动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的驱动力不够，动不了。", "target_word": "驱动力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "驅動力", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让人或机器动起来的力量，如发动机、风力、兴趣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25e7a64-8d32-41c0-a4a3-43a2e96bdbc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26562, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "驱动力", "is_correct": true, "explanation": "“驱动力”指使车动起来的力量，与“来自发动机”相符。"}, {"text": "油漆", "is_correct": false, "explanation": "语义：“油漆”是涂在车身上的涂料，不是使车动起来的力量。"}, {"text": "座位", "is_correct": false, "explanation": "语义：“座位”指供人坐的位置，与发动机提供的力量无关。"}, {"text": "车窗", "is_correct": false, "explanation": "搭配：“车窗”是车的部件，不能说“来自发动机”，句子读不通。"}], "explanations": {"驱动力": "“驱动力”指使车动起来的力量，与“来自发动机”相符。", "油漆": "语义：“油漆”是涂在车身上的涂料，不是使车动起来的力量。", "座位": "语义：“座位”指供人坐的位置，与发动机提供的力量无关。", "车窗": "搭配：“车窗”是车的部件，不能说“来自发动机”，句子读不通。"}, "sentence_index": 0, "correct_answer": "驱动力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "刹车的驱动力让车子停下来。", "explanation": "这里应该用〈制动力〉。驱动力指使车前进的力，让车停下的力要用制动力。"}, {"text": "车身的驱动力压着地面，让轮胎抓地。", "explanation": "这里应该用〈重量〉。驱动力是使车前进的力，压在地面上的应是车身的重量。"}, {"text": "这辆车撞上墙时的驱动力很大。", "explanation": "这里应该用〈冲击力〉。驱动力指使车前进的力，撞击时产生的力要说冲击力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26562, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "驱动力", "is_correct": true, "explanation": "“驱动力”指使机器动起来的力量，与“没有……机器就不会动”相符。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：“早餐”是一顿饭，不能作为机器动起来的前提，句子读不通。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：“窗帘”是遮挡光线的织物，与机器能否运转无关。"}, {"text": "足球", "is_correct": false, "explanation": "语义：“足球”是体育用品，不是机器运转所需的力量，句子读不通。"}], "explanations": {"驱动力": "“驱动力”指使机器动起来的力量，与“没有……机器就不会动”相符。", "早餐": "语义：“早餐”是一顿饭，不能作为机器动起来的前提，句子读不通。", "窗帘": "语义：“窗帘”是遮挡光线的织物，与机器能否运转无关。", "足球": "语义：“足球”是体育用品，不是机器运转所需的力量，句子读不通。"}, "sentence_index": 6, "correct_answer": "驱动力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的驱动力决定了转弯的方向。", "explanation": "这里应该用〈转向力〉。驱动力管的是前进，决定转弯方向的要用转向力。"}, {"text": "这辆车的驱动力很时尚，大家都很喜欢。", "explanation": "这里应该用〈外形〉。驱动力指使车前进的力，不指车的样子或美观程度。"}, {"text": "这辆车的驱动力很鲜艳，路上一眼就能看到。", "explanation": "这里应该用〈颜色〉。驱动力指使车前进的力，不指车的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26562, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆车有一根很大的驱动力。", "corrected_sentence": "这辆车有一股很大的驱动力。", "error_description": "「驱动力」前应用量词「股」，「根」用于细长之物，不能修饰抽象的力量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26562, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电机为小车驱动力。", "corrected_sentence": "这台电机为小车提供驱动力。", "error_description": "缺少动词：“为”是介词，后面要有动词，「驱动力」是名词，应说“为小车提供驱动力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
