INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26564, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "组织、筹办一场活动、比赛或展览。", "primary_collocate": null, "pronunciation": "jǔ bàn", "ipa": "tɕy˨˩˦ pan˥˩", "syllable_count": 2, "sentences": [{"text": "周末社区在公园举办了一场展览。", "target_word": "举办", "complexity_tier": "T3", "furigana": "zhōu mò shè qū zài gōng yuán jǔ bàn le yī chǎng zhǎn lǎn", "sentence_source": "generated"}, {"text": "老师想举办一个读书活动。", "target_word": "举办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们举办了一场小比赛。", "target_word": "举办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区打算举办新年活动。", "target_word": "举办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在酒店举办一场生日宴会吧。", "target_word": "举办", "complexity_tier": "T3", "furigana": "wǒ men zài jiǔ diàn jǔ bàn yī chǎng shēng rì yàn huì ba", "sentence_source": "generated"}, {"text": "他们每个月举办一次爬山活动。", "target_word": "举办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆举办了讲故事活动。", "target_word": "举办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班里准备举办一场晚会。", "target_word": "举办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校明年还要举办这个比赛。", "target_word": "举办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们一起举办了一场音乐会。", "target_word": "举办", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "举办了", "label": "体标"}, {"form": "举办过", "label": "体标"}, {"form": "舉辦", "label": "繁体"}], "register": "中性", "sense_fingerprint": "组织办一场活动、比赛或展览", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '115b89f7-bdbd-4625-a077-7b8981880a73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26564, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "举办", "is_correct": true, "explanation": "正确：“举办”与“展览”搭配，表示组织办一场展览。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉建筑或设施，不能用于展览。"}, {"text": "删除", "is_correct": false, "explanation": "搭配：“删除”用于文件、内容，不与“展览”搭配。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”指弄碎易碎的物品，展览不能被打碎。"}], "explanations": {"举办": "正确：“举办”与“展览”搭配，表示组织办一场展览。", "拆除": "语义：“拆除”指拆掉建筑或设施，不能用于展览。", "删除": "搭配：“删除”用于文件、内容，不与“展览”搭配。", "打碎": "语义：“打碎”指弄碎易碎的物品，展览不能被打碎。"}, "sentence_index": 0, "correct_answer": "举办"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他举办了一个笑话，大家都没笑。", "explanation": "这里应该用〈讲〉。“举办”搭配活动、比赛、展览等，讲笑话应说“讲”。"}, {"text": "他一只手就把那个大箱子举办了。", "explanation": "这里应该用〈举起〉。“举办”指组织活动，搬起重物应说“举起”。"}, {"text": "这家餐厅每天举办三次晚饭。", "explanation": "这里应该用〈做〉。“举办”用于活动、比赛、展览，三餐属于日常事务，应说“做”或“供应”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd95e60b8-a54b-4d98-91a0-30a25dd1f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26564, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "举办", "is_correct": true, "explanation": "正确：“举办”与“讲故事活动”搭配，表示组织办一场活动。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于机器、物品，不与“活动”搭配。"}, {"text": "下载", "is_correct": false, "explanation": "语义：“下载”指把文件从网上取到设备上，活动不能被下载。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：“吃掉”只用于食物，活动不能被吃掉。"}], "explanations": {"举办": "正确：“举办”与“讲故事活动”搭配，表示组织办一场活动。", "修理": "搭配：“修理”用于机器、物品，不与“活动”搭配。", "下载": "语义：“下载”指把文件从网上取到设备上，活动不能被下载。", "吃掉": "语义：“吃掉”只用于食物，活动不能被吃掉。"}, "sentence_index": 6, "correct_answer": "举办"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去银行举办了一笔转账。", "explanation": "这里应该用〈办理〉。“举办”用于活动、比赛、展览，银行业务应说“办理”。"}, {"text": "医生在医院举办了一场手术。", "explanation": "这里应该用〈进行〉。“举办”指组织活动，手术应说“进行”。"}, {"text": "工人们在工地上举办了一座大楼。", "explanation": "这里应该用〈建〉。“举办”用于组织活动、比赛、展览，盖楼应说“建”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd95e60b8-a54b-4d98-91a0-30a25dd1f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26564, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校下周要举办了一场运动会。", "corrected_sentence": "学校下周要举办一场运动会。", "error_description": "错误在“了”。“下周要”表示将来还没发生的事，动词“举办”后不能用表示完成的“了”。正确说法是“学校下周要举办一场运动会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd95e60b8-a54b-4d98-91a0-30a25dd1f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26564, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社区把广场举办了一场音乐节。", "corrected_sentence": "社区在广场举办了一场音乐节。", "error_description": "错误在介词。“举办”的处所要用“在”引出，“把”字句要求“把”后的名词受到处置，“把广场举办”不通。正确说法是“社区在广场举办了一场音乐节”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd95e60b8-a54b-4d98-91a0-30a25dd1f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
