INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26566, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家聚在一起动手学习或做东西的小活动。", "primary_collocate": null, "pronunciation": "gōng zuò fāng", "ipa": "kʊŋ˥ tsuɔ˥˩ fɑŋ˥", "syllable_count": 3, "sentences": [{"text": "我周末报名了一个做陶瓷的工作坊。", "target_word": "工作坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工作坊每周六下午开课。", "target_word": "工作坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在工作坊里学做木头椅子。", "target_word": "工作坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在工作坊上教大家做蛋糕。", "target_word": "工作坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她参加过一次画画工作坊。", "target_word": "工作坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作坊只有十个人，大家都能动手。", "target_word": "工作坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作坊结束后，我带回了自己做的杯子。", "target_word": "工作坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家书店常常办手工工作坊。", "target_word": "工作坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在工作坊里做了一条小木船。", "target_word": "工作坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区中心下个月有一个摄影工作坊。", "target_word": "工作坊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "场", "label": "量词"}], "register": "中性", "sense_fingerprint": "大家动手学习或制作的小型活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '115b89f7-bdbd-4625-a077-7b8981880a73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26566, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作坊", "is_correct": true, "explanation": "正确：“报名”参加的“做陶瓷的工作坊”是可以报名的学习活动。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“报名”不与“教室”搭配，报名的对象应是班或课程。"}, {"text": "画廊", "is_correct": false, "explanation": "语义：“画廊”是展示作品的场所，不能报名参加。"}, {"text": "窑", "is_correct": false, "explanation": "语义：“窑”是烧制陶器的设备，不能报名参加。"}], "explanations": {"工作坊": "正确：“报名”参加的“做陶瓷的工作坊”是可以报名的学习活动。", "教室": "搭配：“报名”不与“教室”搭配，报名的对象应是班或课程。", "画廊": "语义：“画廊”是展示作品的场所，不能报名参加。", "窑": "语义：“窑”是烧制陶器的设备，不能报名参加。"}, "sentence_index": 0, "correct_answer": "工作坊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上吃一个工作坊当早饭。", "explanation": "这里应该用〈面包〉之类的食物。“工作坊”是动手学习或做东西的活动，不能吃。"}, {"text": "这个工作坊是我们班的班主任。", "explanation": "这里应该用〈班级〉之类指人或集体的词。“工作坊”指动手学习的活动，不能当作人来用。"}, {"text": "我把工作坊放进书包，带去学校。", "explanation": "这里应该用〈作品〉。“工作坊”是一种活动，不是东西，不能放进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd95e60b8-a54b-4d98-91a0-30a25dd1f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26566, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作坊", "is_correct": true, "explanation": "正确：“工作坊”结束后可以带回自己做的东西，符合动手学习的活动。"}, {"text": "讲座", "is_correct": false, "explanation": "语义：“讲座”是听讲，不会让人做出杯子带回家。"}, {"text": "音乐会", "is_correct": false, "explanation": "语义：“音乐会”是听演出，不会做出杯子。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”是用餐场所，结束后不会让人带回自己做的杯子。"}], "explanations": {"工作坊": "正确：“工作坊”结束后可以带回自己做的东西，符合动手学习的活动。", "讲座": "语义：“讲座”是听讲，不会让人做出杯子带回家。", "音乐会": "语义：“音乐会”是听演出，不会做出杯子。", "食堂": "语义：“食堂”是用餐场所，结束后不会让人带回自己做的杯子。"}, "sentence_index": 6, "correct_answer": "工作坊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家在工作坊里吃饭唱歌，很热闹。", "explanation": "这里应该用〈聚会〉。“工作坊”强调动手学习或做东西，吃饭唱歌应说“聚会”。"}, {"text": "学员们在工作坊里赛跑，看谁先到终点。", "explanation": "这里应该用〈运动会〉。“工作坊”指动手学习或做东西的小活动，赛跑属于体育比赛，应说“运动会”。"}, {"text": "他把摄影工作坊挂在了客厅的墙上。", "explanation": "“工作坊”是活动，不是实物，不能挂在墙上。这里应该用〈作品〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd95e60b8-a54b-4d98-91a0-30a25dd1f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26566, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天去参加了一个木工工作坊。", "corrected_sentence": "我们明天去参加一个木工工作坊。", "error_description": "错误在“了”。“明天”表示将来，“去参加”后不加“了”。正确说法是“我们明天去参加一个木工工作坊”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd95e60b8-a54b-4d98-91a0-30a25dd1f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26566, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在一只陶艺工作坊里做了一个碗。", "corrected_sentence": "我们在一个陶艺工作坊里做了一个碗。", "error_description": "量词错误：“工作坊”应用“个”或“场”，“只”用于动物等个体，不能用于工作坊，应说“一个陶艺工作坊”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd95e60b8-a54b-4d98-91a0-30a25dd1f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
