INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26568, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "鸟是一类身上长羽毛、有翅膀和嘴巴的动物。", "primary_collocate": null, "pronunciation": "niǎo lèi", "ipa": "njɑʊ˨˩˦ leɪ˥˩", "syllable_count": 2, "sentences": [{"text": "公园里有很多鸟类。", "target_word": "鸟类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟类身上长着羽毛。", "target_word": "鸟类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢的鸟类是小燕子。", "target_word": "鸟类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在动物园看了各种鸟类。", "target_word": "鸟类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟类用嘴巴吃虫子和种子。", "target_word": "鸟类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，很多鸟类飞回了北方。", "target_word": "鸟类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了世界上的鸟类。", "target_word": "鸟类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们去森林观察鸟类。", "target_word": "鸟类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的鸟类会飞，有的不会飞。", "target_word": "鸟类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天很冷，鸟类飞到了南方。", "target_word": "鸟类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "鳥類", "label": "繁体"}], "register": "中性", "sense_fingerprint": "鸟类：日常所说的各种鸟，长羽毛、有翅膀和嘴巴的动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71266d48-abd2-408d-ab3d-49d9cf61150e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26568, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鸟类", "is_correct": true, "explanation": "正确：“鸟类”指各种鸟，“公园里有很多”的语境中可以作宾语。"}, {"text": "煤炭", "is_correct": false, "explanation": "语义：煤炭是矿物，不会在公园里成批出现，与公园的语境不合。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁是金属材料，不会作为公园里的常见事物出现。"}, {"text": "数学", "is_correct": false, "explanation": "语义：“数学”是学科，公园里不会“有很多”它，与具体场所的语境不合。"}], "explanations": {"鸟类": "正确：“鸟类”指各种鸟，“公园里有很多”的语境中可以作宾语。", "煤炭": "语义：煤炭是矿物，不会在公园里成批出现，与公园的语境不合。", "钢铁": "语义：钢铁是金属材料，不会作为公园里的常见事物出现。", "数学": "语义：“数学”是学科，公园里不会“有很多”它，与具体场所的语境不合。"}, "sentence_index": 0, "correct_answer": "鸟类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家阳台上有一棵鸟类。", "explanation": "这里应该用〈种〉。〈棵〉用于树、菜等植物，不能用来数动物。“鸟类”指一类动物，应数“种”。"}, {"text": "我昨天在商店买了三本鸟类。", "explanation": "这里应该用〈种〉。〈本〉用于书籍，不能用来数动物。“鸟类”指一类动物，应数“种”。"}, {"text": "我家养了一条鸟类。", "explanation": "这里应该用〈种〉。〈条〉多用于鱼、蛇、狗等，不用于鸟类这一类动物。“鸟类”指一类动物，应数“种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26568, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鸟类", "is_correct": true, "explanation": "正确：“鸟类”是可以被书介绍的对象，符合“介绍了世界上的”的语境。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”是时间单位，不是可以被书本介绍的事物。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“重量”是测量的结果，不能说“介绍了世界上的重量”。"}, {"text": "胃口", "is_correct": false, "explanation": "语义：“胃口”指食欲，是身体的感受，不是书本可以“介绍”的世界事物，与句意不合。"}], "explanations": {"鸟类": "正确：“鸟类”是可以被书介绍的对象，符合“介绍了世界上的”的语境。", "星期": "语义：“星期”是时间单位，不是可以被书本介绍的事物。", "重量": "搭配：“重量”是测量的结果，不能说“介绍了世界上的重量”。", "胃口": "语义：“胃口”指食欲，是身体的感受，不是书本可以“介绍”的世界事物，与句意不合。"}, "sentence_index": 6, "correct_answer": "鸟类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈买了两辆鸟类。", "explanation": "这里应该用〈种〉。〈辆〉用于车辆，不能用来数动物。“鸟类”指一类动物，应数“种”。"}, {"text": "墙上挂着一张鸟类。", "explanation": "这里应该用〈种〉。〈张〉用于纸张、画等扁平的东西，不能用来数动物。“鸟类”指一类动物，应数“种”。"}, {"text": "这家店卖一台鸟类。", "explanation": "这里应该用〈种〉。〈台〉用于机器、设备，不能用来数动物。“鸟类”指一类动物，应数“种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26568, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公园里有很多只鸟类。", "corrected_sentence": "公园里有很多种鸟类。", "error_description": "错误：“只”指单个动物，“鸟类”指一类动物，应该用“种”，写成“很多只鸟类”。正确：“很多种鸟类”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26568, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "秋天的时候，许多鸟类们飞到了南方。", "corrected_sentence": "秋天的时候，许多鸟类飞到了南方。", "error_description": "错误：“鸟类”已表示一类动物，后面不能再加“们”，写成“鸟类们”。正确：“许多鸟类”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
