INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26570, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能把两个东西粘在一起的东西。", "primary_collocate": null, "pronunciation": "nián hé jì", "ipa": "njɛn˧˥ xɤ˧˥ tɕi˥˩", "syllable_count": 3, "sentences": [{"text": "我想买一瓶黏合剂，修一下我的书包。", "target_word": "黏合剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这种黏合剂可以粘纸和木头。", "target_word": "黏合剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把黏合剂涂在碗的边上。", "target_word": "黏合剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个黏合剂用起来很方便。", "target_word": "黏合剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黏合剂放了很久，已经变硬了。", "target_word": "黏合剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明用黏合剂做了一只小船。", "target_word": "黏合剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用黏合剂以后，要等一会儿再动。", "target_word": "黏合剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里有很多种黏合剂。", "target_word": "黏合剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上的画掉了，我用黏合剂粘了回去。", "target_word": "黏合剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黏合剂干了以后，杯子就不会漏水了。", "target_word": "黏合剂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "黏合劑", "label": "繁体"}, {"form": "粘合剂", "label": "异体写法"}, {"form": "瓶", "label": "量词"}], "register": "中性", "sense_fingerprint": "能把东西粘在一起的胶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '295ce1da-7676-4f3c-bb25-0288a4081964') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26570, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "黏合剂", "is_correct": true, "explanation": "正确：黏合剂能把书包粘好，与“修一下”的语境相符。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水用于书写，不能用来修补书包。"}, {"text": "洗发水", "is_correct": false, "explanation": "搭配：“修一下书包”需要粘补材料，洗发水不能与之搭配。"}, {"text": "果汁", "is_correct": false, "explanation": "语义：果汁是饮料，不能用来修书包。"}], "explanations": {"黏合剂": "正确：黏合剂能把书包粘好，与“修一下”的语境相符。", "墨水": "语义：墨水用于书写，不能用来修补书包。", "洗发水": "搭配：“修一下书包”需要粘补材料，洗发水不能与之搭配。", "果汁": "语义：果汁是饮料，不能用来修书包。"}, "sentence_index": 0, "correct_answer": "黏合剂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件白衬衫用了黏合剂，变得更白了。", "explanation": "这里应该用〈漂白剂〉。黏合剂用于粘合，不能使衣服变白，漂白要用漂白剂。"}, {"text": "饭菜太淡了，他加了一点黏合剂。", "explanation": "这里应该用〈盐〉。黏合剂不能食用，给饭菜调味应加〈盐〉。"}, {"text": "我的手很脏，我用黏合剂洗了洗。", "explanation": "这里应该用〈肥皂〉。黏合剂用于粘合，不能用来清洁，洗手要用〈肥皂〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26570, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黏合剂", "is_correct": true, "explanation": "正确：涂了黏合剂以后要等它干，与“等一会儿再动”的语境相符。"}, {"text": "扫帚", "is_correct": false, "explanation": "语义：扫帚用完不需要等待才能动，与“等一会儿再动”的语境不符。"}, {"text": "草莓", "is_correct": false, "explanation": "搭配：“用”后面的宾语应是工具或材料，草莓不能这样使用。"}, {"text": "皮鞋", "is_correct": false, "explanation": "语义：皮鞋用完不需要等一会儿，与句中“等它干”的语境不符。"}], "explanations": {"黏合剂": "正确：涂了黏合剂以后要等它干，与“等一会儿再动”的语境相符。", "扫帚": "语义：扫帚用完不需要等待才能动，与“等一会儿再动”的语境不符。", "草莓": "搭配：“用”后面的宾语应是工具或材料，草莓不能这样使用。", "皮鞋": "语义：皮鞋用完不需要等一会儿，与句中“等它干”的语境不符。"}, "sentence_index": 6, "correct_answer": "黏合剂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想买两台黏合剂。", "explanation": "这里应该用〈瓶〉或〈管〉。“台”用于机器、家电，不用来数黏合剂。"}, {"text": "他买了三把黏合剂。", "explanation": "这里应该用〈瓶〉或〈管〉。“把”用于有柄的工具，黏合剂不能用“把”来数。"}, {"text": "这束黏合剂放在桌上。", "explanation": "这里应该用〈瓶〉或〈管〉。“束”用于花草等捆在一起的东西，不用来数黏合剂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我用一根黏合剂把杯子修好了。", "corrected_sentence": "我用一管黏合剂把杯子修好了。", "error_description": "量词错误：黏合剂装在管子里，应说“一管”，不能说“一根”，“根”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "黏合剂要透干，东西才粘得牢。", "corrected_sentence": "黏合剂要干透，东西才粘得牢。", "error_description": "补语错误：结果补语“透”应放在“干”之后，应说“干透”，不能说“透干”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
