INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26572, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "很多人一起做同一件事。", "primary_collocate": null, "pronunciation": "jí tǐ xíng dòng", "ipa": "tɕi˧˥ tʰi˨˩˦ ɕiŋ˧˥ tʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "明天上午有集体行动，请大家准时到。", "target_word": "集体行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了救那个孩子，大家展开了集体行动。", "target_word": "集体行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的集体行动是去海边捡垃圾。", "target_word": "集体行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次集体行动，我们班有三十人参加。", "target_word": "集体行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "集体行动要靠每个人的努力。", "target_word": "集体行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢集体行动，更喜欢一个人做事。", "target_word": "集体行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们的集体行动让老板同意了加工资。", "target_word": "集体行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们商量好了，下周开始集体行动。", "target_word": "集体行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "集体行动时，大家要互相照顾。", "target_word": "集体行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一次成功的集体行动需要好的计划。", "target_word": "集体行动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}], "register": "书面", "sense_fingerprint": "集体行动：很多人一起做同一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '295ce1da-7676-4f3c-bb25-0288a4081964') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26572, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集体行动", "is_correct": true, "explanation": "正确。“明天上午有集体行动”指一件需要许多人准时参加的事，与“请大家准时到”相合。"}, {"text": "小说", "is_correct": false, "explanation": "语义：“小说”是书，不是可以“准时到”的活动，句意不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”不是可以安排、可以“准时到”的事，句意不通。"}, {"text": "盐", "is_correct": false, "explanation": "搭配：“有”后接的应是活动或会议，“盐”是调味品，不能作为通知的事项。"}], "explanations": {"集体行动": "正确。“明天上午有集体行动”指一件需要许多人准时参加的事，与“请大家准时到”相合。", "小说": "语义：“小说”是书，不是可以“准时到”的活动，句意不通。", "空气": "语义：“空气”不是可以安排、可以“准时到”的事，句意不通。", "盐": "搭配：“有”后接的应是活动或会议，“盐”是调味品，不能作为通知的事项。"}, "sentence_index": 0, "correct_answer": "集体行动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个集体行动注册在民政局。", "explanation": "这里应该用〈团体〉。〈集体行动〉是一起做的事，不是可以注册的组织，说“注册”要用〈团体〉。"}, {"text": "这个集体行动成立于二〇〇五年。", "explanation": "这里应该用〈组织〉。〈集体行动〉是一次行为，不会“成立”，说成立要用〈组织〉。"}, {"text": "这个集体行动有两百名会员。", "explanation": "这里应该用〈协会〉。〈集体行动〉没有会员，说会员要用〈协会〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26572, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集体行动", "is_correct": true, "explanation": "正确。“工人们的集体行动”指工人一起采取的行动，能促使老板同意加工资，句意相合。"}, {"text": "新闻", "is_correct": false, "explanation": "语义：“新闻”是信息，不能“让老板同意加工资”，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不能作为促使老板同意的主体，句意不通。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“让老板同意”的主语须是有意愿的人或群体，“饭菜”不能与之搭配。"}], "explanations": {"集体行动": "正确。“工人们的集体行动”指工人一起采取的行动，能促使老板同意加工资，句意相合。", "新闻": "语义：“新闻”是信息，不能“让老板同意加工资”，句意不通。", "天气": "语义：“天气”是自然现象，不能作为促使老板同意的主体，句意不通。", "饭菜": "搭配：“让老板同意”的主语须是有意愿的人或群体，“饭菜”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "集体行动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们举办了一座集体行动。", "explanation": "这里应该用〈次〉。〈集体行动〉是一次行动，应按次计，用〈次〉，不能用大型固定物类量词。"}, {"text": "这块集体行动很精彩。", "explanation": "这里应该用〈场〉。〈集体行动〉是一场活动，应按场计，用〈场〉，不能用块状物类量词。"}, {"text": "她报名参加了一本集体行动。", "explanation": "这里应该用〈次〉。〈集体行动〉是一次行动，应按次计，用〈次〉，不能用书册类量词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26572, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "为了保护公园，我们组织了一首集体行动。", "corrected_sentence": "为了保护公园，我们组织了一次集体行动。", "error_description": "“集体行动”计数用“次”，“首”用于诗歌、歌曲，不能修饰它。应改为“一次集体行动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26572, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那把集体行动很成功。", "corrected_sentence": "那次集体行动很成功。", "error_description": "“集体行动”计数时用“次”或“场”，“把”用于有柄的器具，不能修饰它。应改为“那次集体行动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
