INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26574, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26574, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "快要到某种（多为不好的）情况了。", "primary_collocate": null, "pronunciation": "bīn lín", "ipa": "pin˥ lin˧˥", "syllable_count": 2, "sentences": [{"text": "这家老店生意不好，濒临关闭。", "target_word": "濒临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖水一年比一年少，湖濒临干涸。", "target_word": "濒临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他三天没吃饭，身体濒临极限。", "target_word": "濒临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林被砍了很多，许多动物濒临灭绝。", "target_word": "濒临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家经济很差，濒临破产。", "target_word": "濒临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们吵了很久，感情濒临破裂。", "target_word": "濒临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人的情况很不好，濒临死亡。", "target_word": "濒临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到坏消息，她濒临崩溃。", "target_word": "濒临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老桥太旧了，濒临倒塌。", "target_word": "濒临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队连输十场，濒临解散。", "target_word": "濒临", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "濒临着", "label": "体标"}], "register": "书面", "sense_fingerprint": "濒临：快要陷入某种糟糕的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '295ce1da-7676-4f3c-bb25-0288a4081964') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26574, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "濒临", "is_correct": true, "explanation": "濒临表示快要陷入糟糕的情况，「这家老店生意不好，濒临关闭」语义通顺，是唯一合适的词。"}, {"text": "开业", "is_correct": false, "explanation": "语义：开业与关闭的语义相反，句意矛盾。"}, {"text": "欢呼", "is_correct": false, "explanation": "语义：老店关闭不值得欢呼，这一搭配不合情理。"}, {"text": "修建", "is_correct": false, "explanation": "配价：「修建」需要具体的工程对象，「修建关闭」没有合理的结构。"}], "explanations": {"濒临": "濒临表示快要陷入糟糕的情况，「这家老店生意不好，濒临关闭」语义通顺，是唯一合适的词。", "开业": "语义：开业与关闭的语义相反，句意矛盾。", "欢呼": "语义：老店关闭不值得欢呼，这一搭配不合情理。", "修建": "配价：「修建」需要具体的工程对象，「修建关闭」没有合理的结构。"}, "sentence_index": 0, "correct_answer": "濒临"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他努力复习，考试成绩濒临满分。", "explanation": "这里应该用〈接近〉。濒临多用于快要陷入不好的情况，好的结果要用〈接近〉。"}, {"text": "春天濒临了，花都开了。", "explanation": "这里应该用〈来临〉。濒临指快要陷入不好的情况，且后面要带宾语；季节到来要用〈来临〉。"}, {"text": "他正濒临十年前的那段生活。", "explanation": "这里应该用〈回忆〉。濒临指快要到达的情况，过去的生活只能用〈回忆〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26574, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "濒临", "is_correct": true, "explanation": "濒临表示快要陷入不好的状况，「病人的情况很不好，濒临死亡」意思完整，是唯一合适的词。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：病人死亡不值得庆祝，句意荒谬。"}, {"text": "购买", "is_correct": false, "explanation": "配价：「购买」需要具体的商品作宾语，「购买死亡」不成立。"}, {"text": "出版", "is_correct": false, "explanation": "语义：死亡不能被出版，这一搭配荒谬。"}], "explanations": {"濒临": "濒临表示快要陷入不好的状况，「病人的情况很不好，濒临死亡」意思完整，是唯一合适的词。", "庆祝": "语义：病人死亡不值得庆祝，句意荒谬。", "购买": "配价：「购买」需要具体的商品作宾语，「购买死亡」不成立。", "出版": "语义：死亡不能被出版，这一搭配荒谬。"}, "sentence_index": 6, "correct_answer": "濒临"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "球队终于濒临胜利，已经领了奖杯。", "explanation": "这里应该用〈赢得〉。濒临指尚未发生的情况，与“已经领了奖杯”矛盾；已经发生的胜利要用〈赢得〉。"}, {"text": "他们濒临新的挑战，昨天就已经结束了。", "explanation": "这里应该用〈经历〉。濒临只指尚未发生的情况，昨天就已结束的挑战要用〈经历〉。"}, {"text": "我们濒临昨天的春节，玩得很开心。", "explanation": "这里应该用〈度过〉。濒临只指快要到达，已经过去的春节要用〈度过〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家超市连续亏损，已经濒临的倒闭。", "corrected_sentence": "这家超市连续亏损，已经濒临倒闭。", "error_description": "「濒临」与「倒闭」之间不能加「的」，正确形式为「已经濒临倒闭」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小国的经济状况很差，濒临在破产。", "corrected_sentence": "这个小国的经济状况很差，濒临破产。", "error_description": "结构错误：「濒临」直接带所面临的情况作宾语，中间不能加介词「在」，正确形式为「濒临破产」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
