INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26576, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26576, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "雏形是指东西最开始的样子，还没有完全做好。", "primary_collocate": null, "pronunciation": "chú xíng", "ipa": "tʂʰu˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个房子才有雏形，还不能住。", "target_word": "雏形", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新桥已经有了雏形。", "target_word": "雏形", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明做的小船只有一个雏形。", "target_word": "雏形", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张画现在只是一个雏形，还没画完。", "target_word": "雏形", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的网站已经初具雏形了。", "target_word": "雏形", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园的雏形出来了，下个月会更漂亮。", "target_word": "雏形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师看了我做的雏形，说想法很好。", "target_word": "雏形", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆车只是一个雏形，还不能开。", "target_word": "雏形", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过两个月，我们的小店有了雏形。", "target_word": "雏形", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先做一个雏形，再慢慢改。", "target_word": "雏形", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "雛形", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西刚开始的样子、还没做完", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c922d040-007a-4bf8-8a2a-fa6171f2be5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26576, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "雏形", "is_correct": true, "explanation": "正确。雏形指东西刚开始的样子、还没做完，与释义相符。"}, {"text": "出行", "is_correct": false, "explanation": "chū（第一声）与 chú（第二声）声调不同，意思是外出、出门旅行。"}, {"text": "图形", "is_correct": false, "explanation": "tú 与 chú 声母不同（t 与 ch），意思是图案或几何形状。"}, {"text": "除名", "is_correct": false, "explanation": "míng 与 xíng 声母不同（m 与 x），意思是把名字从名单上去掉。"}], "explanations": {"雏形": "正确。雏形指东西刚开始的样子、还没做完，与释义相符。", "出行": "chū（第一声）与 chú（第二声）声调不同，意思是外出、出门旅行。", "图形": "tú 与 chú 声母不同（t 与 ch），意思是图案或几何形状。", "除名": "míng 与 xíng 声母不同（m 与 x），意思是把名字从名单上去掉。"}, "sentence_index": null, "correct_answer": "雏形"}, "level_3": {"options": [{"text": "雏形", "is_correct": true, "explanation": "正确。雏形指东西刚开始的样子，与“才有”和“还不能住”相合。"}, {"text": "尾声", "is_correct": false, "explanation": "语义：“尾声”指结束的部分，与“才有”的开始义相反。"}, {"text": "废墟", "is_correct": false, "explanation": "语义：“废墟”指毁坏后的残迹，与“才有”的开始义相反。"}, {"text": "结局", "is_correct": false, "explanation": "搭配：“才有”说刚出现的事物，不能说才有结局。"}], "explanations": {"雏形": "正确。雏形指东西刚开始的样子，与“才有”和“还不能住”相合。", "尾声": "语义：“尾声”指结束的部分，与“才有”的开始义相反。", "废墟": "语义：“废墟”指毁坏后的残迹，与“才有”的开始义相反。", "结局": "搭配：“才有”说刚出现的事物，不能说才有结局。"}, "sentence_index": 0, "correct_answer": "雏形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份计划已经是雏形，可以开始施工了。", "explanation": "这里应该用〈定稿〉。雏形指尚未完善的样子，定稿的计划才能开始施工。"}, {"text": "这件衣服已经是雏形了，可以直接穿出门。", "explanation": "这里应该用〈成衣〉。雏形指尚未完善的样子，已经做好、可以直接穿的衣服要说成衣。"}, {"text": "这辆玩具车是一个完整的雏形，可以放在柜子里。", "explanation": "这里应该用〈模型〉。雏形指尚未完善的样子，“完整”的玩具车要说模型。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26576, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雏形", "is_correct": true, "explanation": "正确。雏形指东西开始的样子，与“我做的”初步作品相合。"}, {"text": "墓碑", "is_correct": false, "explanation": "语义：墓碑是纪念死者的石碑，不可能是学生做出来的东西。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“做的”说作品，不能说“做的成绩”。"}, {"text": "句号", "is_correct": false, "explanation": "语义：句号是标点符号，不是可以动手做出来的东西。"}], "explanations": {"雏形": "正确。雏形指东西开始的样子，与“我做的”初步作品相合。", "墓碑": "语义：墓碑是纪念死者的石碑，不可能是学生做出来的东西。", "成绩": "搭配：“做的”说作品，不能说“做的成绩”。", "句号": "语义：句号是标点符号，不是可以动手做出来的东西。"}, "sentence_index": 6, "correct_answer": "雏形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器能直接出售，是雏形。", "explanation": "这里应该用〈成品〉。雏形指尚未完善的样子，能直接出售的东西要说成品。"}, {"text": "这个雏形已经上市了，大家都在买。", "explanation": "这里应该用〈产品〉。雏形指尚未完善的样子，已经上市的东西不能叫雏形。"}, {"text": "他的雏形挂在美术馆里，很多人来参观。", "explanation": "这里应该用〈作品〉。雏形指尚未完善，挂在美术馆供人参观的完成之作要说作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校才有一片雏形，还要盖很久。", "corrected_sentence": "这所学校才有一个雏形，还要盖很久。", "error_description": "量词错误：“雏形”应该用“个”。“片”用于成片的地面或事物，不能说“一片雏形”，正确的是“一个雏形”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们画了一颗雏形，还要改很多次。", "corrected_sentence": "他们画了一个雏形，还要改很多次。", "error_description": "量词错误：“雏形”应该用“个”；“颗”用于粒状的小东西，不能说“一颗雏形”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
