INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26578, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用手做东西卖钱的人。", "primary_collocate": null, "pronunciation": "shǒu gōng yè zhě", "ipa": "ʂoʊ˨˩˦ kʊŋ˥ jɛ˥˩ ʈʂɤ˨˩˦", "syllable_count": 4, "sentences": [{"text": "我认识一位手工业者，他会做铜器。", "target_word": "手工业者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手工业者靠自己的手艺挣钱。", "target_word": "手工业者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手工业者做的东西常常很结实。", "target_word": "手工业者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街角住着一位手工业者，他做的鞋很好。", "target_word": "手工业者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位手工业者做了一把漂亮的椅子。", "target_word": "手工业者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客喜欢买手工业者做的小礼物。", "target_word": "手工业者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手工业者卖了一天的布，累坏了。", "target_word": "手工业者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想当手工业者，自己做首饰来卖。", "target_word": "手工业者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的手工业者在路边摆着摊。", "target_word": "手工业者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手工业者把刚做好的茶壶放到桌上。", "target_word": "手工业者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "手工業者", "label": "繁体"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "用手做东西来卖的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '295ce1da-7676-4f3c-bb25-0288a4081964') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26578, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手工业者", "is_correct": true, "explanation": "正确：手工业者指做手艺活的人，与“他会做铜器”相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是物品，不能被“认识”，也不会做铜器。"}, {"text": "城市", "is_correct": false, "explanation": "语义：城市不能用“一位”计数，也不会做铜器。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不会做铜器，与句意相悖。"}], "explanations": {"手工业者": "正确：手工业者指做手艺活的人，与“他会做铜器”相符。", "桌子": "语义：桌子是物品，不能被“认识”，也不会做铜器。", "城市": "语义：城市不能用“一位”计数，也不会做铜器。", "婴儿": "语义：婴儿不会做铜器，与句意相悖。"}, "sentence_index": 0, "correct_answer": "手工业者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂里的手工业者在流水线上装配手机。", "explanation": "这里应该用〈工人〉。手工业者靠手工做东西，不是在流水线上装配产品的人。"}, {"text": "这位手工业者每天坐在办公室里用电脑写报告。", "explanation": "这里应该用〈职员〉。手工业者是用手做东西来卖的人，不是在办公室写报告的人。"}, {"text": "手工业者在实验室里研究新药。", "explanation": "这里应该用〈科学家〉。手工业者不是在实验室研究新药的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26578, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手工业者", "is_correct": true, "explanation": "正确：手工业者靠手艺卖东西，主语是人，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会卖布，与“卖了一天的布”的语境不符。"}, {"text": "路灯", "is_correct": false, "explanation": "搭配：“卖布”的主语应是能做买卖的人，路灯不能与之搭配。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不能卖布。"}], "explanations": {"手工业者": "正确：手工业者靠手艺卖东西，主语是人，符合句意。", "石头": "语义：石头不会卖布，与“卖了一天的布”的语境不符。", "路灯": "搭配：“卖布”的主语应是能做买卖的人，路灯不能与之搭配。", "冰箱": "语义：冰箱是家电，不能卖布。"}, "sentence_index": 6, "correct_answer": "手工业者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块手工业者手艺很好。", "explanation": "这里应该用〈位〉。“块”用于块状的东西，不用来数人。"}, {"text": "村里有一条手工业者，做得很好。", "explanation": "这里应该用〈位〉。“条”用于细长的东西，不用来数人。"}, {"text": "这张手工业者很会卖布。", "explanation": "这里应该用〈位〉。“张”用于平面的东西，不用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26578, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位手工业者做得凳子很稳。", "corrected_sentence": "这位手工业者做的凳子很稳。", "error_description": "助词错误：修饰名词“凳子”应用“的”，“做得”是补语结构，不能修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26578, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我认识一座手工业者，他很会做木工。", "corrected_sentence": "我认识一位手工业者，他很会做木工。", "error_description": "量词错误：指人的“手工业者”应用“位”，“座”用于大型固定物，不能用来数人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
