INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26580, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "邻里就是住在附近的人。", "primary_collocate": null, "pronunciation": "lín lǐ", "ipa": "lin˧˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "邻里都认识这个爱笑的小孩。", "target_word": "邻里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们住的这条街，邻里都很热情。", "target_word": "邻里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻里听到哭声，马上跑了过来。", "target_word": "邻里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她请邻里来家里吃晚饭。", "target_word": "邻里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家有事，邻里都来帮忙。", "target_word": "邻里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻里常常坐在树下聊天。", "target_word": "邻里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过节时，邻里一起包饺子。", "target_word": "邻里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是帮邻里修东西。", "target_word": "邻里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻里之间要互相尊重。", "target_word": "邻里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老街的邻里每天早上都会打招呼。", "target_word": "邻里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "邻里：住在附近的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '295ce1da-7676-4f3c-bb25-0288a4081964') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26580, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "邻里", "is_correct": true, "explanation": "正确。“邻里”指住在附近的人，能够认识这个爱笑的小孩。"}, {"text": "书本", "is_correct": false, "explanation": "语义：“认识”要求有知觉的主语，“书本”不能认识人，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“认识”要求有知觉的主语，“桌子”不能认识人，句意不通。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“都认识……”的主语须是人或动物，“花园”不能与“认识”搭配。"}], "explanations": {"邻里": "正确。“邻里”指住在附近的人，能够认识这个爱笑的小孩。", "书本": "语义：“认识”要求有知觉的主语，“书本”不能认识人，句意不通。", "桌子": "语义：“认识”要求有知觉的主语，“桌子”不能认识人，句意不通。", "花园": "搭配：“都认识……”的主语须是人或动物，“花园”不能与“认识”搭配。"}, "sentence_index": 0, "correct_answer": "邻里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在楼下遇见一位邻里，他姓王。", "explanation": "这里应该用〈邻居〉。邻里指住在附近的人们（集体），指某一个人要用〈邻居〉。"}, {"text": "我家邻里有一家大超市。", "explanation": "这里应该用〈附近〉。邻里指人，不指地方；表示周围的地方要用〈附近〉。"}, {"text": "邻里的工作人员来家里登记。", "explanation": "这里应该用〈社区〉。〈邻里〉是住在附近的人，没有工作人员，负责登记的应是〈社区〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26580, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "邻里", "is_correct": true, "explanation": "正确。“过节时，邻里一起包饺子”指附近的人一起参与节日活动，句意相合。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：“包饺子”需要能动手的主体，“小猫”不能包饺子，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“一起包饺子”要求人或群体作主语，“石头”不能与之搭配。"}, {"text": "雨", "is_correct": false, "explanation": "语义：“雨”是天气现象，不能一起包饺子，句意不通。"}], "explanations": {"邻里": "正确。“过节时，邻里一起包饺子”指附近的人一起参与节日活动，句意相合。", "小猫": "语义：“包饺子”需要能动手的主体，“小猫”不能包饺子，句意不通。", "石头": "搭配：“一起包饺子”要求人或群体作主语，“石头”不能与之搭配。", "雨": "语义：“雨”是天气现象，不能一起包饺子，句意不通。"}, "sentence_index": 6, "correct_answer": "邻里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位邻里每天早上都会和我打招呼。", "explanation": "这里应该用〈邻居〉。邻里是集体说法，指某一个人要用〈邻居〉。"}, {"text": "我家邻里有一条小河。", "explanation": "这里应该用〈附近〉。邻里指住在附近的人，不指地方。"}, {"text": "这两个国家是邻里，常常互相访问。", "explanation": "这里应该用〈邻国〉。邻里指住在附近的人，相邻的国家要用〈邻国〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个老院子里的一位邻里常常互相帮忙。", "corrected_sentence": "这个老院子里的邻里常常互相帮忙。", "error_description": "「邻里」是集体名词，不能用「一位」计数，而且「互相」要求多个人，应去掉「一位」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "邻里的之间要互相体谅。", "corrected_sentence": "邻里之间要互相体谅。", "error_description": "“邻里之间”是固定说法，“之间”前面不能再加“的”。应去掉“的”，说“邻里之间”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
