INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26582, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "种很多树，挡住风和沙子。", "primary_collocate": null, "pronunciation": "fáng hù lín", "ipa": "faŋ˧˥ xu˥˩ lin˧˥", "syllable_count": 3, "sentences": [{"text": "村子北边有一片防护林。", "target_word": "防护林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "防护林能挡住风和沙子。", "target_word": "防护林", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们在沙漠旁边种了防护林。", "target_word": "防护林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为有防护林，农田里的沙子少了。", "target_word": "防护林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片防护林有三十年了，树很高。", "target_word": "防护林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天，学生们去山上给防护林浇水。", "target_word": "防护林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大风来的时候，防护林把沙子挡在外面。", "target_word": "防护林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每天都去看他种的防护林。", "target_word": "防护林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边需要防护林，不然大风会吹坏房子。", "target_word": "防护林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路两边都是防护林。", "target_word": "防护林", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "防護林", "label": "繁体"}], "register": "中性", "sense_fingerprint": "种很多树用来挡风挡沙的树林", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c922d040-007a-4bf8-8a2a-fa6171f2be5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26582, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "防护林", "is_correct": true, "explanation": "正确。防护林是成片的树林，与“一片”和“村子北边”相合。"}, {"text": "答案", "is_correct": false, "explanation": "搭配：“一片”用于地面或成片的事物，不能说一片答案。"}, {"text": "历史", "is_correct": false, "explanation": "语义：历史是过去发生的事，不是可以位于村子北边的一片地方。"}, {"text": "纸牌", "is_correct": false, "explanation": "语义：纸牌是玩具，不是地方，不能位于村子北边。"}], "explanations": {"防护林": "正确。防护林是成片的树林，与“一片”和“村子北边”相合。", "答案": "搭配：“一片”用于地面或成片的事物，不能说一片答案。", "历史": "语义：历史是过去发生的事，不是可以位于村子北边的一片地方。", "纸牌": "语义：纸牌是玩具，不是地方，不能位于村子北边。"}, "sentence_index": 0, "correct_answer": "防护林"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个防护林里养了很多狮子，游客很喜欢。", "explanation": "这里应该用〈动物园〉。防护林是种树挡风沙的，养狮子供游客参观的地方要说动物园。"}, {"text": "这些防护林是用来盖房子的。", "explanation": "这里应该用〈木料〉。防护林是种树挡风沙的，用来盖房子的木材要说木料。"}, {"text": "这座防护林每天接待很多病人，医生很忙。", "explanation": "这里应该用〈医院〉。防护林是种树挡风沙的，接待病人、有医生的地方要说医院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26582, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "防护林", "is_correct": true, "explanation": "正确。防护林能挡住风和沙子，与“把沙子挡在外面”相合。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不是能挡住风沙的实物，不能把沙子挡在外面。"}, {"text": "时间", "is_correct": false, "explanation": "配价：“把……挡在外面”的主语要求能挡东西的具体事物，不能是时间。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是实物，不能把沙子挡在外面。"}], "explanations": {"防护林": "正确。防护林能挡住风和沙子，与“把沙子挡在外面”相合。", "作业": "语义：作业是学习任务，不是能挡住风沙的实物，不能把沙子挡在外面。", "时间": "配价：“把……挡在外面”的主语要求能挡东西的具体事物，不能是时间。", "名字": "语义：名字不是实物，不能把沙子挡在外面。"}, "sentence_index": 6, "correct_answer": "防护林"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的客厅里摆着一个小小的防护林，很好看。", "explanation": "这里应该用〈盆景〉。防护林是种树挡风沙的大片树林，摆在屋里的小型造景要说盆景。"}, {"text": "这个防护林的座位很软，我喜欢坐在上面看书。", "explanation": "这里应该用〈沙发〉。防护林是种树挡风沙的树林，不能有座位，可供人坐着的家具要说沙发。"}, {"text": "我们在防护林吃饭，服务员端来了很多菜。", "explanation": "这里应该用〈餐厅〉。防护林是种树挡风沙的树林，吃饭上菜的地方要说餐厅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26582, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村子东边有一辆防护林。", "corrected_sentence": "村子东边有一片防护林。", "error_description": "量词错误：防护林是成片的树林，应该用“片”；“辆”只用于车，不能说“一辆防护林”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26582, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们村有两只防护林。", "corrected_sentence": "我们村有两片防护林。", "error_description": "量词错误：防护林是成片的树林，应该用“片”；“只”用于动物，不能说“两只防护林”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
