INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26584, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "就是干活，比如种地或做手工。", "primary_collocate": null, "pronunciation": "láo zuò", "ipa": "laʊ˧˥ tswɔ˥˩", "syllable_count": 2, "sentences": [{"text": "农民每天在田里劳作。", "target_word": "劳作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷劳作了一辈子，从不喊累。", "target_word": "劳作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在院子里一边劳作一边聊天。", "target_word": "劳作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她白天在地里劳作，晚上做手工。", "target_word": "劳作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家劳作了一天，都很累。", "target_word": "劳作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们跟着父母一起劳作。", "target_word": "劳作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要在太阳下劳作太久。", "target_word": "劳作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在山上劳作着，没有听到电话。", "target_word": "劳作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们春天忙着在地里劳作。", "target_word": "劳作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人喜欢劳作，不愿意在家闲着。", "target_word": "劳作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "勞作", "label": "繁体"}, {"form": "劳作了", "label": "体标"}, {"form": "劳作着", "label": "体标"}], "register": "中性", "sense_fingerprint": "干体力活，如种地、做手工", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '295ce1da-7676-4f3c-bb25-0288a4081964') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26584, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "劳作", "is_correct": true, "explanation": "劳作是不及物动词，「在田里劳作」完整通顺，是此处唯一合适的词。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：农民每天在田里睡觉不是正常的日常活动，句意荒谬。"}, {"text": "购物", "is_correct": false, "explanation": "语义：田里不是购物的场所，农民每天在田里购物与语境不合。"}, {"text": "飞行", "is_correct": false, "explanation": "语义：人不能在田里飞行，句意荒谬。"}], "explanations": {"劳作": "劳作是不及物动词，「在田里劳作」完整通顺，是此处唯一合适的词。", "睡觉": "语义：农民每天在田里睡觉不是正常的日常活动，句意荒谬。", "购物": "语义：田里不是购物的场所，农民每天在田里购物与语境不合。", "飞行": "语义：人不能在田里飞行，句意荒谬。"}, "sentence_index": 0, "correct_answer": "劳作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台仪器的劳作很简单，两分钟就学会了。", "explanation": "这里应该用〈操作〉。劳作指干活，仪器的使用要用〈操作〉。"}, {"text": "他用脑劳作，很少休息。", "explanation": "这里应该用〈工作〉。劳作指动手干活，如种地、做手工，用脑为主的事务要用〈工作〉。"}, {"text": "孩子们在院子里劳作，跑来跑去。", "explanation": "这里应该用〈玩耍〉。劳作指干活，玩耍不能说劳作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26584, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "劳作", "is_correct": true, "explanation": "劳作表示持续的体力活动，「不要在太阳下劳作太久」意思完整，是唯一合适的词。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚不是可以在太阳下持续进行的活动，句意不通。"}, {"text": "认识", "is_correct": false, "explanation": "配价：「认识」是及物动词，此处缺少宾语，句子不成立。"}, {"text": "选举", "is_correct": false, "explanation": "语义：选举不会在太阳下持续进行，句意荒谬。"}], "explanations": {"劳作": "劳作表示持续的体力活动，「不要在太阳下劳作太久」意思完整，是唯一合适的词。", "结婚": "语义：结婚不是可以在太阳下持续进行的活动，句意不通。", "认识": "配价：「认识」是及物动词，此处缺少宾语，句子不成立。", "选举": "语义：选举不会在太阳下持续进行，句意荒谬。"}, "sentence_index": 6, "correct_answer": "劳作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在图书馆里劳作，看了一下午的书。", "explanation": "这里应该用〈读书〉。劳作指干活，看书学习要用〈读书〉。"}, {"text": "我们在舞台上劳作，唱了三首歌。", "explanation": "这里应该用〈表演〉。劳作指干活，台上的演出要用〈表演〉。"}, {"text": "他在操场上劳作，跑了一小时的步。", "explanation": "这里应该用〈锻炼〉。劳作指干活，为健身而跑步要用〈锻炼〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26584, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他辛苦地劳作地，从不抱怨。", "corrected_sentence": "他辛苦地劳作，从不抱怨。", "error_description": "多余的状语标记：「地」只用在状语与动词之间，“劳作”后不能再加“地”，正确形式为「辛苦地劳作」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26584, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在地里劳作地了一上午，终于歇下来了。", "corrected_sentence": "她在地里劳作了一上午，终于歇下来了。", "error_description": "多余的状语标记：「地」只用在状语与动词之间，动词「劳作」后不能再加「地」，应删去，正确形式为「在地里劳作了一上午」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
