INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26586, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "村民代表是大家选出来帮助村民说话的人。", "primary_collocate": null, "pronunciation": "cūn mín dài biǎo", "ipa": "tsʰwən˥ min˧˥ taɪ̯˥˩ piɑʊ̯˨˩˦", "syllable_count": 4, "sentences": [{"text": "村民代表是大家选出来的人。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民代表帮大家去和村长说话。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们村的村民代表是大家选的，她姓王。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的水管坏了，大家请村民代表帮忙去说一说。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民代表听了大家的话，写在本子上。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村民代表很会说话，大家都喜欢他。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷是大家选出来的村民代表。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民代表明天去镇上，为大家说话。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有事就找村民代表，他会帮大家说话。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想让她当村民代表。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位村民代表", "label": "量词"}, {"form": "村民代表大会", "label": "复合"}], "register": "中性", "sense_fingerprint": "大家选出来、替村民说话的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c922d040-007a-4bf8-8a2a-fa6171f2be5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26586, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "村民代表", "is_correct": true, "explanation": "正确：村民代表是大家选出来、替村民说话的人，与句意相合。"}, {"text": "村委会", "is_correct": false, "explanation": "搭配：“是……的人”要求指人的名词，村委会是机构，不能说“村委会是大家选出来的人”。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗是动物，不会由大家选出来担任职务。"}, {"text": "木桌", "is_correct": false, "explanation": "搭配：“选出来的人”指人，木桌不能说是选出来的人。"}], "explanations": {"村民代表": "正确：村民代表是大家选出来、替村民说话的人，与句意相合。", "村委会": "搭配：“是……的人”要求指人的名词，村委会是机构，不能说“村委会是大家选出来的人”。", "小狗": "语义：小狗是动物，不会由大家选出来担任职务。", "木桌": "搭配：“选出来的人”指人，木桌不能说是选出来的人。"}, "sentence_index": 0, "correct_answer": "村民代表"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "村民代表负责给大家上数学课。", "explanation": "这里应该用〈老师〉。老师负责上课；村民代表替村民说话，不负责教课。"}, {"text": "村民代表替公司说话。", "explanation": "这里应该用〈发言人〉。村民代表替村民说话，不替公司或机构说话。"}, {"text": "村民代表负责做饭。", "explanation": "这里应该用〈厨师〉。厨师负责烹饪；村民代表替村民说话，不负责做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26586, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "村民代表", "is_correct": true, "explanation": "正确：爷爷是大家选出来替村民说话的人，村民代表与句意相合。"}, {"text": "小树", "is_correct": false, "explanation": "语义：小树不是人，不能由大家选出来。"}, {"text": "水桶", "is_correct": false, "explanation": "语义：水桶是器物，不能由大家选出来。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能被选出来，与“选出来的”相冲突。"}], "explanations": {"村民代表": "正确：爷爷是大家选出来替村民说话的人，村民代表与句意相合。", "小树": "语义：小树不是人，不能由大家选出来。", "水桶": "语义：水桶是器物，不能由大家选出来。", "石头": "语义：石头不能被选出来，与“选出来的”相冲突。"}, "sentence_index": 6, "correct_answer": "村民代表"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "村民代表负责教学生。", "explanation": "这里应该用〈老师〉。老师负责教学；村民代表替村民说话，不负责教育学生。"}, {"text": "村民代表负责开车送大家。", "explanation": "这里应该用〈司机〉。司机负责驾驶；村民代表替村民说话，不负责开车。"}, {"text": "村民代表负责给病人打针。", "explanation": "这里应该用〈护士〉。护士负责护理和打针；村民代表不负责医疗操作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26586, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们村推选了两只村民代表。", "corrected_sentence": "我们村推选了两位村民代表。", "error_description": "量词错误：村民代表指人，应用“位”或“个”，“只”用于动物或小物件。错误形式为“两只村民代表”，正确形式为“两位村民代表”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26586, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村里选出了五村民代表。", "corrected_sentence": "村里选出了五位村民代表。", "error_description": "量词缺失：数词“五”后面必须加量词，指人的“村民代表”应用“位”。错误形式为“五村民代表”，正确形式为“五位村民代表”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
