INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26588, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "说话或做事有根据，不是乱说的。", "primary_collocate": null, "pronunciation": "yǒu lǐ yǒu jù", "ipa": "joʊ̯˨˩˦ li˨˩˦ joʊ̯˨˩˦ tɕy˥˩", "syllable_count": 4, "sentences": [{"text": "他说的话有理有据，不是乱说的。", "target_word": "有理有据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做决定有理有据，从不冲动。", "target_word": "有理有据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把为什么这样做讲得有理有据。", "target_word": "有理有据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要有理有据，别人才会听你的。", "target_word": "有理有据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的想法有理有据，老师同意了。", "target_word": "有理有据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法有理有据，不是随便想的。", "target_word": "有理有据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说得有理有据，我没话说了。", "target_word": "有理有据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事有理有据，每一步都有原因。", "target_word": "有理有据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是乱说的，每句话都有理有据。", "target_word": "有理有据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的发言有理有据，大人们都点头。", "target_word": "有理有据", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有理有據", "label": "繁体"}], "register": "中性", "sense_fingerprint": "说话或做事有根据、不是乱说乱做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c922d040-007a-4bf8-8a2a-fa6171f2be5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26588, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有理有据", "is_correct": true, "explanation": "“有理有据”说明他的话有道理、有根据，与“不是乱说的”相符。"}, {"text": "乱七八糟", "is_correct": false, "explanation": "语义：“乱七八糟”指杂乱无章，与“不是乱说的”的意思相矛盾。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”多用于水、眼睛等，不能用来形容说的话。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体型或人物形象，不能用来形容话语。"}], "explanations": {"有理有据": "“有理有据”说明他的话有道理、有根据，与“不是乱说的”相符。", "乱七八糟": "语义：“乱七八糟”指杂乱无章，与“不是乱说的”的意思相矛盾。", "清澈": "搭配：“清澈”多用于水、眼睛等，不能用来形容说的话。", "高大": "搭配：“高大”形容体型或人物形象，不能用来形容话语。"}, "sentence_index": 0, "correct_answer": "有理有据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的话漏洞百出，却有理有据地驳了回去。", "explanation": "这里应该用〈振振有词〉。“有理有据”要求根据充分，此句说“漏洞百出”，前后矛盾。“振振有词”指说话理直气壮、很有把握。"}, {"text": "他有理有据，说的全是没影儿的事。", "explanation": "这里应该用〈信口开河〉。信口开河指不经思考随便乱说，与“有理有据”指说话有根据相反，此句说“全是没影儿的事”，前后矛盾。"}, {"text": "这件事他有理有据，根本没有依据。", "explanation": "这里应该用〈胡说八道〉。“有理有据”要求有依据，此句说“根本没有依据”，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26588, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有理有据", "is_correct": true, "explanation": "“有理有据”说明妈妈的讲法有道理、有根据，所以我没话说了。"}, {"text": "粗壮", "is_correct": false, "explanation": "体貌：“粗壮”形容体型，不能用来形容说话的样子。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”描写人的体型，不能用来描述说话的内容。"}, {"text": "碧绿", "is_correct": false, "explanation": "搭配：“碧绿”形容颜色，不能修饰“说得”，两者搭配不通。"}], "explanations": {"有理有据": "“有理有据”说明妈妈的讲法有道理、有根据，所以我没话说了。", "粗壮": "体貌：“粗壮”形容体型，不能用来形容说话的样子。", "瘦小": "体貌：“瘦小”描写人的体型，不能用来描述说话的内容。", "碧绿": "搭配：“碧绿”形容颜色，不能修饰“说得”，两者搭配不通。"}, "sentence_index": 6, "correct_answer": "有理有据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有理有据，没有一句是实在的。", "explanation": "这里应该用〈夸夸其谈〉。夸夸其谈指说话空泛浮夸，与“有理有据”要求的根据相反，此句说“没有一句是实在的”，两者矛盾。"}, {"text": "这孩子有理有据，编出的理由根本站不住脚。", "explanation": "这里应该用〈强词夺理〉。强词夺理指硬要为错误辩解，此句说理由“站不住脚”，与“有理有据”前后矛盾。"}, {"text": "他有理有据，一句话也没法相信。", "explanation": "这里应该用〈满口胡言〉。满口胡言指说的都是假话或荒唐话，与“有理有据”的要求矛盾，此句说“一句话也没法相信”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有理有据的驳斥了对方的说法。", "corrected_sentence": "她有理有据地驳斥了对方的说法。", "error_description": "结构助词错误：修饰动词“驳斥”时应用“地”，应说“有理有据地驳斥”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老王讲有理有据，大家都服气。", "corrected_sentence": "老王讲得有理有据，大家都服气。", "error_description": "补语错误：“讲”后面引出补语“有理有据”时要用“得”，应说“讲得有理有据”。漏掉“得”，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
