INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26590, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大人们坐在一起听别人说话，然后做决定。", "primary_collocate": null, "pronunciation": "tīng zhèng huì", "ipa": "tʰiŋ˥ ʈʂɤŋ˥˩ xweɪ̯˥˩", "syllable_count": 3, "sentences": [{"text": "听证会上，大人们坐在一起听大家说话。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开听证会的时候，每个人都可以说一说。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里要修路，先开了一场听证会。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈今天去参加听证会，晚上才回家。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家在听证会上说完话，领导才做决定。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听证会开了两个小时，大人们一直在听。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跟爸爸去看了听证会，里面坐了很多大人。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，听证会就是先听大家说，再做决定。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听证会开完以后，他们决定不砍这棵树了。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要换新校服，先开听证会听大家的想法。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场听证会", "label": "量词"}, {"form": "价格听证会", "label": "复合"}, {"form": "聽證會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大人们坐在一起先听大家说话、再做决定的会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c922d040-007a-4bf8-8a2a-fa6171f2be5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26590, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听证会", "is_correct": true, "explanation": "“听证会”是大人坐下来先听大家说话再做决定的会，与句中“大人们坐在一起听大家说话”相符。"}, {"text": "舞会", "is_correct": false, "explanation": "语义：舞会以跳舞为主，与“坐在一起听大家说话”的情境不符。"}, {"text": "音乐会", "is_correct": false, "explanation": "搭配：“音乐会”以欣赏演出为主，不能说“听大家说话”，两者搭配不通。"}, {"text": "运动场", "is_correct": false, "explanation": "语义：运动场是体育活动场地，没有坐下来听人发言的程序。"}], "explanations": {"听证会": "“听证会”是大人坐下来先听大家说话再做决定的会，与句中“大人们坐在一起听大家说话”相符。", "舞会": "语义：舞会以跳舞为主，与“坐在一起听大家说话”的情境不符。", "音乐会": "搭配：“音乐会”以欣赏演出为主，不能说“听大家说话”，两者搭配不通。", "运动场": "语义：运动场是体育活动场地，没有坐下来听人发言的程序。"}, "sentence_index": 0, "correct_answer": "听证会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们开听证会，大家随便聊聊天。", "explanation": "这里应该用〈座谈会〉。座谈会可以随意交流，听证会是大人坐下来先听别人说话、再做决定的正式会，不用于随便聊天。"}, {"text": "大家在听证会上默哀，表示哀悼。", "explanation": "这里应该用〈追悼会〉。追悼会是悼念逝者的场合，听证会是大人先听别人说话、再做决定的正式会，不用于默哀。"}, {"text": "听证会上，老师和同学一起讨论课文。", "explanation": "这里应该用〈研讨会〉。研讨会是大家共同讨论问题的场合，听证会是听别人说话后再做决定，不是同学讨论课文。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26590, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听证会", "is_correct": true, "explanation": "“听证会”是大人坐着听取发言的会，句中“里面坐了很多大人”与之相符。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：菜市场是买卖菜的地方，里面没有成排坐着的大人。"}, {"text": "烧烤", "is_correct": false, "explanation": "语义：烧烤是吃东西的活动，不是坐满大人、听人发言的会，与句意不符。"}, {"text": "鬼屋", "is_correct": false, "explanation": "语义：鬼屋里是恐怖场景，没有成排坐着的大人，与句中“里面坐了很多大人”不符。"}], "explanations": {"听证会": "“听证会”是大人坐着听取发言的会，句中“里面坐了很多大人”与之相符。", "菜市场": "语义：菜市场是买卖菜的地方，里面没有成排坐着的大人。", "烧烤": "语义：烧烤是吃东西的活动，不是坐满大人、听人发言的会，与句意不符。", "鬼屋": "语义：鬼屋里是恐怖场景，没有成排坐着的大人，与句中“里面坐了很多大人”不符。"}, "sentence_index": 6, "correct_answer": "听证会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校要换新校服，先开听证会，向家长介绍新校服的样式。", "explanation": "这里应该用〈说明会〉。说明会是单向介绍情况的会，听证会是大人先听别人说话、再做决定，不用于向家长介绍样式。"}, {"text": "学校要换新校服，先开听证会，请大家一起唱歌跳舞。", "explanation": "这里应该用〈联欢会〉。联欢会是大家一起娱乐庆祝的场合；听证会是听别人说话后再做决定，不是唱歌跳舞。"}, {"text": "学校要换新校服，先开听证会，给学生发奖状。", "explanation": "这里应该用〈颁奖会〉。颁奖会是给人发奖的场合；听证会是先听大家说话、再做决定，不用于发奖状。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家听证会上说话，然后领导做决定。", "corrected_sentence": "大家在听证会上说话，然后领导做决定。", "error_description": "介词错误：“听证会”作处所时要用介词“在”引出，应说“在听证会上说话”，漏掉“在”句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听证会开很长，大人们一直在听。", "corrected_sentence": "听证会开得很长，大人们一直在听。", "error_description": "补语错误：“开”后面引出补语“很长”时要用“得”，应说“开得很长”。漏掉“得”，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
