INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26592, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用工具把树弄倒。", "primary_collocate": null, "pronunciation": "kǎn fá", "ipa": "kʰan˨˩ fa˧˥", "syllable_count": 2, "sentences": [{"text": "工人在山上砍伐大树。", "target_word": "砍伐", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们用锯子砍伐树木。", "target_word": "砍伐", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "不要随便砍伐公园里的树。", "target_word": "砍伐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷年轻时在山里砍伐过树。", "target_word": "砍伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民砍伐了树，准备盖新房子。", "target_word": "砍伐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "砍伐树木以后，雨水会把山上的土冲走。", "target_word": "砍伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了做桌子，他们砍伐了几棵老树。", "target_word": "砍伐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里禁止砍伐，请大家保护森林。", "target_word": "砍伐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我听到山里有人在砍伐。", "target_word": "砍伐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们正在砍伐路边的老树。", "target_word": "砍伐", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "砍伐了", "label": "体标"}, {"form": "砍伐过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用工具把树弄倒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c922d040-007a-4bf8-8a2a-fa6171f2be5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26592, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "砍伐", "is_correct": true, "explanation": "正确答案。砍伐 kǎn fá：用工具把树弄倒。"}, {"text": "看法", "is_correct": false, "explanation": "看法 kàn fǎ 两个音节的声调都与 kǎn fá 不同（第四声、第三声），意思是对事物的见解。"}, {"text": "开发", "is_correct": false, "explanation": "开发 kāi fā 与 kǎn fá 韵母（ai/an）和声调都不同，意思是开拓利用资源或研制新产品。"}, {"text": "刊发", "is_correct": false, "explanation": "刊发 kān fā 第一音节 kān（第一声）与 kǎn（第三声）声调不同，第二音节 fā 与 fá 声调也不同，意思是刊登发表。"}], "explanations": {"砍伐": "正确答案。砍伐 kǎn fá：用工具把树弄倒。", "看法": "看法 kàn fǎ 两个音节的声调都与 kǎn fá 不同（第四声、第三声），意思是对事物的见解。", "开发": "开发 kāi fā 与 kǎn fá 韵母（ai/an）和声调都不同，意思是开拓利用资源或研制新产品。", "刊发": "刊发 kān fā 第一音节 kān（第一声）与 kǎn（第三声）声调不同，第二音节 fā 与 fá 声调也不同，意思是刊登发表。"}, "sentence_index": null, "correct_answer": "砍伐"}, "level_3": {"options": [{"text": "砍伐", "is_correct": true, "explanation": "正确：“在山上砍伐大树”指用工具把大树砍倒，与语境相合。"}, {"text": "粉刷", "is_correct": false, "explanation": "搭配：粉刷用于墙面等表面，不说“粉刷大树”。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：装修的对象是房屋，不说“装修大树”。"}, {"text": "修建", "is_correct": false, "explanation": "语义：修建指建造道路、房屋等设施，与在山上处理大树的语境不合。"}], "explanations": {"砍伐": "正确：“在山上砍伐大树”指用工具把大树砍倒，与语境相合。", "粉刷": "搭配：粉刷用于墙面等表面，不说“粉刷大树”。", "装修": "搭配：装修的对象是房屋，不说“装修大树”。", "修建": "语义：修建指建造道路、房屋等设施，与在山上处理大树的语境不合。"}, "sentence_index": 0, "correct_answer": "砍伐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "园丁每周都砍伐院子里的花草。", "explanation": "这里应该用〈修剪〉。修剪用于整理花草枝叶；砍伐指把树砍倒，不用于花草。"}, {"text": "工人砍伐了那座旧房子。", "explanation": "这里应该用〈拆〉。拆用于拆除建筑；砍伐只用于树木。"}, {"text": "妈妈用剪刀砍伐了一根线。", "explanation": "这里应该用〈剪断〉。剪断用于细长物，如线、绳；砍伐的对象是树木。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26592, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "砍伐", "is_correct": true, "explanation": "正确：为了做桌子而取材，砍伐老树与句中的目的相合。"}, {"text": "栽种", "is_correct": false, "explanation": "语义：栽种是为了让树生长，与为做桌子而取材的目的相反。"}, {"text": "浇灌", "is_correct": false, "explanation": "语义：浇灌是给植物浇水，与为做桌子取材的目的不合。"}, {"text": "移植", "is_correct": false, "explanation": "语义：移植是把树挪到别处栽活，与做桌子取材的目的不合。"}], "explanations": {"砍伐": "正确：为了做桌子而取材，砍伐老树与句中的目的相合。", "栽种": "语义：栽种是为了让树生长，与为做桌子而取材的目的相反。", "浇灌": "语义：浇灌是给植物浇水，与为做桌子取材的目的不合。", "移植": "语义：移植是把树挪到别处栽活，与做桌子取材的目的不合。"}, "sentence_index": 6, "correct_answer": "砍伐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民在地里砍伐红薯。", "explanation": "这里应该用〈挖〉。挖用于取出地下的块根；砍伐只用于把树木砍倒。"}, {"text": "他在果园里砍伐了几个梨。", "explanation": "这里应该用〈摘〉。摘指把果实从树上取下；砍伐指把树砍倒。"}, {"text": "她在厨房里砍伐了几个土豆。", "explanation": "这里应该用〈切〉。切用于把食物切开；砍伐专指把树木砍倒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26592, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人在山上砍伐了三只大树。", "corrected_sentence": "工人在山上砍伐了三棵大树。", "error_description": "量词错误：树木的量词应为“棵”，“只”用于动物等。错误形式为“三只大树”，正确形式为“三棵大树”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26592, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村里的老人说，他们以前砍伐了过几棵大槐树。", "corrected_sentence": "村里的老人说，他们以前砍伐过几棵大槐树。", "error_description": "体标错误：“了”与“过”不能同用，“过”应紧接动词。错误形式为“砍伐了过”，正确形式为“砍伐过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26594, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赞同", "is_correct": true, "explanation": "“赞同”表示认为对而支持，与“反对”（不赞同）意思相反，是反义词。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”指躺下休息，与“反对”没有反义关系。"}, {"text": "购买", "is_correct": false, "explanation": "“购买”指花钱得到东西，与“反对”没有反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”指深入探讨问题，与“反对”没有反义关系。"}], "correct_answer": "赞同", "explanations": {"赞同": "“赞同”表示认为对而支持，与“反对”（不赞同）意思相反，是反义词。", "睡觉": "“睡觉”指躺下休息，与“反对”没有反义关系。", "购买": "“购买”指花钱得到东西，与“反对”没有反义关系。", "研究": "“研究”指深入探讨问题，与“反对”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26594, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "支持", "is_correct": true, "explanation": "“支持”表示赞成、拥护，与“反对”（不赞同）意思相反，是反义词。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”指用声音演唱，与“反对”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指随意走动，与“反对”没有反义关系。"}, {"text": "保存", "is_correct": false, "explanation": "“保存”指把东西留存下来，与“反对”没有反义关系。"}], "correct_answer": "支持", "explanations": {"支持": "“支持”表示赞成、拥护，与“反对”（不赞同）意思相反，是反义词。", "唱歌": "“唱歌”指用声音演唱，与“反对”没有反义关系。", "散步": "“散步”指随意走动，与“反对”没有反义关系。", "保存": "“保存”指把东西留存下来，与“反对”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26594, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不赞同别人的想法或做法。", "primary_collocate": null, "pronunciation": "fǎn duì", "ipa": "fan²¹⁴ tuei⁵¹", "syllable_count": 2, "sentences": [{"text": "很多人反对他的想法，觉得太冒险。", "target_word": "反对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不反对你换工作，但要想清楚。", "target_word": "反对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从来不反对朋友的决定。", "target_word": "反对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村民们反对在河边盖工厂。", "target_word": "反对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板反对员工上班时玩手机。", "target_word": "反对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家要是反对，我们就换个办法。", "target_word": "反对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥反对我和他们一起去旅行。", "target_word": "反对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她反对吃太多甜的东西。", "target_word": "反对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有人反对这个做法，会议很快就结束了。", "target_word": "反对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很少反对孩子的选择。", "target_word": "反对", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "反對", "label": "繁体"}, {"form": "反对了", "label": "体标"}, {"form": "反对过", "label": "体标"}, {"form": "反对者", "label": "复合"}, {"form": "反对派", "label": "复合"}], "register": "中性", "sense_fingerprint": "不赞同别人的想法或做法（动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b05fab6d-52c3-4f0b-9cb0-3e12924a3383') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26594, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反对", "is_correct": true, "explanation": "“反对”表示不赞同，与“觉得太冒险”的看法一致。"}, {"text": "回答", "is_correct": false, "explanation": "搭配：“回答”的对象应是问题，不能说“回答他的想法”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“想法”搭配，说“吃他的想法”不成立。"}, {"text": "夸", "is_correct": false, "explanation": "语义：“夸”是称赞，与后面“觉得太冒险”的否定看法矛盾。"}], "explanations": {"反对": "“反对”表示不赞同，与“觉得太冒险”的看法一致。", "回答": "搭配：“回答”的对象应是问题，不能说“回答他的想法”。", "吃": "搭配：“吃”不能与“想法”搭配，说“吃他的想法”不成立。", "夸": "语义：“夸”是称赞，与后面“觉得太冒险”的否定看法矛盾。"}, "sentence_index": 0, "correct_answer": "反对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "对方进攻后，我们迅速反对，扳平了比分。", "explanation": "这里应该用〈反击〉。反击指对进攻进行还击，反对指不赞同，不能用于比赛中的还手。"}, {"text": "月光照在水面上，又被反对回来。", "explanation": "这里应该用〈反射〉。反射指光线遇到水面等障碍后返回，反对指不赞同，不能用于光线。"}, {"text": "用力推墙时，墙也会给你一个反对。", "explanation": "这里应该用〈反作用〉。反作用指一个力作用于另一物体时产生的相反作用力，反对指不赞同，不能用于物理作用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26594, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反对", "is_correct": true, "explanation": "“反对”表示不同意我和他们一起去旅行，符合句意。"}, {"text": "拥抱", "is_correct": false, "explanation": "搭配：“拥抱”的对象是人，不能接“一起去旅行”这样的事件。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”是为喜事表示庆贺，“一起去旅行”不是需要祝贺的事，句意不通。"}, {"text": "安慰", "is_correct": false, "explanation": "搭配：“安慰”的对象是人或心情，不能接“一起去旅行”。"}], "explanations": {"反对": "“反对”表示不同意我和他们一起去旅行，符合句意。", "拥抱": "搭配：“拥抱”的对象是人，不能接“一起去旅行”这样的事件。", "祝贺": "语义：“祝贺”是为喜事表示庆贺，“一起去旅行”不是需要祝贺的事，句意不通。", "安慰": "搭配：“安慰”的对象是人或心情，不能接“一起去旅行”。"}, "sentence_index": 6, "correct_answer": "反对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "居民向物业反对了噪音问题，希望尽快解决。", "explanation": "这里应该用〈反映〉。反映指把情况告诉有关部门，反对只表示不同意，不能用来说提出问题。"}, {"text": "球撞到墙上，又反对回来。", "explanation": "这里应该用〈反弹〉。反弹指物体碰撞后返回，反对指不赞同，不能用来描述物体的运动。"}, {"text": "他的情绪很反对，一会儿高兴，一会儿难过。", "explanation": "这里应该用〈反复〉。反复指情绪等变化不定，反对指不赞成，不能用来形容情绪变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里人对这项计划反对很厉害。", "corrected_sentence": "村里人对这项计划反对得很厉害。", "error_description": "“反对”后接程度补语时要用“得”，应说“反对得很厉害”，不能直接说“反对很厉害”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我反对的他们搬到城里去住。", "corrected_sentence": "我反对他们搬到城里去住。", "error_description": "“反对”后直接接小句作宾语，中间不能加“的”，应说“我反对他们搬到城里去住”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
