INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26598, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "请别人来玩或做事情。", "primary_collocate": null, "pronunciation": "yāo qǐng", "ipa": "iau˥ tɕʰiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我邀请他明天来我家玩。", "target_word": "邀请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明邀请我去打篮球。", "target_word": "邀请", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末他邀请朋友们一起看电影。", "target_word": "邀请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能邀请小李来家里玩吗？", "target_word": "邀请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她邀请了几个同学来家里玩游戏。", "target_word": "邀请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈邀请邻居来家里喝茶。", "target_word": "邀请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们邀请过他，可是他没有空。", "target_word": "邀请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着邀请我跟他一起跑步。", "target_word": "邀请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟邀请同学来看他的新玩具。", "target_word": "邀请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想去公园的人，我都邀请了。", "target_word": "邀请", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "邀请了", "label": "体标"}, {"form": "邀请过", "label": "体标"}, {"form": "邀请函", "label": "复合"}, {"form": "邀請", "label": "繁体"}], "register": "口语", "sense_fingerprint": "请别人来玩或一起做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e67beeef-49bd-4c02-a835-fa2b3ca19b5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26598, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "邀请", "is_correct": true, "explanation": "正确：“邀请”表示请别人来玩或做事，与“我___他明天来我家玩”相符。"}, {"text": "惩罚", "is_correct": false, "explanation": "语义：“惩罚”是处罚，与“请他来我家玩”的意思相反。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”的对象是错误或人，不能接“他明天来我家玩”这样的邀请。"}, {"text": "训斥", "is_correct": false, "explanation": "语义：“训斥”是责备，不能用来请人来玩。"}], "explanations": {"邀请": "正确：“邀请”表示请别人来玩或做事，与“我___他明天来我家玩”相符。", "惩罚": "语义：“惩罚”是处罚，与“请他来我家玩”的意思相反。", "批评": "搭配：“批评”的对象是错误或人，不能接“他明天来我家玩”这样的邀请。", "训斥": "语义：“训斥”是责备，不能用来请人来玩。"}, "sentence_index": 0, "correct_answer": "邀请"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我邀请他明天别来了。", "explanation": "这里应该用〈劝〉。劝是请人改变想法或不做某事，邀请是请人来玩或做事，意思相反。"}, {"text": "老师邀请他打扫教室。", "explanation": "这里应该用〈叫〉。邀请带有礼貌、自愿的意思，分派打扫教室这类任务用“叫”，语气和含义都不同。"}, {"text": "学生邀请老师能不能早退。", "explanation": "这里应该用〈请示〉。请示是向上级请求指示或许可，邀请是请人来玩或做事，不能用于请示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26598, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "邀请", "is_correct": true, "explanation": "正确：“邀请”表示请别人来，与“我们___过他，可是他没有空”的语境相符。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言或文字，不能用于人。"}, {"text": "冒犯", "is_correct": false, "explanation": "语义：“冒犯”是得罪人，与“可是他没有空”的语境不合。"}, {"text": "诋毁", "is_correct": false, "explanation": "语义：“诋毁”是贬低别人，与后半句“可是他没有空”的语境不合。"}], "explanations": {"邀请": "正确：“邀请”表示请别人来，与“我们___过他，可是他没有空”的语境相符。", "翻译": "搭配：“翻译”的对象是语言或文字，不能用于人。", "冒犯": "语义：“冒犯”是得罪人，与“可是他没有空”的语境不合。", "诋毁": "语义：“诋毁”是贬低别人，与后半句“可是他没有空”的语境不合。"}, "sentence_index": 6, "correct_answer": "邀请"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我邀请他快点写作业。", "explanation": "这里应该用〈催促〉。催促是催人赶快做事，邀请不能表示催促。"}, {"text": "妈妈邀请我带伞。", "explanation": "这里应该用〈提醒〉。提醒是让人留意某事，邀请只表示请人来玩或做事，不能替代。"}, {"text": "警察邀请他立即离开现场。", "explanation": "这里应该用〈命令〉。邀请是礼貌地请人来玩或做事，不带强制意味；要求他立即离开现场是命令，不能用邀请。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天邀请着他来我家玩。", "corrected_sentence": "我昨天邀请了他来我家玩。", "error_description": "错误：“昨天邀请”是已经完成的动作，不能用“着”。正确：用“了”，说“我昨天邀请了他来我家玩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们从来不邀请过我去看电影。", "corrected_sentence": "他们从来没邀请过我去看电影。", "error_description": "错误在否定词：“从来”搭配过去的经历，要用“没”，不能用“不”。应说“从来没邀请过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
