INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26600, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "林业就是种树和管树的工作，让树长大给我们用。", "primary_collocate": null, "pronunciation": "lín yè", "ipa": "lin˧˥ ie˥˩", "syllable_count": 2, "sentences": [{"text": "林业就是种树和管树。", "target_word": "林业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他喜欢林业，因为他爱树。", "target_word": "林业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "林业工人每天都在山上工作。", "target_word": "林业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学林业的人懂很多关于树的事。", "target_word": "林业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "林业让山上有很多树。", "target_word": "林业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我爸爸做林业，常常住在山里。", "target_word": "林业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做林业的人每天上山种树。", "target_word": "林业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想长大以后做林业。", "target_word": "林业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里的林业做得很好。", "target_word": "林业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "林业给我们提供木头。", "target_word": "林业", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "林业工人", "label": "复合"}, {"form": "林業", "label": "繁体"}], "register": "口语", "sense_fingerprint": "种树和管树的工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e67beeef-49bd-4c02-a835-fa2b3ca19b5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26600, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "林业", "is_correct": true, "explanation": "正确：“就是”后接种树和管树的工作，“林业”正是这种工作，与句意相符。"}, {"text": "语文", "is_correct": false, "explanation": "语义：“语文”是学科，不是种树和管树的工作。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不是种树和管树的工作。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“就是”后要接一种工作或活动，“厨房”是场所，不能这样定义。"}], "explanations": {"林业": "正确：“就是”后接种树和管树的工作，“林业”正是这种工作，与句意相符。", "语文": "语义：“语文”是学科，不是种树和管树的工作。", "天气": "语义：“天气”是自然现象，不是种树和管树的工作。", "厨房": "搭配：“就是”后要接一种工作或活动，“厨房”是场所，不能这样定义。"}, "sentence_index": 0, "correct_answer": "林业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "林业让田地里长满了庄稼。", "explanation": "这里应该用〈农业〉。农业指种植庄稼、饲养牲畜，林业是培育森林的产业，田里长庄稼不能说林业。"}, {"text": "林业在厨房里做饭。", "explanation": "这里应该用〈厨师〉。在厨房做饭的是厨师；林业是种树、管树的行业，不能指做饭的人或做饭这件事。"}, {"text": "工人在种林业。", "explanation": "这里应该用〈树苗〉。种的是树苗，林业是行业，不能说“种林业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26600, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "林业", "is_correct": true, "explanation": "正确：林业是种树和管树的工作，做林业的人每天上山种树。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是疾病，不能说“做感冒的人”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不是一种工作。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”是时间单位，不是工作，不能说“做星期的人”。"}], "explanations": {"林业": "正确：林业是种树和管树的工作，做林业的人每天上山种树。", "感冒": "语义：“感冒”是疾病，不能说“做感冒的人”。", "天气": "语义：“天气”是自然现象，不是一种工作。", "星期": "语义：“星期”是时间单位，不是工作，不能说“做星期的人”。"}, "sentence_index": 6, "correct_answer": "林业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山上的林业绿油油的，一眼望不到边。", "explanation": "这里应该用〈森林〉。林业是行业，不是一片树林；绿油油、一眼望不到边描述的是森林。"}, {"text": "工人用林业盖房子。", "explanation": "这里应该用〈木材〉。林业是产业，不是建材，盖房子要用木材。"}, {"text": "林业会变黄。", "explanation": "这里应该用〈树叶〉。树叶会变黄，林业是产业，不是植物，不会变黄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26600, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她将来想做了林业。", "corrected_sentence": "她将来想做林业。", "error_description": "错误在“了”：“将来”指未发生的事，“想做”也未发生，不能加“了”。应说“将来想做林业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26600, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我叔叔年轻时做着林业。", "corrected_sentence": "我叔叔年轻时做过林业。", "error_description": "错误在“过”与“着”：“年轻时”指过去的经历，应用经历体“过”，说“做过林业”；“着”表示持续或进行，与“年轻时”的过去经历不符。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
