INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26602, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "告诉别人怎么做。", "primary_collocate": null, "pronunciation": "zhǐ dǎo", "ipa": "ʈʂʐ̩˨˩˦ tau˨˩˦", "syllable_count": 2, "sentences": [{"text": "妈妈指导我怎么洗衣服。", "target_word": "指导", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你指导我用这个机器。", "target_word": "指导", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "哥哥指导我玩这个游戏。", "target_word": "指导", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师指导同学们怎么画画。", "target_word": "指导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸指导我怎么骑自行车。", "target_word": "指导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "师傅指导我们做面条。", "target_word": "指导", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她指导过我很多次。", "target_word": "指导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人指导孩子怎么种花。", "target_word": "指导", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "教练指导大家做热身运动。", "target_word": "指导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他指导着我一步一步地做。", "target_word": "指导", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指导了", "label": "体标"}, {"form": "指导过", "label": "体标"}, {"form": "指导着", "label": "体标"}, {"form": "指導", "label": "繁体"}], "register": "中性", "sense_fingerprint": "告诉别人具体怎么做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e67beeef-49bd-4c02-a835-fa2b3ca19b5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26602, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "知道", "is_correct": false, "explanation": "zhī dào 与 zhǐ dǎo 两个音节的声调都不同，意思是知道、了解，不是告诉别人怎么做。"}, {"text": "指导", "is_correct": true, "explanation": "正确答案：指导（zhǐ dǎo），意思是告诉别人具体怎么做。"}, {"text": "直到", "is_correct": false, "explanation": "zhí dào 与 zhǐ dǎo 第一音节声调不同（第二声与第三声），第二音节也不同，意思是一直到某个时候。"}, {"text": "主导", "is_correct": false, "explanation": "zhǔ dǎo 与 zhǐ dǎo 第一音节韵母不同（ǔ 与 ǐ），意思是居于主要地位、起支配作用。"}, {"text": "执导", "is_correct": false, "explanation": "zhí dǎo 与 zhǐ dǎo 第一音节声调不同（第二声与第三声），意思是担任导演。"}], "explanations": {"知道": "zhī dào 与 zhǐ dǎo 两个音节的声调都不同，意思是知道、了解，不是告诉别人怎么做。", "指导": "正确答案：指导（zhǐ dǎo），意思是告诉别人具体怎么做。", "直到": "zhí dào 与 zhǐ dǎo 第一音节声调不同（第二声与第三声），第二音节也不同，意思是一直到某个时候。", "主导": "zhǔ dǎo 与 zhǐ dǎo 第一音节韵母不同（ǔ 与 ǐ），意思是居于主要地位、起支配作用。", "执导": "zhí dǎo 与 zhǐ dǎo 第一音节声调不同（第二声与第三声），意思是担任导演。"}, "sentence_index": null, "correct_answer": "指导"}, "level_3": {"options": [{"text": "指导", "is_correct": true, "explanation": "正确：“指导我怎么洗衣服”即告诉我洗衣服的具体做法。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“我”作宾语表示告诉，“吃我怎么洗衣服”不成句。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示抛掷，与“告诉我怎么洗衣服”的意思无关，句子不通。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：“摔”不能带“我”作宾语表示教授，句子不成立。"}], "explanations": {"指导": "正确：“指导我怎么洗衣服”即告诉我洗衣服的具体做法。", "吃": "搭配：“吃”不能带“我”作宾语表示告诉，“吃我怎么洗衣服”不成句。", "扔": "语义：“扔”表示抛掷，与“告诉我怎么洗衣服”的意思无关，句子不通。", "摔": "搭配：“摔”不能带“我”作宾语表示教授，句子不成立。"}, "sentence_index": 0, "correct_answer": "指导"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校指导我们放假的消息。", "explanation": "这里应该用〈通知〉。指导是教给别人具体做事的方法，不能用来说传达放假的消息；告知消息要用通知。"}, {"text": "他指导了一张照片。", "explanation": "这里应该用〈拍〉。指导的对象是人，不能指导一张照片。"}, {"text": "小明指导了老师的问题。", "explanation": "这里应该用〈回答〉。指导是告诉别人怎么做，不能说指导问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26602, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指导", "is_correct": true, "explanation": "正确：“指导过我很多次”表示教过我很多次，句意通顺。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”是咽下去，“吞过我”不成句。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”的对象应是食物，不能说“烤过我”。"}, {"text": "织", "is_correct": false, "explanation": "语义：“织”是编织，“织过我”没有这样的意思，句子不通。"}], "explanations": {"指导": "正确：“指导过我很多次”表示教过我很多次，句意通顺。", "吞": "语义：“吞”是咽下去，“吞过我”不成句。", "烤": "搭配：“烤”的对象应是食物，不能说“烤过我”。", "织": "语义：“织”是编织，“织过我”没有这样的意思，句子不通。"}, "sentence_index": 6, "correct_answer": "指导"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生指导病人的伤口。", "explanation": "这里应该用〈治疗〉。指导是告诉别人怎么做，不用于处理伤口。"}, {"text": "师傅指导坏掉的自行车。", "explanation": "这里应该用〈修理〉。指导的对象是人，不能指导一辆自行车。"}, {"text": "阿姨每天指导地板。", "explanation": "这里应该用〈擦〉。指导的对象是人或做事的方法，不能说指导地板。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26602, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐不指导过我做作业。", "corrected_sentence": "姐姐没指导过我做作业。", "error_description": "错误：“指导过”表示经历，否定要用“没”，不能用“不”。正确：“姐姐没指导过我做作业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26602, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教练指导着我们着跑步。", "corrected_sentence": "教练指导着我们跑步。", "error_description": "错误：“着”重复使用，“我们”后又多了一个“着”。正确：“教练指导着我们跑步”，只保留紧跟“指导”的一个“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
