INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26606, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "批评做错了事的人，让他记住以后不再犯错。", "primary_collocate": null, "pronunciation": "jiào xùn", "ipa": "tɕjɑʊ˥˩ ɕyn˥˩", "syllable_count": 2, "sentences": [{"text": "爸爸教训了弟弟一顿，因为他又说谎了。", "target_word": "教训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师当着大家的面教训了他。", "target_word": "教训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈正在教训打碎杯子的孩子。", "target_word": "教训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别教训我，我知道自己错了。", "target_word": "教训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他迟到了三次，经理把他教训了一顿。", "target_word": "教训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶教训孙子，不许再玩火。", "target_word": "教训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做错了事，爷爷严厉地教训了他。", "target_word": "教训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥常常教训我，要我好好做作业。", "target_word": "教训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学打了人，校长教训了他半天。", "target_word": "教训", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我要好好教训一下这个说谎的人。", "target_word": "教训", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "教训了", "label": "体标"}, {"form": "教訓", "label": "繁体"}], "register": "口语", "sense_fingerprint": "批评做错事的人，让他记住不再犯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b05fab6d-52c3-4f0b-9cb0-3e12924a3383') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26606, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "教训", "is_correct": true, "explanation": "教训 jiàoxùn：意思是批评做错事的人，与听到的读音一致。"}, {"text": "校训", "is_correct": false, "explanation": "xiàoxùn 与 jiàoxùn 声母不同（x 与 j），意思是学校的校训，不是批评。"}, {"text": "驾训", "is_correct": false, "explanation": "jià 与 jiào 韵母不同（a 与 ao），意思是驾驶培训。"}, {"text": "校讯", "is_correct": false, "explanation": "xiàoxùn 与 jiàoxùn 声母不同（x 与 j），意思是学校的通知。"}], "explanations": {"教训": "教训 jiàoxùn：意思是批评做错事的人，与听到的读音一致。", "校训": "xiàoxùn 与 jiàoxùn 声母不同（x 与 j），意思是学校的校训，不是批评。", "驾训": "jià 与 jiào 韵母不同（a 与 ao），意思是驾驶培训。", "校讯": "xiàoxùn 与 jiàoxùn 声母不同（x 与 j），意思是学校的通知。"}, "sentence_index": null, "correct_answer": "教训"}, "level_3": {"options": [{"text": "教训", "is_correct": true, "explanation": "“教训”指批评做错事的人，与“又说谎了”的情况相符。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：表扬是肯定，与“说谎”这种过错相反。"}, {"text": "安慰", "is_correct": false, "explanation": "搭配：“一顿”多用于打骂、训斥，不能用于安慰。"}, {"text": "称赞", "is_correct": false, "explanation": "搭配：“一顿”不用于称赞，说“称赞了弟弟一顿”不通。"}], "explanations": {"教训": "“教训”指批评做错事的人，与“又说谎了”的情况相符。", "表扬": "语义：表扬是肯定，与“说谎”这种过错相反。", "安慰": "搭配：“一顿”多用于打骂、训斥，不能用于安慰。", "称赞": "搭配：“一顿”不用于称赞，说“称赞了弟弟一顿”不通。"}, "sentence_index": 0, "correct_answer": "教训"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师在班上教训了他的进步。", "explanation": "这里应该用〈赞美〉。赞美是称赞、肯定；教训是批评做错事的人，不能用来说“进步”这类好事。"}, {"text": "全家人在门口教训远道而来的客人。", "explanation": "这里应该用〈迎接〉。迎接是表示欢迎；教训是批评做错事的人，不能用来对远道而来的客人。"}, {"text": "全家人一起教训这顿美味的晚饭。", "explanation": "这里应该用〈享用〉。享用指吃喝、享受；教训是批评做错事的人，不能用于食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26606, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教训", "is_correct": true, "explanation": "“教训”指批评做错事的人，与“做错了事”的情况相符。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：夸奖是表扬，与“做错了事”相反。"}, {"text": "亲吻", "is_correct": false, "explanation": "语义：亲吻表示疼爱，与“严厉”的语气相冲突。"}, {"text": "拥抱", "is_correct": false, "explanation": "搭配：拥抱不说“严厉地拥抱”，与“严厉”搭配不当。"}], "explanations": {"教训": "“教训”指批评做错事的人，与“做错了事”的情况相符。", "夸奖": "语义：夸奖是表扬，与“做错了事”相反。", "亲吻": "语义：亲吻表示疼爱，与“严厉”的语气相冲突。", "拥抱": "搭配：拥抱不说“严厉地拥抱”，与“严厉”搭配不当。"}, "sentence_index": 6, "correct_answer": "教训"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈教训我很聪明。", "explanation": "这里应该用〈夸〉。夸是赞扬，教训是批评，不能用于赞扬别人。"}, {"text": "我真诚地教训你的帮助。", "explanation": "这里应该用〈感谢〉。感谢是表达谢意；教训是批评做错事的人，不能用来对待别人的帮助。"}, {"text": "老师教训了他一朵小红花。", "explanation": "这里应该用〈奖励〉。奖励是给好处，教训是批评，不能用于给人小红花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26606, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师教训他了一顿，因为他作业没交。", "corrected_sentence": "老师教训了他一顿，因为他作业没交。", "error_description": "动态助词“了”位置错误：“了”应紧跟动词“教训”，说“教训了他一顿”，不能说“教训他了一顿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26606, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在教训了弟弟，语气很严厉。", "corrected_sentence": "他正在教训弟弟，语气很严厉。", "error_description": "“正在”和“了”不能同时用。“正在”表示动作正在进行，“了”表示动作已完成，二者矛盾，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
