INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26608, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事情做得符合科学道理，不会出错。", "primary_collocate": null, "pronunciation": "kē xué xìng", "ipa": "kʰɤ˥ ɕɥœ˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "他的复习计划很有科学性，一步一步不容易出错。", "target_word": "科学性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样安排工作，科学性强，也不容易出错。", "target_word": "科学性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生制订的减肥办法很讲究科学性。", "target_word": "科学性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套训练方法的科学性，让运动员很少受伤。", "target_word": "科学性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做事一向讲究科学性，从不乱来。", "target_word": "科学性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要提高养鱼的科学性，别再凭感觉做了。", "target_word": "科学性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们这样管理仓库，科学性不够，常常出错。", "target_word": "科学性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用这个办法做实验，科学性更高，结果更可靠。", "target_word": "科学性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师夸他整理资料很有科学性。", "target_word": "科学性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈安排我们一家人的饮食，很有科学性。", "target_word": "科学性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "科學性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "做事的方法符合科学道理、不容易出错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b05fab6d-52c3-4f0b-9cb0-3e12924a3383') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26608, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "科学性", "is_correct": true, "explanation": "“很有科学性”指做事符合科学道理，与“一步一步不容易出错”的说法相呼应。"}, {"text": "随意性", "is_correct": false, "explanation": "语义：随意性指做事不讲规划，与“一步一步”的计划正好相反。"}, {"text": "偶然性", "is_correct": false, "explanation": "语义：偶然性指事情靠运气、不确定，与“不容易出错”的说法冲突。"}, {"text": "娱乐性", "is_correct": false, "explanation": "搭配：娱乐性多用于游戏、节目，不能用来形容复习计划。"}], "explanations": {"科学性": "“很有科学性”指做事符合科学道理，与“一步一步不容易出错”的说法相呼应。", "随意性": "语义：随意性指做事不讲规划，与“一步一步”的计划正好相反。", "偶然性": "语义：偶然性指事情靠运气、不确定，与“不容易出错”的说法冲突。", "娱乐性": "搭配：娱乐性多用于游戏、节目，不能用来形容复习计划。"}, "sentence_index": 0, "correct_answer": "科学性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他喜欢学习科学性。", "explanation": "这里应该用〈科学〉。科学指知识、学科，可以学习；科学性是事物的性质，不能学习。"}, {"text": "她的性格很有科学性，总是很冷静。", "explanation": "这里应该用〈理性〉。理性指人讲道理、不冲动；科学性指事情做得符合科学道理，只用于做法、计划等，不能用来形容人的性格或脾气。"}, {"text": "这首歌的科学性很高，连小孩都会唱。", "explanation": "这里应该用〈知名度〉。知名度指大家知道、熟悉的程度，用来说歌曲有多受欢迎；科学性指做法符合科学道理，不能用来说歌曲有没有名气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26608, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "科学性", "is_correct": true, "explanation": "“科学性不够”指做事方法缺少科学道理，与“常常出错”相呼应。"}, {"text": "观赏性", "is_correct": false, "explanation": "语义：观赏性指供人欣赏的价值，与管理仓库的工作无关。"}, {"text": "趣味性", "is_correct": false, "explanation": "语义：趣味性指有意思、好玩，不是评价管理工作的标准，也与“常常出错”不符。"}, {"text": "艺术性", "is_correct": false, "explanation": "搭配：“艺术性”多用于文艺作品，不能说管理仓库“艺术性不够”。"}], "explanations": {"科学性": "“科学性不够”指做事方法缺少科学道理，与“常常出错”相呼应。", "观赏性": "语义：观赏性指供人欣赏的价值，与管理仓库的工作无关。", "趣味性": "语义：趣味性指有意思、好玩，不是评价管理工作的标准，也与“常常出错”不符。", "艺术性": "搭配：“艺术性”多用于文艺作品，不能说管理仓库“艺术性不够”。"}, "sentence_index": 6, "correct_answer": "科学性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们正在做科学性。", "explanation": "这里应该用〈实验〉。实验是做的事情，科学性是性质，不能被“做”。"}, {"text": "他是一位科学性。", "explanation": "这里应该用〈科学家〉。科学家指人，科学性是事物的性质，不能用来指人。"}, {"text": "这个科学性很有道理。", "explanation": "这里应该用〈理论〉。“很有道理”说的是理论或说法，科学性是性质，不能用来指一个理论。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26608, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套方法的科学性很大，效果很好。", "corrected_sentence": "这套方法的科学性很强，效果很好。", "error_description": "搭配错误：“科学性”常与“强”“高”搭配，不说“科学性很大”，应改为“科学性很强”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26608, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们的管理很科学性，所以出错很少。", "corrected_sentence": "他们的管理很有科学性，所以出错很少。", "error_description": "“很”后面漏了“有”。“很有＋名词”表示具有某种性质，“很＋名词”不成立。应改为“很有科学性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
