INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26610, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "植被就是地上长着的所有花草树木。", "primary_collocate": null, "pronunciation": "zhí bèi", "ipa": "ʈʂɻ̩˧˥ peɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这座山的植被很丰富，有高高的树，也有小花小草。", "target_word": "植被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，北方的植被变黄了。", "target_word": "植被", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们不能随便破坏山上的植被。", "target_word": "植被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热带雨林的植被特别茂密。", "target_word": "植被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植被能留住水，也能保护土地。", "target_word": "植被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片荒地上几乎没有植被。", "target_word": "植被", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师带我们去看海边的植被。", "target_word": "植被", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨水多的地方，植被一般长得好。", "target_word": "植被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小动物常常藏在植被里。", "target_word": "植被", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开矿以后，山上的植被少了很多。", "target_word": "植被", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片植被", "label": "量词"}], "register": "中性", "sense_fingerprint": "植被：地上长的所有花草树木", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71266d48-abd2-408d-ab3d-49d9cf61150e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26610, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "植被", "is_correct": true, "explanation": "正确。“这座山的植被很丰富，有高高的树，也有小花小草”，植被指山上长着的花草树木。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口指居民人数，与后面的高树和小花小草不相关，不合语境。"}, {"text": "家具", "is_correct": false, "explanation": "语义：“家具”是室内用品，不会长在山上，不能说“这座山的家具很丰富，有高高的树”。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是人造物，不会像树和花草一样生长在山上。"}], "explanations": {"植被": "正确。“这座山的植被很丰富，有高高的树，也有小花小草”，植被指山上长着的花草树木。", "人口": "语义：人口指居民人数，与后面的高树和小花小草不相关，不合语境。", "家具": "语义：“家具”是室内用品，不会长在山上，不能说“这座山的家具很丰富，有高高的树”。", "玩具": "语义：玩具是人造物，不会像树和花草一样生长在山上。"}, "sentence_index": 0, "correct_answer": "植被"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "草地上的植被跑来跑去。", "explanation": "这里应该用〈动物〉。植被是地上长着的植物，不会跑来跑去，“跑来跑去”应指动物。"}, {"text": "植被是木头做的。", "explanation": "这里应该用〈家具〉。植被是地上长着的植物，不能用木头做，说木制的应是家具。"}, {"text": "老师在黑板上写植被。", "explanation": "这里应该用〈字〉。植被是植物的总称，不能用来书写，“写”的对象应是字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26610, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "植被", "is_correct": true, "explanation": "正确。“老师带我们去看海边的植被”，植被是可以去观看的景物。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不是可以到海边去看的景物。"}, {"text": "语言", "is_correct": false, "explanation": "语义：语言是抽象的交流工具，不能到海边去看。"}, {"text": "粉笔", "is_correct": false, "explanation": "搭配：“看”不接“粉笔”这类学习用品，与海边的景物不搭。"}], "explanations": {"植被": "正确。“老师带我们去看海边的植被”，植被是可以去观看的景物。", "作业": "语义：作业是学习任务，不是可以到海边去看的景物。", "语言": "语义：语言是抽象的交流工具，不能到海边去看。", "粉笔": "搭配：“看”不接“粉笔”这类学习用品，与海边的景物不搭。"}, "sentence_index": 6, "correct_answer": "植被"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的植被唱得很好听。", "explanation": "这里应该用〈歌〉。植被是地上长着的植物，不会唱歌，“唱得好听”的对象应是歌。"}, {"text": "他今天穿的植被很漂亮。", "explanation": "这里应该用〈衣服〉。植被是地上长着的植物，不能穿在身上，“穿”的对象应是衣服。"}, {"text": "同学们正在操场上踢植被。", "explanation": "这里应该用〈足球〉。植被不能用脚踢，“踢”的对象应是球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26610, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山上长着一座茂密的植被。", "corrected_sentence": "山上长着一片茂密的植被。", "error_description": "错误：量词“座”用于山、楼房等大型固定的东西，不能用来数植被。正确：“一片茂密的植被”，“片”用于成片的草地、树林等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26610, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨季过后，山坡上长出了茂密地植被。", "corrected_sentence": "雨季过后，山坡上长出了茂密的植被。", "error_description": "结构助词错误：“茂密”修饰名词“植被”，应用“的”，不用“地”。“地”用于修饰动词。正确说法：茂密的植被。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
