INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26612, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "矮矮的、没有大树那么高的木头植物。", "primary_collocate": null, "pronunciation": "guàn mù", "ipa": "kwan˥˩ mu˥˩", "syllable_count": 2, "sentences": [{"text": "院子旁边有一丛灌木。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些灌木没有粗粗的树干。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟在灌木里做了个窝。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灌木太矮，不能给人遮太阳。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡上的灌木秋天变红了。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把家门口的灌木剪得很整齐。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种灌木很矮，小孩也能摸到叶子。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠边上只长着一些灌木。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，灌木上长出了新叶子。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，灌木上挂满了水珠。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "丛", "label": "量词"}, {"form": "灌木丛", "label": "复合"}], "register": "中性", "sense_fingerprint": "矮矮的、没有大树那么高的木本植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e67beeef-49bd-4c02-a835-fa2b3ca19b5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26612, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灌木", "is_correct": true, "explanation": "正确。灌木矮矮的，没有大树那么高，可以用“丛”来数。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“丛”用于草木等丛生之物，桌子不能说“一丛”，句子不成立。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“一丛”不用于石头，石头应该说“一堆”。"}, {"text": "水井", "is_correct": false, "explanation": "搭配：“丛”用于丛生的草木，水井要说“一口”，不能说“一丛水井”。"}], "explanations": {"灌木": "正确。灌木矮矮的，没有大树那么高，可以用“丛”来数。", "桌子": "搭配：“丛”用于草木等丛生之物，桌子不能说“一丛”，句子不成立。", "石头": "搭配：“一丛”不用于石头，石头应该说“一堆”。", "水井": "搭配：“丛”用于丛生的草木，水井要说“一口”，不能说“一丛水井”。"}, "sentence_index": 0, "correct_answer": "灌木"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵灌木很高，夏天能遮住整个院子。", "explanation": "这里应该用〈大树〉。灌木比大树矮，不能说“很高”，也遮不住整个院子。"}, {"text": "山坡上的灌木比房子还高，树冠大得能遮住半个院子。", "explanation": "这里应该用〈乔木〉。灌木矮矮的，没有大树那么高；比房子还高、树冠很大的是乔木。"}, {"text": "灌木的茎又细又软，冬天就枯死了。", "explanation": "这里应该用〈草本植物〉。灌木的茎木质化、较硬，不会一个冬天就枯死；茎又细又软、易枯死是草本植物的特点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26612, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灌木", "is_correct": true, "explanation": "正确。这种灌木很矮，小孩也能摸到叶子。"}, {"text": "乔木", "is_correct": false, "explanation": "体貌：乔木高大，与“很矮”的描述相矛盾。"}, {"text": "高楼", "is_correct": false, "explanation": "语义：高楼不是植物，句子说的是能摸到叶子的植物。"}, {"text": "电线杆", "is_correct": false, "explanation": "搭配：电线杆上没有叶子，“摸到叶子”不能用来描述它。"}], "explanations": {"灌木": "正确。这种灌木很矮，小孩也能摸到叶子。", "乔木": "体貌：乔木高大，与“很矮”的描述相矛盾。", "高楼": "语义：高楼不是植物，句子说的是能摸到叶子的植物。", "电线杆": "搭配：电线杆上没有叶子，“摸到叶子”不能用来描述它。"}, "sentence_index": 6, "correct_answer": "灌木"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门前的灌木一节一节的，又直又高，一点分枝都没有。", "explanation": "这里应该用〈竹子〉。竹子有节、直立、不分枝；灌木矮矮的，从地面附近就分枝，不能说“一节一节、没有分枝”。"}, {"text": "池塘里漂着一丛灌木，随水轻轻摇摆。", "explanation": "这里应该用〈水草〉。灌木长在陆地上，不会漂在池塘里随水摇摆；随水漂动的是水草。"}, {"text": "院子角落的灌木中间是空的，细长的茎风一吹就弯下腰。", "explanation": "这里应该用〈芦苇〉。灌木的茎是木质的，不是中空的；中空、细长、风一吹就弯腰的是芦苇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26612, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山上的灌木们都被风吹歪了。", "corrected_sentence": "山上的灌木都被风吹歪了。", "error_description": "错在“灌木”后面加了“们”。“们”一般只用在指人的名词后面，植物不能加“们”，直接说“灌木”就表示很多。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26612, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子里的那支灌木开了很多花。", "corrected_sentence": "院子里的那丛灌木开了很多花。", "error_description": "错在量词。“灌木”应用量词“丛”，“支”用于细长的杆状物，不能修饰灌木。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
