INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26614, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "草本植物是茎很软的植物。", "primary_collocate": null, "pronunciation": "cǎo běn zhí wù", "ipa": "tsʰɑʊ˨˩˦ pən˨˩˦ ʈʂɨ˧˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "草本植物的茎又细又软。", "target_word": "草本植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玫瑰是灌木，向日葵是草本植物。", "target_word": "草本植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盆草本植物需要每天浇水。", "target_word": "草本植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草本植物比树矮得多。", "target_word": "草本植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜园里种的青菜都是草本植物。", "target_word": "草本植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天来了，草本植物慢慢枯死了。", "target_word": "草本植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家阳台上养着几盆草本植物。", "target_word": "草本植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兔子最爱吃新鲜的草本植物。", "target_word": "草本植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草本植物的叶子软软的，一摸就弯。", "target_word": "草本植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药店里的很多药材都来自草本植物。", "target_word": "草本植物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "一年生草本植物", "label": "复合"}], "register": "中性", "sense_fingerprint": "茎很软的植物，不像树那样有硬树干", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e67beeef-49bd-4c02-a835-fa2b3ca19b5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26614, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "草本植物", "is_correct": true, "explanation": "正确：草本植物是茎软的植物，与“茎又细又软”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有茎，“石头的茎又细又软”说不通。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁是金属，不是植物，没有可以细软的茎。"}, {"text": "动物", "is_correct": false, "explanation": "搭配：“茎”是植物的部分，动物不说“茎”，与“的茎”搭配不当。"}], "explanations": {"草本植物": "正确：草本植物是茎软的植物，与“茎又细又软”相符。", "石头": "语义：石头没有茎，“石头的茎又细又软”说不通。", "钢铁": "语义：钢铁是金属，不是植物，没有可以细软的茎。", "动物": "搭配：“茎”是植物的部分，动物不说“茎”，与“的茎”搭配不当。"}, "sentence_index": 0, "correct_answer": "草本植物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵草本植物的树干粗得要两个人才能抱住。", "explanation": "这里应该用〈大树〉。草本植物茎软，没有木质的粗树干；树干粗、要两人才能抱住的应说大树。"}, {"text": "草本植物的茎很硬，能长成大树。", "explanation": "这里应该用〈木本植物〉。草本植物茎软，长不成大树；茎木质化、能长成大树的应说木本植物。"}, {"text": "这块草本植物又硬又重，可以用来盖房子。", "explanation": "这里应该用〈木头〉。草本植物茎很软，不能用来盖房子；又硬又重、能盖房子的是木头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26614, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "草本植物", "is_correct": true, "explanation": "正确：“几盆草本植物”，草本植物可以盆栽养在阳台上，句意通顺。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：量词“盆”不能用来数电视，“几盆电视”搭配不当。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能被养在阳台上，“养”的对象是动植物，句子说不通。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块遇热就化，不能被养着，阳台上养冰块与语境不符。"}], "explanations": {"草本植物": "正确：“几盆草本植物”，草本植物可以盆栽养在阳台上，句意通顺。", "电视": "搭配：量词“盆”不能用来数电视，“几盆电视”搭配不当。", "汽车": "语义：汽车不能被养在阳台上，“养”的对象是动植物，句子说不通。", "冰块": "语义：冰块遇热就化，不能被养着，阳台上养冰块与语境不符。"}, "sentence_index": 6, "correct_answer": "草本植物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种草本植物能长到二十多米高。", "explanation": "这里应该用〈乔木〉。草本植物茎软、长不了那么高；能长到二十多米的应说乔木。"}, {"text": "这块草本植物很柔软，躺上去很舒服。", "explanation": "这里应该用〈草坪〉。草本植物是植物的统称，不能指可以躺卧的成片草地。"}, {"text": "花坛里开满了草本植物。", "explanation": "这里应该用〈鲜花〉。“开满”说的是花，草本植物是植物类别，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26614, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里种着一条草本植物。", "corrected_sentence": "院子里种着一株草本植物。", "error_description": "错误：量词“条”用于细长的东西，如鱼、路，不能用于草本植物。正确：“一株草本植物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26614, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "阳台上放着三本草本植物。", "corrected_sentence": "阳台上放着三盆草本植物。", "error_description": "错误：量词“本”用于书，不能用于草本植物。正确：盆栽的草本植物用“盆”，即“三盆草本植物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
