INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26616, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26616, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很高的大树。", "primary_collocate": null, "pronunciation": "qiáo mù", "ipa": "tɕʰjɑʊ˧˥ mu˥˩", "syllable_count": 2, "sentences": [{"text": "校门口种着一排乔木。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种乔木能长到二十多米。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷家后院有一棵老乔木。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨后，乔木的叶子特别绿。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乔木比灌木高得多。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在乔木下面休息了一会儿。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里的乔木能让空气变得更清新。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，北方的乔木掉光了叶子。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片林子里的乔木已有百年树龄。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里的乔木把阳光挡住了。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "棵", "label": "量词"}, {"form": "常绿乔木", "label": "复合"}, {"form": "喬木", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很高的大树", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e67beeef-49bd-4c02-a835-fa2b3ca19b5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26616, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乔木", "is_correct": true, "explanation": "正确：“种着一排乔木”，乔木是可以种植的树木，句意通顺。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“种”不能接“房子”，房子是建造的，不能种。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能被种植，“种着一排石头”不成句。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线是架设的，不是种出来的，“种着一排电线”与语境不符。"}], "explanations": {"乔木": "正确：“种着一排乔木”，乔木是可以种植的树木，句意通顺。", "房子": "搭配：“种”不能接“房子”，房子是建造的，不能种。", "石头": "语义：石头不能被种植，“种着一排石头”不成句。", "电线": "语义：电线是架设的，不是种出来的，“种着一排电线”与语境不符。"}, "sentence_index": 0, "correct_answer": "乔木"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这丛乔木只到我的膝盖，叶子又小又密。", "explanation": "这里应该用〈灌木〉。乔木是高大的树木，只到膝盖、丛生的植物应说灌木。"}, {"text": "这排乔木刚栽下，才几厘米高。", "explanation": "这里应该用〈树苗〉。乔木指已长成的大树，刚栽下的小苗应说树苗。"}, {"text": "我每天骑乔木上班。", "explanation": "这里应该用〈自行车〉。骑的对象是车辆或动物，乔木是树，不能被骑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26616, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乔木", "is_correct": true, "explanation": "正确：“城市里的乔木能让空气变得更清新”，乔木能净化空气，句意通顺。"}, {"text": "卡车", "is_correct": false, "explanation": "语义：卡车排放废气，不能让空气变得更清新，句子语义相悖。"}, {"text": "烟囱", "is_correct": false, "explanation": "语义：烟囱排放烟尘，只会让空气变脏，与“让空气变得更清新”相悖。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“电视”与“让空气变得更清新”不搭配，句子不成立。"}], "explanations": {"乔木": "正确：“城市里的乔木能让空气变得更清新”，乔木能净化空气，句意通顺。", "卡车": "语义：卡车排放废气，不能让空气变得更清新，句子语义相悖。", "烟囱": "语义：烟囱排放烟尘，只会让空气变脏，与“让空气变得更清新”相悖。", "电视": "搭配：“电视”与“让空气变得更清新”不搭配，句子不成立。"}, "sentence_index": 6, "correct_answer": "乔木"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "乔木很柔软，躺上去很舒服。", "explanation": "这里应该用〈草坪〉。乔木是高大的树木，不能柔软得让人躺上去很舒服；可以躺卧的柔软草地要说草坪。"}, {"text": "花坛里开满了乔木。", "explanation": "这里应该用〈鲜花〉。“开满”说的是花，乔木是树，不能这样说。"}, {"text": "这座乔木有五十层，在城市里特别显眼。", "explanation": "这里应该用〈高楼〉。乔木只指树木，不能用来指建筑物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26616, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "路边有一个乔木。", "corrected_sentence": "路边有一棵乔木。", "error_description": "错误：量词“个”不能用于乔木。正确：“一棵乔木”，树木应使用量词“棵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26616, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公园里有一朵很高的乔木。", "corrected_sentence": "公园里有一棵很高的乔木。", "error_description": "错误：量词“朵”用于花，不能用于乔木。正确：树木用“棵”，即“一棵很高的乔木”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
