INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26618, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "相机是一种可以拍照片和录像的机器。", "primary_collocate": null, "pronunciation": "xiàng jī", "ipa": "ɕjɑŋ˥˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "相机是用来拍照片的机器。", "target_word": "相机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸送给我一台黑色的相机。", "target_word": "相机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她背着相机去公园拍花。", "target_word": "相机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台相机太重了，我拿不动。", "target_word": "相机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学拍照，所以要买一台相机。", "target_word": "相机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的相机能不能借我用一下？", "target_word": "相机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把相机放进包里，就出门了。", "target_word": "相机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "相机坏了，照片拍不出来。", "target_word": "相机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩对着相机笑了。", "target_word": "相机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在海边用相机拍了很多照片。", "target_word": "相机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "数码相机", "label": "复合"}, {"form": "相机包", "label": "复合"}, {"form": "相機", "label": "繁体"}], "register": "中性", "sense_fingerprint": "相机：可以拍照片和录像的机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e1bb1b-df41-4c43-a922-40e41116d20b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26618, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "相机", "is_correct": true, "explanation": "正确：xiàng jī，指可以拍照片和录像的机器。"}, {"text": "相济", "is_correct": false, "explanation": "xiāng jì 与 xiàng jī 声母韵母相同，只是声调不同，意思是互相帮助、补充。"}, {"text": "向西", "is_correct": false, "explanation": "xiàng xī 与 xiàng jī 第二音节声母不同（x 与 j），声调相同，意思是朝西方。"}, {"text": "相继", "is_correct": false, "explanation": "xiāng jì 与 xiàng jī 两个音节声调都不同，意思是接连不断。"}], "explanations": {"相机": "正确：xiàng jī，指可以拍照片和录像的机器。", "相济": "xiāng jì 与 xiàng jī 声母韵母相同，只是声调不同，意思是互相帮助、补充。", "向西": "xiàng xī 与 xiàng jī 第二音节声母不同（x 与 j），声调相同，意思是朝西方。", "相继": "xiāng jì 与 xiàng jī 两个音节声调都不同，意思是接连不断。"}, "sentence_index": null, "correct_answer": "相机"}, "level_3": {"options": [{"text": "相机", "is_correct": true, "explanation": "正确：相机是用来拍照片的机器，与句意一致。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱用来冷藏食物，不是拍照片的机器。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视用来播放节目，不用来拍照片。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“……的机器”只修饰机械设备，雨伞不说“机器”，搭配不当。"}], "explanations": {"相机": "正确：相机是用来拍照片的机器，与句意一致。", "冰箱": "语义：冰箱用来冷藏食物，不是拍照片的机器。", "电视": "语义：电视用来播放节目，不用来拍照片。", "雨伞": "搭配：“……的机器”只修饰机械设备，雨伞不说“机器”，搭配不当。"}, "sentence_index": 0, "correct_answer": "相机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一把相机。", "explanation": "这里应该用〈台〉。相机是机器，应用“台”计量；“把”用于带柄的器具。"}, {"text": "他用相机闻远处的花，闻得很香。", "explanation": "这里应该用〈鼻子〉。相机不能闻东西，闻气味要用鼻子。"}, {"text": "我用相机告诉妈妈我到了。", "explanation": "这里应该用〈电话〉。相机不能用来传达消息，打电话要用电话或手机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26618, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相机", "is_correct": true, "explanation": "正确：相机体积小，可以放进包里，与“他把相机放进包里”一致。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子太大，装不进包里，与句意不符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子远比包大，不可能放进包里。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：空气不能用“放进包里”来说，搭配不当。"}], "explanations": {"相机": "正确：相机体积小，可以放进包里，与“他把相机放进包里”一致。", "桌子": "语义：桌子太大，装不进包里，与句意不符。", "房子": "语义：房子远比包大，不可能放进包里。", "空气": "搭配：空气不能用“放进包里”来说，搭配不当。"}, "sentence_index": 6, "correct_answer": "相机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在海边用相机打电话给家人。", "explanation": "这里应该用〈手机〉。相机不能打电话，打电话要用手机。"}, {"text": "我们在海边用相机听广播。", "explanation": "这里应该用〈收音机〉。相机用来拍摄，听广播要用收音机。"}, {"text": "我们在海边用相机煮了一锅粥。", "explanation": "这里应该用〈电饭煲〉。相机不能煮饭，煮粥要用电饭煲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26618, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸给我换了一只新相机。", "corrected_sentence": "爸爸给我换了一台新相机。", "error_description": "量词错误：相机是机器，应说“一台新相机”；“只”用于动物等，不用于机器。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26618, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台的相机很重，我拿不动。", "corrected_sentence": "这台相机很重，我拿不动。", "error_description": "多余的“的”：指示词加量词修饰名词时，中间不能加“的”，应说“这台相机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
