INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26620, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "红外是一种眼睛看不见的光。", "primary_collocate": null, "pronunciation": "hóng wài", "ipa": "xʊŋ˧˥ waɪ˥˩", "syllable_count": 2, "sentences": [{"text": "红外是眼睛看不见的光。", "target_word": "红外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的眼睛看不到红外，但相机能拍到。", "target_word": "红外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳光里有红外，所以晒太阳觉得暖和。", "target_word": "红外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上的监控用红外照亮，人眼却看不出来。", "target_word": "红外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红外虽然看不见，但是皮肤能感觉到热。", "target_word": "红外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛇能感觉到红外，所以黑夜里也能找到老鼠。", "target_word": "红外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视遥控器发出的红外，我们用眼睛看不到。", "target_word": "红外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手靠近火炉，感觉到热，那是红外。", "target_word": "红外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红外的波长比红光长，眼睛看不见。", "target_word": "红外", "complexity_tier": "T3", "furigana": "hóng wài de bō cháng bǐ hóng guāng cháng, yǎn jīng kàn bu jiàn.", "sentence_source": "generated"}, {"text": "我买的夜视仪能利用红外，在黑暗中看清东西。", "target_word": "红外", "complexity_tier": "T3", "furigana": "wǒ mǎi de yè shì yí néng lì yòng hóng wài, zài hēi àn zhōng kàn qīng dōng xi.", "sentence_source": "generated"}], "morphological_forms": [{"form": "红外线", "label": "复合"}, {"form": "紅外", "label": "繁体"}], "register": "中性", "sense_fingerprint": "红外：人眼看不见的光，能让人感到热", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e1bb1b-df41-4c43-a922-40e41116d20b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26620, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "红外", "is_correct": true, "explanation": "正确：红外是人眼看不见的光，与“眼睛看不见的光”一致。"}, {"text": "红光", "is_correct": false, "explanation": "语义：红光是人眼能看见的可见光，与“眼睛看不见”矛盾。"}, {"text": "白光", "is_correct": false, "explanation": "语义：白光也是可见光，人眼能看到，不符合“看不见”的定义。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：声音不是光，不能说“是……的光”。"}], "explanations": {"红外": "正确：红外是人眼看不见的光，与“眼睛看不见的光”一致。", "红光": "语义：红光是人眼能看见的可见光，与“眼睛看不见”矛盾。", "白光": "语义：白光也是可见光，人眼能看到，不符合“看不见”的定义。", "声音": "搭配：声音不是光，不能说“是……的光”。"}, "sentence_index": 0, "correct_answer": "红外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这朵花是红外的，很漂亮。", "explanation": "这里应该用〈红色〉。红外是人眼看不见的光，不是颜色，不能用来形容花的样子。"}, {"text": "红外能让皮肤变黑，所以夏天要防晒。", "explanation": "这里应该用〈紫外线〉。紫外线会让皮肤变黑；红外让人感到热，不会晒黑。"}, {"text": "太阳放出一只红外，让人觉得暖和。", "explanation": "这里应该用〈束〉。光线用“束”计量，“只”用于动物等，不用于光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26620, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "红外", "is_correct": true, "explanation": "正确：红外是人眼看不见的光，遥控器发出的正是它。"}, {"text": "灯光", "is_correct": false, "explanation": "语义：灯光是可见光，人眼看得见，与“用眼睛看不到”矛盾。"}, {"text": "紫光", "is_correct": false, "explanation": "语义：紫光也是人眼能看到的可见光，与句意不符。"}, {"text": "火光", "is_correct": false, "explanation": "语义：火光是可见光，人眼看得见，与句末“用眼睛看不到”矛盾。"}], "explanations": {"红外": "正确：红外是人眼看不见的光，遥控器发出的正是它。", "灯光": "语义：灯光是可见光，人眼看得见，与“用眼睛看不到”矛盾。", "紫光": "语义：紫光也是人眼能看到的可见光，与句意不符。", "火光": "语义：火光是可见光，人眼看得见，与句末“用眼睛看不到”矛盾。"}, "sentence_index": 6, "correct_answer": "红外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜里有了红外，人眼就能看清楚东西。", "explanation": "这里应该用〈可见光〉。人眼看不见红外，要看清东西需要可见光。"}, {"text": "医生用红外看胎儿的心跳。", "explanation": "这里应该用〈超声波〉。超声波用于检查心跳；红外是人眼看不见的光，不能用来测心跳。"}, {"text": "收音机靠红外接收广播。", "explanation": "这里应该用〈无线电〉。广播靠无线电波传送，红外是光，传输距离很短，不能用来接收广播。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜视仪能接收一个红外。", "corrected_sentence": "夜视仪能接收红外。", "error_description": "量词错误：「红外」是一种光，不能用「一个」来计量；应删去「一个」，说「夜视仪能接收红外」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种很红外夜视仪很贵。", "corrected_sentence": "这种红外夜视仪很贵。", "error_description": "程度副词错误：「红外」是名词，不能被「很」修饰；应说「这种红外夜视仪很贵」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
