INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26622, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一个一个地，一个接一个。", "primary_collocate": null, "pronunciation": "lù xù", "ipa": "lu˥˩ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "客人陆续走进了房间。", "target_word": "陆续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们陆续站了起来。", "target_word": "陆续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影结束了，观众陆续离开。", "target_word": "陆续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们陆续回答了老师的问题。", "target_word": "陆续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课前，学生陆续进了教室。", "target_word": "陆续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了车，大家陆续往前走。", "target_word": "陆续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宴会开始了，客人陆续坐下。", "target_word": "陆续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们陆续跑出了学校。", "target_word": "陆续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让病人陆续进来。", "target_word": "陆续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会了，同事们陆续到了。", "target_word": "陆续", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，人或事物一个接一个地依次出现或行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e1bb1b-df41-4c43-a922-40e41116d20b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26622, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "露宿", "is_correct": false, "explanation": "sù（第四声）与 xù（第四声）的声母不同（s 与 x），其余相同，意思是在户外过夜，与“一个接一个”无关。"}, {"text": "陆续", "is_correct": true, "explanation": "正确答案：lù xù，表示一个接一个地依次出现或行动。"}, {"text": "路遇", "is_correct": false, "explanation": "yù（第四声）与 xù 的声母不同（零声母 y 与 x），意思是途中偶然碰见。"}, {"text": "芦絮", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，意思是芦苇的絮状穗。"}], "explanations": {"露宿": "sù（第四声）与 xù（第四声）的声母不同（s 与 x），其余相同，意思是在户外过夜，与“一个接一个”无关。", "陆续": "正确答案：lù xù，表示一个接一个地依次出现或行动。", "路遇": "yù（第四声）与 xù 的声母不同（零声母 y 与 x），意思是途中偶然碰见。", "芦絮": "lú（第二声）与 lù（第四声）声调不同，意思是芦苇的絮状穗。"}, "sentence_index": null, "correct_answer": "陆续"}, "level_3": {"options": [{"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示进行中，与“走进了”的完成义冲突。"}, {"text": "陆续", "is_correct": true, "explanation": "正确：客人一个接一个地走进房间，符合“陆续”的含义。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示持续不变，与已经发生的“走进了”矛盾。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”强调持续不断，与“陆续”的先后相继义不符，“走进房间”是一次性动作。"}], "explanations": {"正在": "体貌：“正在”表示进行中，与“走进了”的完成义冲突。", "陆续": "正确：客人一个接一个地走进房间，符合“陆续”的含义。", "永远": "语义：“永远”表示持续不变，与已经发生的“走进了”矛盾。", "一直": "语义：“一直”强调持续不断，与“陆续”的先后相继义不符，“走进房间”是一次性动作。"}, "sentence_index": 0, "correct_answer": "陆续"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他陆续站了起来。", "explanation": "这里应该用〈猛地〉。陆续指多人或多件事先后相继，一个人突然站起不能用陆续。"}, {"text": "那辆车陆续撞上了路灯。", "explanation": "这里应该用〈一下子〉。陆续表示多个人或事物先后相继，一辆车只撞上路灯一次，是一次性事件，不能用陆续。"}, {"text": "他陆续坐在院子里。", "explanation": "这里应该用〈一直〉。陆续强调前后相继，不能描述持续不断的“坐在院子里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26622, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示间或发生，与宴会开始后客人依次入座的语境不合。"}, {"text": "陆续", "is_correct": true, "explanation": "正确：宴会开始后，客人一个接一个地坐下，符合“陆续”的含义。"}, {"text": "亲手", "is_correct": false, "explanation": "搭配：“亲手”指亲自动手，要求施事的动作有明确的操作对象，“坐下”不能说亲手。"}, {"text": "不断", "is_correct": false, "explanation": "语义：“坐下”是一次性动作，宴会开始后不宜说“不断”坐下。"}], "explanations": {"偶尔": "语义：“偶尔”表示间或发生，与宴会开始后客人依次入座的语境不合。", "陆续": "正确：宴会开始后，客人一个接一个地坐下，符合“陆续”的含义。", "亲手": "搭配：“亲手”指亲自动手，要求施事的动作有明确的操作对象，“坐下”不能说亲手。", "不断": "语义：“坐下”是一次性动作，宴会开始后不宜说“不断”坐下。"}, "sentence_index": 6, "correct_answer": "陆续"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他陆续就到。", "explanation": "这里应该用〈马上〉。陆续用于多人或多事物先后出现，一个人马上到达不能用陆续。"}, {"text": "他陆续摔了一跤。", "explanation": "这里应该用〈突然〉。陆续表示多个动作先后相继，摔一跤是一次性的动作，不能用陆续。"}, {"text": "他陆续打了个寒战。", "explanation": "这里应该用〈顿时〉。陆续表示多个动作先后相继，打了一个寒战是一次性的动作，不能用陆续。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们的陆续走出了教室。", "corrected_sentence": "同学们陆续走出了教室。", "error_description": "助词错误：副词「陆续」后不能加「的」，「同学们的陆续走出了教室」不通，应删去「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会议开始前，同事们很陆续进了会议室。", "corrected_sentence": "会议开始前，同事们陆续进了会议室。", "error_description": "「陆续」是副词，只修饰动词，前面不能加「很」，应说「同事们陆续进了会议室」；「很陆续」是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
