INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26626, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "动物或植物住的地方。", "primary_collocate": null, "pronunciation": "qī xī dì", "ipa": "tɕʰi˥ ɕi˥ ti˥˩", "syllable_count": 3, "sentences": [{"text": "这片森林是很多鸟的栖息地。", "target_word": "栖息地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大熊猫的栖息地在四川的山里。", "target_word": "栖息地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂太多，动物的栖息地越来越小。", "target_word": "栖息地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖边是水鸟喜欢的栖息地。", "target_word": "栖息地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护栖息地，就是保护动物的家。", "target_word": "栖息地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们在山上盖房子，破坏了鸟的栖息地。", "target_word": "栖息地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方成了小鱼的新栖息地。", "target_word": "栖息地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草原是牛羊和野马的栖息地。", "target_word": "栖息地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护栖息地，政府不让人进山。", "target_word": "栖息地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条河是白鹭的栖息地。", "target_word": "栖息地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词：动植物生活的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54dc7929-d038-45aa-8c18-bc8b7ecc58a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26626, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "栖息地", "is_correct": true, "explanation": "正确：“栖息地”指动植物生活的地方，与“很多鸟的”语境相符。"}, {"text": "食物", "is_correct": false, "explanation": "语义：“食物”指可以吃的东西，不是鸟生活的地方。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：“玩具”指供玩耍的物品，与鸟的生活场所无关。"}, {"text": "工地", "is_correct": false, "explanation": "语义：“工地”是施工的场地，与鸟的生活场所无关，不能说“很多鸟的工地”。"}], "explanations": {"栖息地": "正确：“栖息地”指动植物生活的地方，与“很多鸟的”语境相符。", "食物": "语义：“食物”指可以吃的东西，不是鸟生活的地方。", "玩具": "语义：“玩具”指供玩耍的物品，与鸟的生活场所无关。", "工地": "语义：“工地”是施工的场地，与鸟的生活场所无关，不能说“很多鸟的工地”。"}, "sentence_index": 0, "correct_answer": "栖息地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的栖息地很干净。", "explanation": "这里应该用〈内部〉。“栖息地”指动植物生活的地方，不能用来形容电脑；形容电脑内部干净要说“内部很干净”。"}, {"text": "这个山洞的栖息地很深。", "explanation": "这里应该用〈深度〉。“栖息地”指动植物生活的地方，不能用来形容山洞；形容山洞的深浅要说“很深”。"}, {"text": "这个水杯的栖息地很大。", "explanation": "这里应该用〈容量〉。“栖息地”指动植物生活的地方，不能用来形容杯子；形容杯子的大小要说“容量很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26626, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "栖息地", "is_correct": true, "explanation": "正确：“栖息地”指动植物生活的地方，与“小鱼的新”的搭配相符。"}, {"text": "垃圾场", "is_correct": false, "explanation": "语义：“垃圾场”指堆放垃圾的地方，与小鱼的生活场所不符。"}, {"text": "牢房", "is_correct": false, "explanation": "语义：“牢房”指关押人的房间，不能用于小鱼。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：“工厂”多指人造的生产场所，不与“小鱼的”这样的生物搭配。"}], "explanations": {"栖息地": "正确：“栖息地”指动植物生活的地方，与“小鱼的新”的搭配相符。", "垃圾场": "语义：“垃圾场”指堆放垃圾的地方，与小鱼的生活场所不符。", "牢房": "语义：“牢房”指关押人的房间，不能用于小鱼。", "工厂": "搭配：“工厂”多指人造的生产场所，不与“小鱼的”这样的生物搭配。"}, "sentence_index": 6, "correct_answer": "栖息地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子的栖息地很软。", "explanation": "这里应该用〈坐垫〉。“栖息地”指动植物生活的地方，不能用来形容椅子的软硬；形容椅子软要说“坐垫很软”。"}, {"text": "这盏灯的栖息地很亮。", "explanation": "这里应该用〈亮度〉。“栖息地”指动植物生活的地方，不能用来形容灯；形容灯的明暗要说“亮度很高”。"}, {"text": "这条裤子的栖息地很长。", "explanation": "这里应该用〈长度〉。“栖息地”指动植物生活的地方，不能用来形容裤子；形容裤子的长短要说“很长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26626, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只栖息地里住着很多候鸟。", "corrected_sentence": "这片栖息地里住着很多候鸟。", "error_description": "量词错误：“栖息地”指一块地方，应用量词“片”，不能用“只”（“只”用于动物等个体）。正确为“这片栖息地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26626, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条河成了白鹭的一只新栖息地。", "corrected_sentence": "这条河成了白鹭的一片新栖息地。", "error_description": "量词错误：“栖息地”指一块地方，应用量词“片”，“只”用于动物等个体，不能用于地方。正确为“一片新栖息地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
