INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26628, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一类用乳汁哺育幼崽的动物，人也属于这一类。", "primary_collocate": null, "pronunciation": "bǔ rǔ dòng wù", "ipa": "pu˨˩˦ ɻu˨˩˦ tʊŋ˥˩ u˥˩", "syllable_count": 4, "sentences": [{"text": "小狗是哺乳动物，它喝妈妈的奶长大。", "target_word": "哺乳动物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人也是哺乳动物。", "target_word": "哺乳动物", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老鼠是一种很小的哺乳动物。", "target_word": "哺乳动物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海豚住在水里，却是哺乳动物。", "target_word": "哺乳动物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鸡会下蛋，不是哺乳动物。", "target_word": "哺乳动物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牛是哺乳动物，所以牛妈妈有奶。", "target_word": "哺乳动物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，兔子也是哺乳动物。", "target_word": "哺乳动物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哺乳动物的宝宝生下来就喝奶。", "target_word": "哺乳动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道哪些哺乳动物生活在森林里吗？", "target_word": "哺乳动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熊猫是中国有名的哺乳动物。", "target_word": "哺乳动物", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种哺乳动物", "label": "量词"}], "register": "中性", "sense_fingerprint": "哺乳动物：用乳汁哺育幼崽的动物，人也是", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71266d48-abd2-408d-ab3d-49d9cf61150e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26628, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哺乳动物", "is_correct": true, "explanation": "正确。小狗属于哺乳动物，所以喝妈妈的奶长大。"}, {"text": "鸟类", "is_correct": false, "explanation": "语义：小狗不是鸟类，鸟类不用乳汁喂养幼崽，与后半句矛盾。"}, {"text": "爬行动物", "is_correct": false, "explanation": "语义：小狗不是爬行动物，爬行动物也不喝奶，与“喝妈妈的奶长大”不符。"}, {"text": "鱼类", "is_correct": false, "explanation": "体貌：鱼用鳃呼吸、身上有鳞，小狗身上有毛、用肺呼吸，外形与生理都不符。"}], "explanations": {"哺乳动物": "正确。小狗属于哺乳动物，所以喝妈妈的奶长大。", "鸟类": "语义：小狗不是鸟类，鸟类不用乳汁喂养幼崽，与后半句矛盾。", "爬行动物": "语义：小狗不是爬行动物，爬行动物也不喝奶，与“喝妈妈的奶长大”不符。", "鱼类": "体貌：鱼用鳃呼吸、身上有鳞，小狗身上有毛、用肺呼吸，外形与生理都不符。"}, "sentence_index": 0, "correct_answer": "哺乳动物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家厨房里有一把哺乳动物。", "explanation": "这里应该用〈种〉。〈把〉用于有柄的器具，不能用来数哺乳动物。"}, {"text": "我们在河边看到一条哺乳动物。", "explanation": "这里应该用〈种〉（或〈只〉）。〈条〉多用于鱼、蛇等细长的东西，不用来数哺乳动物。"}, {"text": "山上住着一座哺乳动物。", "explanation": "这里应该用〈种〉。〈座〉用于山、楼房等大型固定的东西，不能用来数动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26628, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哺乳动物", "is_correct": true, "explanation": "正确。兔子用肺呼吸、身上有毛，属于哺乳动物。"}, {"text": "植物", "is_correct": false, "explanation": "语义：兔子是动物，不是植物，与“也是”后面的类别对不上。"}, {"text": "矿物", "is_correct": false, "explanation": "语义：兔子是有生命的动物，矿物没有生命，与句中的类别矛盾。"}, {"text": "机器人", "is_correct": false, "explanation": "体貌：机器人没有毛发和血肉，兔子身上长毛、会呼吸，外形与生理都不符。"}], "explanations": {"哺乳动物": "正确。兔子用肺呼吸、身上有毛，属于哺乳动物。", "植物": "语义：兔子是动物，不是植物，与“也是”后面的类别对不上。", "矿物": "语义：兔子是有生命的动物，矿物没有生命，与句中的类别矛盾。", "机器人": "体貌：机器人没有毛发和血肉，兔子身上长毛、会呼吸，外形与生理都不符。"}, "sentence_index": 6, "correct_answer": "哺乳动物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "草地上开着一朵哺乳动物。", "explanation": "这里应该用〈种〉。〈朵〉用于花、云等，哺乳动物不能用〈朵〉来数。"}, {"text": "门上挂着一扇哺乳动物。", "explanation": "这里应该用〈种〉。〈扇〉用于门、窗等，哺乳动物不能用〈扇〉来数。"}, {"text": "院子里长着一棵哺乳动物。", "explanation": "这里应该用〈种〉。〈棵〉用于树、菜等植物，哺乳动物不能用〈棵〉来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26628, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "动物园里有很多座哺乳动物。", "corrected_sentence": "动物园里有很多种哺乳动物。", "error_description": "错误形式是“很多座哺乳动物”，正确形式是“很多种哺乳动物”。“座”用于山、楼房等大型固定的东西，不能用来数动物；说动物的种类要用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26628, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "非洲有很多条大型哺乳动物。", "corrected_sentence": "非洲有很多种大型哺乳动物。", "error_description": "错误形式是“很多条大型哺乳动物”，正确形式是“很多种大型哺乳动物”。这里说的是动物的种类，应用“种”；“条”多用于鱼、蛇等细长的东西，不用来数哺乳动物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
