INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26630, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或工具把飞在空中的东西拿住。", "primary_collocate": null, "pronunciation": "bǔ zhuō dào", "ipa": "pu˨˩˦ ʈʂwo˥ taʊ˥˩", "syllable_count": 3, "sentences": [{"text": "他伸手捕捉到一只飞过的蝴蝶。", "target_word": "捕捉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用网捕捉到一只蜻蜓。", "target_word": "捕捉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手捕捉到了一只乱飞的苍蝇。", "target_word": "捕捉到", "complexity_tier": "T3", "furigana": "tā yòng shǒu bǔ zhuō dào le yì zhī luàn fēi de cāng yíng。", "sentence_source": "generated"}, {"text": "爷爷用长竿捕捉到树上飞起的蝉。", "target_word": "捕捉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "傍晚，我用网捕捉到几只萤火虫。", "target_word": "捕捉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手一伸，捕捉到了飞来的蚊子。", "target_word": "捕捉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他挥起蝇拍，捕捉到了一只飞虫。", "target_word": "捕捉到", "complexity_tier": "T3", "furigana": "tā huī qǐ yíng pāi， bǔ zhuō dào le yì zhī fēi chóng。", "sentence_source": "generated"}, {"text": "老人用网捕捉到飞出蜂箱的蜜蜂。", "target_word": "捕捉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，他用网捕捉到飞进屋里的蛾子。", "target_word": "捕捉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在院子里捕捉到一只飞来的甲虫。", "target_word": "捕捉到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "捕捉到", "label": "原形"}, {"form": "捕捉不到", "label": "可能补语否定式"}], "register": "中性", "sense_fingerprint": "动词，用手或工具成功抓住飞在空中的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e1bb1b-df41-4c43-a922-40e41116d20b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26630, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挥舞", "is_correct": false, "explanation": "搭配：“挥舞”的宾语应是手中挥动的器具，不能说挥舞一只飞过的蝴蝶。"}, {"text": "捕捉到", "is_correct": true, "explanation": "正确：伸手捉住一只飞过的蝴蝶，符合语境。"}, {"text": "喂养", "is_correct": false, "explanation": "语义：“喂养”指饲养需要照顾的动物，句子说的是飞过的蝴蝶，不是饲养。"}, {"text": "购买到", "is_correct": false, "explanation": "搭配：“购买”的对象是商品，不能说购买一只飞过的蝴蝶。"}], "explanations": {"挥舞": "搭配：“挥舞”的宾语应是手中挥动的器具，不能说挥舞一只飞过的蝴蝶。", "捕捉到": "正确：伸手捉住一只飞过的蝴蝶，符合语境。", "喂养": "语义：“喂养”指饲养需要照顾的动物，句子说的是飞过的蝴蝶，不是饲养。", "购买到": "搭配：“购买”的对象是商品，不能说购买一只飞过的蝴蝶。"}, "sentence_index": 0, "correct_answer": "捕捉到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在河边捕捉到一块石头。", "explanation": "这里应该用〈捡起〉。捕捉到只用于飞在空中的东西，石头静止在河边，应说捡起。"}, {"text": "他从树上捕捉到一个苹果。", "explanation": "这里应该用〈摘下〉。苹果挂在树上，不是飞在空中的东西，应说摘下。"}, {"text": "他在桌上捕捉到一把钥匙。", "explanation": "这里应该用〈拿起〉。钥匙放在桌上，不是飞在空中的东西，应说拿起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26630, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抚摸到", "is_correct": false, "explanation": "搭配：蝇拍是用来拍打的，不能用来抚摸飞虫。"}, {"text": "捕捉到", "is_correct": true, "explanation": "正确：挥起蝇拍去捉，成功捉住一只飞虫，符合语境。"}, {"text": "吞下", "is_correct": false, "explanation": "语义：挥蝇拍是为了捉住飞虫，句子并没有说吞下它。"}, {"text": "驯服", "is_correct": false, "explanation": "语义：蝇拍的用途是拍打捉虫，句子说的是捉住飞虫，不是驯服它。"}], "explanations": {"抚摸到": "搭配：蝇拍是用来拍打的，不能用来抚摸飞虫。", "捕捉到": "正确：挥起蝇拍去捉，成功捉住一只飞虫，符合语境。", "吞下": "语义：挥蝇拍是为了捉住飞虫，句子并没有说吞下它。", "驯服": "语义：蝇拍的用途是拍打捉虫，句子说的是捉住飞虫，不是驯服它。"}, "sentence_index": 6, "correct_answer": "捕捉到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在站台上捕捉到了一列开走的火车。", "explanation": "这里应该用〈目送〉。捕捉到只用于拿住飞在空中的东西，火车在地面开走，只能目送，不能捕捉。"}, {"text": "他在路上捕捉到多年不见的朋友。", "explanation": "这里应该用〈遇见〉。捕捉到只用于拿住飞在空中的东西，偶然碰到的老朋友不是被拿住的对象，应说遇见。"}, {"text": "我在山路上捕捉到了一条涨水的溪流。", "explanation": "这里应该用〈看见〉。捕捉到只用于拿住飞在空中的东西，溪流不能被拿住，应说看见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26630, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈用纱网捕捉到的一只飞进厨房的苍蝇。", "corrected_sentence": "妈妈用纱网捕捉到了一只飞进厨房的苍蝇。", "error_description": "助词错误：「捕捉到了」的「了」误写成「的」，「捕捉到的一只飞进厨房的苍蝇」只是名词短语，缺少谓语，应说「妈妈用纱网捕捉到了一只飞进厨房的苍蝇」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在窗边把捕捉到了一只飞来的小蜂。", "corrected_sentence": "我在窗边捕捉到了一只飞来的小蜂。", "error_description": "介词错误：「把」字句中「把」后须接宾语，「把捕捉到了」缺少宾语，应删去「把」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
