INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26632, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种像猫的动物，身上有斑点。", "primary_collocate": null, "pronunciation": "bào māo", "ipa": "pɑu˥˩ mɑu˥", "syllable_count": 2, "sentences": [{"text": "豹猫像猫，身上有很多斑点。", "target_word": "豹猫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只豹猫的身上有黑色的斑点。", "target_word": "豹猫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只动物长得像猫，身上有斑点，是豹猫。", "target_word": "豹猫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里有一张豹猫的照片，它身上有斑点。", "target_word": "豹猫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "豹猫看起来像猫，可是比猫更野。", "target_word": "豹猫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们问：“这个像猫的动物是什么？”老师说：“是豹猫。”", "target_word": "豹猫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "豹猫喜欢爬树，它的尾巴很长。", "target_word": "豹猫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图片上的豹猫走着，身上的斑点很清楚。", "target_word": "豹猫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "豹猫的名字里有“豹”，因为它身上有斑点。", "target_word": "豹猫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想养一只猫，可是妈妈说豹猫不能养。", "target_word": "豹猫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "豹貓", "label": "繁体"}], "register": "中性", "sense_fingerprint": "外形像猫、身上有斑点的动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c14fd65d-7562-43e3-b9a1-66b88150ec98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26632, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "豹猫", "is_correct": true, "explanation": "豹猫是一种像猫、身上有斑点的动物，符合“像猫”“有很多斑点”的描述。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是动物，与“像猫”的描述矛盾。"}, {"text": "雨伞", "is_correct": false, "explanation": "体貌：雨伞没有身体和四肢，不会有像猫的身形和斑点。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是动物，句意不通。"}], "explanations": {"豹猫": "豹猫是一种像猫、身上有斑点的动物，符合“像猫”“有很多斑点”的描述。", "书包": "语义：书包不是动物，与“像猫”的描述矛盾。", "雨伞": "体貌：雨伞没有身体和四肢，不会有像猫的身形和斑点。", "桌子": "语义：桌子是家具，不是动物，句意不通。"}, "sentence_index": 0, "correct_answer": "豹猫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "豹猫在天上飞来飞去，叫声很好听。", "explanation": "这里应该用〈小鸟〉。豹猫是像猫的动物，不会飞；在天上飞、叫声好听的是鸟。"}, {"text": "妈妈把豹猫种在花盆里，每天给它浇水。", "explanation": "这里应该用〈花〉。豹猫是动物，不能种在花盆里浇水。"}, {"text": "豹猫在河里游来游去，用鳃呼吸。", "explanation": "这里应该用〈鱼〉。用鳃呼吸、生活在水里的是鱼；豹猫是陆地上像猫的动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26632, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "豹猫", "is_correct": true, "explanation": "豹猫体型小，四肢灵活，善于爬树，尾巴较长，符合句意。"}, {"text": "鲨鱼", "is_correct": false, "explanation": "语义：鲨鱼生活在水中，不会爬树。"}, {"text": "大象", "is_correct": false, "explanation": "体貌：大象体型庞大、四肢粗壮，不擅长爬树，与“尾巴很长”的描述也不符。"}, {"text": "鸭子", "is_correct": false, "explanation": "语义：鸭子是水禽，一般不爬树，与句意不符。"}], "explanations": {"豹猫": "豹猫体型小，四肢灵活，善于爬树，尾巴较长，符合句意。", "鲨鱼": "语义：鲨鱼生活在水中，不会爬树。", "大象": "体貌：大象体型庞大、四肢粗壮，不擅长爬树，与“尾巴很长”的描述也不符。", "鸭子": "语义：鸭子是水禽，一般不爬树，与句意不符。"}, "sentence_index": 6, "correct_answer": "豹猫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他穿了一件豹猫的外套。", "explanation": "这里应该用〈豹纹〉。“豹纹”指斑纹图案，“豹猫”是动物名，不能用来指花纹。"}, {"text": "他真是个豹猫胆，什么危险都不怕。", "explanation": "这里应该用〈豹子〉。“豹子胆”是固定说法，形容胆子大，不能把“豹子”换成“豹猫”。"}, {"text": "我每天早上喝一杯豹猫。", "explanation": "这里应该用〈牛奶〉。豹猫是动物，不能喝；早上喝的是牛奶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26632, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在山路上看到一条豹猫。", "corrected_sentence": "我在山路上看到一只豹猫。", "error_description": "量词错误：“豹猫”是动物，应用量词“只”。“条”多用于蛇、鱼等细长的东西，不用于豹猫，应改为“一只豹猫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26632, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "森林里住着很多豹猫们。", "corrected_sentence": "森林里住着很多豹猫。", "error_description": "复数错误：“很多”已经表示复数，后面的名词不能再加“们”，应去掉“们”，写成“很多豹猫”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
