INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26634, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26634, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "斑羚是一种像山羊的动物，住在山上。", "primary_collocate": null, "pronunciation": "bān líng", "ipa": "pan˥ liŋ˧˥", "syllable_count": 2, "sentences": [{"text": "斑羚是一种住在山上的动物。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "斑羚看起来像山羊。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上有两只斑羚。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只斑羚站在石头上。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "斑羚喜欢吃草和树叶。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了斑羚的照片。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "斑羚的腿又细又长。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天亮了，斑羚走下山来。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟很喜欢斑羚。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "斑羚不怕高，也不怕陡的山。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词，住在山上、像山羊的一种动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e1bb1b-df41-4c43-a922-40e41116d20b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26634, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鱼", "is_correct": false, "explanation": "语义：鱼生活在水里，不住在山上。"}, {"text": "斑羚", "is_correct": true, "explanation": "斑羚是住在山上的动物，符合释义。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“住”要求有生命的主语，石头不能住在山上。"}, {"text": "树木", "is_correct": false, "explanation": "语义：树木是植物，不是动物，不能说成“一种动物”。"}], "explanations": {"鱼": "语义：鱼生活在水里，不住在山上。", "斑羚": "斑羚是住在山上的动物，符合释义。", "石头": "搭配：“住”要求有生命的主语，石头不能住在山上。", "树木": "语义：树木是植物，不是动物，不能说成“一种动物”。"}, "sentence_index": 0, "correct_answer": "斑羚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在山上看到一棵斑羚。", "explanation": "这里应该用〈只〉。“棵”用于树木、植物，斑羚是动物，应用“只”。"}, {"text": "山脚下跑来一根斑羚。", "explanation": "这里应该用〈只〉。“根”用于细长的条状物，不用于动物。"}, {"text": "草地上趴着一条斑羚。", "explanation": "这里应该用〈只〉。“条”多用于鱼、蛇等细长的东西，斑羚应用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26634, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "云", "is_correct": false, "explanation": "体貌：云没有腿，与“腿又细又长”不符。"}, {"text": "斑羚", "is_correct": true, "explanation": "斑羚有腿，且腿又细又长，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "体貌：石头没有腿，不能说“腿又细又长”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是有腿的生物，“腿”不能用于河流。"}], "explanations": {"云": "体貌：云没有腿，与“腿又细又长”不符。", "斑羚": "斑羚有腿，且腿又细又长，符合句意。", "石头": "体貌：石头没有腿，不能说“腿又细又长”。", "河流": "语义：河流不是有腿的生物，“腿”不能用于河流。"}, "sentence_index": 6, "correct_answer": "斑羚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷留着一撮斑羚胡子。", "explanation": "这里应该用〈山羊〉。“山羊胡子”是固定说法，斑羚不能这样搭配。"}, {"text": "这家牧场每天挤出两桶斑羚奶。", "explanation": "这里应该用〈羊〉。“挤奶”针对家养的羊、牛等，斑羚是野生动物，不能这样说。"}, {"text": "牧童每天赶着一群斑羚去草场放牧。", "explanation": "这里应该用〈羊〉。“放牧”“赶群”多用于家养的羊、牛等牲畜，斑羚是野生动物，不能这样放牧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条斑羚在山上吃草。", "corrected_sentence": "那只斑羚在山上吃草。", "error_description": "量词错误：“斑羚”是动物，应使用量词“只”；“条”多用于鱼、蛇等细长的东西，不能用于斑羚。正确说法是“那只斑羚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我见过一条斑羚。", "corrected_sentence": "我见过一只斑羚。", "error_description": "量词错误：“斑羚”是动物，应使用量词“只”；“条”多用于鱼、蛇等细长的东西，不能用于斑羚。正确说法是“我见过一只斑羚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
