INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26636, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "林区就是有很多树的地方。", "primary_collocate": null, "pronunciation": "lín qū", "ipa": "lin˧˥ tɕʰy˥˥", "syllable_count": 2, "sentences": [{"text": "林区就在我们村子后面。", "target_word": "林区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们开车进了林区。", "target_word": "林区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "林区里到处都是绿色的树。", "target_word": "林区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的林区特别漂亮。", "target_word": "林区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "林区的人用木头盖房子。", "target_word": "林区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在林区里发现了一只小鹿。", "target_word": "林区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，林区的空气更新鲜了。", "target_word": "林区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "林区里很安静，只能听到鸟叫。", "target_word": "林区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们去林区看树。", "target_word": "林区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "林区的路上有很多落叶。", "target_word": "林区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "林區", "label": "繁体"}], "register": "通用", "sense_fingerprint": "有很多树的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a1fb72f-7f26-46aa-b253-c34484e0d5e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26636, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "林区", "is_correct": true, "explanation": "正确：林区是有很多树的地方，可以位于村子后面。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是室内电器，不会位于村子后面，与“村子后面”的位置不符。"}, {"text": "书架", "is_correct": false, "explanation": "搭配：“就在……后面”要求表示地点的词，书架是家具，不能作为村后的地点。"}, {"text": "汽水", "is_correct": false, "explanation": "语义：汽水是饮料，不是可以存在于村子后面的地方。"}], "explanations": {"林区": "正确：林区是有很多树的地方，可以位于村子后面。", "电视": "语义：电视是室内电器，不会位于村子后面，与“村子后面”的位置不符。", "书架": "搭配：“就在……后面”要求表示地点的词，书架是家具，不能作为村后的地点。", "汽水": "语义：汽水是饮料，不是可以存在于村子后面的地方。"}, "sentence_index": 0, "correct_answer": "林区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他背着林区去上学。", "explanation": "这里应该用〈书包〉。书包可以背着去上学；林区是有很多树的地方，无法背着走。"}, {"text": "妈妈把一束菊花插进了林区里。", "explanation": "这里应该用〈花瓶〉。花瓶用来插花；林区是有很多树的地方，不能用来插花。"}, {"text": "他用林区打开了门。", "explanation": "这里应该用〈钥匙〉。钥匙用来开门；林区是有很多树的地方，不能用来开门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26636, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "林区", "is_correct": true, "explanation": "正确：林区有很多树，下雨后会让周围的空气更新鲜，语义通顺。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是计时器具，不会影响空气，与“空气更新鲜了”冲突。"}, {"text": "玻璃杯", "is_correct": false, "explanation": "语义：玻璃杯是容器，与“空气更新鲜”没有关系，不能作为空气的所在地。"}, {"text": "篮球", "is_correct": false, "explanation": "搭配：“……的空气”需要一个有空气流动的地点，篮球是球类，不能这样搭配。"}], "explanations": {"林区": "正确：林区有很多树，下雨后会让周围的空气更新鲜，语义通顺。", "闹钟": "语义：闹钟是计时器具，不会影响空气，与“空气更新鲜了”冲突。", "玻璃杯": "语义：玻璃杯是容器，与“空气更新鲜”没有关系，不能作为空气的所在地。", "篮球": "搭配：“……的空气”需要一个有空气流动的地点，篮球是球类，不能这样搭配。"}, "sentence_index": 6, "correct_answer": "林区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们坐在林区上看电视。", "explanation": "这里应该用〈沙发〉。沙发可以坐人；林区是有很多树的地方，不能坐在上面看电视。"}, {"text": "他把林区举到眼前，能照见自己的脸。", "explanation": "这里应该用〈镜子〉。镜子能照见人影；林区是有很多树的地方，不能举到眼前照见脸。"}, {"text": "他把林区装进了背包里，带回了家。", "explanation": "这里应该用〈书〉。背包能装东西；林区是有很多树的地方，不能装进背包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26636, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们进了那把林区，走了很久。", "corrected_sentence": "我们进了那片林区，走了很久。", "error_description": "量词用错：“林区”指大片地区，应用“片”；“把”用于有柄的器具，不能用来计量林区。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26636, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位林区很大，我们走了很久。", "corrected_sentence": "那片林区很大，我们走了很久。", "error_description": "量词用错：林区指大片地区，应用“片”，“位”用于人，应说“那片林区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
