INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26638, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人或者动物走过留下的脚印。", "primary_collocate": null, "pronunciation": "zōng jì", "ipa": "tsʊŋ˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "雪地上有一行小动物的踪迹。", "target_word": "踪迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着地上的踪迹走进了树林。", "target_word": "踪迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙子上留下了他走过的踪迹。", "target_word": "踪迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下过雨以后，泥地上能看到老虎的踪迹。", "target_word": "踪迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猎人看着地上的踪迹，知道狼刚走过。", "target_word": "踪迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的软泥里有很多鸟的踪迹。", "target_word": "踪迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在海边的沙滩上留下了小小的踪迹。", "target_word": "踪迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，沙地上的踪迹就不见了。", "target_word": "踪迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的雪很厚，我们看不到动物的踪迹。", "target_word": "踪迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他蹲下来，仔细看地上的踪迹。", "target_word": "踪迹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "蹤跡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人或动物走过后地上留下的脚印", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c74c4ae1-9515-4459-b540-8770b8d0940f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26638, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "踪迹", "is_correct": true, "explanation": "踪迹 zōng jì：人或动物走过后留下的脚印，是正确答案。"}, {"text": "总计", "is_correct": false, "explanation": "zǒng（第三声）与 zōng（第一声）声调不同，意思是合计、总共。"}, {"text": "总机", "is_correct": false, "explanation": "两个音节的声调都与 zōng jì 不同（zǒng jī），意思是电话总机。"}, {"text": "中继", "is_correct": false, "explanation": "zhōng 与 zōng 声母不同（zh 与 z），意思是中间转接，如中继站。"}], "explanations": {"踪迹": "踪迹 zōng jì：人或动物走过后留下的脚印，是正确答案。", "总计": "zǒng（第三声）与 zōng（第一声）声调不同，意思是合计、总共。", "总机": "两个音节的声调都与 zōng jì 不同（zǒng jī），意思是电话总机。", "中继": "zhōng 与 zōng 声母不同（zh 与 z），意思是中间转接，如中继站。"}, "sentence_index": null, "correct_answer": "踪迹"}, "level_3": {"options": [{"text": "踪迹", "is_correct": true, "explanation": "踪迹：指小动物在雪地上留下的脚印，与“一行”搭配，符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "语义：雪地上一行可见的是痕迹，不是声音，句中的“一行”也不能计量声音。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格与雪地上的小动物无关，句中不能是一行价格。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不属于小动物，也不能用“一行”计量，不合句意。"}], "explanations": {"踪迹": "踪迹：指小动物在雪地上留下的脚印，与“一行”搭配，符合句意。", "声音": "语义：雪地上一行可见的是痕迹，不是声音，句中的“一行”也不能计量声音。", "价格": "语义：价格与雪地上的小动物无关，句中不能是一行价格。", "天气": "语义：天气不属于小动物，也不能用“一行”计量，不合句意。"}, "sentence_index": 0, "correct_answer": "踪迹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "衣服上还留着许多踪迹。", "explanation": "这里应该用〈痕迹〉。踪迹指人或动物走过后留下的线索，衣服上的污渍、划痕要用痕迹。"}, {"text": "天气有转冷的踪迹。", "explanation": "这里应该用〈迹象〉。踪迹指行动后留下的痕迹，表示天气转冷等征兆要用迹象。"}, {"text": "这座古村的房子是用踪迹建成的。", "explanation": "这里应该用〈石头〉。踪迹指行动后留下的线索，不能作建筑材料；古村的房子要说用石头建成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26638, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "踪迹", "is_correct": true, "explanation": "踪迹：孩子们在沙滩上留下的小小脚印，与“留下”搭配，符合句意。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资不是可以留在沙滩上的东西，与句中的“小小的”不符。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：“留下”不能与“学费”搭配，学费一般说缴、交。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单是账目凭证，不能留在沙滩上，与句意不符。"}], "explanations": {"踪迹": "踪迹：孩子们在沙滩上留下的小小脚印，与“留下”搭配，符合句意。", "工资": "语义：工资不是可以留在沙滩上的东西，与句中的“小小的”不符。", "学费": "搭配：“留下”不能与“学费”搭配，学费一般说缴、交。", "账单": "语义：账单是账目凭证，不能留在沙滩上，与句意不符。"}, "sentence_index": 6, "correct_answer": "踪迹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这枚旧印章的价格是三十个踪迹。", "explanation": "这里应该用〈元〉，写作“三十元”。踪迹不能用来计价，应说“这枚旧印章的价格是三十元”。"}, {"text": "桌布上留下了许多踪迹。", "explanation": "这里应该用〈油渍〉。踪迹指行走后留下的线索，桌布上的污渍要用油渍。"}, {"text": "他的膝盖上留着许多踪迹。", "explanation": "这里应该用〈伤疤〉。踪迹指行动后留下的线索，皮肤愈合的伤口要用伤疤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26638, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "猎人在雪地上发现了一块清楚的踪迹。", "corrected_sentence": "猎人在雪地上发现了一行清楚的踪迹。", "error_description": "量词错误。“块”用于块状实物，不能计量“踪迹”；可改用“一行”，即“一行清楚的踪迹”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "风把他踪迹吹没了。", "corrected_sentence": "风把他的踪迹吹没了。", "error_description": "错误形式是“他踪迹”，正确形式是“他的踪迹”。“他”修饰“踪迹”时要加“的”，省略后不成词组。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26642, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱", "is_correct": true, "explanation": "“弱”与“强”是反义词，都指力气或体质的大小，符合本义。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”说速度，与力气大小没有反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "“轻”说分量，与“力气大”不构成反义。"}, {"text": "矮", "is_correct": false, "explanation": "“矮”说高度，与力气、身体壮实无关。"}], "correct_answer": "弱", "explanations": {"弱": "“弱”与“强”是反义词，都指力气或体质的大小，符合本义。", "慢": "“慢”说速度，与力气大小没有反义关系。", "轻": "“轻”说分量，与“力气大”不构成反义。", "矮": "“矮”说高度，与力气、身体壮实无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26642, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱", "is_correct": true, "explanation": "“弱”与“强”是反义词，都指力气或体质的大小，符合本义。"}, {"text": "懒", "is_correct": false, "explanation": "“懒”指不愿做事，与力气大小没有反义关系。"}, {"text": "远", "is_correct": false, "explanation": "“远”指距离，与力气、身体壮实无关。"}, {"text": "甜", "is_correct": false, "explanation": "“甜”描述味道，与力气大小没有反义关系。"}], "correct_answer": "弱", "explanations": {"弱": "“弱”与“强”是反义词，都指力气或体质的大小，符合本义。", "懒": "“懒”指不愿做事，与力气大小没有反义关系。", "远": "“远”指距离，与力气、身体壮实无关。", "甜": "“甜”描述味道，与力气大小没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26642, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示力气大或身体壮。", "primary_collocate": null, "pronunciation": "qiáng", "ipa": "tɕʰjaŋ˧˥", "syllable_count": 1, "sentences": [{"text": "他的力量很强，一个人能搬动桌子。", "target_word": "强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥身体强，冬天也不感冒。", "target_word": "强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时身体很强，能挑两桶水。", "target_word": "强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员的腿部力量很强。", "target_word": "强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的身体比我强，一口气能爬上六楼。", "target_word": "强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小伙子身体强，干活不累。", "target_word": "强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多锻炼以后，我的身体比以前强了。", "target_word": "强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这匹马的力量很强，能拉着车走很远。", "target_word": "强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看起来很瘦，其实体质很强。", "target_word": "强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他天天游泳，身体越来越强。", "target_word": "强", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "強", "label": "繁体"}, {"form": "强壮", "label": "复合词"}], "register": "中性", "sense_fingerprint": "力气大，身体结实", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a60a7be6-0797-43ec-a9b8-273314716fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26642, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "强", "is_correct": true, "explanation": "这是目标词本身，读 qiáng，指力气大、身体壮。"}, {"text": "抢", "is_correct": false, "explanation": "qiǎng（第三声）与 qiáng（第二声）声调不同，意思是抢夺。"}, {"text": "枪", "is_correct": false, "explanation": "qiāng（第一声）与 qiáng（第二声）声调不同，意思是枪。"}, {"text": "呛", "is_correct": false, "explanation": "qiàng（第四声）与 qiáng（第二声）声调不同，意思是呛住。"}, {"text": "腔", "is_correct": false, "explanation": "qiāng（第一声）与 qiáng（第二声）声调不同，意思是腔调。"}], "explanations": {"强": "这是目标词本身，读 qiáng，指力气大、身体壮。", "抢": "qiǎng（第三声）与 qiáng（第二声）声调不同，意思是抢夺。", "枪": "qiāng（第一声）与 qiáng（第二声）声调不同，意思是枪。", "呛": "qiàng（第四声）与 qiáng（第二声）声调不同，意思是呛住。", "腔": "qiāng（第一声）与 qiáng（第二声）声调不同，意思是腔调。"}, "sentence_index": null, "correct_answer": "强"}, "level_3": {"options": [{"text": "强", "is_correct": true, "explanation": "“很”后接形容力气大的形容词，与“能搬动桌子”一致。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“力量”不能用“亮”来形容，搭配不当。"}, {"text": "轻", "is_correct": false, "explanation": "语义：“轻”指分量小，与“能搬动桌子”的句意相反。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”说速度，不能形容力量，“力量很慢”说不通。"}], "explanations": {"强": "“很”后接形容力气大的形容词，与“能搬动桌子”一致。", "亮": "搭配：“力量”不能用“亮”来形容，搭配不当。", "轻": "语义：“轻”指分量小，与“能搬动桌子”的句意相反。", "慢": "语义：“慢”说速度，不能形容力量，“力量很慢”说不通。"}, "sentence_index": 0, "correct_answer": "强"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的颜色很强，穿出去很显眼。", "explanation": "这里应该用〈鲜艳〉。强形容力气，颜色的鲜艳程度要说“鲜艳”。"}, {"text": "他的病情很强，医生让他马上住院。", "explanation": "这里应该用〈严重〉。强不形容病情，病情重要说“严重”。"}, {"text": "他的工资很强，每个月都能存下很多钱。", "explanation": "这里应该用〈高〉。强不形容工资的多少，工资多要说“高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26642, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "强", "is_correct": true, "explanation": "这是目标词本身，读 qiáng，指力气大、身体壮。"}, {"text": "详", "is_correct": false, "explanation": "xiáng 与 qiáng 声母不同（x/q），意思是详细。"}, {"text": "前", "is_correct": false, "explanation": "qián 与 qiáng 韵母不同（an/ang），意思是前面。"}, {"text": "情", "is_correct": false, "explanation": "qíng 与 qiáng 韵母不同（ing/ang），意思是感情。"}], "explanations": {"强": "这是目标词本身，读 qiáng，指力气大、身体壮。", "详": "xiáng 与 qiáng 声母不同（x/q），意思是详细。", "前": "qián 与 qiáng 韵母不同（an/ang），意思是前面。", "情": "qíng 与 qiáng 韵母不同（ing/ang），意思是感情。"}, "sentence_index": null, "correct_answer": "强"}, "level_3": {"options": [{"text": "强", "is_correct": true, "explanation": "“比以前”后接形容身体状况的形容词，“强了”说明身体变好。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”描述味道，不能形容身体状况。"}, {"text": "湿", "is_correct": false, "explanation": "搭配：“身体湿了”不成立，“湿”不用于身体状况。"}, {"text": "远", "is_correct": false, "explanation": "语义：“远”指距离，不能用来形容身体状况。"}], "explanations": {"强": "“比以前”后接形容身体状况的形容词，“强了”说明身体变好。", "甜": "语义：“甜”描述味道，不能形容身体状况。", "湿": "搭配：“身体湿了”不成立，“湿”不用于身体状况。", "远": "语义：“远”指距离，不能用来形容身体状况。"}, "sentence_index": 6, "correct_answer": "强"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间教室的空间很强，坐下一百个人也不挤。", "explanation": "这里应该用〈大〉。强不形容空间的大小，空间大要说“大”。"}, {"text": "这篇文章的字数很强，老师让他删掉一半。", "explanation": "这里应该用〈多〉。强不用于字数的多少，字数多要说“多”。"}, {"text": "他的身高很强，站在队伍里很显眼。", "explanation": "这里应该用〈高〉。强形容力气和体质，形容身材的高矮要说“高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一个力气很强人。", "corrected_sentence": "他是一个力气很强的人。", "error_description": "结构错误：“力气很强”修饰名词“人”时要加“的”，应说“力气很强的人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26642, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他天天锻炼，力气越来越很强。", "corrected_sentence": "他天天锻炼，力气越来越强。", "error_description": "程度词错误：“越来越”后面不能再加“很”，应说“越来越强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
