INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26644, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "植物生病或被害虫咬了。", "primary_collocate": null, "pronunciation": "bìng chóng hài", "ipa": "piŋ˥˩ ʈʂʰʊŋ˧˥ xaɪ˥˩", "syllable_count": 3, "sentences": [{"text": "我家阳台的花有了病虫害，叶子都黄了。", "target_word": "病虫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜园里的青菜遇到病虫害，要马上处理。", "target_word": "病虫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈发现月季有了病虫害，赶紧买药。", "target_word": "病虫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小树苗有了病虫害，叶子上全是小洞。", "target_word": "病虫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵苹果树有病虫害，需要喷药。", "target_word": "病虫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人发现菜叶上有虫眼，知道是病虫害。", "target_word": "病虫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花盆里的植物发生病虫害，要先隔离。", "target_word": "病虫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了避免病虫害，爷爷常常给果树检查叶子。", "target_word": "病虫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玫瑰花有了病虫害，花瓣都掉了。", "target_word": "病虫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校花园里的树出现病虫害，老师请人来看。", "target_word": "病虫害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "病蟲害", "label": "繁体"}], "register": "中性", "sense_fingerprint": "花草树木生病或被虫子咬坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a60a7be6-0797-43ec-a9b8-273314716fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26644, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "病虫害", "is_correct": true, "explanation": "“有了……”后接植物出现的病害或虫害，与“叶子都黄了”一致。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“感冒”是人的疾病，“花”不能得感冒。"}, {"text": "近视", "is_correct": false, "explanation": "语义：“近视”指眼睛的视力问题，与花叶发黄无关，不能用于植物。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”指人或动物体温升高，花不会发烧。"}], "explanations": {"病虫害": "“有了……”后接植物出现的病害或虫害，与“叶子都黄了”一致。", "感冒": "搭配：“感冒”是人的疾病，“花”不能得感冒。", "近视": "语义：“近视”指眼睛的视力问题，与花叶发黄无关，不能用于植物。", "发烧": "语义：“发烧”指人或动物体温升高，花不会发烧。"}, "sentence_index": 0, "correct_answer": "病虫害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生说我爸爸有病虫害，需要住院治疗。", "explanation": "这里应该用〈疾病〉。病虫害只指植物生病或被害虫咬，不用于人的疾病。"}, {"text": "这份报告里的病虫害太多了，需要重新写。", "explanation": "这里应该用〈错误〉。病虫害专指植物生病或被虫咬，报告中的错误应说“错误”，不宜用“病虫害”来比喻。"}, {"text": "我的手机中了病虫害，只好送去修理。", "explanation": "这里应该用〈病毒〉。病虫害只用于植物，不能指手机中的病毒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26644, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病虫害", "is_correct": true, "explanation": "“发生”后接侵害植物的病害或虫害，符合“要先隔离”的处理。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学生的功课，植物不会“发生作业”。"}, {"text": "生日", "is_correct": false, "explanation": "搭配：“生日”不能与“发生”搭配，也不需要“隔离”。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：“友谊”指人与人的感情，植物不会发生友谊。"}], "explanations": {"病虫害": "“发生”后接侵害植物的病害或虫害，符合“要先隔离”的处理。", "作业": "语义：“作业”是学生的功课，植物不会“发生作业”。", "生日": "搭配：“生日”不能与“发生”搭配，也不需要“隔离”。", "友谊": "语义：“友谊”指人与人的感情，植物不会发生友谊。"}, "sentence_index": 6, "correct_answer": "病虫害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子的腿上有病虫害，需要修一修。", "explanation": "这里应该用〈损坏〉。病虫害只用于植物，不用于家具。"}, {"text": "这场地震带来了很多病虫害，房子倒了不少。", "explanation": "这里应该用〈灾害〉。病虫害指病菌、害虫对植物的危害，不包括地震等自然灾害。"}, {"text": "这箱饼干里有病虫害，大家都不要吃。", "explanation": "这里应该用〈虫子〉。病虫害指病菌、害虫对植物的危害，饼干里的虫子不宜用“病虫害”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26644, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种药向病虫害很有效。", "corrected_sentence": "这种药对病虫害很有效。", "error_description": "介词错误：表示“有效”的对象要用介词“对”引出，应说“对病虫害很有效”，不能用“向”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26644, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天菜园里出现了一只病虫害，青菜损失了一半。", "corrected_sentence": "昨天菜园里出现了一次病虫害，青菜损失了一半。", "error_description": "量词错误：“病虫害”是抽象的灾害名词，应用量词“次”，不能用“只”（多用于动物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
