INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26646, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自己调整自己，让自己变好。", "primary_collocate": null, "pronunciation": "zì wǒ tiáo jié", "ipa": "tsɨ˥˩ wɔ˨˩˦ tʰjɑʊ˧˥ tɕjɛ˧˥", "syllable_count": 4, "sentences": [{"text": "考试没考好，他先自我调节，再继续学习。", "target_word": "自我调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作压力大时，你要学会自我调节。", "target_word": "自我调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用听音乐的办法自我调节心情。", "target_word": "自我调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，运动员需要自我调节，不能太紧张。", "target_word": "自我调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会自我调节，难过一晚就好了。", "target_word": "自我调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭完以后，慢慢自我调节好了。", "target_word": "自我调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失败以后，我花了几天时间自我调节。", "target_word": "自我调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教大家怎么自我调节坏心情。", "target_word": "自我调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心情不好，就出去走走，自我调节一下。", "target_word": "自我调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到难事，他总是先自我调节，不着急。", "target_word": "自我调节", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自我調節", "label": "繁体"}, {"form": "自我调节能力", "label": "复合"}], "register": "中性", "sense_fingerprint": "人靠自己调整心情或状态，让自己恢复得更好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c74c4ae1-9515-4459-b540-8770b8d0940f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26646, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自我放弃", "is_correct": false, "explanation": "语义：“放弃”与后面的“再继续学习”相矛盾，无法衔接。"}, {"text": "自我陶醉", "is_correct": false, "explanation": "语义：“自我陶醉”指自我欣赏、沾沾自喜，与“考试没考好”后调整心情的语境相反。"}, {"text": "自我调节", "is_correct": true, "explanation": "自我调节指自己调整自己的心情或状态，正对应“考试没考好”后先调整心情。"}, {"text": "自我介绍", "is_correct": false, "explanation": "语义：“自我介绍”是向他人介绍自己，与“先……再继续学习”的语境不合。"}], "explanations": {"自我放弃": "语义：“放弃”与后面的“再继续学习”相矛盾，无法衔接。", "自我陶醉": "语义：“自我陶醉”指自我欣赏、沾沾自喜，与“考试没考好”后调整心情的语境相反。", "自我调节": "自我调节指自己调整自己的心情或状态，正对应“考试没考好”后先调整心情。", "自我介绍": "语义：“自我介绍”是向他人介绍自己，与“先……再继续学习”的语境不合。"}, "sentence_index": 0, "correct_answer": "自我调节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我自我调节了电视的音量。", "explanation": "这里应该用〈调小〉。自我调节只用于人调整自身状态，电视音量是外部设备，不能说自我调节。"}, {"text": "老师自我调节了学生的情绪。", "explanation": "这里应该用〈安抚〉。自我调节只指自己调整自己，不能用来替别人调整情绪。"}, {"text": "医生自我调节了病人，让他心情好了。", "explanation": "这里应该用〈安慰〉。自我调节的主体是自己，不能用于医生替病人调整心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26646, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自我介绍", "is_correct": false, "explanation": "语义：“自我介绍”是向他人介绍自己，与“花了几天时间”调整心理状态的语境不合。"}, {"text": "自我表扬", "is_correct": false, "explanation": "语义：“表扬”与“失败以后”的语境相反，不能用来描述失败后的心理调整。"}, {"text": "自我满足", "is_correct": false, "explanation": "语义：“满足”表示自得，与“失败以后”的心理调整不合。"}, {"text": "自我调节", "is_correct": true, "explanation": "自我调节指自己调整自己的心情或状态，正对应失败之后的心理恢复。"}], "explanations": {"自我介绍": "语义：“自我介绍”是向他人介绍自己，与“花了几天时间”调整心理状态的语境不合。", "自我表扬": "语义：“表扬”与“失败以后”的语境相反，不能用来描述失败后的心理调整。", "自我满足": "语义：“满足”表示自得，与“失败以后”的心理调整不合。", "自我调节": "自我调节指自己调整自己的心情或状态，正对应失败之后的心理恢复。"}, "sentence_index": 6, "correct_answer": "自我调节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他自我调节了朋友的心情，让朋友开心起来。", "explanation": "这里应该用〈劝慰〉。劝慰是替他人排解情绪，自我调节只指自己调整自己，不能用于替朋友调整心情。"}, {"text": "司机自我调节了座位的高度。", "explanation": "这里应该用〈调整〉。自我调节只用于调整自身状态，座位的高度不属于自身，不能用自我调节。"}, {"text": "教练自我调节了运动员的耐力。", "explanation": "这里应该用〈训练〉。自我调节只指自己调整自己，教练对运动员耐力的提升是外部训练，不能用自我调节。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26646, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我输了比赛，就先被自我调节一下心情。", "corrected_sentence": "我输了比赛，就先自我调节一下心情。", "error_description": "错误：“自我调节”是主动动词，不能加“被”构成被动式。应说“就先自我调节一下心情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26646, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他失败以后，会很自我调节。", "corrected_sentence": "他失败以后，会慢慢自我调节。", "error_description": "错误：“很”是程度副词，不能修饰“自我调节”这类动作。“慢慢”是状语，应说“他失败以后，会慢慢自我调节。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
