INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26648, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指所有年纪不大的人。", "primary_collocate": null, "pronunciation": "nián qīng yí dài", "ipa": "njɛn˧˥ tɕʰiŋ˥˥ i˧˥ taɪ˥˩", "syllable_count": 4, "sentences": [{"text": "这个节目很受年轻一代欢迎。", "target_word": "年轻一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻一代的想法常常很新。", "target_word": "年轻一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里的笑声大多来自年轻一代。", "target_word": "年轻一代", "complexity_tier": "T3", "furigana": "xuéxiào lǐ de xiàoshēng dàduō láizì nián qīng yídài", "sentence_source": "generated"}, {"text": "年轻一代都在用这个新软件。", "target_word": "年轻一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街上的咖啡店是年轻一代常去的地方。", "target_word": "年轻一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在年轻一代每天都很忙。", "target_word": "年轻一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种衣服是专门为年轻一代做的。", "target_word": "年轻一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻一代也很关心社会问题。", "target_word": "年轻一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一本书，讲给年轻一代听。", "target_word": "年轻一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的公园里，经常能看到年轻一代在打球。", "target_word": "年轻一代", "complexity_tier": "T3", "furigana": "zhōumò de gōngyuán lǐ jīngcháng néng kàndào nián qīng yídài zài dǎqiú", "sentence_source": "generated"}], "morphological_forms": [{"form": "年輕一代", "label": "繁体"}], "register": "中性", "sense_fingerprint": "年纪不大的所有人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a60a7be6-0797-43ec-a9b8-273314716fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26648, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年轻一代", "is_correct": true, "explanation": "正确。年轻一代指喜欢这个节目的年轻人群，与「受……欢迎」的语境相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有欣赏能力，不会因节目而受欢迎。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水不是能观看节目的主体，「很受雨水欢迎」无法成立。"}, {"text": "书法", "is_correct": false, "explanation": "搭配：「受……欢迎」的对象应是人群，「书法」是艺术形式，不能与之搭配。"}], "explanations": {"年轻一代": "正确。年轻一代指喜欢这个节目的年轻人群，与「受……欢迎」的语境相符。", "桌子": "语义：桌子没有欣赏能力，不会因节目而受欢迎。", "雨水": "语义：雨水不是能观看节目的主体，「很受雨水欢迎」无法成立。", "书法": "搭配：「受……欢迎」的对象应是人群，「书法」是艺术形式，不能与之搭配。"}, "sentence_index": 0, "correct_answer": "年轻一代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的爷爷今年八十岁，也算是年轻一代。", "explanation": "这里应该用〈老年人〉。年轻一代指年纪不大的人群，八十岁的老人不属于这个群体。"}, {"text": "我们公司新来了一位年轻一代。", "explanation": "这里应该用〈年轻人〉。年轻一代是泛指人群的集体名词，不能用「位」计量单个人。"}, {"text": "他年轻一代时期去过很多国家。", "explanation": "这里应该用〈年轻时期〉。年轻一代指一代人，不表示人生的阶段；说某人年轻时去过哪里，要用〈年轻时期〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26648, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年轻一代", "is_correct": true, "explanation": "正确。年轻一代作「为……做的」的对象，指年轻人群，与「这种衣服」的目标人群相符。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是摆设，不会穿衣服，「专门为花瓶做的衣服」不合常理。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不穿衣服，「专门为石头做的衣服」不合常理。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不穿衣服，不可能是服装的使用对象。"}], "explanations": {"年轻一代": "正确。年轻一代作「为……做的」的对象，指年轻人群，与「这种衣服」的目标人群相符。", "花瓶": "语义：花瓶是摆设，不会穿衣服，「专门为花瓶做的衣服」不合常理。", "石头": "语义：石头不穿衣服，「专门为石头做的衣服」不合常理。", "冰箱": "语义：冰箱不穿衣服，不可能是服装的使用对象。"}, "sentence_index": 6, "correct_answer": "年轻一代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我姐姐是我们家的一个年轻一代，最近很忙。", "explanation": "这里应该用〈年轻人〉。年轻一代是集体概念，不能用「一个」计量单个人。"}, {"text": "这款年轻一代汽车性能很好。", "explanation": "这里应该用〈新一代〉。年轻一代只指人群，不能用来修饰汽车这类产品；说新款汽车应用〈新一代〉。"}, {"text": "我家养了两只年轻一代，很可爱。", "explanation": "这里应该用〈小狗〉。年轻一代指年轻人群，不能用来指动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市的一个年轻一代都很爱运动。", "corrected_sentence": "这座城市的年轻一代都很爱运动。", "error_description": "错误在于「一个」：年轻一代是泛指人群的集体名词，前面不能用数量词「一个」计量。正确说法是「这座城市的年轻一代」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小区的三个年轻一代都很努力。", "corrected_sentence": "这个小区的年轻一代都很努力。", "error_description": "错误在于「三个」：年轻一代是泛指人群的集体名词，不能用数量词「三个」计量单个人。正确说法是「这个小区的年轻一代」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
