INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26650, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "家乡，自己出生的地方。", "primary_collocate": null, "pronunciation": "xiāng tǔ", "ipa": "ɕiɑŋ˥ tʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "他离开乡土已经二十年了。", "target_word": "乡土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无论走到哪里，他都忘不了乡土。", "target_word": "乡土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，乡土是他出生的地方。", "target_word": "乡土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在国外读书，常常想念乡土。", "target_word": "乡土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节时，许多在外打工的人都思念乡土。", "target_word": "乡土", "complexity_tier": "T3", "furigana": "chūnjié shí xǔduō zài wài dǎgōng de rén dōu sīniàn xiāngtǔ", "sentence_source": "generated"}, {"text": "这首歌让他想起了遥远的乡土。", "target_word": "乡土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生都没有离开过乡土。", "target_word": "乡土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年纪大了，他越来越想回到乡土。", "target_word": "乡土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把与乡土有关的照片挂在墙上。", "target_word": "乡土", "complexity_tier": "T3", "furigana": "tā bǎ yǔ xiāngtǔ yǒuguān de zhàopiàn guà zài qiángshang", "sentence_source": "generated"}, {"text": "离开乡土多年，他还是说着家乡话。", "target_word": "乡土", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "鄉土", "label": "繁体"}], "register": "书面", "sense_fingerprint": "自己出生的家乡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a60a7be6-0797-43ec-a9b8-273314716fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26650, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乡土", "is_correct": true, "explanation": "正确。「离开乡土已经二十年了」指离开自己出生的家乡，与语境相符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：「离开」后接手机不合常理，人不会因为「离开手机」而计算二十年。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无处不在，「离开空气已经二十年」不能成立。"}, {"text": "星期", "is_correct": false, "explanation": "配价：「离开」后接的应是处所或地方，「星期」是时间词，不能充当宾语。"}], "explanations": {"乡土": "正确。「离开乡土已经二十年了」指离开自己出生的家乡，与语境相符。", "手机": "语义：「离开」后接手机不合常理，人不会因为「离开手机」而计算二十年。", "空气": "语义：空气无处不在，「离开空气已经二十年」不能成立。", "星期": "配价：「离开」后接的应是处所或地方，「星期」是时间词，不能充当宾语。"}, "sentence_index": 0, "correct_answer": "乡土"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他毕业后用乡土付了房租。", "explanation": "这里应该用〈钱〉。乡土指家乡，不能用来付房租这类款项。"}, {"text": "他是我的乡土，常来我家玩。", "explanation": "这里应该用〈老乡〉。乡土指家乡这个地方，不指同乡的人。"}, {"text": "他把乡土切成三片，放进了冰箱。", "explanation": "这里应该用〈面包〉。乡土指自己出生的家乡，不是可以切开放进冰箱的食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26650, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乡土", "is_correct": true, "explanation": "正确。「一生都没有离开过乡土」指一辈子没有离开家乡，与语境相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不能被「离开过」，句子不合常理。"}, {"text": "时间", "is_correct": false, "explanation": "配价：「离开过」后接的应是地方，「时间」不能作为「离开」的宾语。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调是电器，人不会「离开过空调」，句子不成立。"}], "explanations": {"乡土": "正确。「一生都没有离开过乡土」指一辈子没有离开家乡，与语境相符。", "冰箱": "语义：冰箱是家电，不能被「离开过」，句子不合常理。", "时间": "配价：「离开过」后接的应是地方，「时间」不能作为「离开」的宾语。", "空调": "语义：空调是电器，人不会「离开过空调」，句子不成立。"}, "sentence_index": 6, "correct_answer": "乡土"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤的乡土很鲜美。", "explanation": "这里应该用〈味道〉。乡土指家乡这个地方，不能用来形容食物的味道。"}, {"text": "这次考试，他的乡土考得很好。", "explanation": "乡土是地方概念，不能作为考试的主语；这里应该用〈他〉。"}, {"text": "这张桌子是乡土，很结实。", "explanation": "这里应该用〈家具〉。乡土指自己出生的家乡，不指家具这类物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很久没有回到乡土这片，心里很想念。", "corrected_sentence": "他很久没有回到乡土，心里很想念。", "error_description": "错误在于「这片」位置：指示量词短语须放在名词前，且「回到乡土」已明确地点，「这片」后置既不合语法又多余；去掉即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小时候从来没有离开了乡土。", "corrected_sentence": "他小时候从来没有离开过乡土。", "error_description": "错误在于「了」：「没有」否定过去的经历时不能与「了」同用，表示经历应用「过」：「从来没有离开过乡土」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
