INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26652, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用相机或手机把画面记下来。", "primary_collocate": null, "pronunciation": "pāi shè", "ipa": "pʰaɪ̯˥ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "他用手机拍摄了一段日落的视频。", "target_word": "拍摄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要在博物馆里拍摄展品。", "target_word": "拍摄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影在云南拍摄，风景很美。", "target_word": "拍摄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想拍摄一张全家人的照片。", "target_word": "拍摄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摄影师正在拍摄新娘的婚纱照。", "target_word": "拍摄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们花了三个月拍摄这部纪录片。", "target_word": "拍摄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无人机从天上拍摄了整座城市。", "target_word": "拍摄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们对着镜头笑，妈妈在旁边拍摄。", "target_word": "拍摄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片是去年春天在公园拍摄的。", "target_word": "拍摄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导演要求大家安静，现在开始拍摄。", "target_word": "拍摄", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拍摄了", "label": "完成体"}, {"form": "拍摄过", "label": "经历体"}, {"form": "拍摄着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "拍摄：用相机或手机记录画面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b44a80eb-78df-43d2-b3b5-0ae745060986') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26652, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拍摄", "is_correct": true, "explanation": "正确：“拍摄”指用手机记录画面，与“用手机”和“视频”搭配。"}, {"text": "熨", "is_correct": false, "explanation": "语义：“熨”是用熨斗烫平衣物，与用手机记录画面无关。"}, {"text": "浇", "is_correct": false, "explanation": "搭配：“浇”多用于液体，不能说“浇视频”。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热食物，不能用于手机记录画面。"}], "explanations": {"拍摄": "正确：“拍摄”指用手机记录画面，与“用手机”和“视频”搭配。", "熨": "语义：“熨”是用熨斗烫平衣物，与用手机记录画面无关。", "浇": "搭配：“浇”多用于液体，不能说“浇视频”。", "煮": "语义：“煮”是加热食物，不能用于手机记录画面。"}, "sentence_index": 0, "correct_answer": "拍摄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在录音室拍摄了一首歌。", "explanation": "这里应该用〈录制〉。拍摄只用于记录画面，录音只能说〈录制〉。"}, {"text": "他用手拍摄了我的肩膀。", "explanation": "这里是“用手轻拍”的意思，应该用〈拍打〉。拍摄只用于记录画面，不表示打。"}, {"text": "老师拍摄了一个问题。", "explanation": "拍摄的对象必须是能被记录画面的人或景物，“问题”不能拍摄，这里应该用〈解答〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26652, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拍摄", "is_correct": true, "explanation": "正确：“拍摄”指用无人机记录画面，能够用来说拍下整座城市。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”需要咬住具体的东西，“咬了整座城市”不通。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”是加热食物，与无人机和城市无关。"}, {"text": "刷", "is_correct": false, "explanation": "搭配：“刷”用于清洁或涂抹，不能用来记录城市画面。"}], "explanations": {"拍摄": "正确：“拍摄”指用无人机记录画面，能够用来说拍下整座城市。", "咬": "搭配：“咬”需要咬住具体的东西，“咬了整座城市”不通。", "烤": "语义：“烤”是加热食物，与无人机和城市无关。", "刷": "搭配：“刷”用于清洁或涂抹，不能用来记录城市画面。"}, "sentence_index": 6, "correct_answer": "拍摄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电影院每晚都拍摄老电影。", "explanation": "这里应该用〈放映〉。电影院播放电影要说〈放映〉，拍摄是记录画面。"}, {"text": "他用斧头拍摄了木头。", "explanation": "这里应该用〈劈〉。拍摄只能记录画面，不能表示用斧头砍木头。"}, {"text": "这幅古画去年被拍摄出了八十万元。", "explanation": "这里应该用〈拍卖〉。拍卖是把东西卖出高价，拍摄只指记录画面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26652, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用手机拍摄了一本视频。", "corrected_sentence": "他用手机拍摄了一段视频。", "error_description": "量词错误：“视频”应用“段”计量，不能用“本”（“本”用于书籍）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26652, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们正在拍摄了纪录片。", "corrected_sentence": "他们正在拍摄纪录片。", "error_description": "“正在”表示动作正在进行，不能与“了”同用。应说“正在拍摄纪录片”，不能说“正在拍摄了纪录片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
