INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26656, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "把真实的人、地方或事情拍下来，给大家看的电影或电视节目。", "primary_collocate": null, "pronunciation": "jì lù piàn", "ipa": "tɕi˥˩ lu˥˩ pʰiɛn˥˩", "syllable_count": 3, "sentences": [{"text": "电视里正在播放一部纪录片。", "target_word": "纪录片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最爱看讲美食的纪录片。", "target_word": "纪录片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部纪录片带我们走进了小山村。", "target_word": "纪录片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们看完纪录片，知道了海洋动物的生活。", "target_word": "纪录片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部纪录片里没有演员，都是真实的人。", "target_word": "纪录片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每晚都看一个小时纪录片。", "target_word": "纪录片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的网站上有很多免费的纪录片。", "target_word": "纪录片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部纪录片把老工人的故事拍了下来。", "target_word": "纪录片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我推荐你看这部关于长城的纪录片。", "target_word": "纪录片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们拍了一部纪录片，介绍自己的城市。", "target_word": "纪录片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "紀錄片", "label": "繁体"}, {"form": "纪录片导演", "label": "复合"}], "register": "中性", "sense_fingerprint": "拍下真实人事、供人观看的电影或电视节目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a60a7be6-0797-43ec-a9b8-273314716fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26656, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纪录片", "is_correct": true, "explanation": "正确。“电视里正在播放”的影视节目，“一部纪录片”指这类作品。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：“播放”用于影视、音像节目，不说“播放一部小说”。"}, {"text": "词典", "is_correct": false, "explanation": "搭配：“词典”不是影音节目，不能“播放”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是电子设备，不是可以在电视里播放的节目。"}], "explanations": {"纪录片": "正确。“电视里正在播放”的影视节目，“一部纪录片”指这类作品。", "小说": "搭配：“播放”用于影视、音像节目，不说“播放一部小说”。", "词典": "搭配：“词典”不是影音节目，不能“播放”。", "手机": "语义：“手机”是电子设备，不是可以在电视里播放的节目。"}, "sentence_index": 0, "correct_answer": "纪录片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部纪录片里的小猫会说话。", "explanation": "这里应该用〈动画片〉。纪录片拍的是真实的人和事，不能有会说话的小猫这类虚构内容。"}, {"text": "这部纪录片讲了一个英雄打败怪兽的故事。", "explanation": "这里应该用〈奇幻片〉。纪录片拍的是真实的人和事，英雄打败怪兽的故事属于虚构的奇幻题材。"}, {"text": "这部纪录片的主角一脚就能踢飞一辆汽车。", "explanation": "这里应该用〈武打片〉。纪录片拍的是真实的人和事，一脚踢飞汽车的情节属于虚构的武打片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纪录片", "is_correct": true, "explanation": "正确。“学校的网站上有很多免费的”指免费提供的影视作品，“纪录片”与之相符。"}, {"text": "出租车", "is_correct": false, "explanation": "语义：“出租车”是交通工具，不会在网站上免费提供。"}, {"text": "房产", "is_correct": false, "explanation": "搭配：“免费的”一般不修饰“房产”这类需要交易的财产，此处不通顺。"}, {"text": "轮船", "is_correct": false, "explanation": "语义：“轮船”是交通工具，与网站上的免费内容无关。"}], "explanations": {"纪录片": "正确。“学校的网站上有很多免费的”指免费提供的影视作品，“纪录片”与之相符。", "出租车": "语义：“出租车”是交通工具，不会在网站上免费提供。", "房产": "搭配：“免费的”一般不修饰“房产”这类需要交易的财产，此处不通顺。", "轮船": "语义：“轮船”是交通工具，与网站上的免费内容无关。"}, "sentence_index": 6, "correct_answer": "纪录片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部纪录片是一场足球比赛的直播。", "explanation": "这里应该用〈直播〉。纪录片是拍摄后编辑播出的作品，不是正在进行的比赛直播。"}, {"text": "这部纪录片的主角是一个从未来穿越来的机器人。", "explanation": "这里应该用〈科幻片〉。纪录片拍的是真实的人和事，从未来穿越来的机器人属于虚构的科幻题材。"}, {"text": "这部纪录片的结尾，女主角突然变成了一只蝴蝶。", "explanation": "这里应该用〈童话〉。纪录片拍的是真实的人和事，女主角变成蝴蝶属于虚构的童话情节。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学校今天放了一本纪录片。", "corrected_sentence": "我们学校今天放了一部纪录片。", "error_description": "量词错误：「纪录片」是影视作品，应用量词「部」；「本」用于书籍，不能用来计量它。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一部关于长城纪录片。", "corrected_sentence": "这是一部关于长城的纪录片。", "error_description": "结构错误：修饰名词“纪录片”的“关于长城”后面要加“的”，漏掉“的”就不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
