INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26658, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "觉得自己和别人或事情一样，心里觉得好。", "primary_collocate": null, "pronunciation": "rèn tóng gǎn", "ipa": "ɻən˥˩ tʰʊŋ˧˥ kan˨˩˦", "syllable_count": 3, "sentences": [{"text": "听到别人也这样想，他很有认同感。", "target_word": "认同感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的看法一样，让她有了认同感。", "target_word": "认同感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读到这篇文章，我心里有很强的认同感。", "target_word": "认同感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说出了我的想法，我立刻有认同感。", "target_word": "认同感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话让我产生了认同感。", "target_word": "认同感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看这部电影时，很多人有认同感。", "target_word": "认同感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她讲的那段经历，让我很有认同感。", "target_word": "认同感", "complexity_tier": "T3", "furigana": "tā jiǎng de nà duàn jīnglì, ràng wǒ hěn yǒu rèn tóng gǎn", "sentence_source": "generated"}, {"text": "我们都爱吃辣，聊天时有认同感。", "target_word": "认同感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的经历相似，所以彼此有认同感。", "target_word": "认同感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了她的故事，我心里有了认同感。", "target_word": "认同感", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "認同感", "label": "繁体"}, {"form": "强烈认同感", "label": "复合"}], "register": "中性", "sense_fingerprint": "与别人想法相同而产生的愉快感受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a60a7be6-0797-43ec-a9b8-273314716fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26658, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "认同感", "is_correct": true, "explanation": "正确。“听到别人也这样想”说明与人想法一致而愉快，“很有认同感”与语境相符。"}, {"text": "分歧", "is_correct": false, "explanation": "语义：“分歧”指意见不合，与“别人也这样想”的一致正相矛盾。"}, {"text": "敌意", "is_correct": false, "explanation": "语义：“敌意”表示对立的恶意，与“也这样想”所体现的认同不符。"}, {"text": "利润", "is_correct": false, "explanation": "语义：「利润」是经济收益，与「听到别人也这样想」的心理感受无关，句子不通。"}], "explanations": {"认同感": "正确。“听到别人也这样想”说明与人想法一致而愉快，“很有认同感”与语境相符。", "分歧": "语义：“分歧”指意见不合，与“别人也这样想”的一致正相矛盾。", "敌意": "语义：“敌意”表示对立的恶意，与“也这样想”所体现的认同不符。", "利润": "语义：「利润」是经济收益，与「听到别人也这样想」的心理感受无关，句子不通。"}, "sentence_index": 0, "correct_answer": "认同感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到噩耗，她很有认同感。", "explanation": "这里应该用〈震惊〉。认同感指觉得自己与别人想法一致、心里觉得好，听到噩耗的反应要用“震惊”。"}, {"text": "夜里听到敲门声，他很有认同感。", "explanation": "这里应该用〈害怕〉。认同感表示想法一致而心里觉得好，夜里被敲门声吓到要用“害怕”。"}, {"text": "被老板批评后，他很有认同感。", "explanation": "这里应该用〈沮丧〉。认同感表示想法一致而心里觉得好，被批评后的低落要用“沮丧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26658, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "认同感", "is_correct": true, "explanation": "正确。“她讲的那段经历”让我产生与她相似的感受，“很有认同感”与语境相符。"}, {"text": "仇恨", "is_correct": false, "explanation": "语义：“仇恨”是强烈的敌对情绪，与听到别人经历后的共鸣不符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」是买卖中的数额，与「她讲的经历」引起的共鸣无关，句子不通。"}, {"text": "偏见", "is_correct": false, "explanation": "语义：“偏见”指固执的成见，与“她讲的经历”引起的理解和共鸣相反。"}], "explanations": {"认同感": "正确。“她讲的那段经历”让我产生与她相似的感受，“很有认同感”与语境相符。", "仇恨": "语义：“仇恨”是强烈的敌对情绪，与听到别人经历后的共鸣不符。", "价格": "语义：「价格」是买卖中的数额，与「她讲的经历」引起的共鸣无关，句子不通。", "偏见": "语义：“偏见”指固执的成见，与“她讲的经历”引起的理解和共鸣相反。"}, "sentence_index": 6, "correct_answer": "认同感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "考试没考好，他很有认同感。", "explanation": "这里应该用〈失望〉。认同感指想法一致时的愉快，考试失利后的心情要用“失望”。"}, {"text": "看到朋友成功，他很有认同感。", "explanation": "这里应该用〈羡慕〉。认同感表示想法一致，别人成功时的心情要用“羡慕”。"}, {"text": "在大家面前出丑，他很有认同感。", "explanation": "这里应该用〈尴尬〉。认同感表示想法一致而心里觉得好，当众出丑的窘迫要用“尴尬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26658, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到这个观点，我心里有一块认同感。", "corrected_sentence": "听到这个观点，我心里有一种认同感。", "error_description": "量词错误：“认同感”是抽象的心理感受，应说“一种认同感”；“一块”用于有形的块状物，不能修饰它。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26658, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我他的观点很有认同感。", "corrected_sentence": "我对他的观点很有认同感。", "error_description": "介词错误：认同感要指向对象时，需用介词“对”引出，应说“对他的观点很有认同感”，漏掉“对”句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
