INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26660, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "意思是方向或顺序换了一下。", "primary_collocate": null, "pronunciation": "fǎn guò lái", "ipa": "fan˨˩ kwɔ˥˩ laɪ˧˥", "syllable_count": 3, "sentences": [{"text": "这张图放反了，请你反过来看。", "target_word": "反过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这本书反过来放，封面朝下。", "target_word": "反过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "名字写反了，要反过来读。", "target_word": "反过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这两个字反过来，意思就不一样了。", "target_word": "反过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子反过来放在桌上，水就流出来了。", "target_word": "反过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把衣服反过来穿了。", "target_word": "反过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把队伍反过来排，矮的站前面。", "target_word": "反过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸反过来看，字就倒了。", "target_word": "反过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先说结果再说原因，也可以反过来说。", "target_word": "反过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把纸条反过来，看到后面有字。", "target_word": "反过来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反過來", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把方向、顺序或朝向翻转一下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c74c4ae1-9515-4459-b540-8770b8d0940f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26660, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "照常", "is_correct": false, "explanation": "语义：“照常”表示按平常方式进行，与“放反了”需要改变方向的语境相矛盾。"}, {"text": "反过来", "is_correct": true, "explanation": "反过来表示把方向翻转，正对应“放反了”，请人把图转过来看。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示故意违背期望，句中没有这样的对立语境。"}, {"text": "一直", "is_correct": false, "explanation": "体貌：“一直”表示持续不断，与一次性的翻转动作不符。"}], "explanations": {"照常": "语义：“照常”表示按平常方式进行，与“放反了”需要改变方向的语境相矛盾。", "反过来": "反过来表示把方向翻转，正对应“放反了”，请人把图转过来看。", "偏偏": "语义：“偏偏”表示故意违背期望，句中没有这样的对立语境。", "一直": "体貌：“一直”表示持续不断，与一次性的翻转动作不符。"}, "sentence_index": 0, "correct_answer": "反过来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去超市买了牛奶，反过来借了一把雨伞。", "explanation": "这里应该用〈顺便〉。顺便表示附带做的事；反过来表示方向或顺序的翻转，买牛奶与借雨伞之间没有翻转关系。"}, {"text": "我买了一条鱼，反过来煮了一锅汤。", "explanation": "这里应该用〈接着〉。接着表示紧接着做下一件事；反过来表示方向或顺序的翻转，买鱼与煮汤之间没有翻转关系。"}, {"text": "他下楼去买菜，反过来写了一封信。", "explanation": "这里应该用〈另外〉。另外表示再做一件事；反过来表示方向或顺序的翻转，下楼买菜与写信之间没有翻转关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26660, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同时", "is_correct": false, "explanation": "语义：“同时”表示并列发生，与“矮的站前面”所要求的先后排列不合。"}, {"text": "反过来", "is_correct": true, "explanation": "反过来表示顺序翻转，把队伍颠倒排列，与“矮的站前面”的新排法相符。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示完成，与“请把……排”这一尚未发生的指令矛盾。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，与有计划的排队安排不合。"}], "explanations": {"同时": "语义：“同时”表示并列发生，与“矮的站前面”所要求的先后排列不合。", "反过来": "反过来表示顺序翻转，把队伍颠倒排列，与“矮的站前面”的新排法相符。", "已经": "体貌：“已经”表示完成，与“请把……排”这一尚未发生的指令矛盾。", "忽然": "语义：“忽然”表示突然发生，与有计划的排队安排不合。"}, "sentence_index": 6, "correct_answer": "反过来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小红去了超市，反过来买了一本书。", "explanation": "这里应该用〈另外〉。另外表示再做一件事；反过来表示方向或顺序的翻转，去超市与买书之间没有翻转关系。"}, {"text": "我洗完澡，反过来写了作业。", "explanation": "这里应该用〈然后〉。然后表示接着做下一件事；反过来表示方向或顺序的翻转，洗澡与写作业之间没有翻转关系。"}, {"text": "妈妈在厨房做饭，反过来看起了电视。", "explanation": "这里应该用〈于是〉。于是表示因此接着做某事；反过来表示方向或顺序的翻转，做饭与看电视之间没有翻转关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26660, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "碗放反了，你把它反过来的放。", "corrected_sentence": "碗放反了，你把它反过来放。", "error_description": "错误：“反过来”后面不能加“的”。它是状语，直接修饰动词“放”，不带“的”，正确说法是“把它反过来放”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26660, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把相框反来过看，后面写着日期。", "corrected_sentence": "他把相框反过来看，后面写着日期。", "error_description": "错误：词序不对。“反过来”是固定的说法，不能说成“反来过”。正确说法是“他把相框反过来看”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
