INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26662, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "你说的话。", "primary_collocate": null, "pronunciation": "huà yǔ", "ipa": "xwa˥˩ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "你的话语我都记在心里。", "target_word": "话语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到你的话语，他很生气。", "target_word": "话语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不明白你刚才的话语是什么意思。", "target_word": "话语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的话语让我很感动。", "target_word": "话语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的话语让大家都笑了。", "target_word": "话语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要为自己的话语负责。", "target_word": "话语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我很喜欢你温柔的话语。", "target_word": "话语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "朋友，你的话语给了我力量。", "target_word": "话语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的话语里有很多关心。", "target_word": "话语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她很认真地听你的话语。", "target_word": "话语", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "话语权", "label": "复合"}, {"form": "話語", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对方所说的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13188d60-d15b-49e9-baa3-e9e2c11c9219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26662, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "话语", "is_correct": true, "explanation": "话语指你说的话。"}, {"text": "华语", "is_correct": false, "explanation": "huà（第四声）与 huá（第二声）声调不同，华语指华人使用的汉语。"}, {"text": "花语", "is_correct": false, "explanation": "huà（第四声）与 huā（第一声）声调不同，花语指花所代表的寓意。"}, {"text": "花雨", "is_correct": false, "explanation": "huà（第四声）与 huā（第一声）声调不同，花雨指花瓣像雨一样落下。"}], "explanations": {"话语": "话语指你说的话。", "华语": "huà（第四声）与 huá（第二声）声调不同，华语指华人使用的汉语。", "花语": "huà（第四声）与 huā（第一声）声调不同，花语指花所代表的寓意。", "花雨": "huà（第四声）与 huā（第一声）声调不同，花雨指花瓣像雨一样落下。"}, "sentence_index": null, "correct_answer": "话语"}, "level_3": {"options": [{"text": "话语", "is_correct": true, "explanation": "话语指你说的话，「记在心里」多用于话语、教导一类内容，与句意相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被「记在心里」，与句意相悖。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：「记在心里」通常接话语或教导，「课本」不搭配。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，不能被「记在心里」。"}], "explanations": {"话语": "话语指你说的话，「记在心里」多用于话语、教导一类内容，与句意相合。", "天气": "语义：天气不能被「记在心里」，与句意相悖。", "课本": "搭配：「记在心里」通常接话语或教导，「课本」不搭配。", "沙发": "语义：沙发是家具，不能被「记在心里」。"}, "sentence_index": 0, "correct_answer": "话语"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间房子的话语很大。", "explanation": "这里应该用〈面积〉。话语指说出的话，不指空间的大小；房子的大小要用面积。"}, {"text": "这台电脑的话语很快。", "explanation": "这里应该用〈速度〉。话语指说出的话，不指运行快慢；电脑的快慢要用速度。"}, {"text": "这块石头的话语很重。", "explanation": "这里应该用〈重量〉。话语指说出的话，不指物体的轻重；石头的轻重要用重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa21c3ca-db0c-4672-952f-90452429b298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26662, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "话语", "is_correct": true, "explanation": "话语指人说的话，「温柔的话语」指说话的方式，与句意相合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：「温柔」不修饰石头，句中指人的言语。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不具备「温柔」的性质，句子说的是人的言语。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：「温柔的饭菜」不成立，「温柔」一般用来形容人的说话方式。"}], "explanations": {"话语": "话语指人说的话，「温柔的话语」指说话的方式，与句意相合。", "石头": "语义：「温柔」不修饰石头，句中指人的言语。", "电脑": "语义：电脑不具备「温柔」的性质，句子说的是人的言语。", "饭菜": "搭配：「温柔的饭菜」不成立，「温柔」一般用来形容人的说话方式。"}, "sentence_index": 6, "correct_answer": "话语"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯咖啡的话语很香。", "explanation": "这里应该用〈味道〉。话语指说出的话，不能用来形容饮品的气味。"}, {"text": "这块布的话语很鲜艳。", "explanation": "这里应该用〈颜色〉。话语不指物体的颜色，形容颜色要用颜色。"}, {"text": "这只小猫的话语很可爱。", "explanation": "这里应该用〈叫声〉。话语指人说的话，小猫的叫声不能说成话语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa21c3ca-db0c-4672-952f-90452429b298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你的一朵话语让我很感动。", "corrected_sentence": "你的一句话语让我很感动。", "error_description": "「话语」的量词应为「句」，不能用「朵」；「朵」多用于花。应说「一句话语」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa21c3ca-db0c-4672-952f-90452429b298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你话语总是让我安心。", "corrected_sentence": "你的话语总是让我安心。", "error_description": "定语「你」与「话语」之间要用「的」，应说「你的话语」，不说「你话语」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa21c3ca-db0c-4672-952f-90452429b298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
