INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26664, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "农民耕田、种庄稼的劳动。", "primary_collocate": null, "pronunciation": "nóng gēng", "ipa": "nʊŋ˧˥ kɤŋ˥", "syllable_count": 2, "sentences": [{"text": "农民每天都在为农耕忙碌。", "target_word": "农耕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农耕让他们有饭吃。", "target_word": "农耕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们也向大人学农耕。", "target_word": "农耕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨以后，农耕可以开始了。", "target_word": "农耕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农耕很辛苦，夏天太阳又大。", "target_word": "农耕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家不种田，不懂农耕。", "target_word": "农耕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "从事农耕的人早上起得很早。", "target_word": "农耕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人说农耕要看天气。", "target_word": "农耕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想去乡下体验一天农耕。", "target_word": "农耕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农耕离不开水和土地。", "target_word": "农耕", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "农耕文化", "label": "复合"}, {"form": "農耕", "label": "繁体"}], "register": "书面", "sense_fingerprint": "耕田种地的农业劳动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13188d60-d15b-49e9-baa3-e9e2c11c9219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26664, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "农耕", "is_correct": true, "explanation": "农耕指农民在田里从事的耕种劳动，与「农民」「每天忙碌」相合。"}, {"text": "考试", "is_correct": false, "explanation": "语义：句中的主语是农民，农民每天为考试忙碌与语境不符。"}, {"text": "股票", "is_correct": false, "explanation": "语义：「农民每天在田里」的语境与股票市场无关。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：「为……忙碌」后接「钢琴」不成立，「钢琴」不能与「忙碌」组成这样的短语。"}], "explanations": {"农耕": "农耕指农民在田里从事的耕种劳动，与「农民」「每天忙碌」相合。", "考试": "语义：句中的主语是农民，农民每天为考试忙碌与语境不符。", "股票": "语义：「农民每天在田里」的语境与股票市场无关。", "钢琴": "搭配：「为……忙碌」后接「钢琴」不成立，「钢琴」不能与「忙碌」组成这样的短语。"}, "sentence_index": 0, "correct_answer": "农耕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个县的农耕特别爱笑。", "explanation": "这里应该用〈居民〉。农耕是耕种的活动，不会笑；说一个县里的人爱笑要用居民。"}, {"text": "农场的农耕有五十亩。", "explanation": "这里应该用〈耕地〉。农耕指耕种活动，不指土地，说有多少亩要用耕地。"}, {"text": "他的农耕比我还高。", "explanation": "这里应该用〈个子〉。农耕是耕种的活动，不指人的身高；说人的高矮要用个子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa21c3ca-db0c-4672-952f-90452429b298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26664, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "农耕", "is_correct": true, "explanation": "农耕指耕种土地、栽培作物的农业劳动，与「早上起得很早」相合。"}, {"text": "夜生活", "is_correct": false, "explanation": "语义：从事夜生活的人通常晚睡，与「早上起得很早」相矛盾。"}, {"text": "深夜", "is_correct": false, "explanation": "搭配：「从事」后不能接「深夜」这样的时间词，搭配不成立。"}, {"text": "酒吧", "is_correct": false, "explanation": "语义：酒吧的工作多在夜间，与「早上起得很早」的语境相悖。"}], "explanations": {"农耕": "农耕指耕种土地、栽培作物的农业劳动，与「早上起得很早」相合。", "夜生活": "语义：从事夜生活的人通常晚睡，与「早上起得很早」相矛盾。", "深夜": "搭配：「从事」后不能接「深夜」这样的时间词，搭配不成立。", "酒吧": "语义：酒吧的工作多在夜间，与「早上起得很早」的语境相悖。"}, "sentence_index": 6, "correct_answer": "农耕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在田里喷了农耕。", "explanation": "这里应该用〈农药〉。农耕是耕种的活动，不是可以喷洒的药剂；喷在田里的东西要用农药。"}, {"text": "玉米地里的农耕长得很高。", "explanation": "这里应该用〈庄稼〉。农耕是耕种的活动，不会生长；地里长出来的玉米要用庄稼。"}, {"text": "他是村里最能干的农耕。", "explanation": "这里应该用〈农民〉。农耕指耕种的活动，不指人；说一个人能干要用农民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa21c3ca-db0c-4672-952f-90452429b298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26664, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一个很农耕的人。", "corrected_sentence": "他是一个很懂农耕的人。", "error_description": "「农耕」是名词，不能直接受「很」修饰；应说「很懂农耕」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa21c3ca-db0c-4672-952f-90452429b298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26664, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们至今还保留着一件传统的农耕。", "corrected_sentence": "他们至今还保留着一种传统的农耕。", "error_description": "「农耕」的量词应为「种」，不能用「件」；应说「一种农耕」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa21c3ca-db0c-4672-952f-90452429b298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
