INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26666, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "写下来的话是这样的。", "primary_collocate": null, "pronunciation": "xiě dào", "ipa": "ɕjɛ˨˩ tau˥˩", "syllable_count": 2, "sentences": [{"text": "他在墙上写道：“请保持安静。”", "target_word": "写道", "complexity_tier": "T3", "furigana": "tā zài qiáng shàng xiědào: “qǐng bǎochí ānjìng.”", "sentence_source": "generated"}, {"text": "有人在牌子上写道：“小心地滑。”", "target_word": "写道", "complexity_tier": "T3", "furigana": "yǒu rén zài páizi shàng xiědào: “xiǎoxīn dì huá.”", "sentence_source": "generated"}, {"text": "书中写道：“知识就是力量。”", "target_word": "写道", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的来信里写道：“我下周回国。”", "target_word": "写道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "课本上写道：“水往低处流。”", "target_word": "写道", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "通知上写道：“明天不用上课。”", "target_word": "写道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "短信里写道：“我已经到家了。”", "target_word": "写道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古书上写道：“人无信不立。”", "target_word": "写道", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她在明信片上写道：“这里的海很蓝。”", "target_word": "写道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那封信上写道：“谢谢你的帮助。”", "target_word": "写道", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "文字、告示或书中写的内容如下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc273de9-6dff-4982-aa1e-b39faa6f353a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26666, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "写道", "is_correct": true, "explanation": "写道：文字写在墙上，内容如下，与“墙上”的语境相符。"}, {"text": "大喊", "is_correct": false, "explanation": "语义：“大喊”是大声叫出来，与“墙上”的书写不符。"}, {"text": "低语", "is_correct": false, "explanation": "语义：“低语”是轻声说话，不能写在墙上。"}, {"text": "吟诵", "is_correct": false, "explanation": "语义：“吟诵”是有节奏地念出声来，属于口头行为，不能“在墙上”进行。"}], "explanations": {"写道": "写道：文字写在墙上，内容如下，与“墙上”的语境相符。", "大喊": "语义：“大喊”是大声叫出来，与“墙上”的书写不符。", "低语": "语义：“低语”是轻声说话，不能写在墙上。", "吟诵": "语义：“吟诵”是有节奏地念出声来，属于口头行为，不能“在墙上”进行。"}, "sentence_index": 0, "correct_answer": "写道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在电话里写道：“我下周回国。”", "explanation": "这里应该用〈说道〉。电话里传达的是口头话语，“写道”表示文字写着如下，不能用于此处。"}, {"text": "他对着人群写道：“我们赢了！”", "explanation": "这里应该用〈呼喊〉。对着人群大声说话是口头的，“写道”指文字写着如下，不能用于此处。"}, {"text": "他站在广场中央大声写道：“我下周回国。”", "explanation": "这里应该用〈大喊〉。大声说出的话是口头的，“写道”表示文字写着如下，不能与“大声”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "写道", "is_correct": true, "explanation": "写道：短信是文字，内容以文字如下呈现，与后面的引文相符。"}, {"text": "呼喊", "is_correct": false, "explanation": "语义：“呼喊”是大声喊出，与短信的文字形式不符。"}, {"text": "朗诵", "is_correct": false, "explanation": "语义：“朗诵”是大声念出来，属于口头行为，短信是文字，不能“朗诵”内容。"}, {"text": "耳语", "is_correct": false, "explanation": "搭配：“耳语”指悄悄说话，不能用于短信这种书面媒介。"}], "explanations": {"写道": "写道：短信是文字，内容以文字如下呈现，与后面的引文相符。", "呼喊": "语义：“呼喊”是大声喊出，与短信的文字形式不符。", "朗诵": "语义：“朗诵”是大声念出来，属于口头行为，短信是文字，不能“朗诵”内容。", "耳语": "搭配：“耳语”指悄悄说话，不能用于短信这种书面媒介。"}, "sentence_index": 6, "correct_answer": "写道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在门口对我写道：“路上小心。”", "explanation": "这里应该用〈嘱咐〉。门口对我说的叮嘱是口头的，“写道”表示文字写着如下，不能用于此处。"}, {"text": "他喃喃写道：“真可惜。”", "explanation": "这里应该用〈说道〉。“喃喃”是低声自语，是口头的，“写道”不能表示此义。"}, {"text": "他朝楼上写道：“快下来。”", "explanation": "这里应该用〈叫道〉。朝楼上叫话是口头的，“写道”指文字写着如下，不能用于此处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在墙上写道了：“请勿喧哗。”", "corrected_sentence": "他在墙上写道：“请勿喧哗。”", "error_description": "错误：“写道”后直接加“了”。“写道”是引出引文的动词，不能带时态助词“了”，应为“写道：”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那封信上写道了：“期待你的回信。”", "corrected_sentence": "那封信上写道：“期待你的回信。”", "error_description": "错误：“写道”后直接加“了”。“写道”是引出引文的动词，不能带时态助词“了”，应为“写道：”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
