INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26672, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "回到自己的家乡。", "primary_collocate": null, "pronunciation": "fǎn xiāng", "ipa": "fan˨˩˦ ɕiɑŋ˥", "syllable_count": 2, "sentences": [{"text": "他工作结束后，马上返乡看父母。", "target_word": "返乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暑假到了，学生们都高高兴兴地返乡。", "target_word": "返乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年纪大了，身体也不太好，所以决定返乡。", "target_word": "返乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出国多年，今年夏天第一次返乡。", "target_word": "返乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节前，很多人坐火车返乡。", "target_word": "返乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带着礼物返乡，家人都很高兴。", "target_word": "返乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说你下周返乡，是真的吗？", "target_word": "返乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司放假三天，同事们都想返乡。", "target_word": "返乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想早点返乡，和家人一起过节。", "target_word": "返乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几年没见，返乡后他发现村子变了。", "target_word": "返乡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "返乡了", "label": "完成体"}, {"form": "返乡过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "回到家乡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13188d60-d15b-49e9-baa3-e9e2c11c9219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26672, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "返乡", "is_correct": true, "explanation": "正确答案。返乡指回到自己的家，读作 fǎn xiāng。"}, {"text": "反响", "is_correct": false, "explanation": "fǎn xiǎng（第三声）与 fǎn xiāng（第一声）只有第二音节声调不同，意思是回声或反应。"}, {"text": "饭香", "is_correct": false, "explanation": "第一音节声调不同（fàn，第四声），意思是饭菜的香味。"}, {"text": "返现", "is_correct": false, "explanation": "fǎn xiàn 与 fǎn xiāng 只有第二音节的韵母不同（an 与 ang），声调也不同，意思是返还现金。"}], "explanations": {"返乡": "正确答案。返乡指回到自己的家，读作 fǎn xiāng。", "反响": "fǎn xiǎng（第三声）与 fǎn xiāng（第一声）只有第二音节声调不同，意思是回声或反应。", "饭香": "第一音节声调不同（fàn，第四声），意思是饭菜的香味。", "返现": "fǎn xiàn 与 fǎn xiāng 只有第二音节的韵母不同（an 与 ang），声调也不同，意思是返还现金。"}, "sentence_index": null, "correct_answer": "返乡"}, "level_3": {"options": [{"text": "上班", "is_correct": false, "explanation": "语义：“上班”指去单位工作，“马上上班看父母”没有逻辑。"}, {"text": "返乡", "is_correct": true, "explanation": "正确答案。“马上返乡看父母”指工作结束后马上回到家里探望父母。"}, {"text": "加班", "is_correct": false, "explanation": "搭配：“加班”是延长工作时间，不能接“看父母”这样的目的。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：“跑步”是运动，与“看父母”的目的不相符。"}], "explanations": {"上班": "语义：“上班”指去单位工作，“马上上班看父母”没有逻辑。", "返乡": "正确答案。“马上返乡看父母”指工作结束后马上回到家里探望父母。", "加班": "搭配：“加班”是延长工作时间，不能接“看父母”这样的目的。", "跑步": "语义：“跑步”是运动，与“看父母”的目的不相符。"}, "sentence_index": 0, "correct_answer": "返乡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "晚饭后，她去公园返乡。", "explanation": "这里应该用〈散步〉。返乡指回到自己的家，去公园只能说“散步”。"}, {"text": "她每天骑车去学校返乡。", "explanation": "这里应该用〈上学〉。返乡指回到自己的家，每天去学校不能用“返乡”，应说“上学”。"}, {"text": "他每天在教室里返乡，认真听讲。", "explanation": "这里应该用〈上课〉。返乡指回到自己的家，在教室里听讲应说“上课”，不能用“返乡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa21c3ca-db0c-4672-952f-90452429b298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26672, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "返乡", "is_correct": true, "explanation": "正确答案。返乡指回到自己的家，读作 fǎn xiāng。"}, {"text": "反向", "is_correct": false, "explanation": "第二音节声调不同（xiàng，第四声），意思是相反的方向。"}, {"text": "翻箱", "is_correct": false, "explanation": "fān（第一声）与 fǎn（第三声）只有声调不同，翻箱指翻动箱子找东西。"}, {"text": "焚香", "is_correct": false, "explanation": "fén xiāng 与 fǎn xiāng 韵母 en 与 an 不同，声调也不同，意思是点燃香料。"}], "explanations": {"返乡": "正确答案。返乡指回到自己的家，读作 fǎn xiāng。", "反向": "第二音节声调不同（xiàng，第四声），意思是相反的方向。", "翻箱": "fān（第一声）与 fǎn（第三声）只有声调不同，翻箱指翻动箱子找东西。", "焚香": "fén xiāng 与 fǎn xiāng 韵母 en 与 an 不同，声调也不同，意思是点燃香料。"}, "sentence_index": null, "correct_answer": "返乡"}, "level_3": {"options": [{"text": "去世", "is_correct": false, "explanation": "语义：“去世”指人死亡，与“听说你下周……是真的吗”的安排不符。"}, {"text": "返乡", "is_correct": true, "explanation": "正确答案。“听说你下周返乡”指下周回到家里，符合语境。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”只能用于新生命的诞生，不能用于已经成年的人的安排。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”是日常休闲，不是需要“听说……是真的吗”去核实的安排，语境说不通。"}], "explanations": {"去世": "语义：“去世”指人死亡，与“听说你下周……是真的吗”的安排不符。", "返乡": "正确答案。“听说你下周返乡”指下周回到家里，符合语境。", "出生": "语义：“出生”只能用于新生命的诞生，不能用于已经成年的人的安排。", "散步": "搭配：“散步”是日常休闲，不是需要“听说……是真的吗”去核实的安排，语境说不通。"}, "sentence_index": 6, "correct_answer": "返乡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去博物馆返乡了一下午。", "explanation": "这里应该用〈参观〉。返乡指回到自己的家，去博物馆只能说“参观”。"}, {"text": "他每天在公司返乡，用电脑写报告。", "explanation": "这里应该用〈上班〉。返乡指回到自己的家，在公司工作应说“上班”，不能用“返乡”。"}, {"text": "我周末去商场返乡。", "explanation": "这里应该用〈购物〉。返乡指回到自己的家，去商场购物不能用“返乡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa21c3ca-db0c-4672-952f-90452429b298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26672, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她去年返乡着看父母。", "corrected_sentence": "她去年返乡看父母。", "error_description": "“返乡着”是错误形式：“着”表示动作的持续或状态，而“返乡”是一次性的动作，不能带“着”。应说“返乡看父母”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa21c3ca-db0c-4672-952f-90452429b298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26672, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来不返乡过。", "corrected_sentence": "他从来没返乡过。", "error_description": "“不返乡过”是错误形式：表示没有某种经历要用“没”，不用“不”。应说“从来没返乡过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa21c3ca-db0c-4672-952f-90452429b298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26674, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "抽象", "is_correct": true, "explanation": "正确。“抽象”与“具象”相对，指不具形象、不能直接感知的，是反义词。"}, {"text": "温和", "is_correct": false, "explanation": "与“具象”无反义关系，“温和”形容性情或气候，与具象、抽象之分无关。"}, {"text": "巨大", "is_correct": false, "explanation": "与“具象”无反义关系，“巨大”形容体积或规模，不与“具象”相对。"}, {"text": "流畅", "is_correct": false, "explanation": "与“具象”无反义关系，“流畅”形容文字或动作，不属于具象与抽象的对立。"}], "correct_answer": "抽象", "explanations": {"抽象": "正确。“抽象”与“具象”相对，指不具形象、不能直接感知的，是反义词。", "温和": "与“具象”无反义关系，“温和”形容性情或气候，与具象、抽象之分无关。", "巨大": "与“具象”无反义关系，“巨大”形容体积或规模，不与“具象”相对。", "流畅": "与“具象”无反义关系，“流畅”形容文字或动作，不属于具象与抽象的对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26674, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "抽象", "is_correct": true, "explanation": "正确。“抽象”与“具象”相对，指不具形象、不能直接感知的，是反义词。"}, {"text": "迟钝", "is_correct": false, "explanation": "与“具象”无反义关系，“迟钝”形容反应慢，与具象、抽象的对立无关。"}, {"text": "粗糙", "is_correct": false, "explanation": "与“具象”无反义关系，“粗糙”形容质地不光滑，不属于具象与抽象的对立。"}, {"text": "轻浮", "is_correct": false, "explanation": "与“具象”无反义关系，“轻浮”形容态度不庄重，与此义项无关。"}], "correct_answer": "抽象", "explanations": {"抽象": "正确。“抽象”与“具象”相对，指不具形象、不能直接感知的，是反义词。", "迟钝": "与“具象”无反义关系，“迟钝”形容反应慢，与具象、抽象的对立无关。", "粗糙": "与“具象”无反义关系，“粗糙”形容质地不光滑，不属于具象与抽象的对立。", "轻浮": "与“具象”无反义关系，“轻浮”形容态度不庄重，与此义项无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26674, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指能直接看到或摸到的东西，不是想象的。", "primary_collocate": null, "pronunciation": "jù xiàng", "ipa": "tɕy˥˩ ɕiɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "苹果是具象的东西，我们可以摸到。", "target_word": "具象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱是抽象的，花是具象的。", "target_word": "具象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友先学具象的东西，再学抽象的。", "target_word": "具象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画是具象的，一看就知道画的是一只猫。", "target_word": "具象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "具象的东西看得见，也摸得到。", "target_word": "具象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词太抽象，请给我一个具象的例子。", "target_word": "具象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子、杯子都是具象的东西。", "target_word": "具象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用具象的图画给孩子讲故事。", "target_word": "具象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具很具象，像真的小狗一样。", "target_word": "具象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学课上，老师用具象的积木教加法。", "target_word": "具象", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "具象化", "label": "复合"}], "register": "中性", "sense_fingerprint": "看得见摸得着、不是凭想象的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc273de9-6dff-4982-aa1e-b39faa6f353a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26674, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "具象", "is_correct": true, "explanation": "正确。具象（jù xiàng）：能直接看到或摸到的东西，不是想象的。"}, {"text": "巨响", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàng（第四声）声调不同，“巨响”意思是很大的响声。"}, {"text": "去向", "is_correct": false, "explanation": "qù 与 jù 声母不同，“去向”意思是去往的方向。"}, {"text": "巨匠", "is_correct": false, "explanation": "jiàng 与 xiàng 声母不同，“巨匠”意思是技艺高超的大师。"}, {"text": "巨量", "is_correct": false, "explanation": "liàng 与 xiàng 声母不同，“巨量”意思是极大的数量。"}], "explanations": {"具象": "正确。具象（jù xiàng）：能直接看到或摸到的东西，不是想象的。", "巨响": "xiǎng（第三声）与 xiàng（第四声）声调不同，“巨响”意思是很大的响声。", "去向": "qù 与 jù 声母不同，“去向”意思是去往的方向。", "巨匠": "jiàng 与 xiàng 声母不同，“巨匠”意思是技艺高超的大师。", "巨量": "liàng 与 xiàng 声母不同，“巨量”意思是极大的数量。"}, "sentence_index": null, "correct_answer": "具象"}, "level_3": {"options": [{"text": "具象", "is_correct": true, "explanation": "正确。“具象的东西”指能直接看见、摸到的事物，与后半句“我们可以摸到”一致。"}, {"text": "抽象", "is_correct": false, "explanation": "语义：“抽象的东西”摸不到，与后半句“我们可以摸到”相矛盾。"}, {"text": "虚幻", "is_correct": false, "explanation": "语义：“虚幻”指不真实的东西，苹果是实物，与“可以摸到”不符。"}, {"text": "遥远", "is_correct": false, "explanation": "搭配：“遥远”多形容距离或时间，不能修饰可以摸到的苹果。"}], "explanations": {"具象": "正确。“具象的东西”指能直接看见、摸到的事物，与后半句“我们可以摸到”一致。", "抽象": "语义：“抽象的东西”摸不到，与后半句“我们可以摸到”相矛盾。", "虚幻": "语义：“虚幻”指不真实的东西，苹果是实物，与“可以摸到”不符。", "遥远": "搭配：“遥远”多形容距离或时间，不能修饰可以摸到的苹果。"}, "sentence_index": 0, "correct_answer": "具象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爱是具象的，我们摸不到。", "explanation": "这里应该用〈抽象〉。“具象”指能看见、摸到的东西，爱是摸不到的，应说“抽象”。"}, {"text": "请给我一个具象的时间。", "explanation": "这里应该用〈具体〉。“具象”指看得见、摸得着的东西，时间不能被看见或摸到，应说“具体的时间”。"}, {"text": "这个道理很具象，我们只能想象。", "explanation": "这里应该用〈抽象〉。“具象”指能直接看到或摸到的东西，道理无法直接看到或摸到，只能想象，应说“抽象”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26674, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "具象", "is_correct": true, "explanation": "正确。桌子、杯子都是能直接看见、摸到的东西，与“具象”的含义相符。"}, {"text": "深奥", "is_correct": false, "explanation": "语义：“深奥”形容道理难懂，无法修饰桌子、杯子这类具体物品。"}, {"text": "辽阔", "is_correct": false, "explanation": "搭配：“辽阔”形容土地或空间，不能修饰桌子、杯子。"}, {"text": "空灵", "is_correct": false, "explanation": "语义：“空灵”指虚无缥缈的意境，与对桌子、杯子等具体物品的描述不符。"}], "explanations": {"具象": "正确。桌子、杯子都是能直接看见、摸到的东西，与“具象”的含义相符。", "深奥": "语义：“深奥”形容道理难懂，无法修饰桌子、杯子这类具体物品。", "辽阔": "搭配：“辽阔”形容土地或空间，不能修饰桌子、杯子。", "空灵": "语义：“空灵”指虚无缥缈的意境，与对桌子、杯子等具体物品的描述不符。"}, "sentence_index": 6, "correct_answer": "具象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇论文的推理很具象。", "explanation": "这里应该用〈严密〉。“具象”指看得见、摸得着的东西，推理是抽象的，不能说“推理很具象”。"}, {"text": "他的感受很具象，大家都能摸到。", "explanation": "这里应该用〈抽象〉。“具象”指能直接看到或摸到的东西，感受是抽象的，不能说“感受很具象”。"}, {"text": "这段话的意思很具象。", "explanation": "这里应该用〈清楚〉。“具象”指能看见、摸到的东西，意思是抽象的，不能说“意思很具象”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师要把这个概念具象。", "corrected_sentence": "老师要把这个概念具象化。", "error_description": "词形错误：使概念变得能看见、摸得着要用“具象化”。“具象”单独作谓语不能带“把”字宾语，应为“具象化”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26674, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈用具象地照片教孩子认识动物。", "corrected_sentence": "妈妈用具象的照片教孩子认识动物。", "error_description": "错误：“具象地照片”。修饰名词“照片”要用“的”，“地”只用来修饰动词，应改为“具象的照片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
