INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26676, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "话就是人说出来让人听到的意思。", "primary_collocate": null, "pronunciation": "huà", "ipa": "xwa˥˩", "syllable_count": 1, "sentences": [{"text": "他的话我听见了，也听懂了。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话是什么意思，你知道吗？", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的话让大家都笑了。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把心里的话告诉你。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把话说完以后，就走了。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王说的话，大家都听得很清楚。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的话我一直记在心里。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请听清楚我下面的话。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的话让我想了很久。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几句话，他说得很慢。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一句话", "label": "量词"}, {"form": "话语", "label": "复合"}, {"form": "对话", "label": "复合"}], "register": "中性", "sense_fingerprint": "说出来让人听的意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b44a80eb-78df-43d2-b3b5-0ae745060986') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26676, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "话", "is_correct": true, "explanation": "正确答案。话（huà）指人说出来让人听到的意思。"}, {"text": "华", "is_correct": false, "explanation": "huá（第二声）与 huà（第四声）声调不同，意思是中华、华丽。"}, {"text": "活", "is_correct": false, "explanation": "huó（第二声）与 huà（第四声）声调不同，意思是活动、生存。"}, {"text": "货", "is_correct": false, "explanation": "huò 与 huà 韵母不同（-o 与 -a），声调相同，意思是货物。"}, {"text": "坏", "is_correct": false, "explanation": "huài 与 huà 韵母不同（-ai 与 -a），意思是坏、不好。"}], "explanations": {"话": "正确答案。话（huà）指人说出来让人听到的意思。", "华": "huá（第二声）与 huà（第四声）声调不同，意思是中华、华丽。", "活": "huó（第二声）与 huà（第四声）声调不同，意思是活动、生存。", "货": "huò 与 huà 韵母不同（-o 与 -a），声调相同，意思是货物。", "坏": "huài 与 huà 韵母不同（-ai 与 -a），意思是坏、不好。"}, "sentence_index": null, "correct_answer": "话"}, "level_3": {"options": [{"text": "话", "is_correct": true, "explanation": "正确。“他的话”指他说出的言语，“听见了，也听懂了”与言语相符。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭不能被“听见”或“听懂”，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是看见的，不是听见的，无法“听见了”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是实物，不能被听见或听懂。"}], "explanations": {"话": "正确。“他的话”指他说出的言语，“听见了，也听懂了”与言语相符。", "饭": "语义：饭不能被“听见”或“听懂”，句意不通。", "颜色": "语义：颜色是看见的，不是听见的，无法“听见了”。", "桌子": "语义：桌子是实物，不能被听见或听懂。"}, "sentence_index": 0, "correct_answer": "话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想把心里的话吃给你。", "explanation": "这里应该用〈告诉〉。话不能吃，表达心里的话要说给对方，应说“告诉”。"}, {"text": "我想把心里的话煮给你。", "explanation": "这里应该用〈告诉〉。话不能煮，表达心里的话应说“告诉”。"}, {"text": "我想把心里的一个话告诉你。", "explanation": "量词错误：话用〈句〉计量，这里不能用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26676, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "话", "is_correct": true, "explanation": "正确答案。话（huà）指人说出来让人听到的意思。"}, {"text": "货", "is_correct": false, "explanation": "huò 与 huà 韵母不同（-o 与 -a），声调相同，意思是货物。"}, {"text": "晃", "is_correct": false, "explanation": "huàng 与 huà 韵母不同（-ang 与 -a），意思是晃动、闪光。"}, {"text": "坏", "is_correct": false, "explanation": "huài 与 huà 韵母不同（-ai 与 -a），意思是坏、不好。"}, {"text": "花", "is_correct": false, "explanation": "huā（第一声）与 huà（第四声）声调不同，意思是花朵。"}], "explanations": {"话": "正确答案。话（huà）指人说出来让人听到的意思。", "货": "huò 与 huà 韵母不同（-o 与 -a），声调相同，意思是货物。", "晃": "huàng 与 huà 韵母不同（-ang 与 -a），意思是晃动、闪光。", "坏": "huài 与 huà 韵母不同（-ai 与 -a），意思是坏、不好。", "花": "huā（第一声）与 huà（第四声）声调不同，意思是花朵。"}, "sentence_index": null, "correct_answer": "话"}, "level_3": {"options": [{"text": "话", "is_correct": true, "explanation": "正确。“奶奶的话”指奶奶说的言语，“记在心里”与言语相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是人说的话，“奶奶的价格”无法记在心里。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能说是“奶奶的”，也不能“记在心里”。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：“记在心里”只用于话语、事情，不能用于行李。"}], "explanations": {"话": "正确。“奶奶的话”指奶奶说的言语，“记在心里”与言语相符。", "价格": "语义：价格不是人说的话，“奶奶的价格”无法记在心里。", "天气": "语义：天气是自然现象，不能说是“奶奶的”，也不能“记在心里”。", "行李": "搭配：“记在心里”只用于话语、事情，不能用于行李。"}, "sentence_index": 6, "correct_answer": "话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这几个话，他说得很慢。", "explanation": "量词错误：话用〈句〉计量，这里应该用“几句”，不能用“几个”。"}, {"text": "这几句话，他弹得很慢。", "explanation": "这里应该用〈曲子〉。弹的是乐曲，话不能弹。"}, {"text": "这几首话，他说得很慢。", "explanation": "量词错误：“首”用于诗歌、歌曲，话应用“句”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你话说清楚。", "corrected_sentence": "请你把话说清楚。", "error_description": "漏掉介词“把”：处置式“把+宾语+动补”要求加“把”，应说“请你把话说清楚”，不能说“请你话说清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你说得话我都记下来了。", "corrected_sentence": "你说的话我都记下来了。", "error_description": "定语标记错误：修饰名词“话”的定语应用“的”，“得”是补语标记，不能说“说得话”，应说“说的话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
