INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26678, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "答应别人要做的事情，就要说到做到。", "primary_collocate": null, "pronunciation": "chéng nuò", "ipa": "ʈʂʰɤŋ˧˥ nuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "他向女儿承诺，周末一定回家。", "target_word": "承诺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府承诺今年建好三所学校。", "target_word": "承诺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我承诺过，不会把秘密告诉别人。", "target_word": "承诺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生承诺会尽力治好病人。", "target_word": "承诺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不能做到的事，就不要随便承诺。", "target_word": "承诺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他承诺还钱，可是一直没有还。", "target_word": "承诺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友承诺借我一辆车。", "target_word": "承诺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理承诺这件事明天就处理好。", "target_word": "承诺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她承诺了很多，却没有做到。", "target_word": "承诺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子承诺每天读半小时书。", "target_word": "承诺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "承诺了", "label": "完成体"}, {"form": "承诺过", "label": "经历体"}, {"form": "承诺书", "label": "复合词"}], "register": "中性", "sense_fingerprint": "答应别人的事就要说到做到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13188d60-d15b-49e9-baa3-e9e2c11c9219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26678, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与后半句“周末一定回家”的许诺口吻相矛盾。"}, {"text": "承诺", "is_correct": true, "explanation": "正确答案。“向女儿承诺”指答应女儿一件事，并表示一定做到。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”带有讥讽意味，与“周末一定回家”的许诺语气不合。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”是休闲动作，不能用于“向女儿……周末一定回家”这样的许诺。"}], "explanations": {"拒绝": "语义：“拒绝”与后半句“周末一定回家”的许诺口吻相矛盾。", "承诺": "正确答案。“向女儿承诺”指答应女儿一件事，并表示一定做到。", "嘲笑": "语义：“嘲笑”带有讥讽意味，与“周末一定回家”的许诺语气不合。", "散步": "搭配：“散步”是休闲动作，不能用于“向女儿……周末一定回家”这样的许诺。"}, "sentence_index": 0, "correct_answer": "承诺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们昨晚在电视上承诺了一场比赛。", "explanation": "这里应该用〈看〉。承诺是答应别人要做到某事，在电视上看比赛不能说承诺。"}, {"text": "他常常承诺过去的那段时光。", "explanation": "这里应该用〈怀念〉。承诺是答应将来要做的事，对过去的时光只能说怀念。"}, {"text": "妈妈每天早上都用布承诺地板。", "explanation": "这里应该用〈擦〉。承诺是答应做到某事，用布清洁地板应说擦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa21c3ca-db0c-4672-952f-90452429b298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26678, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夸奖", "is_correct": false, "explanation": "配价：“夸奖”的宾语是人或成绩，不能直接带“借我一辆车”这样的行为。"}, {"text": "承诺", "is_correct": true, "explanation": "正确答案。“朋友承诺借我一辆车”表示朋友答应借车，并会做到。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”带有讥讽意味，与“借我一辆车”的好意不相符。"}, {"text": "拍卖", "is_correct": false, "explanation": "搭配：“拍卖”指公开卖出物品，不能与“借”连用。"}], "explanations": {"夸奖": "配价：“夸奖”的宾语是人或成绩，不能直接带“借我一辆车”这样的行为。", "承诺": "正确答案。“朋友承诺借我一辆车”表示朋友答应借车，并会做到。", "嘲笑": "语义：“嘲笑”带有讥讽意味，与“借我一辆车”的好意不相符。", "拍卖": "搭配：“拍卖”指公开卖出物品，不能与“借”连用。"}, "sentence_index": 6, "correct_answer": "承诺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶在厨房里承诺饺子。", "explanation": "这里应该用〈包〉。承诺是答应别人要做到某事，做饺子应说包饺子。"}, {"text": "工人承诺了楼下的水管。", "explanation": "这里应该用〈修理〉。承诺是答应做到某事，修好水管应说修理。"}, {"text": "老师在黑板上承诺了几个字。", "explanation": "这里应该用〈写〉。承诺是答应做到某事，在黑板上写字不能用承诺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa21c3ca-db0c-4672-952f-90452429b298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她向老师很承诺，明天一定交作业。", "corrected_sentence": "她向老师承诺，明天一定交作业。", "error_description": "副词误用：「很」不能修饰动词「承诺」，应去掉「很」，说「她向老师承诺」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa21c3ca-db0c-4672-952f-90452429b298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朋友承诺着周末借我一辆车。", "corrected_sentence": "朋友承诺周末借我一辆车。", "error_description": "体标错误：“承诺”表示一次性的许诺，不能带“着”。应去掉“着”，说“朋友承诺周末借我一辆车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa21c3ca-db0c-4672-952f-90452429b298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
