INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26680, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自己能决定自己做什么，不用别人一直告诉。", "primary_collocate": null, "pronunciation": "zì zhǔ xìng", "ipa": "tsɨ˥˩ ʈʂu˨˩˦ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "孩子长大了，我们要培养他的自主性。", "target_word": "自主性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所学校很重视学生的自主性。", "target_word": "自主性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我们很大的自主性。", "target_word": "自主性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作有自主性，我就更愿意努力。", "target_word": "自主性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的自主性很强，什么事都自己决定。", "target_word": "自主性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母管得太多，会影响孩子的自主性。", "target_word": "自主性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏让小朋友有更多自主性。", "target_word": "自主性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给员工一定的自主性，大家都很满意。", "target_word": "自主性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习需要自主性，不能总等老师说。", "target_word": "自主性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想要更多的自主性，不想事事听父母的。", "target_word": "自主性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "自己做决定、不依赖别人指挥的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77bd49ee-81b2-46c0-a146-5020ea436bdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26680, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自主性", "is_correct": true, "explanation": "正确：「培养」的对象是「自主性」这样的品质。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：「身高」是外形特征，不是可以培养的品质。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」是外观，不能被培养。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：「培养」不与「工资」搭配，工资是领取的钱。"}], "explanations": {"自主性": "正确：「培养」的对象是「自主性」这样的品质。", "身高": "体貌：「身高」是外形特征，不是可以培养的品质。", "颜色": "语义：「颜色」是外观，不能被培养。", "工资": "搭配：「培养」不与「工资」搭配，工资是领取的钱。"}, "sentence_index": 0, "correct_answer": "自主性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头的自主性很高，很难切开。", "explanation": "这里应该用〈硬度〉。「硬度」说物体硬不硬，「自主性」是个体自己决定事情的能力，不能用来说石头。"}, {"text": "这条路的自主性很宽。", "explanation": "这里应该用〈宽度〉。「自主性」没有宽窄，路的宽窄应该说「宽度」。"}, {"text": "这块布的自主性很长。", "explanation": "这里应该用〈长度〉。「自主性」没有长短，布的长短应该说「长度」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26680, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自主性", "is_correct": true, "explanation": "正确：「更多自主性」是游戏可以带给孩子的东西，与句意相符。"}, {"text": "美貌", "is_correct": false, "explanation": "体貌：「美貌」指外表，游戏不能让孩子有更多外貌。"}, {"text": "煤炭", "is_correct": false, "explanation": "语义：「煤炭」是燃料，游戏不能带来煤炭。"}, {"text": "作业", "is_correct": false, "explanation": "语义：「作业」是课后的任务，不是游戏能带给孩子的东西。"}], "explanations": {"自主性": "正确：「更多自主性」是游戏可以带给孩子的东西，与句意相符。", "美貌": "体貌：「美貌」指外表，游戏不能让孩子有更多外貌。", "煤炭": "语义：「煤炭」是燃料，游戏不能带来煤炭。", "作业": "语义：「作业」是课后的任务，不是游戏能带给孩子的东西。"}, "sentence_index": 6, "correct_answer": "自主性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的自主性很红。", "explanation": "这里应该用〈颜色〉。「颜色」说东西是红是蓝，「自主性」是自己决定事情的能力，没有颜色。"}, {"text": "他的自主性很圆，像一个球。", "explanation": "这里应该用〈形状〉。「形状」用来说物体的样子，「自主性」是个体自己决定事情的能力，没有形状，不能说圆不圆。"}, {"text": "这堵墙的自主性很厚。", "explanation": "这里应该用〈厚度〉。「自主性」没有厚薄，墙的厚薄应该说「厚度」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26680, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她做事很自主性，从不等别人催。", "corrected_sentence": "她做事很有自主性，从不等别人催。", "error_description": "错误：「很自主性」。正确：「很有自主性」。「自主性」是名词，前面要加动词「有」，「很」才能修饰「有自主性」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26680, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师应该给学生一片自主性。", "corrected_sentence": "老师应该给学生一些自主性。", "error_description": "错误：「一片自主性」。正确：「一些自主性」。「片」用于森林、草地等大片的东西，表示数量的「一些」才适合抽象的特性。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26682, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "软弱", "is_correct": true, "explanation": "软弱与坚韧意义相反，指意志薄弱，遇到困难容易屈服。"}, {"text": "愉快", "is_correct": false, "explanation": "愉快与“坚韧”没有反义关系，指心情好。"}, {"text": "安静", "is_correct": false, "explanation": "安静与“坚韧”没有反义关系，指没有声音或活动。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐与“坚韧”没有反义关系，指排列有序。"}], "correct_answer": "软弱", "explanations": {"软弱": "软弱与坚韧意义相反，指意志薄弱，遇到困难容易屈服。", "愉快": "愉快与“坚韧”没有反义关系，指心情好。", "安静": "安静与“坚韧”没有反义关系，指没有声音或活动。", "整齐": "整齐与“坚韧”没有反义关系，指排列有序。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
