INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26682, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "遇到困难不害怕，一直努力不放弃。", "primary_collocate": null, "pronunciation": "jiān rèn", "ipa": "tɕiɛn˥ ɻən˥˩", "syllable_count": 2, "sentences": [{"text": "工作很累，但他很坚韧，从不说放弃。", "target_word": "坚韧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很坚韧，摔倒了又站起来。", "target_word": "坚韧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想做一个坚韧的人。", "target_word": "坚韧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶很坚韧，再苦也不哭。", "target_word": "坚韧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坚韧的孩子遇到难题不会逃避。", "target_word": "坚韧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她坚韧地学了三年汉语。", "target_word": "坚韧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很坚韧，生病了也坚持学习。", "target_word": "坚韧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛很难，但他很坚韧，没有放弃。", "target_word": "坚韧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师夸我们坚韧，一直在努力。", "target_word": "坚韧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坚韧的人不怕失败。", "target_word": "坚韧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "坚韧不拔", "label": "复合"}], "register": "中性", "sense_fingerprint": "遇到困难不怕、一直努力不放弃", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc273de9-6dff-4982-aa1e-b39faa6f353a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26682, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "坚韧", "is_correct": true, "explanation": "正确。工作累却从不说放弃，正是“坚韧”：遇到困难一直努力。"}, {"text": "脆弱", "is_correct": false, "explanation": "语义：“脆弱”指容易被困难打倒，与“从不说放弃”矛盾。"}, {"text": "抽象", "is_correct": false, "explanation": "搭配：“抽象”说概念或道理，不形容人。"}, {"text": "慵懒", "is_correct": false, "explanation": "语义：“慵懒”指懒散没精神，与“从不说放弃”相反。"}], "explanations": {"坚韧": "正确。工作累却从不说放弃，正是“坚韧”：遇到困难一直努力。", "脆弱": "语义：“脆弱”指容易被困难打倒，与“从不说放弃”矛盾。", "抽象": "搭配：“抽象”说概念或道理，不形容人。", "慵懒": "语义：“慵懒”指懒散没精神，与“从不说放弃”相反。"}, "sentence_index": 0, "correct_answer": "坚韧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的房间很坚韧，每天都打扫得很干净。", "explanation": "这里应该用〈整洁〉。“坚韧”形容面对困难时的忍耐，形容房间干净要用“整洁”。"}, {"text": "他的文章很坚韧，读起来很舒服。", "explanation": "这里应该用〈流畅〉。坚韧形容面对困难时的忍耐，形容文章通顺、读起来顺畅要用流畅。"}, {"text": "他坚韧地摔了门，谁也劝不住。", "explanation": "这里应该用〈愤怒〉。坚韧形容面对困难时的忍耐，摔门这样的激动情绪要用愤怒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26682, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坚韧", "is_correct": true, "explanation": "正确。生病了也坚持学习，说明她遇到困难不放弃，是“坚韧”。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”的人不爱学习，与“坚持学习”矛盾。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容房间等空间，不形容人。"}, {"text": "慌乱", "is_correct": false, "explanation": "语义：“慌乱”指心里乱、没主意，与“坚持学习”的意思不符。"}], "explanations": {"坚韧": "正确。生病了也坚持学习，说明她遇到困难不放弃，是“坚韧”。", "懒惰": "语义：“懒惰”的人不爱学习，与“坚持学习”矛盾。", "宽敞": "搭配：“宽敞”形容房间等空间，不形容人。", "慌乱": "语义：“慌乱”指心里乱、没主意，与“坚持学习”的意思不符。"}, "sentence_index": 6, "correct_answer": "坚韧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议安排得很坚韧，一上午就结束了。", "explanation": "这里应该用〈紧凑〉。坚韧形容面对困难时的忍耐，形容会议安排紧密、节奏快要用紧凑。"}, {"text": "这位老师讲课很坚韧。", "explanation": "这里应该用〈温和〉。坚韧形容面对困难时的忍耐，讲课的态度要用温和。"}, {"text": "消防员坚韧地冲进了火场。", "explanation": "这里应该用〈勇敢〉。坚韧强调承受困难、不放弃，形容冲进危险的行动要用勇敢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我觉得他很坚韧很，不会轻易认输。", "corrected_sentence": "我觉得他很坚韧，不会轻易认输。", "error_description": "错误：“很坚韧很”。“很”修饰形容词只用一次，形容词后多加的“很”应删去，说“很坚韧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父亲用坚韧地态度面对了病痛。", "corrected_sentence": "父亲用坚韧的态度面对了病痛。", "error_description": "错误：“坚韧地态度”。修饰名词“态度”要用“的”，“地”只修饰动词，应改为“坚韧的态度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
