INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26684, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大自然生病了，很危险。", "primary_collocate": null, "pronunciation": "shēng tài wēi jī", "ipa": "ʂɤŋ˥ tʰaɪ˥˩ weɪ˥ tɕi˥", "syllable_count": 4, "sentences": [{"text": "河水变黑，鱼都死了，这是生态危机。", "target_word": "生态危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球正在经历生态危机。", "target_word": "生态危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人担心生态危机越来越严重。", "target_word": "生态危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了生态危机的故事。", "target_word": "生态危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气太脏也是一种生态危机。", "target_word": "生态危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在新闻里看到了生态危机的消息。", "target_word": "生态危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了不让生态危机变严重，我们少用塑料。", "target_word": "生态危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生态危机让很多动物没有水喝。", "target_word": "生态危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们画了一幅关于生态危机的画。", "target_word": "生态危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要一起解决生态危机。", "target_word": "生态危机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场生态危机", "label": "量词"}], "register": "中性", "sense_fingerprint": "大自然出了大问题、很危险的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc273de9-6dff-4982-aa1e-b39faa6f353a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26684, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生态危机", "is_correct": true, "explanation": "正确。河水变黑、鱼死亡说明大自然出现了严重问题，与“生态危机”的含义一致。"}, {"text": "好消息", "is_correct": false, "explanation": "语义：河水变黑、鱼死亡是坏事，不能称为“好消息”。"}, {"text": "美食节", "is_correct": false, "explanation": "语义：句中描述的是污染和死鱼，与美食节无关，不能说“这是美食节”。"}, {"text": "生日派对", "is_correct": false, "explanation": "搭配：“这是”后接“生日派对”，与污染、死鱼的描述不搭配，语境完全不合。"}], "explanations": {"生态危机": "正确。河水变黑、鱼死亡说明大自然出现了严重问题，与“生态危机”的含义一致。", "好消息": "语义：河水变黑、鱼死亡是坏事，不能称为“好消息”。", "美食节": "语义：句中描述的是污染和死鱼，与美食节无关，不能说“这是美食节”。", "生日派对": "搭配：“这是”后接“生日派对”，与污染、死鱼的描述不搭配，语境完全不合。"}, "sentence_index": 0, "correct_answer": "生态危机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片森林的生态危机很健康。", "explanation": "这里应该用〈生态系统〉。“生态危机”指大自然生病的危险状况，不能说“很健康”；形容森林状态健康应说“生态系统”。"}, {"text": "我们正面对一只生态危机。", "explanation": "这里量词应用〈场〉。“只”用于动物等有形个体，“生态危机”是一场局面，不能说“一只”。"}, {"text": "我们要加强生态危机。", "explanation": "这里应该用〈生态保护〉。“加强”的对象是保护工作，“生态危机”是一种状况，不能加强。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26684, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生态危机", "is_correct": true, "explanation": "正确。“变严重”需要负面的环境状况作主语，与“少用塑料”这一环保措施相符。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒与少用塑料无关，减少塑料使用无法阻止感冒变严重。"}, {"text": "蛀牙", "is_correct": false, "explanation": "语义：蛀牙与塑料使用没有因果联系，句中的措施无法影响它。"}, {"text": "考试压力", "is_correct": false, "explanation": "搭配：“考试压力”与“少用塑料”之间缺乏逻辑联系，两者搭配不当。"}], "explanations": {"生态危机": "正确。“变严重”需要负面的环境状况作主语，与“少用塑料”这一环保措施相符。", "感冒": "语义：感冒与少用塑料无关，减少塑料使用无法阻止感冒变严重。", "蛀牙": "语义：蛀牙与塑料使用没有因果联系，句中的措施无法影响它。", "考试压力": "搭配：“考试压力”与“少用塑料”之间缺乏逻辑联系，两者搭配不当。"}, "sentence_index": 6, "correct_answer": "生态危机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要一起保护生态危机。", "explanation": "这里应该用〈生态环境〉。“保护”的对象是环境，“生态危机”是需要解决的状况，不能保护。"}, {"text": "游客们在山里欣赏生态危机。", "explanation": "这里应该用〈自然风光〉。“欣赏”的对象是美景，“生态危机”是令人担忧的状况，不能欣赏。"}, {"text": "我们要提高生态危机。", "explanation": "这里应该用〈环境质量〉。“提高”用于质量、水平，“生态危机”是一种状况，不能提高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26684, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地球正在经历一只严重的生态危机。", "corrected_sentence": "地球正在经历一场严重的生态危机。", "error_description": "量词错误：“生态危机”的量词应为“场”。“只”用于动物等有形个体，不能用来修饰“危机”。正确为“一场严重的生态危机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26684, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他写了一篇关于生态危机文章。", "corrected_sentence": "他写了一篇关于生态危机的文章。", "error_description": "“的”遗漏：“关于生态危机”修饰“文章”时需要加“的”，应为“关于生态危机的文章”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
