INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26686, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事说话刚刚好，不多也不少。", "primary_collocate": null, "pronunciation": "qià rú qí fèn", "ipa": "tɕʰia˥˩ ɻu˧˥ tɕʰi˧˥ fən˥˩", "syllable_count": 4, "sentences": [{"text": "他的话说得恰如其分。", "target_word": "恰如其分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜的盐放得恰如其分。", "target_word": "恰如其分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给的帮助恰如其分。", "target_word": "恰如其分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的玩笑开得恰如其分，没人生气。", "target_word": "恰如其分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的灯光恰如其分，不太亮。", "target_word": "恰如其分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事他处理得恰如其分。", "target_word": "恰如其分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他恰如其分地道了歉。", "target_word": "恰如其分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友恰如其分的提醒，让我少走了弯路。", "target_word": "恰如其分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的音量恰如其分。", "target_word": "恰如其分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对孩子的要求恰如其分。", "target_word": "恰如其分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恰如其分地", "label": "状语形式"}], "register": "书面", "sense_fingerprint": "做事说话刚刚好、不多不少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b44a80eb-78df-43d2-b3b5-0ae745060986') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26686, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恰如其分", "is_correct": true, "explanation": "正确：“恰如其分”作“说得”后的补语，说明说话刚刚好、不多不少。"}, {"text": "漆黑", "is_correct": false, "explanation": "语义：“漆黑”形容光线暗或颜色深，不能用来评价说话的分寸。"}, {"text": "滚烫", "is_correct": false, "explanation": "搭配：“滚烫”多用于温度或液体，“说得滚烫”不通。"}, {"text": "雪白", "is_correct": false, "explanation": "体貌：“雪白”描写颜色，不能用来形容说话的样子。"}], "explanations": {"恰如其分": "正确：“恰如其分”作“说得”后的补语，说明说话刚刚好、不多不少。", "漆黑": "语义：“漆黑”形容光线暗或颜色深，不能用来评价说话的分寸。", "滚烫": "搭配：“滚烫”多用于温度或液体，“说得滚烫”不通。", "雪白": "体貌：“雪白”描写颜色，不能用来形容说话的样子。"}, "sentence_index": 0, "correct_answer": "恰如其分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我到车站的时候，车恰如其分地开走了。", "explanation": "这里表示“正好碰上”，应该用〈恰好〉。恰如其分说的是做事说话的分寸，不表示时间上的巧合。"}, {"text": "这个女孩长得恰如其分。", "explanation": "这里应该用〈漂亮〉。恰如其分只用于说明做事说话的分寸，不用来形容外貌。"}, {"text": "这个班恰如其分有二十个人。", "explanation": "这里应该用〈正好〉。恰如其分说的是分寸，不用来表示人数恰好相等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26686, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恰如其分", "is_correct": true, "explanation": "正确：“恰如其分地”修饰“道歉”，表示道歉得有分寸、合适。"}, {"text": "狭窄", "is_correct": false, "explanation": "语义：“狭窄”指空间小，与道歉的态度和分寸无关。"}, {"text": "碧绿", "is_correct": false, "explanation": "体貌：“碧绿”描写颜色，不能用来修饰道歉。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”多用于物体表面，不能修饰“道歉”。"}], "explanations": {"恰如其分": "正确：“恰如其分地”修饰“道歉”，表示道歉得有分寸、合适。", "狭窄": "语义：“狭窄”指空间小，与道歉的态度和分寸无关。", "碧绿": "体貌：“碧绿”描写颜色，不能用来修饰道歉。", "粗糙": "搭配：“粗糙”多用于物体表面，不能修饰“道歉”。"}, "sentence_index": 6, "correct_answer": "恰如其分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的箭恰如其分地射中了靶心。", "explanation": "这里表示位置上正好命中，应该用〈正中〉。恰如其分指做事的分寸，不指位置准确。"}, {"text": "我们的看法恰如其分地相反。", "explanation": "这里表示“正好相反”，应该用〈恰恰〉。恰如其分指做事说话的分寸，不表示方向上的对立。"}, {"text": "他恰如其分地把作业忘了。", "explanation": "这里表示“忘得干干净净”，应该用〈彻底〉。恰如其分指分寸合适，不表示程度上的完全。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
